--
-- Name: books_account_map_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_account_map_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  acct      record;
  expected  text;
  locked_to date;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'books_account_map is the history of where each posting role went; a repoint is a new row, never a change (%).', TG_OP
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT a.landlord_id, a.business_id, a.type, a.active, a.name INTO acct
    FROM books_accounts a WHERE a.id = NEW.account_id;
  IF acct.landlord_id IS DISTINCT FROM NEW.landlord_id OR acct.business_id IS DISTINCT FROM NEW.business_id THEN
    RAISE EXCEPTION 'That account belongs to another company''s chart.' USING ERRCODE = 'check_violation';
  END IF;
  IF acct.active IS FALSE THEN
    RAISE EXCEPTION '% is retired. Choose an active account.', acct.name USING ERRCODE = 'check_violation';
  END IF;
  expected := CASE NEW.map_kind
                WHEN 'role' THEN ledger_account_role_type(NEW.map_value)
                WHEN 'bank_connection' THEN 'asset'
                WHEN 'sales_tax' THEN 'liability'
                WHEN 'rent_line' THEN 'income'
                WHEN 'stay_line' THEN 'income'
                WHEN 'loan' THEN 'liability'
                WHEN 'expense_category' THEN '*'
                WHEN 'income_category' THEN '*'
              END;
  IF expected IS NULL THEN
    RAISE EXCEPTION '% is not a posting role the books use.', NEW.map_value USING ERRCODE = 'check_violation';
  END IF;
  IF expected = '*' THEN
    IF NOT EXISTS (SELECT 1 FROM books_categories c
                    WHERE c.id::text = NEW.map_value
                      AND c.direction = CASE NEW.map_kind WHEN 'expense_category' THEN 'expense' ELSE 'income' END
                      AND c.landlord_id IS NOT DISTINCT FROM NEW.landlord_id
                      AND c.business_id IS NOT DISTINCT FROM NEW.business_id) THEN
      RAISE EXCEPTION 'That category is not one of this company''s.' USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM books_account_map m
                WHERE m.account_id = NEW.account_id AND m.map_kind = 'role' AND ledger_account_role_is_control(m.map_value)) THEN
      RAISE EXCEPTION '% is kept by GAM from the money records. Choose another account for this category.', acct.name
        USING ERRCODE = 'check_violation';
    END IF;
  ELSIF acct.type IS DISTINCT FROM expected THEN
    RAISE EXCEPTION '% is an % account; this needs an % account.', acct.name, acct.type, expected
      USING ERRCODE = 'check_violation';
  END IF;
  -- The first row for a key may cover all history; a repoint never reaches
  -- into a closed month. 10/12 review: nor does a category's starting role
  -- history written down as its own (services/booksCategories pointCategory,
  -- the first time a category that already posted is pointed): each copy is
  -- one of that role's own rows, the same account from the same day, and every
  -- row the category has so far is such a copy — so the category charges
  -- exactly where it always did on every day, closed months included.
  IF expected = '*' AND EXISTS (
       SELECT 1 FROM books_categories c
         JOIN books_account_map r
           ON r.map_kind = 'role'
          AND r.map_value = COALESCE(c.default_role, CASE c.direction WHEN 'expense' THEN 'other_expenses' ELSE 'other_income' END)
          AND r.landlord_id IS NOT DISTINCT FROM NEW.landlord_id AND r.business_id IS NOT DISTINCT FROM NEW.business_id
          AND r.account_id = NEW.account_id AND r.effective_from = NEW.effective_from
        WHERE c.id::text = NEW.map_value)
     AND NOT EXISTS (
       SELECT 1 FROM books_account_map m
        WHERE m.map_kind = NEW.map_kind AND m.map_value = NEW.map_value
          AND m.landlord_id IS NOT DISTINCT FROM NEW.landlord_id AND m.business_id IS NOT DISTINCT FROM NEW.business_id
          AND NOT EXISTS (
            SELECT 1 FROM books_categories c2
              JOIN books_account_map r2
                ON r2.map_kind = 'role'
               AND r2.map_value = COALESCE(c2.default_role, CASE c2.direction WHEN 'expense' THEN 'other_expenses' ELSE 'other_income' END)
               AND r2.landlord_id IS NOT DISTINCT FROM m.landlord_id AND r2.business_id IS NOT DISTINCT FROM m.business_id
               AND r2.account_id = m.account_id AND r2.effective_from = m.effective_from
             WHERE c2.id::text = m.map_value)) THEN
    RETURN NEW;
  END IF;
  IF EXISTS (SELECT 1 FROM books_account_map m
              WHERE m.map_kind = NEW.map_kind AND m.map_value = NEW.map_value
                AND ((NEW.landlord_id IS NOT NULL AND m.landlord_id = NEW.landlord_id)
                     OR (NEW.business_id IS NOT NULL AND m.business_id = NEW.business_id))) THEN
    locked_to := ledger_closed_through(NEW.landlord_id, NEW.business_id);
    IF locked_to IS NOT NULL AND NEW.effective_from <= locked_to THEN
      RAISE EXCEPTION 'The books are closed through %; a repoint takes effect after that.', locked_to
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: books_accounts_ledger_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_accounts_ledger_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  has_lines  boolean;
  is_mapped  boolean;
  ever_mapped boolean;
  repl       record;
BEGIN
  IF NEW.type IS NOT DISTINCT FROM OLD.type
     AND NEW.active IS NOT DISTINCT FROM OLD.active
     AND NEW.landlord_id IS NOT DISTINCT FROM OLD.landlord_id
     AND NEW.business_id IS NOT DISTINCT FROM OLD.business_id
     AND NEW.replaced_by_account_id IS NOT DISTINCT FROM OLD.replaced_by_account_id THEN
    RETURN NEW;
  END IF;

  has_lines := EXISTS (SELECT 1 FROM ledger_posting_lines l WHERE l.account_id = OLD.id);
  ever_mapped := EXISTS (SELECT 1 FROM books_account_map m WHERE m.account_id = OLD.id);
  -- "Mapped" = the row in force today for some (kind, value) of this company
  -- points here (the latest row; a repoint is never dated in the future).
  is_mapped := ever_mapped AND EXISTS (
    SELECT 1 FROM (
      SELECT DISTINCT ON (m.map_kind, m.map_value) m.account_id
        FROM books_account_map m
       WHERE (OLD.landlord_id IS NOT NULL AND m.landlord_id = OLD.landlord_id)
          OR (OLD.business_id IS NOT NULL AND m.business_id = OLD.business_id)
       ORDER BY m.map_kind, m.map_value, m.effective_from DESC, m.id DESC
    ) cur WHERE cur.account_id = OLD.id);

  IF NEW.type IS DISTINCT FROM OLD.type AND (has_lines OR is_mapped) THEN
    RAISE EXCEPTION '% already carries automatic postings, so its type cannot change. Add a new account of the right type and point the posting role at it.', OLD.name
      USING ERRCODE = 'check_violation';
  END IF;

  IF (NEW.landlord_id IS DISTINCT FROM OLD.landlord_id OR NEW.business_id IS DISTINCT FROM OLD.business_id)
     AND (has_lines OR ever_mapped) THEN
    RAISE EXCEPTION '% belongs to its company''s books and cannot move to another company.', OLD.name
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.replaced_by_account_id IS NOT NULL THEN
    IF NEW.replaced_by_account_id = NEW.id THEN
      RAISE EXCEPTION 'An account cannot replace itself.' USING ERRCODE = 'check_violation';
    END IF;
    SELECT a.landlord_id, a.business_id, a.type, a.active, a.name INTO repl
      FROM books_accounts a WHERE a.id = NEW.replaced_by_account_id;
    IF repl.landlord_id IS DISTINCT FROM NEW.landlord_id OR repl.business_id IS DISTINCT FROM NEW.business_id
       OR repl.type IS DISTINCT FROM NEW.type OR repl.active IS NOT TRUE THEN
      RAISE EXCEPTION 'The replacement must be an active % account in the same chart.', NEW.type
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF OLD.active IS NOT FALSE AND NEW.active IS FALSE THEN
    IF is_mapped THEN
      RAISE EXCEPTION '% is where automatic postings go. Choose the account that takes its place, then delete it.', OLD.name
        USING ERRCODE = 'check_violation';
    END IF;
    IF has_lines AND NEW.replaced_by_account_id IS NULL THEN
      RAISE EXCEPTION '% has posted history. Choose the account that takes its place, then delete it.', OLD.name
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: books_categories_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_categories_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.direction IS DISTINCT FROM OLD.direction OR NEW.landlord_id IS DISTINCT FROM OLD.landlord_id
     OR NEW.business_id IS DISTINCT FROM OLD.business_id OR NEW.default_role IS DISTINCT FROM OLD.default_role
     OR NEW.system_key IS DISTINCT FROM OLD.system_key OR NEW.system_use IS DISTINCT FROM OLD.system_use THEN
    RAISE EXCEPTION 'A category''s direction, company and starting account never change; make a new category instead.'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: books_category_account(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_category_account(p_category uuid, p_day date) RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
  WITH c AS (
    SELECT id, landlord_id, business_id,
           CASE direction WHEN 'expense' THEN 'expense_category' ELSE 'income_category' END AS kind,
           COALESCE(default_role, CASE direction WHEN 'expense' THEN 'other_expenses' ELSE 'other_income' END) AS role
      FROM books_categories WHERE id = p_category)
  SELECT COALESCE(
    (SELECT m.account_id FROM books_account_map m, c
      WHERE m.map_kind = c.kind AND m.map_value = c.id::text
        AND m.landlord_id IS NOT DISTINCT FROM c.landlord_id AND m.business_id IS NOT DISTINCT FROM c.business_id
      ORDER BY (m.effective_from <= p_day) DESC,
               CASE WHEN m.effective_from <= p_day THEN m.effective_from END DESC NULLS LAST,
               m.effective_from, m.id DESC
      LIMIT 1),
    (SELECT m.account_id FROM books_account_map m, c
      WHERE m.map_kind = 'role' AND m.map_value = c.role
        AND m.landlord_id IS NOT DISTINCT FROM c.landlord_id AND m.business_id IS NOT DISTINCT FROM c.business_id
      ORDER BY (m.effective_from <= p_day) DESC,
               CASE WHEN m.effective_from <= p_day THEN m.effective_from END DESC NULLS LAST,
               m.effective_from, m.id DESC
      LIMIT 1))
$$;


--
-- Name: books_category_account_type(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_category_account_type(p_category uuid) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE(
    (SELECT a.type FROM books_accounts a WHERE a.id = books_category_account(p_category, CURRENT_DATE)),
    (SELECT ledger_account_role_type(COALESCE(c.default_role,
              CASE c.direction WHEN 'expense' THEN 'other_expenses' ELSE 'other_income' END))
       FROM books_categories c WHERE c.id = p_category))
$$;


--
-- Name: books_category_account_type_on(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_category_account_type_on(p_category uuid, p_day date) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE(
    (SELECT a.type FROM books_accounts a WHERE a.id = books_category_account(p_category, p_day)),
    (SELECT ledger_account_role_type(COALESCE(c.default_role,
              CASE c.direction WHEN 'expense' THEN 'other_expenses' ELSE 'other_income' END))
       FROM books_categories c WHERE c.id = p_category))
$$;


--
-- Name: books_category_for_row(uuid, text, text, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_category_for_row(p_landlord uuid, p_direction text, p_text text, p_account uuid, p_day date) RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE(
    (SELECT c.id FROM books_categories c
      WHERE p_account IS NOT NULL AND c.landlord_id = p_landlord AND c.direction = p_direction AND c.archived_at IS NULL
        AND books_category_account(c.id, COALESCE(p_day, CURRENT_DATE)) = p_account
      ORDER BY (c.system_key = lower(regexp_replace(btrim(COALESCE(p_text, '')), '[^A-Za-z0-9]+', '_', 'g'))
                OR lower(btrim(c.name)) = lower(btrim(COALESCE(p_text, '')))) DESC NULLS LAST,
               (c.system_key IS NOT NULL) DESC, c.created_at, c.id
      LIMIT 1),
    books_category_for_text(p_landlord, p_direction, p_text))
$$;


--
-- Name: books_category_for_text(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_category_for_text(p_landlord uuid, p_direction text, p_text text) RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE(
    (SELECT c.id FROM books_categories c
      WHERE c.landlord_id = p_landlord AND c.direction = p_direction AND c.archived_at IS NULL
        AND (c.system_key = lower(regexp_replace(btrim(COALESCE(p_text, '')), '[^A-Za-z0-9]+', '_', 'g'))
             OR lower(btrim(c.name)) = lower(btrim(COALESCE(p_text, ''))))
      ORDER BY (c.system_key IS NOT NULL) DESC, c.created_at LIMIT 1),
    (SELECT c.id FROM books_categories c
      WHERE c.landlord_id = p_landlord AND c.direction = p_direction AND c.system_key = 'other'))
$$;


--
-- Name: books_category_on_pl(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_category_on_pl(p_category uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN p_category IS NULL THEN TRUE
              ELSE COALESCE((SELECT books_category_account_type(c.id) = c.direction
                               FROM books_categories c WHERE c.id = p_category), TRUE) END
$$;


--
-- Name: FUNCTION books_category_on_pl(p_category uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.books_category_on_pl(p_category uuid) IS '10/12 (Nic, L5): TRUE when a category''s money counts on the Profit & Loss (its account is an expense account for money out, an income account for money in). An owner draw on equity, payroll''s take-home pay on a liability: real money, not a cost.';


--
-- Name: books_category_on_pl_on(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_category_on_pl_on(p_category uuid, p_day date) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN p_category IS NULL THEN TRUE
              ELSE COALESCE((SELECT books_category_account_type_on(c.id, COALESCE(p_day, CURRENT_DATE)) = c.direction
                               FROM books_categories c WHERE c.id = p_category), TRUE) END
$$;


--
-- Name: FUNCTION books_category_on_pl_on(p_category uuid, p_day date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.books_category_on_pl_on(p_category uuid, p_day date) IS '10/12 review: books_category_on_pl as the category''s account stood on p_day — how a row dated that day counts on a Profit & Loss outside the ledger.';


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: books_contractors; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.books_contractors (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    landlord_id uuid,
    first_name character varying(100),
    last_name character varying(100),
    business_name character varying(200),
    email character varying(200),
    phone character varying(20),
    address text,
    ein character varying(10),
    ssn_last4 character varying(4),
    entity_type character varying(30) DEFAULT 'individual'::character varying,
    trade character varying(100),
    pay_rate numeric(10,2),
    pay_unit character varying(20) DEFAULT 'project'::character varying,
    status character varying(20) DEFAULT 'active'::character varying,
    ytd_paid numeric(12,2) DEFAULT 0,
    w9_on_file boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    business_id uuid,
    CONSTRAINT books_contractors_one_owner CHECK ((num_nonnulls(landlord_id, business_id) <= 1))
);


--
-- Name: books_contractor_vendor_fields(public.books_contractors); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_contractor_vendor_fields(c public.books_contractors) RETURNS TABLE(name text, contact_name text, tax_classification text, tax_id text, ssn_last4 text, pay_unit text, status text)
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT left(COALESCE(NULLIF(btrim(c.business_name), ''),
                       NULLIF(btrim(concat_ws(' ', btrim(c.first_name), btrim(c.last_name))), ''),
                       'Contractor'), 200),
         left(NULLIF(btrim(concat_ws(' ', btrim(c.first_name), btrim(c.last_name))), ''), 200),
         CASE WHEN c.entity_type IN ('individual', 'c_corp', 's_corp', 'partnership', 'llc', 'other') THEN c.entity_type END,
         NULLIF(btrim(c.ein), ''),
         CASE WHEN c.ssn_last4 ~ '^[0-9]{4}$' THEN c.ssn_last4 END,
         CASE WHEN c.pay_unit IN ('project', 'hour', 'day', 'sqft') THEN c.pay_unit END,
         CASE WHEN c.status IS NULL OR c.status = 'active' THEN 'active' ELSE 'inactive' END
$_$;


--
-- Name: books_contractors_fold(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_contractors_fold() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  f record;
BEGIN
  SELECT * INTO f FROM books_contractor_vendor_fields(NEW);
  IF NOT EXISTS (SELECT 1 FROM books_vendors v WHERE v.migrated_from_contractor_id = NEW.id) THEN
    INSERT INTO books_vendors (landlord_id, business_id, name, contact_name, email, phone, address, payment_terms,
                               vendor_type, is_1099, tax_classification, tax_id, ssn_last4, w9_on_file,
                               trade, pay_rate, pay_unit, status, migrated_from_contractor_id)
    VALUES (NEW.landlord_id, NEW.business_id, f.name, f.contact_name, NEW.email, NEW.phone, NEW.address, NULL,
            'contractor', TRUE, f.tax_classification, f.tax_id, f.ssn_last4, COALESCE(NEW.w9_on_file, FALSE),
            NEW.trade, CASE WHEN NEW.pay_rate > 0 THEN NEW.pay_rate END, f.pay_unit, f.status, NEW.id);
  ELSIF TG_OP = 'UPDATE' THEN
    UPDATE books_vendors v
       SET name = f.name, contact_name = f.contact_name, email = NEW.email, phone = NEW.phone, address = NEW.address,
           tax_classification = f.tax_classification, tax_id = f.tax_id, ssn_last4 = f.ssn_last4,
           w9_on_file = COALESCE(NEW.w9_on_file, FALSE), trade = NEW.trade,
           pay_rate = CASE WHEN NEW.pay_rate > 0 THEN NEW.pay_rate END, pay_unit = f.pay_unit, status = f.status,
           updated_at = now()
     WHERE v.migrated_from_contractor_id = NEW.id;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: FUNCTION books_contractors_fold(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.books_contractors_fold() IS '10/12 (Nic): the Contractors list folded into the one Vendors list; until the code that retires the Contractors page ships, a contractor saved there is folded (and kept in step) at once.';


--
-- Name: books_expense_fixed_asset(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_expense_fixed_asset(p_expense uuid) RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
  SELECT f.id FROM books_fixed_assets f
   WHERE f.voided_at IS NULL
     AND (f.source_expense_id = p_expense
          OR EXISTS (SELECT 1 FROM books_fixed_asset_funding x
                      WHERE x.asset_id = f.id AND x.expense_id = p_expense AND x.replaced_at IS NULL))
   ORDER BY f.created_at, f.id
   LIMIT 1
$$;


--
-- Name: FUNCTION books_expense_fixed_asset(p_expense uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.books_expense_fixed_asset(p_expense uuid) IS '10/13 (Nic): the live fixed asset an expense is part of — made from it (source_expense_id) or named by a live funding line — or NULL.';


--
-- Name: books_fill_category_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_fill_category_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  dir text := CASE TG_TABLE_NAME WHEN 'landlord_other_income' THEN 'income' ELSE 'expense' END;
BEGIN
  IF NEW.category_id IS NOT NULL OR NEW.landlord_id IS NULL THEN RETURN NEW; END IF;
  PERFORM books_seed_categories(NEW.landlord_id);
  SELECT c.id INTO NEW.category_id FROM books_categories c
   WHERE c.landlord_id = NEW.landlord_id AND c.direction = dir
     AND c.system_key = COALESCE(NULLIF(NEW.category, ''), 'other');
  IF NEW.category_id IS NULL THEN
    SELECT c.id INTO NEW.category_id FROM books_categories c
     WHERE c.landlord_id = NEW.landlord_id AND c.direction = dir AND c.system_key = 'other';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: books_fixed_asset_funding_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_fixed_asset_funding_check() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  msg text;
BEGIN
  IF TG_TABLE_NAME = 'books_loans' THEN
    msg := books_loan_funding_problem(NEW.id);
  ELSIF TG_TABLE_NAME = 'books_fixed_assets' THEN
    msg := books_fixed_asset_funding_problem(NEW.id);
    IF msg IS NULL AND NEW.funded_loan_id IS NOT NULL THEN
      msg := books_loan_funding_problem(NEW.funded_loan_id);
    END IF;
  ELSE
    msg := books_fixed_asset_funding_problem(NEW.asset_id);
  END IF;
  IF msg IS NOT NULL THEN
    RAISE EXCEPTION '%', msg USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: books_fixed_asset_funding_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_fixed_asset_funding_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'A fixed asset''s funding line is never removed; say where the money came from again instead.' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.replaced_at IS NOT NULL
     OR (NEW.asset_id, NEW.landlord_id, NEW.kind, NEW.loan_id, NEW.expense_id, NEW.amount, NEW.line_no, NEW.created_by, NEW.created_at)
        IS DISTINCT FROM (OLD.asset_id, OLD.landlord_id, OLD.kind, OLD.loan_id, OLD.expense_id, OLD.amount, OLD.line_no, OLD.created_by, OLD.created_at) THEN
    RAISE EXCEPTION 'A fixed asset''s funding line does not change; say where the money came from again instead.' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: books_fixed_asset_funding_problem(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_fixed_asset_funding_problem(p_asset uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
  a record;
  total numeric;
  bad record;
  msg text;
BEGIN
  SELECT f.id, f.name, f.cost, f.landlord_id, f.voided_at, f.funded_by, f.funded_loan_id, f.source_expense_id, f.property_id
    INTO a FROM books_fixed_assets f WHERE f.id = p_asset;
  IF NOT FOUND THEN
    IF EXISTS (SELECT 1 FROM books_fixed_asset_funding x WHERE x.asset_id = p_asset AND x.replaced_at IS NULL) THEN
      RETURN format('A funding line names fixed asset %s, which is not on the books.', p_asset);
    END IF;
    RETURN NULL;
  END IF;
  IF a.voided_at IS NOT NULL THEN RETURN NULL; END IF;
  SELECT sum(x.amount) INTO total FROM books_fixed_asset_funding x WHERE x.asset_id = a.id AND x.replaced_at IS NULL;
  IF total IS NULL THEN RETURN NULL; END IF;
  IF a.funded_by IS NOT NULL OR a.funded_loan_id IS NOT NULL OR a.source_expense_id IS NOT NULL THEN
    RETURN format('The fixed asset "%s" says where its money came from once, as a list.', a.name);
  END IF;
  IF total <> a.cost THEN
    RETURN format('Where the money for "%s" came from adds up to %s, and it cost %s. The amounts must add up to what it cost.',
                  a.name, to_char(total, 'FM$999,999,990.00'), to_char(a.cost, 'FM$999,999,990.00'));
  END IF;
  IF EXISTS (SELECT 1 FROM books_fixed_asset_funding x WHERE x.asset_id = a.id AND x.replaced_at IS NULL
                AND x.landlord_id IS DISTINCT FROM a.landlord_id) THEN
    RETURN format('Where the money for "%s" came from must be its own company''s.', a.name);
  END IF;
  FOR bad IN SELECT DISTINCT x.loan_id FROM books_fixed_asset_funding x
              WHERE x.asset_id = a.id AND x.replaced_at IS NULL AND x.loan_id IS NOT NULL LOOP
    msg := books_loan_funding_problem(bad.loan_id);
    IF msg IS NOT NULL THEN RETURN msg; END IF;
  END LOOP;
  SELECT e.id, e.amount, x.amount AS line, e.description,
         (SELECT count(*) FROM books_fixed_asset_funding y WHERE y.asset_id = a.id AND y.replaced_at IS NULL AND y.expense_id = e.id) AS lines_here,
         EXISTS (SELECT 1 FROM books_fixed_assets g
                  WHERE g.id <> a.id AND g.voided_at IS NULL
                    AND (g.source_expense_id = e.id
                         OR EXISTS (SELECT 1 FROM books_fixed_asset_funding z
                                     WHERE z.asset_id = g.id AND z.expense_id = e.id AND z.replaced_at IS NULL))) AS elsewhere
    INTO bad
    FROM books_fixed_asset_funding x JOIN landlord_expenses e ON e.id = x.expense_id
   WHERE x.asset_id = a.id AND x.replaced_at IS NULL
     AND (x.amount <> e.amount OR e.landlord_id IS DISTINCT FROM a.landlord_id
          OR (SELECT count(*) FROM books_fixed_asset_funding y WHERE y.asset_id = a.id AND y.replaced_at IS NULL AND y.expense_id = e.id) > 1
          OR EXISTS (SELECT 1 FROM books_fixed_assets g
                      WHERE g.id <> a.id AND g.voided_at IS NULL
                        AND (g.source_expense_id = e.id
                             OR EXISTS (SELECT 1 FROM books_fixed_asset_funding z
                                         WHERE z.asset_id = g.id AND z.expense_id = e.id AND z.replaced_at IS NULL))))
   LIMIT 1;
  IF FOUND THEN
    IF bad.elsewhere THEN RETURN format('The expense "%s" is already part of another fixed asset.', COALESCE(bad.description, 'chosen')); END IF;
    IF bad.lines_here > 1 THEN RETURN format('The expense "%s" is named twice for "%s".', COALESCE(bad.description, 'chosen'), a.name); END IF;
    RETURN format('An expense counts toward a fixed asset whole: the expense "%s" is %s.', COALESCE(bad.description, 'chosen'),
                  to_char(bad.amount, 'FM$999,999,990.00'));
  END IF;
  IF EXISTS (SELECT 1 FROM books_fixed_asset_funding x WHERE x.asset_id = a.id AND x.replaced_at IS NULL AND x.expense_id IS NOT NULL
                AND NOT EXISTS (SELECT 1 FROM landlord_expenses e WHERE e.id = x.expense_id)) THEN
    RETURN format('Where the money for "%s" came from names an expense that is not on the books.', a.name);
  END IF;
  -- 10/13 review: an expense pays for part of an asset only where the asset is.
  SELECT e.description INTO bad
    FROM books_fixed_asset_funding x JOIN landlord_expenses e ON e.id = x.expense_id
   WHERE x.asset_id = a.id AND x.replaced_at IS NULL
     AND COALESCE((SELECT u.property_id FROM units u WHERE u.id = e.unit_id), e.property_id) IS DISTINCT FROM a.property_id
   LIMIT 1;
  IF FOUND THEN
    RETURN format('The expense "%s" is not filed where the fixed asset "%s" goes. An expense pays for part of an asset only where the asset is.',
                  COALESCE(bad.description, 'chosen'), a.name);
  END IF;
  IF EXISTS (SELECT 1 FROM books_fixed_asset_funding x WHERE x.asset_id = a.id AND x.replaced_at IS NULL AND x.loan_id IS NOT NULL
                AND NOT EXISTS (SELECT 1 FROM books_loans l WHERE l.id = x.loan_id AND l.landlord_id = a.landlord_id)) THEN
    RETURN format('Where the money for "%s" came from names a loan that is not this company''s.', a.name);
  END IF;
  RETURN NULL;
END $_$;


--
-- Name: books_fixed_assets_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_fixed_assets_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'A fixed asset is never removed; void it instead.' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.voided_at IS NOT NULL THEN
    RAISE EXCEPTION 'Fixed asset % was voided: it is a record and does not change.', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.landlord_id IS DISTINCT FROM OLD.landlord_id OR NEW.business_id IS DISTINCT FROM OLD.business_id
     OR NEW.source_expense_id IS DISTINCT FROM OLD.source_expense_id THEN
    RAISE EXCEPTION 'A fixed asset''s company and the expense it was made from never change.' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: books_legacy_expense_key(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_legacy_expense_key(p_category uuid) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE((SELECT c.system_key FROM books_categories c
                    WHERE c.id = p_category
                      AND c.system_key IN ('maintenance', 'repairs', 'utilities', 'insurance', 'property_tax', 'management',
                                           'supplies', 'landscaping', 'professional', 'mortgage_interest', 'hoa',
                                           'advertising', 'lot_rent', 'bank_fees', 'other')), 'other')
$$;


--
-- Name: books_loan_funding_problem(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_loan_funding_problem(p_loan uuid) RETURNS text
    LANGUAGE sql STABLE
    AS $_$
  SELECT format('The loan "%s" lent %s, and the fixed assets it paid for add up to %s. Lower what the assets say came from it, or check the amount borrowed.',
                l.name, to_char(l.original_amount, 'FM$999,999,990.00'), to_char(books_loan_used_by_assets(l.id), 'FM$999,999,990.00'))
    FROM books_loans l
   WHERE l.id = p_loan AND books_loan_used_by_assets(l.id) > l.original_amount
$_$;


--
-- Name: books_loan_payments_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_loan_payments_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  loan record;
  line record;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'A loan payment is never removed; void it instead.' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF OLD.voided_at IS NOT NULL THEN
      RAISE EXCEPTION 'Loan payment % was voided: it is a record and does not change.', OLD.id USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.loan_id IS DISTINCT FROM OLD.loan_id OR NEW.landlord_id IS DISTINCT FROM OLD.landlord_id
       OR NEW.business_id IS DISTINCT FROM OLD.business_id OR NEW.source IS DISTINCT FROM OLD.source THEN
      RAISE EXCEPTION 'A loan payment''s loan, company and source never change; void it and record another.'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  SELECT l.landlord_id, l.business_id, l.voided_at INTO loan FROM books_loans l WHERE l.id = NEW.loan_id;
  IF loan.landlord_id IS DISTINCT FROM NEW.landlord_id OR loan.business_id IS DISTINCT FROM NEW.business_id THEN
    RAISE EXCEPTION 'A loan payment belongs to its loan''s company.' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.voided_at IS NULL AND loan.voided_at IS NOT NULL THEN
    RAISE EXCEPTION 'That loan was voided; it takes no payments.' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.bank_transaction_id IS NOT NULL AND NEW.voided_at IS NULL
     AND (TG_OP = 'INSERT' OR NEW.bank_transaction_id IS DISTINCT FROM OLD.bank_transaction_id) THEN
    SELECT bt.amount, bt.landlord_id INTO line FROM bank_transactions bt WHERE bt.id = NEW.bank_transaction_id;
    IF line.landlord_id IS DISTINCT FROM NEW.landlord_id THEN
      RAISE EXCEPTION 'That bank line belongs to another company.' USING ERRCODE = 'check_violation';
    END IF;
    IF line.amount >= 0 THEN
      RAISE EXCEPTION 'That bank line is money coming in; a loan payment is money going out.' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.amount > abs(line.amount) THEN
      RAISE EXCEPTION 'The loan payment (%) is more than the bank line (%).', NEW.amount, abs(line.amount)
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: books_loan_used_by_assets(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_loan_used_by_assets(p_loan uuid) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE((SELECT sum(x.amount) FROM books_fixed_asset_funding x
                     JOIN books_fixed_assets f ON f.id = x.asset_id AND f.voided_at IS NULL
                    WHERE x.loan_id = p_loan AND x.replaced_at IS NULL), 0)
       + COALESCE((SELECT sum(f.cost) FROM books_fixed_assets f
                    WHERE f.funded_loan_id = p_loan AND f.funded_by = 'loan' AND f.voided_at IS NULL), 0)
$$;


--
-- Name: books_loans_asset_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_loans_asset_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  a record;
BEGIN
  IF (NEW.voided_at IS NOT NULL AND OLD.voided_at IS NULL) OR NEW.funded_to IS DISTINCT FROM OLD.funded_to THEN
    SELECT f.name INTO a FROM books_fixed_assets f
     WHERE f.voided_at IS NULL
       AND (f.funded_loan_id = NEW.id
            OR EXISTS (SELECT 1 FROM books_fixed_asset_funding x WHERE x.asset_id = f.id AND x.loan_id = NEW.id AND x.replaced_at IS NULL))
     LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'This loan paid for the fixed asset "%". Void the asset on the Fixed assets page first.', a.name
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.start_date IS DISTINCT FROM OLD.start_date THEN
    SELECT f.name, f.acquired_on, x.books_start_date INTO a
      FROM books_fixed_assets f JOIN landlords x ON x.id = f.landlord_id
     WHERE f.voided_at IS NULL AND x.books_start_date IS NOT NULL
       AND (f.funded_loan_id = NEW.id
            OR EXISTS (SELECT 1 FROM books_fixed_asset_funding y WHERE y.asset_id = f.id AND y.loan_id = NEW.id AND y.replaced_at IS NULL))
       AND (NEW.start_date < x.books_start_date) <> (f.acquired_on < x.books_start_date)
     LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'This loan paid for the fixed asset "%", bought on %. Your books start on %, and the loan''s day cannot be on the other side of that day from the asset''s (the asset''s cost would count twice, or not at all). Change the asset''s day on the Fixed assets page first.',
        a.name, a.acquired_on, a.books_start_date
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: books_loans_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_loans_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'A loan is never removed; void it instead.' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.voided_at IS NOT NULL THEN
    RAISE EXCEPTION 'Loan % was voided: it is a record and does not change.', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.landlord_id IS DISTINCT FROM OLD.landlord_id OR NEW.business_id IS DISTINCT FROM OLD.business_id THEN
    RAISE EXCEPTION 'A loan''s company never changes.' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: books_move_retired_rows(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_move_retired_rows(p_landlord uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  n integer := 0;
  k integer;
BEGIN
  PERFORM books_seed_categories(x.landlord_id)
     FROM (SELECT landlord_id FROM books_bills
            WHERE landlord_id IS NOT NULL AND migrated_expense_id IS NULL AND (p_landlord IS NULL OR landlord_id = p_landlord)
           UNION SELECT landlord_id FROM books_transactions
            WHERE landlord_id IS NOT NULL AND migrated_at IS NULL AND (p_landlord IS NULL OR landlord_id = p_landlord)) x;

  -- ── Bills → expenses ──────────────────────────────────────────────────────
  INSERT INTO landlord_expenses
    (landlord_id, category, category_id, amount, description, vendor, vendor_id, bill_number, expense_date, due_date,
     is_common, allocate_per_unit, status, payments_tracked, migrated_from_table, migrated_from_id, created_at, updated_at)
  SELECT b.landlord_id, books_legacy_expense_key(m.cat), m.cat, b.amount,
         concat_ws(' — ', NULLIF(btrim(b.description), ''), NULLIF(btrim(b.notes), '')),
         v.name, b.vendor_id, b.bill_number, b.date, b.due_date,
         FALSE, FALSE, 'active', TRUE, 'books_bills', b.id, COALESCE(b.created_at, now()), now()
    FROM books_bills b
    LEFT JOIN books_vendors v ON v.id = b.vendor_id
   CROSS JOIN LATERAL (SELECT books_category_for_row(b.landlord_id, 'expense', b.category, b.account_id, b.date) AS cat) m
   WHERE b.landlord_id IS NOT NULL AND (p_landlord IS NULL OR b.landlord_id = p_landlord)
     AND b.migrated_expense_id IS NULL AND b.amount > 0
     AND NOT EXISTS (SELECT 1 FROM landlord_expenses e
                      WHERE e.migrated_from_table = 'books_bills' AND e.migrated_from_id = b.id AND e.status = 'active');
  GET DIAGNOSTICS k = ROW_COUNT; n := n + k;

  UPDATE books_bills b SET migrated_expense_id = e.id, migrated_at = now()
    FROM landlord_expenses e
   WHERE e.migrated_from_table = 'books_bills' AND e.migrated_from_id = b.id AND e.status = 'active'
     AND b.migrated_expense_id IS NULL AND (p_landlord IS NULL OR b.landlord_id = p_landlord);

  -- Each bill payment, oldest first, never more than the bill — for a bill
  -- whose expense has nothing paid on it yet (the first move).
  INSERT INTO landlord_expense_payments
    (expense_id, landlord_id, paid_on, amount, method, source, memo, created_by, created_at)
  SELECT x.expense_id, x.landlord_id, x.paid_on, x.applied, 'other', 'migrated',
         'Paid on the old GAM Books Bills page', x.created_by, x.created_at
    FROM (SELECT b.migrated_expense_id AS expense_id, b.landlord_id, p.paid_on, p.created_by, p.created_at,
                 LEAST(p.amount, GREATEST(0, b.amount - COALESCE(sum(p.amount) OVER (
                   PARTITION BY p.bill_id ORDER BY p.paid_on, p.created_at, p.id
                   ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0))) AS applied
            FROM books_bill_payments p JOIN books_bills b ON b.id = p.bill_id
           WHERE b.migrated_expense_id IS NOT NULL AND p.amount > 0
             AND (p_landlord IS NULL OR b.landlord_id = p_landlord)) x
    JOIN landlord_expenses e ON e.id = x.expense_id AND e.status = 'active'
   WHERE x.applied > 0
     AND NOT EXISTS (SELECT 1 FROM landlord_expense_payments q WHERE q.expense_id = x.expense_id);
  GET DIAGNOSTICS k = ROW_COUNT; n := n + k;

  -- 10/12 review: what the bill says was paid beyond what its expense already
  -- has from it (the old pay route moves amount_paid; a payment row may come
  -- too) — dated the latest payment row when those cover it, else the day the
  -- bill was paid off, else today; never more than the bill, nor than the
  -- expense still owes.
  INSERT INTO landlord_expense_payments
    (expense_id, landlord_id, paid_on, amount, method, source, memo)
  SELECT x.expense_id, x.landlord_id, x.day, x.delta, 'other', 'migrated', 'Paid on the old GAM Books Bills page'
    FROM (SELECT b.migrated_expense_id AS expense_id, b.landlord_id,
                 LEAST(LEAST(b.amount, GREATEST(COALESCE(b.amount_paid, 0), COALESCE(bp.paid, 0))) - COALESCE(mp.paid, 0),
                       e.amount - COALESCE(ap.paid, 0)) AS delta,
                 CASE WHEN bp.last_day IS NOT NULL AND COALESCE(bp.paid, 0) >= COALESCE(b.amount_paid, 0) THEN bp.last_day
                      ELSE COALESCE(b.paid_at::date, CURRENT_DATE) END AS day
            FROM books_bills b
            JOIN landlord_expenses e ON e.id = b.migrated_expense_id AND e.status = 'active'
            LEFT JOIN (SELECT bill_id, sum(amount) AS paid, max(paid_on) AS last_day FROM books_bill_payments GROUP BY bill_id) bp
                   ON bp.bill_id = b.id
            LEFT JOIN (SELECT expense_id, sum(amount) AS paid FROM landlord_expense_payments
                        WHERE voided_at IS NULL AND source = 'migrated' GROUP BY expense_id) mp ON mp.expense_id = e.id
            LEFT JOIN (SELECT expense_id, sum(amount) AS paid FROM landlord_expense_payments
                        WHERE voided_at IS NULL GROUP BY expense_id) ap ON ap.expense_id = e.id
           WHERE b.landlord_id IS NOT NULL AND (p_landlord IS NULL OR b.landlord_id = p_landlord)) x
   WHERE x.delta > 0;
  GET DIAGNOSTICS k = ROW_COUNT; n := n + k;

  -- ── Transactions: money out → expenses paid that day ──────────────────────
  INSERT INTO landlord_expenses
    (landlord_id, category, category_id, amount, description, expense_date,
     is_common, allocate_per_unit, status, payments_tracked, migrated_from_table, migrated_from_id, created_at, updated_at)
  SELECT t.landlord_id, books_legacy_expense_key(m.cat), m.cat, abs(t.amount),
         concat_ws(' — ', NULLIF(btrim(t.description), ''), NULLIF(btrim(t.reference), '')),
         t.date, FALSE, FALSE, 'active', TRUE, 'books_transactions', t.id, COALESCE(t.created_at, now()), now()
    FROM books_transactions t
   CROSS JOIN LATERAL (SELECT books_category_for_row(t.landlord_id, 'expense', t.category, t.account_id, t.date) AS cat) m
   WHERE t.landlord_id IS NOT NULL AND (p_landlord IS NULL OR t.landlord_id = p_landlord)
     AND t.type = 'expense' AND t.deleted_at IS NULL AND t.migrated_expense_id IS NULL AND t.amount <> 0
     AND NOT EXISTS (SELECT 1 FROM landlord_expenses e
                      WHERE e.migrated_from_table = 'books_transactions' AND e.migrated_from_id = t.id AND e.status = 'active');
  GET DIAGNOSTICS k = ROW_COUNT; n := n + k;

  UPDATE books_transactions t SET migrated_expense_id = e.id, migrated_at = now()
    FROM landlord_expenses e
   WHERE e.migrated_from_table = 'books_transactions' AND e.migrated_from_id = t.id AND e.status = 'active'
     AND t.migrated_expense_id IS NULL AND (p_landlord IS NULL OR t.landlord_id = p_landlord);

  INSERT INTO landlord_expense_payments
    (expense_id, landlord_id, paid_on, amount, method, source, memo, created_at)
  SELECT e.id, e.landlord_id, e.expense_date, e.amount, 'other', 'migrated',
         'Typed on the old GAM Books Transactions page', e.created_at
    FROM landlord_expenses e
   WHERE e.migrated_from_table = 'books_transactions' AND e.status = 'active'
     AND (p_landlord IS NULL OR e.landlord_id = p_landlord)
     AND NOT EXISTS (SELECT 1 FROM landlord_expense_payments q WHERE q.expense_id = e.id);

  -- ── Transactions: money in → other income ─────────────────────────────────
  INSERT INTO landlord_other_income
    (landlord_id, category, category_id, amount, description, income_date, is_common, status,
     migrated_from_table, migrated_from_id, created_at, updated_at)
  SELECT t.landlord_id,
         COALESCE((SELECT c.system_key FROM books_categories c WHERE c.id = m.cat), 'other'), m.cat,
         abs(t.amount),
         concat_ws(' — ', NULLIF(btrim(t.description), ''), NULLIF(btrim(t.reference), '')),
         t.date, FALSE, 'active', 'books_transactions', t.id, COALESCE(t.created_at, now()), now()
    FROM books_transactions t
   CROSS JOIN LATERAL (SELECT books_category_for_row(t.landlord_id, 'income', t.category, t.account_id, t.date) AS cat) m
   WHERE t.landlord_id IS NOT NULL AND (p_landlord IS NULL OR t.landlord_id = p_landlord)
     AND t.type = 'income' AND t.deleted_at IS NULL AND t.migrated_other_income_id IS NULL AND t.amount <> 0
     AND NOT EXISTS (SELECT 1 FROM landlord_other_income o
                      WHERE o.migrated_from_table = 'books_transactions' AND o.migrated_from_id = t.id AND o.status = 'active');
  GET DIAGNOSTICS k = ROW_COUNT; n := n + k;

  UPDATE books_transactions t SET migrated_other_income_id = o.id, migrated_at = now()
    FROM landlord_other_income o
   WHERE o.migrated_from_table = 'books_transactions' AND o.migrated_from_id = t.id AND o.status = 'active'
     AND t.migrated_other_income_id IS NULL AND (p_landlord IS NULL OR t.landlord_id = p_landlord);
  RETURN n;
END $$;


--
-- Name: FUNCTION books_move_retired_rows(p_landlord uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.books_move_retired_rows(p_landlord uuid) IS '10/12 (Nic, L5): moves what the old GAM Books Bills and Transactions pages hold for a landlord company onto Expenses / other income (and a bill''s payments onto its expense). Idempotent; run by the migration and by the window triggers.';


--
-- Name: books_period_closes_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_period_closes_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION '% is a record of the books as they were closed; it is never changed or removed (%).', TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'check_violation';
END $$;


--
-- Name: books_register_stock_changes_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_register_stock_changes_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'books_register_stock_changes is append-only: record a new choice instead'
    USING ERRCODE = 'restrict_violation';
END $$;


--
-- Name: books_retired_rows_follow(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_retired_rows_follow() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF pg_trigger_depth() > 1 THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NULL END;
  END IF;
  IF TG_TABLE_NAME = 'books_transactions' THEN
    IF TG_OP = 'DELETE' THEN
      PERFORM books_transaction_moved_follows(OLD, TRUE);
      RETURN OLD;
    END IF;
    IF TG_OP = 'UPDATE' THEN PERFORM books_transaction_moved_follows(NEW, FALSE); END IF;
  END IF;
  PERFORM books_move_retired_rows(NEW.landlord_id);
  RETURN NULL;
END $$;


--
-- Name: FUNCTION books_retired_rows_follow(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.books_retired_rows_follow() IS '10/12 (Nic, L5): until the code that retires the old Bills and Transactions pages ships, every landlord row they write is moved (and kept in step) at once.';


--
-- Name: books_seed_categories(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_seed_categories(p_landlord uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  n integer;
BEGIN
  IF p_landlord IS NULL THEN RETURN 0; END IF;
  INSERT INTO books_categories (landlord_id, direction, name, system_key, default_role, system_use)
  SELECT p_landlord, s.direction, s.name, s.key, s.role, s.system_use
    FROM (VALUES
      ('expense', 'maintenance',           'Maintenance',                'repairs_maintenance',    NULL::text, 1),
      ('expense', 'repairs',               'Repairs',                    'repairs_maintenance',    NULL, 2),
      ('expense', 'utilities',             'Utilities',                  'utilities_expense',      NULL, 3),
      ('expense', 'insurance',             'Insurance',                  'insurance',              NULL, 4),
      ('expense', 'property_tax',          'Property tax',               'property_taxes',         NULL, 5),
      ('expense', 'management',            'Management',                 'management_fees',        NULL, 6),
      ('expense', 'supplies',              'Supplies',                   'supplies',               NULL, 7),
      ('expense', 'landscaping',           'Landscaping',                'landscaping',            NULL, 8),
      ('expense', 'professional',          'Legal / professional',       'professional_fees',      NULL, 9),
      ('expense', 'mortgage_interest',     'Mortgage interest',          'mortgage_interest',      NULL, 10),
      ('expense', 'hoa',                   'HOA',                        'hoa_fees',               NULL, 11),
      ('expense', 'advertising',           'Advertising',                'advertising',            NULL, 12),
      ('expense', 'lot_rent',              'Lot rent',                   'lot_rent_expense',       NULL, 13),
      ('expense', 'bank_fees',             'Bank fees / charges',        'bank_fees',              NULL, 14),
      ('expense', 'other',                 'Other',                      'other_expenses',         NULL, 15),
      ('expense', 'pest_control',          'Pest control',               'pest_control',           NULL, 16),
      ('expense', 'accounting',            'Accounting and bookkeeping', 'accounting_fees',        NULL, 17),
      ('expense', 'software',              'Software and subscriptions', 'software_subscriptions', NULL, 18),
      ('expense', 'vehicle_travel',        'Vehicle and travel',         'vehicle_travel',         NULL, 19),
      ('expense', 'contractor_payments',   'Contractor payments',        'contractor_payments',    NULL, 20),
      ('expense', 'wages',                 'Wages paid outside payroll', 'payroll_expense',        NULL, 21),
      ('expense', 'owner_draw',            'Owner draw',                 'owner_draws',            NULL, 22),
      ('expense', 'payroll_take_home',     'Payroll: take-home pay',     'net_pay_payable',        'payroll', 23),
      ('expense', 'payroll_taxes',         'Payroll: taxes owed',        'payroll_liabilities',    'payroll', 24),
      ('expense', 'work_trade_labor',      'Work trade labor',           'work_trade_labor',       NULL, 25),
      ('income',  'laundry',               'Laundry',                    'laundry_vending',        NULL, 101),
      ('income',  'vending',               'Vending',                    'laundry_vending',        NULL, 102),
      ('income',  'storage',               'Storage',                    'storage_fees',           NULL, 103),
      ('income',  'utility_reimbursement', 'Utility reimbursement',      'utility_other',          NULL, 104),
      ('income',  'late_fees',             'Late fees',                  'late_fees',              NULL, 105),
      ('income',  'application_fees',      'Application fees',           'application_fees',       NULL, 106),
      ('income',  'pet_fees',              'Pet fees',                   'pet_fees',               NULL, 107),
      ('income',  'parking',               'Parking',                    'other_income',           NULL, 108),
      ('income',  'propane_fuel',          'Propane / fuel',             'utility_propane',        NULL, 109),
      ('income',  'insurance_claim',       'Insurance claim',            'other_income',           NULL, 110),
      ('income',  'tax_refund',            'Tax refund',                 'other_income',           NULL, 111),
      ('income',  'sale_proceeds',         'Sale proceeds',              'suspense',               NULL, 112),
      ('income',  'owner_contribution',    'Owner contribution',         'owner_equity',           NULL, 113),
      ('income',  'interest',              'Interest earned',            'interest_earned',        NULL, 114),
      ('income',  'other',                 'Other income',               'other_income',           NULL, 115)
    ) AS s(direction, key, name, role, system_use, ord)
   WHERE NOT EXISTS (SELECT 1 FROM books_categories c
                      WHERE c.landlord_id = p_landlord AND c.direction = s.direction AND c.system_key = s.key)
   ORDER BY s.ord
  -- A name the company already gave a category of its own keeps it; GAM's
  -- starting one of the same name is simply not added.
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;


--
-- Name: FUNCTION books_seed_categories(p_landlord uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.books_seed_categories(p_landlord uuid) IS '10/12 (Nic, L5): adds GAM''s starting categories a company does not have yet (BOOKS_DEFAULT_*_CATEGORIES), Work trade labor included (20261014240100). Idempotent.';


--
-- Name: books_start_asset_loan_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_start_asset_loan_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  a record;
BEGIN
  SELECT f.name AS asset_name, f.acquired_on, l.name AS loan_name, l.start_date INTO a
    FROM books_fixed_assets f JOIN books_loans l ON l.id = f.funded_loan_id
   WHERE f.landlord_id = NEW.id AND f.voided_at IS NULL AND f.funded_by = 'loan'
     AND (l.start_date < NEW.books_start_date) <> (f.acquired_on < NEW.books_start_date)
   LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'Your books cannot start on %: the fixed asset "%" (bought on %) and the loan "%" that paid for it (made on %) would be on different sides of that day, so the asset''s cost would count twice, or not at all. Change the asset''s day or the loan''s first.',
      NEW.books_start_date, a.asset_name, a.acquired_on, a.loan_name, a.start_date
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT f.name AS asset_name, f.acquired_on, l.name AS loan_name, l.start_date INTO a
    FROM books_fixed_assets f
    JOIN books_fixed_asset_funding x ON x.asset_id = f.id AND x.replaced_at IS NULL AND x.kind IN ('loan', 'expense')
    LEFT JOIN books_loans l ON l.id = x.loan_id
   WHERE f.landlord_id = NEW.id AND f.voided_at IS NULL
     AND (f.acquired_on < NEW.books_start_date OR l.start_date < NEW.books_start_date)
   ORDER BY f.acquired_on, f.id
   LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'Your books cannot start on %: the fixed asset "%" (bought on %) was paid for in part by %, which would then be before your books start, so part of its cost would count twice. Change where that asset''s money came from first.',
      NEW.books_start_date, a.asset_name, a.acquired_on,
      CASE WHEN a.loan_name IS NOT NULL THEN format('the loan "%s" (made on %s)', a.loan_name, a.start_date) ELSE 'an expense' END
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: books_transactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.books_transactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    landlord_id uuid,
    date date NOT NULL,
    description text NOT NULL,
    amount numeric(12,2) NOT NULL,
    type character varying(20) NOT NULL,
    category character varying(100),
    account_id uuid,
    reference text,
    reconciled boolean DEFAULT false,
    reconciled_at timestamp with time zone,
    source character varying(30) DEFAULT 'manual'::character varying,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    business_id uuid,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    migrated_expense_id uuid,
    migrated_other_income_id uuid,
    migrated_at timestamp with time zone,
    CONSTRAINT books_transactions_one_owner CHECK ((num_nonnulls(landlord_id, business_id) <= 1))
);


--
-- Name: COLUMN books_transactions.migrated_expense_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.books_transactions.migrated_expense_id IS '10/12 (Nic, L5): the expense this money-out transaction became. The transaction stays as it was, read only.';


--
-- Name: COLUMN books_transactions.migrated_other_income_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.books_transactions.migrated_other_income_id IS '10/12 (Nic, L5): the other income this money-in transaction became. The transaction stays as it was, read only.';


--
-- Name: books_transaction_moved_follows(public.books_transactions, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.books_transaction_moved_follows(t public.books_transactions, removed boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  cat uuid;
  words text := concat_ws(' — ', NULLIF(btrim(t.description), ''), NULLIF(btrim(t.reference), ''));
BEGIN
  IF t.migrated_expense_id IS NOT NULL THEN
    IF removed OR t.deleted_at IS NOT NULL OR t.type <> 'expense' OR t.amount = 0 THEN
      UPDATE landlord_expenses SET status = 'voided', voided_at = now(), updated_at = now()
       WHERE id = t.migrated_expense_id AND status = 'active';
      IF NOT removed THEN
        UPDATE books_transactions
           SET migrated_expense_id = NULL, migrated_at = CASE WHEN migrated_other_income_id IS NULL THEN NULL ELSE migrated_at END
         WHERE id = t.id;
      END IF;
    ELSE
      cat := books_category_for_row(t.landlord_id, 'expense', t.category, t.account_id, t.date);
      UPDATE landlord_expenses
         SET amount = abs(t.amount), expense_date = t.date, description = words,
             category = books_legacy_expense_key(cat), category_id = cat, updated_at = now()
       WHERE id = t.migrated_expense_id AND status = 'active'
         AND (amount, expense_date, description, category_id) IS DISTINCT FROM (abs(t.amount), t.date, words, cat);
      UPDATE landlord_expense_payments
         SET amount = abs(t.amount), paid_on = t.date, updated_at = now()
       WHERE expense_id = t.migrated_expense_id AND voided_at IS NULL AND source = 'migrated'
         AND (amount, paid_on) IS DISTINCT FROM (abs(t.amount), t.date);
    END IF;
  END IF;
  IF t.migrated_other_income_id IS NOT NULL THEN
    IF removed OR t.deleted_at IS NOT NULL OR t.type <> 'income' OR t.amount = 0 THEN
      UPDATE landlord_other_income SET status = 'voided', voided_at = now(), updated_at = now()
       WHERE id = t.migrated_other_income_id AND status = 'active';
      IF NOT removed THEN
        UPDATE books_transactions
           SET migrated_other_income_id = NULL, migrated_at = CASE WHEN migrated_expense_id IS NULL THEN NULL ELSE migrated_at END
         WHERE id = t.id;
      END IF;
    ELSE
      cat := books_category_for_row(t.landlord_id, 'income', t.category, t.account_id, t.date);
      UPDATE landlord_other_income
         SET amount = abs(t.amount), income_date = t.date, description = words,
             category = COALESCE((SELECT c.system_key FROM books_categories c WHERE c.id = cat), 'other'), category_id = cat,
             updated_at = now()
       WHERE id = t.migrated_other_income_id AND status = 'active'
         AND (amount, income_date, description, category_id) IS DISTINCT FROM (abs(t.amount), t.date, words, cat);
    END IF;
  END IF;
END $$;


--
-- Name: cancel_unsigned_sale_on_void(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_unsigned_sale_on_void() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  buyer_signed boolean;
BEGIN
  IF NEW.status = 'voided' AND OLD.status IS DISTINCT FROM 'voided' THEN
    PERFORM 1 FROM home_sale_contracts
      WHERE purchase_document_id = NEW.id AND status IN ('pending_signature', 'active')
      FOR UPDATE;

    SELECT EXISTS (
      SELECT 1 FROM lease_document_signers s
       WHERE s.document_id = NEW.id AND s.signed_at IS NOT NULL
         AND s.role NOT IN ('landlord', 'witness')) INTO buyer_signed;

    IF NOT buyer_signed AND EXISTS (
      SELECT 1 FROM home_sale_contracts c
        JOIN home_sale_installments i ON i.contract_id = c.id
        JOIN payments p ON p.home_sale_installment_id = i.id
       WHERE c.purchase_document_id = NEW.id AND c.status = 'active'
         AND p.status IN ('pending', 'failed')) THEN
      RAISE EXCEPTION 'The sale on installment contract % still has home payments on the buyer''s bill. Void it through lib/voidDocument, which takes them off first.', NEW.id
        USING ERRCODE = 'check_violation';
    END IF;

    UPDATE home_sale_contracts
       SET status = 'cancelled', cancelled_at = COALESCE(cancelled_at, now()), updated_at = now()
     WHERE purchase_document_id = NEW.id
       AND (status = 'pending_signature' OR (status = 'active' AND NOT buyer_signed));
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: credit_remaining_moves_by_ledger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.credit_remaining_moves_by_ledger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- current_setting(..., true) is NULL when never set in this session: read
  -- through COALESCE so NULL means "off".
  IF COALESCE(current_setting('gam.credit_ledger', true), '') = 'on'
     OR COALESCE(current_setting('gam.credit_backfill', true), '') = 'on' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' AND NEW.amount_remaining <> NEW.amount_original THEN
    RAISE EXCEPTION 'A new credit starts whole' USING ERRCODE = '23514';
  ELSIF TG_OP = 'UPDATE' AND NEW.amount_remaining IS DISTINCT FROM OLD.amount_remaining THEN
    RAISE EXCEPTION 'Credit balance moves only through credit_uses' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION credit_remaining_moves_by_ledger(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.credit_remaining_moves_by_ledger() IS 'S655 C0: amount_remaining on both credit tables moves only through credit_uses (trg_credit_uses_apply) or the deploy backfill; a new credit starts whole.';


--
-- Name: credit_uses_apply(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.credit_uses_apply() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  -- current_setting(..., true) is NULL when the setting was never made in this
  -- session, so the switch is read through COALESCE: NULL must mean "off".
  switch_on      boolean := COALESCE(current_setting('gam.credit_backfill', true), '') = 'on';
  backfill       boolean := switch_on AND NEW.source = 'backfill';
  live_before    boolean := false;
  applied_before boolean := false;
  live_after     boolean;
  delta          numeric(12,2) := 0;
  pay            record;
  cr             record;
  lease_owner    uuid;
  covered        numeric(12,2);
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- What a use IS never changes: its credit, its target, its amount, its
    -- month, its source, who wrote it and when.
    IF NEW.amount <> OLD.amount
       OR NEW.deposit_return_id   IS DISTINCT FROM OLD.deposit_return_id
       OR NEW.payment_reversal_id IS DISTINCT FROM OLD.payment_reversal_id
       OR NEW.tenant_credit_id    IS DISTINCT FROM OLD.tenant_credit_id
       OR NEW.prepaid_credit_id   IS DISTINCT FROM OLD.prepaid_credit_id
       OR NEW.remittance_id       IS DISTINCT FROM OLD.remittance_id
       OR NEW.source <> OLD.source
       OR NEW.created_by IS DISTINCT FROM OLD.created_by
       OR NEW.held_at <> OLD.held_at
       OR NEW.lease_id <> OLD.lease_id OR NEW.billing_month <> OLD.billing_month THEN
      RAISE EXCEPTION 'A credit use is a record: only its status moves' USING ERRCODE = '23514';
    END IF;
    -- The one other change: the FK's ON DELETE SET NULL on a released use (its
    -- unpaid charge was deleted). Nothing else may move with it.
    IF NEW.payment_id IS DISTINCT FROM OLD.payment_id THEN
      IF OLD.status = 'released' AND NEW.status = 'released'
         AND OLD.payment_id IS NOT NULL AND NEW.payment_id IS NULL
         AND NEW.applied_at     IS NOT DISTINCT FROM OLD.applied_at
         AND NEW.released_at    IS NOT DISTINCT FROM OLD.released_at
         AND NEW.release_reason IS NOT DISTINCT FROM OLD.release_reason THEN
        RETURN NEW;
      END IF;
      RAISE EXCEPTION 'A credit use is a record: only its status moves' USING ERRCODE = '23514';
    END IF;
    -- The stamps are history: when it was used, and when and why it was given
    -- back or undone. Deposit interest counts as income on the day it is used,
    -- so moving applied_at would rewrite a report. Writing the same status again
    -- changes nothing, and may not touch a stamp either.
    IF NEW.status = OLD.status THEN
      IF NEW.applied_at        IS DISTINCT FROM OLD.applied_at
         OR NEW.released_at    IS DISTINCT FROM OLD.released_at
         OR NEW.release_reason IS DISTINCT FROM OLD.release_reason THEN
        RAISE EXCEPTION 'A credit use is a record: only its status moves' USING ERRCODE = '23514';
      END IF;
      RETURN NEW;
    END IF;
    IF NOT (   (OLD.status = 'held'    AND NEW.status IN ('applied','released'))
            OR (OLD.status = 'applied' AND NEW.status = 'reversed')
            OR (OLD.status = 'applied' AND NEW.status = 'released' AND NEW.release_reason = 'stay_shortened')
            OR (OLD.status = 'applied' AND NEW.status = 'released' AND NEW.release_reason = 'late_fee_credit_withdrawn')
            -- 10/18 (Nic): "we need to undo credit, but no undoing payments
            -- that were actually real money handed over." A credit the
            -- landlord gave, taken back whole: what it paid comes back off
            -- every bill it paid (services/creditUse undoIssuedCredit).
            OR (OLD.status = 'applied' AND NEW.status = 'released' AND NEW.release_reason = 'credit_undone')) THEN
      RAISE EXCEPTION 'A credit use cannot go from % to %', OLD.status, NEW.status USING ERRCODE = '23514';
    END IF;
    -- Spent credit given back because a shortened stay no longer has the nights
    -- it paid (decisions #30 / #35.3): only credit the landlord issued, on rent.
    -- Deposit interest and paid-ahead money are the guest's money: what a
    -- shortened stay no longer owes of them is banked as money paid ahead.
    IF OLD.status = 'applied' AND NEW.status = 'released' AND NEW.release_reason = 'stay_shortened'
       AND (NEW.tenant_credit_id IS NULL OR NEW.payment_id IS NULL
            OR (SELECT tc.category FROM tenant_credits tc WHERE tc.id = NEW.tenant_credit_id) = 'deposit_interest'
            OR (SELECT p.type FROM payments p WHERE p.id = NEW.payment_id) IS DISTINCT FROM 'rent') THEN
      RAISE EXCEPTION 'Only credit the landlord issued, spent on rent, comes back when a stay is shortened'
        USING ERRCODE = '23514';
    END IF;
    -- 10/6 (Nic): a late-fee credit taken back — only the credit GAM wrote to
    -- net out a never-owed late fee (category late_fee_refund, source
    -- late_fee_credit, on a late_fee row): an Undo of the bank match that
    -- credited it, or the landlord deleting that fee in the onboarding month.
    IF OLD.status = 'applied' AND NEW.status = 'released' AND NEW.release_reason = 'late_fee_credit_withdrawn'
       AND (NEW.tenant_credit_id IS NULL OR NEW.payment_id IS NULL OR NEW.source <> 'late_fee_credit'
            OR (SELECT tc.category FROM tenant_credits tc WHERE tc.id = NEW.tenant_credit_id) IS DISTINCT FROM 'late_fee_refund'
            OR (SELECT p.type FROM payments p WHERE p.id = NEW.payment_id) IS DISTINCT FROM 'late_fee') THEN
      RAISE EXCEPTION 'Only a late-fee credit on its own late fee is taken back this way'
        USING ERRCODE = '23514';
    END IF;
    -- 10/18 (Nic): a credit the landlord gave, taken back because it was
    -- typed by mistake — only a credit HE TYPED (issued_by_landlord: never
    -- deposit interest, which the tenant is owed by law; never money the
    -- tenant paid ahead; and never a credit GAM wrote itself to cancel or
    -- refund a fee, which is not his to take back), and only off a bill. The
    -- route refuses it the moment real money is on that bill
    -- (routes/tenantCredits), and the whole credit comes back or none of it
    -- does.
    IF OLD.status = 'applied' AND NEW.status = 'released' AND NEW.release_reason = 'credit_undone'
       AND (NEW.tenant_credit_id IS NULL OR NEW.payment_id IS NULL
            OR NOT COALESCE((SELECT tc.issued_by_landlord FROM tenant_credits tc
                              WHERE tc.id = NEW.tenant_credit_id), false)
            OR (SELECT tc.category FROM tenant_credits tc WHERE tc.id = NEW.tenant_credit_id) = 'deposit_interest') THEN
      RAISE EXCEPTION 'Only a credit the landlord typed himself, spent on a bill, is taken back this way'
        USING ERRCODE = '23514';
    END IF;
    -- Undoing a spend keeps the day it was spent.
    IF OLD.status = 'applied' AND NEW.applied_at IS DISTINCT FROM OLD.applied_at THEN
      RAISE EXCEPTION 'A credit use keeps the day it was used' USING ERRCODE = '23514';
    END IF;
    -- Lock order, the same as an insert: the charge first, then the credit.
    -- The issued-credit total below is then summed after every other writer of
    -- this charge has committed. (Summed by a statement that started before
    -- waiting on the charge, it would keep its old view of the uses and drop
    -- one committed meanwhile.)
    IF NEW.payment_id IS NOT NULL THEN
      PERFORM 1 FROM payments WHERE id = NEW.payment_id FOR UPDATE;
    END IF;
    live_before    := OLD.status IN ('held','applied');
    applied_before := OLD.status = 'applied';
  ELSE
    IF NEW.status NOT IN ('held','applied') THEN
      RAISE EXCEPTION 'A credit use starts held or applied' USING ERRCODE = '23514';
    END IF;
    -- The backfill source exists only for the one deploy backfill, which turns
    -- the switch on for its own transaction. Anything else using it is a bug.
    IF NEW.source = 'backfill' AND NOT switch_on THEN
      RAISE EXCEPTION 'Source backfill is only for the deploy backfill (gam.credit_backfill)'
        USING ERRCODE = '23514';
    END IF;
    IF NEW.payment_id IS NOT NULL THEN
      -- Lock the charge so two writers cannot both pass the coverage check.
      SELECT p.lease_id, p.tenant_id, p.type, p.status, p.revenue_owner, p.entry_description,
             p.lease_fee_id, p.work_trade_suspended_at, p.reversal_id, p.unit_id, p.amount,
             p.stripe_payment_intent_id
        INTO pay FROM payments p WHERE p.id = NEW.payment_id FOR UPDATE;
      -- Credit pays only a charge still owed: pending with no Stripe intent, or
      -- failed. A pending charge that already carries an intent may have money
      -- on its way (the same rule as payableRowSql), so it takes no use. A
      -- charge whose money is in flight (processing) takes only the HELD use its
      -- own Stripe charge writes as it puts the charge in flight: the use's
      -- remittance must carry the charge's own intent (so a path that stamps the
      -- charge first stamps its remittance with the intent before holding
      -- credit). Any other use would let the credit and that money both pay the
      -- row. This is the backstop for payableRowSql and creditEligibleRowSql
      -- (services/moneyPredicates.ts), which the app checks first.
      IF NOT backfill
         AND NOT ((pay.status = 'pending' AND pay.stripe_payment_intent_id IS NULL)
                  OR pay.status = 'failed'
                  OR (pay.status = 'processing' AND NEW.status = 'held'
                      AND EXISTS (SELECT 1 FROM tenant_remittances r
                                   WHERE r.id = NEW.remittance_id
                                     AND r.stripe_payment_intent_id = pay.stripe_payment_intent_id))) THEN
        RAISE EXCEPTION 'Charge % is already paid or being paid; credit cannot pay it again', NEW.payment_id
          USING ERRCODE = '23514';
      END IF;
      -- Eligibility (shelved cases 2, 3, 4; reopened rows; move-out rows).
      -- Mirrored by creditEligibleRowSql in apps/api/src/services/moneyPredicates.ts
      -- (and, for a reopened row, creditEligibleRowForCreditSql): a row a
      -- dispute reopened (reversal_id) takes only the paid-ahead credit that
      -- same dispute gave back — the credit whose spend on the disputed
      -- original it undid ('reversed') — decisions #48.7.
      IF pay.revenue_owner IS DISTINCT FROM 'landlord'
         -- 10/26 (Nic): a tenant's OWN overpayment may pay their trailer
         -- payment. Kim Bowman paid $550 against $639.60; it settled rent,
         -- water and the late fee exactly, and the $10.40 left over became
         -- paid-ahead credit that could never touch the $100 home payment he
         -- still owed. The net was right and the money was stuck.
         --
         -- Scoped to PAID-AHEAD credit (NEW.prepaid_credit_id): it is his
         -- money, against his own bill. Credit the landlord ISSUED and
         -- work-trade credit stay barred — hours worked and a goodwill credit
         -- do not buy somebody a trailer (the same rule that keeps work trade
         -- off a home payment). FLEXPAY stays barred to every kind: that is
         -- GAM's own collection, not a landlord charge.
         OR NOT (pay.type IN ('rent','utility','late_fee','fee')
                 OR (pay.type = 'home_payment' AND NEW.prepaid_credit_id IS NOT NULL))
         OR pay.entry_description = 'FLEXPAY'
         OR (pay.entry_description = 'HOMEPMT' AND NEW.prepaid_credit_id IS NULL)
         OR (pay.entry_description = 'DEPOSIT' AND pay.lease_fee_id IS NULL)
         OR pay.work_trade_suspended_at IS NOT NULL
         OR (pay.reversal_id IS NOT NULL AND NOT (
               NEW.prepaid_credit_id IS NOT NULL AND EXISTS (
                 SELECT 1 FROM payment_reversals dg_r
                   JOIN credit_uses dg_u ON dg_u.payment_id = dg_r.payment_id
                  WHERE dg_r.id = pay.reversal_id AND dg_u.status = 'reversed'
                    AND dg_u.prepaid_credit_id = NEW.prepaid_credit_id)))
         OR pay.unit_id IS NULL
         OR pay.lease_id IS DISTINCT FROM NEW.lease_id THEN
        RAISE EXCEPTION 'Credit cannot pay charge % (not an eligible landlord charge on lease %)',
          NEW.payment_id, NEW.lease_id USING ERRCODE = '23514';
      END IF;
      -- One payment at a time. Credit a card or bank payment set aside on this
      -- charge stays that payment's until it is given back; a failed charge
      -- whose retry is still scheduled keeps it. Any other use, held or spent,
      -- would let the retry's money and this credit both pay the row. Paying
      -- over a scheduled retry releases that credit first
      -- (creditUse.supersedeScheduledRetry), so a correct path is never refused.
      IF EXISTS (SELECT 1 FROM credit_uses u
                  WHERE u.payment_id = NEW.payment_id AND u.id <> NEW.id
                    AND u.status = 'held'
                    AND u.remittance_id IS DISTINCT FROM NEW.remittance_id) THEN
        RAISE EXCEPTION 'Charge % still has credit set aside by another payment; release the scheduled retry''s credit first',
          NEW.payment_id USING ERRCODE = '23514';
      END IF;
      SELECT COALESCE(SUM(u.amount), 0) INTO covered FROM credit_uses u
       WHERE u.payment_id = NEW.payment_id AND u.status IN ('held','applied');
      IF covered > pay.amount THEN
        RAISE EXCEPTION 'Charge % would be paid twice by credit', NEW.payment_id USING ERRCODE = '23514';
      END IF;
      -- decisions #48.7: the dispute's own credit pays its reopened row only up
      -- to what the dispute gave back of it (the undone spend), never more.
      IF pay.reversal_id IS NOT NULL
         AND (SELECT COALESCE(SUM(u.amount), 0) FROM credit_uses u
               WHERE u.payment_id = NEW.payment_id AND u.prepaid_credit_id = NEW.prepaid_credit_id
                 AND u.status IN ('held','applied'))
           > (SELECT COALESCE(SUM(dg_u.amount), 0) FROM payment_reversals dg_r
                JOIN credit_uses dg_u ON dg_u.payment_id = dg_r.payment_id
               WHERE dg_r.id = pay.reversal_id AND dg_u.status = 'reversed'
                 AND dg_u.prepaid_credit_id = NEW.prepaid_credit_id) THEN
        RAISE EXCEPTION 'Charge % was reopened by a dispute: its credit pays it only up to what the dispute gave back',
          NEW.payment_id USING ERRCODE = '23514';
      END IF;
    END IF;
    IF NEW.deposit_return_id IS NOT NULL
       AND (SELECT dr.lease_id FROM deposit_returns dr WHERE dr.id = NEW.deposit_return_id)
           IS DISTINCT FROM NEW.lease_id THEN
      RAISE EXCEPTION 'Paid-ahead money joins only its own lease''s move-out' USING ERRCODE = '23514';
    END IF;
    IF NEW.prepaid_credit_id IS NOT NULL THEN
      SELECT c.lease_id, c.voided_at INTO cr FROM lease_prepaid_credits c
       WHERE c.id = NEW.prepaid_credit_id FOR UPDATE;
      IF cr.lease_id IS DISTINCT FROM NEW.lease_id THEN
        RAISE EXCEPTION 'Paid-ahead money pays only its own lease' USING ERRCODE = '23514';
      END IF;
      IF cr.voided_at IS NOT NULL THEN
        RAISE EXCEPTION 'A withdrawn credit cannot be used' USING ERRCODE = '23514';
      END IF;
    ELSE
      IF NEW.payment_id IS NULL AND NEW.deposit_return_id IS NULL THEN
        RAISE EXCEPTION 'An issued credit pays only a charge' USING ERRCODE = '23514';
      END IF;
      SELECT tc.lease_id, tc.landlord_id, tc.tenant_id, tc.status, tc.category INTO cr
        FROM tenant_credits tc WHERE tc.id = NEW.tenant_credit_id FOR UPDATE;
      IF cr.status IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION 'A voided credit cannot be used' USING ERRCODE = '23514';
      END IF;
      -- Step 9 review (fix pass 2): the one credit a move-out takes besides
      -- paid-ahead money is deposit interest on that lease (owed back with the
      -- deposit). Landlord-issued credit never joins a move-out.
      IF NEW.deposit_return_id IS NOT NULL
         AND (cr.category IS DISTINCT FROM 'deposit_interest' OR cr.lease_id IS DISTINCT FROM NEW.lease_id) THEN
        RAISE EXCEPTION 'Only deposit interest on this lease joins its move-out' USING ERRCODE = '23514';
      END IF;
      SELECT l.landlord_id INTO lease_owner FROM leases l WHERE l.id = NEW.lease_id;
      -- Every comparison below is NULL-safe: a missing tenant or landlord on
      -- either side refuses the use, it never lets it through.
      --
      -- 10/18 (Nic): "if a person has two households, right, two spaces, two
      -- bills for October, they can't pay one for October and then pay that
      -- same one for November. It does need to go on the October bill for the
      -- other spot." A credit the landlord GAVE is the household's: the space
      -- it was issued on records where he gave it, it is not a fence. So it
      -- pays any bill of that person with that company, and the app walks
      -- those bills by DUE DATE, oldest first, across every space
      -- (creditUse.buildCreditPlan). Deposit interest still stays on its own
      -- lease: GAM owes it back with THAT deposit at move-out. Money the
      -- tenant paid ahead stays with the space they paid it for, above.
      IF cr.category = 'deposit_interest' AND cr.lease_id IS NOT NULL THEN
        IF cr.lease_id IS DISTINCT FROM NEW.lease_id THEN
          RAISE EXCEPTION 'Deposit interest belongs to another lease: it goes back with that deposit'
            USING ERRCODE = '23514';
        END IF;
        IF cr.landlord_id IS DISTINCT FROM lease_owner THEN
          RAISE EXCEPTION 'This credit was given by another landlord, not the landlord on this lease'
            USING ERRCODE = '23514';
        END IF;
      ELSIF cr.landlord_id IS DISTINCT FROM lease_owner
         OR NOT (COALESCE(pay.tenant_id = cr.tenant_id, false) OR EXISTS (
                   SELECT 1 FROM lease_tenants lt
                    WHERE lt.lease_id = NEW.lease_id AND lt.tenant_id = cr.tenant_id)) THEN
        RAISE EXCEPTION 'A credit pays only its own tenant''s bills with the landlord who gave it'
          USING ERRCODE = '23514';
      END IF;
    END IF;
  END IF;

  live_after := NEW.status IN ('held','applied');
  -- The deploy backfill records spends that already lowered amount_remaining.
  IF NOT backfill THEN
    IF live_after AND NOT live_before THEN delta := -NEW.amount;
    ELSIF live_before AND NOT live_after THEN delta := NEW.amount;
    END IF;
    IF delta <> 0 THEN
      PERFORM set_config('gam.credit_ledger', 'on', true);
      IF NEW.tenant_credit_id IS NOT NULL THEN
        UPDATE tenant_credits SET amount_remaining = amount_remaining + delta, updated_at = now()
         WHERE id = NEW.tenant_credit_id;
      ELSE
        UPDATE lease_prepaid_credits SET amount_remaining = amount_remaining + delta, updated_at = now()
         WHERE id = NEW.prepaid_credit_id;
      END IF;
      PERFORM set_config('gam.credit_ledger', 'off', true);
    END IF;
  END IF;

  -- The sum of the row's applied landlord-issued uses, recounted only when this
  -- use enters or leaves 'applied' (held and released uses never count). The
  -- charge is locked above on both paths, so this statement's view of the uses
  -- includes every one committed before it.
  IF NEW.tenant_credit_id IS NOT NULL AND NEW.payment_id IS NOT NULL
     AND (NEW.status = 'applied') IS DISTINCT FROM applied_before THEN
    UPDATE payments SET issued_credit_amount = (
      SELECT COALESCE(SUM(u.amount), 0)
        FROM credit_uses u JOIN tenant_credits tc ON tc.id = u.tenant_credit_id
       WHERE u.payment_id = NEW.payment_id AND u.status = 'applied'
         AND tc.category <> 'deposit_interest')
     WHERE id = NEW.payment_id;
  END IF;
  -- Credit given back because a shortened stay no longer has the nights it
  -- paid takes its rent row's amount down with it, in this statement: the row
  -- then asks only what its own money (and any credit still on it) paid, so
  -- that money (amount − issued_credit_amount) never moves, no report or
  -- payout counts the given-back credit as money, and the credit is counted
  -- once, as the guest's saved credit. The caller only notes the change on
  -- the row and its invoice (services/bookingLeaseBilling).
  IF TG_OP = 'UPDATE' AND OLD.status = 'applied' AND NEW.status = 'released' AND NEW.release_reason = 'stay_shortened' THEN
    UPDATE payments SET amount = amount - NEW.amount WHERE id = NEW.payment_id;
  END IF;
  RETURN NEW;
END $_$;


--
-- Name: credit_uses_choice_target_fixed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.credit_uses_choice_target_fixed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Fires only when paid_ahead_choice_id moves (the trigger's WHEN): a use's
  -- target is part of what the use IS (the same rule as refund_part_id).
  RAISE EXCEPTION 'A credit use is a record: only its status moves' USING ERRCODE = '23514';
END $$;


--
-- Name: credit_uses_kept_forever(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.credit_uses_kept_forever() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'Credit uses are kept forever' USING ERRCODE = '23514';
END $$;


--
-- Name: credit_uses_refund_target_fixed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.credit_uses_refund_target_fixed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Fires only when refund_part_id moves (the trigger's WHEN): a use's target
  -- is part of what the use IS, like the other targets credit_uses_apply guards.
  RAISE EXCEPTION 'A credit use is a record: only its status moves' USING ERRCODE = '23514';
END $$;


--
-- Name: email_log_block_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_log_block_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF email_log_is_permanent(OLD.category) THEN
    RAISE EXCEPTION
      'email_send_log row % is correspondence (category=%) and cannot be deleted — the log is the log',
      OLD.id, OLD.category;
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: email_log_freeze_content(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_log_freeze_content() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF email_log_is_permanent(OLD.category) THEN
    IF NEW.to_email   IS DISTINCT FROM OLD.to_email
    OR NEW.subject    IS DISTINCT FROM OLD.subject
    OR NEW.body_text  IS DISTINCT FROM OLD.body_text
    OR NEW.category   IS DISTINCT FROM OLD.category
    OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
      RAISE EXCEPTION
        'email_send_log row % is correspondence — recipient, subject, body, category and timestamp are frozen',
        OLD.id;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: email_log_is_permanent(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_log_is_permanent(p_category text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT COALESCE(p_category, '') IN (
    'support_message',            -- an admin wrote this by hand
    'landlord_welcome_outreach'   -- our first reach-out to a new signup
  )
$$;


--
-- Name: enforce_meter_utility_retype(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_meter_utility_retype() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_unit text;
BEGIN
  IF NEW.utility_type IS DISTINCT FROM OLD.utility_type THEN
    SELECT u.unit_number INTO v_unit
      FROM utility_meter_units mu
      JOIN units u ON u.id = mu.unit_id
     WHERE mu.meter_id = NEW.id
       AND EXISTS (
         SELECT 1 FROM utility_meter_units mu2
           JOIN utility_meters m2 ON m2.id = mu2.meter_id
          WHERE mu2.unit_id = mu.unit_id
            AND m2.id <> NEW.id
            AND m2.utility_type = NEW.utility_type)
     LIMIT 1;
    IF v_unit IS NOT NULL THEN
      RAISE EXCEPTION
        'Unit % is already on another % meter. Changing this meter to % would put that unit on two.',
        v_unit, NEW.utility_type, NEW.utility_type
        USING ERRCODE = 'unique_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_one_meter_per_unit_utility(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_one_meter_per_unit_utility() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_utility text;
  v_conflict text;
BEGIN
  SELECT utility_type INTO v_utility FROM utility_meters WHERE id = NEW.meter_id;
  SELECT m.label INTO v_conflict
    FROM utility_meter_units mu
    JOIN utility_meters m ON m.id = mu.meter_id
   WHERE mu.unit_id = NEW.unit_id
     AND m.id <> NEW.meter_id
     AND m.utility_type = v_utility
   LIMIT 1;
  IF v_conflict IS NOT NULL THEN
    RAISE EXCEPTION
      'This unit is already on the % meter "%". A unit can only be on one % meter — remove it from that one first.',
      v_utility, v_conflict, v_utility
      USING ERRCODE = 'unique_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: ensure_pm_owner_relationship(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_pm_owner_relationship() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.pm_company_id IS NOT NULL AND NEW.landlord_id IS NOT NULL THEN
    INSERT INTO pm_owner_relationships (pm_company_id, landlord_id)
    VALUES (NEW.pm_company_id, NEW.landlord_id)
    ON CONFLICT (pm_company_id, landlord_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_invoice_late_fee_subtotal_rollup_single(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_invoice_late_fee_subtotal_rollup_single(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE invoices
  SET subtotal_late_fees = COALESCE((
    SELECT SUM(amount)
    FROM payments
    WHERE invoice_id = p_invoice_id
      AND type = 'late_fee'
      AND status IN ('pending', 'processing', 'settled')
  ), 0)
  WHERE id = p_invoice_id;
END;
$$;


--
-- Name: fn_invoice_late_fee_subtotal_rollup_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_invoice_late_fee_subtotal_rollup_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.type = 'late_fee' AND NEW.invoice_id IS NOT NULL THEN
      PERFORM fn_invoice_late_fee_subtotal_rollup_single(NEW.invoice_id);
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.type = 'late_fee' AND OLD.invoice_id IS NOT NULL THEN
      PERFORM fn_invoice_late_fee_subtotal_rollup_single(OLD.invoice_id);
    END IF;
    IF NEW.type = 'late_fee' AND NEW.invoice_id IS NOT NULL
       AND (OLD.type IS DISTINCT FROM 'late_fee'
            OR OLD.invoice_id IS DISTINCT FROM NEW.invoice_id) THEN
      PERFORM fn_invoice_late_fee_subtotal_rollup_single(NEW.invoice_id);
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.type = 'late_fee' AND OLD.invoice_id IS NOT NULL THEN
      PERFORM fn_invoice_late_fee_subtotal_rollup_single(OLD.invoice_id);
    END IF;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: fn_invoice_status_rollup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_invoice_status_rollup() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (TG_OP = 'DELETE') THEN
    IF OLD.invoice_id IS NOT NULL THEN
      PERFORM fn_invoice_status_rollup_single(OLD.invoice_id);
    END IF;
    RETURN OLD;
  END IF;

  IF (TG_OP = 'UPDATE' AND OLD.invoice_id IS DISTINCT FROM NEW.invoice_id
      AND OLD.invoice_id IS NOT NULL) THEN
    PERFORM fn_invoice_status_rollup_single(OLD.invoice_id);
  END IF;

  IF NEW.invoice_id IS NOT NULL THEN
    PERFORM fn_invoice_status_rollup_single(NEW.invoice_id);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_invoice_status_rollup_single(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_invoice_status_rollup_single(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_total_children   INTEGER;
  v_settled_children INTEGER;
  v_current_status   TEXT;
  v_new_status       TEXT;
BEGIN
  SELECT status INTO v_current_status FROM invoices WHERE id = p_invoice_id;
  IF v_current_status = 'void' THEN
    RETURN;
  END IF;

  -- 10/12 (Nic): a voided line (decisions #48.5) is owed by nobody and paid
  -- by nothing — it is a record, not a line of the bill, and is left out
  -- exactly as the deleted line it replaces was.
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE status = 'settled')
  INTO v_total_children, v_settled_children
  FROM payments
  WHERE invoice_id = p_invoice_id
    AND status <> 'voided';

  IF v_total_children = 0 THEN
    v_new_status := 'pending';
  ELSIF v_settled_children = 0 THEN
    v_new_status := 'pending';
  ELSIF v_settled_children = v_total_children THEN
    v_new_status := 'settled';
  ELSE
    v_new_status := 'partial';
  END IF;

  IF v_new_status IS DISTINCT FROM v_current_status THEN
    UPDATE invoices
    SET status = v_new_status, updated_at = now()
    WHERE id = p_invoice_id;
  END IF;
END;
$$;


--
-- Name: fn_invoices_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_invoices_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: fn_lease_unit_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_lease_unit_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO lease_unit_history (lease_id, unit_id, effective_from)
    VALUES (NEW.id, NEW.unit_id, NEW.start_date);
    RETURN NEW;
  END IF;

  IF NEW.unit_id IS DISTINCT FROM OLD.unit_id THEN
    -- The move date is carried on the lease row by the move endpoint; a bare
    -- UPDATE with no date falls back to today, which is the honest default for
    -- somebody correcting a mistake rather than recording a move.
    UPDATE lease_unit_history
       SET effective_to = COALESCE(NEW.unit_moved_on, CURRENT_DATE)
     WHERE lease_id = NEW.id AND effective_to IS NULL;
    INSERT INTO lease_unit_history (lease_id, unit_id, effective_from)
    VALUES (NEW.id, NEW.unit_id, COALESCE(NEW.unit_moved_on, CURRENT_DATE));
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_pos_items_log_price_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_pos_items_log_price_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  actor_id uuid;
BEGIN
  IF NEW.sell_price IS DISTINCT FROM OLD.sell_price
     OR NEW.cost_price IS DISTINCT FROM OLD.cost_price THEN
    -- Read actor from session GUC if set by the route layer; ignore
    -- error if unset (direct SQL writes log with NULL changed_by).
    BEGIN
      actor_id := current_setting('gam.user_id', true)::uuid;
    EXCEPTION WHEN OTHERS THEN
      actor_id := NULL;
    END;

    INSERT INTO pos_price_history
      (item_id, old_price, new_price, old_cost, new_cost, changed_by)
    VALUES
      (NEW.id, OLD.sell_price, NEW.sell_price, OLD.cost_price, NEW.cost_price, actor_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_pos_tax_rates_journal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_pos_tax_rates_journal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  actor uuid;
  ll uuid; rid uuid; pid uuid; nm text;
  o_rate numeric(7,4); n_rate numeric(7,4);
  o_active boolean;    n_active boolean;
  o_stays boolean;     n_stays boolean;
  o_reach jsonb;       n_reach jsonb;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- The same row written back is not a change (keeps the journal readable).
    IF to_jsonb(OLD) = to_jsonb(NEW) THEN RETURN NULL; END IF;
  END IF;
  BEGIN
    actor := current_setting('gam.user_id', true)::uuid;
  EXCEPTION WHEN OTHERS THEN
    actor := NULL;
  END;
  IF TG_OP <> 'INSERT' THEN
    ll := OLD.landlord_id; rid := OLD.id; pid := OLD.property_id; nm := OLD.name;
    o_rate := OLD.rate; o_active := OLD.is_active; o_stays := OLD.on_stays;
    o_reach := jsonb_build_object('appliesTo', to_jsonb(OLD.applies_to),
                                  'categoryIds', to_jsonb(OLD.category_ids),
                                  'itemIds', to_jsonb(OLD.item_ids));
  END IF;
  IF TG_OP <> 'DELETE' THEN
    ll := NEW.landlord_id; rid := NEW.id; pid := NEW.property_id; nm := NEW.name;
    n_rate := NEW.rate; n_active := NEW.is_active; n_stays := NEW.on_stays;
    n_reach := jsonb_build_object('appliesTo', to_jsonb(NEW.applies_to),
                                  'categoryIds', to_jsonb(NEW.category_ids),
                                  'itemIds', to_jsonb(NEW.item_ids));
  END IF;
  INSERT INTO pos_tax_rate_changes
    (landlord_id, rate_id, property_id, name,
     old_rate, new_rate, old_is_active, new_is_active, old_on_stays, new_on_stays,
     old_reach, new_reach, changed_by)
  VALUES (ll, rid, pid, nm, o_rate, n_rate, o_active, n_active, o_stays, n_stays,
          o_reach, n_reach, actor);
  RETURN NULL;
END $$;


--
-- Name: fn_pos_tax_rates_sync_stay_tax(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_pos_tax_rates_sync_stay_tax() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE ll uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN ll := OLD.landlord_id; ELSE ll := NEW.landlord_id; END IF;
  UPDATE properties p
     SET short_term_tax_rate = public.property_stay_tax_pct(p.id)
   WHERE p.landlord_id = ll
     AND p.short_term_tax_rate IS DISTINCT FROM public.property_stay_tax_pct(p.id);
  RETURN NULL;
END $$;


--
-- Name: fn_properties_follow_stay_tax(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_properties_follow_stay_tax() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pos_tax_rates r
                  WHERE r.landlord_id = NEW.landlord_id AND r.is_active AND r.on_stays
                    AND (r.property_id = NEW.id OR r.property_id IS NULL)) THEN
    RETURN NULL;
  END IF;
  UPDATE properties p
     SET short_term_tax_rate = public.property_stay_tax_pct(p.id)
   WHERE p.id = NEW.id
     AND p.short_term_tax_rate IS DISTINCT FROM public.property_stay_tax_pct(p.id);
  RETURN NULL;
END $$;


--
-- Name: fn_space_rent_carryforward_assumed_by(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_space_rent_carryforward_assumed_by() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE cf_id uuid;
BEGIN
  UPDATE space_rent_carryforwards
     SET assumed_tenant_id = NEW.tenant_id, updated_at = now()
   WHERE assumed_lease_id = NEW.lease_id
     AND assumed_tenant_id IS NULL
     AND status = 'open'
  RETURNING id INTO cf_id;
  IF cf_id IS NULL THEN RETURN NULL; END IF;

  UPDATE payments
     SET tenant_id = NEW.tenant_id
   WHERE space_carryforward_id = cf_id
     AND type = 'carried_balance'
     AND status IN ('pending', 'failed');
  RETURN NULL;
END $$;


--
-- Name: fn_space_rent_carryforward_follows_the_space(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_space_rent_carryforward_follows_the_space() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE cf_id uuid;
BEGIN
  IF NEW.status NOT IN ('pending', 'active') THEN RETURN NULL; END IF;
  SELECT c.id INTO cf_id
    FROM space_rent_carryforwards c
    JOIN units u ON u.id = c.unit_id
   WHERE c.unit_id = NEW.unit_id
     AND c.status = 'open'
     AND c.origin_lease_id <> NEW.id
     AND c.landlord_id = NEW.landlord_id
     AND u.dwelling_ownership = 'tenant'
   LIMIT 1;
  IF cf_id IS NULL THEN RETURN NULL; END IF;

  UPDATE space_rent_carryforwards
     SET assumed_lease_id = NEW.id,
         -- The residents are added to lease_tenants after the lease row, so the
         -- second trigger stamps who took it on, and moves the charge to them.
         assumed_tenant_id = NULL,
         assumed_at = now(),
         updated_at = now()
   WHERE id = cf_id;

  UPDATE payments
     SET lease_id = NEW.id
   WHERE space_carryforward_id = cf_id
     AND type = 'carried_balance'
     AND status IN ('pending', 'failed');

  RETURN NULL;
END $$;


--
-- Name: fn_space_rent_carryforward_rollup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_space_rent_carryforward_rollup() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  cf_id      uuid;
  still_owed numeric;
  paid       numeric;
  taken_off  numeric;
  last_day   date;
  was        text;
  becomes    text;
BEGIN
  cf_id := COALESCE(NEW.space_carryforward_id, OLD.space_carryforward_id);
  IF cf_id IS NULL THEN RETURN NULL; END IF;

  SELECT c.status INTO was FROM space_rent_carryforwards c WHERE c.id = cf_id;
  IF was IS NULL THEN RETURN NULL; END IF;

  SELECT COALESCE(SUM(p.amount) FILTER (WHERE p.status IN ('pending', 'processing', 'failed')), 0),
         COALESCE(SUM(p.amount) FILTER (WHERE p.status IN ('settled', 'paid_via_deposit')), 0),
         COALESCE(SUM(p.amount) FILTER (WHERE p.status = 'voided'), 0),
         MAX((p.settled_at AT TIME ZONE COALESCE(pr.timezone, 'America/Phoenix'))::date)
           FILTER (WHERE p.status IN ('settled', 'paid_via_deposit'))
    INTO still_owed, paid, taken_off, last_day
    FROM payments p
    LEFT JOIN units u     ON u.id = p.unit_id
    LEFT JOIN properties pr ON pr.id = u.property_id
   WHERE p.space_carryforward_id = cf_id
     AND p.type = 'carried_balance';

  becomes := CASE
    -- Taken off by hand (services/spaceRentCarryforward takeOffCarryforward)
    -- and never un-taken-off by a later payment landing.
    WHEN was = 'voided'                THEN 'voided'
    WHEN still_owed > 0                THEN 'open'
    WHEN taken_off > 0                 THEN 'voided'
    WHEN paid > 0                      THEN 'settled'
    -- Nothing owed, nothing paid, nothing written off: a claim whose charge is
    -- gone some other way (a bank return whose money came back off a GAM
    -- balance instead of a new row). Still owed in substance, so still open,
    -- and the landlord can take it off.
    ELSE 'open' END;

  UPDATE space_rent_carryforwards c
     SET settled_amount = paid,
         status = becomes,
         settled_on = CASE WHEN becomes = 'settled' THEN COALESCE(last_day, CURRENT_DATE) END,
         updated_at = now()
   WHERE c.id = cf_id;

  RETURN NULL;
END $$;


--
-- Name: fn_unit_bookings_stamp_cancelled_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_unit_bookings_stamp_cancelled_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'cancelled' AND NEW.cancelled_at IS NULL THEN
    NEW.cancelled_at := NOW();
  ELSIF NEW.status <> 'cancelled' THEN
    NEW.cancelled_at := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_unit_bookings_stamp_stay_tax(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_unit_bookings_stamp_stay_tax() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE pct numeric;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.stay_tax_rate IS NOT NULL THEN RETURN NEW; END IF;
  ELSE
    IF NEW.stay_tax_rate IS DISTINCT FROM OLD.stay_tax_rate THEN RETURN NEW; END IF;
    IF NEW.total_amount IS NOT DISTINCT FROM OLD.total_amount THEN RETURN NEW; END IF;
    IF OLD.stay_tax_rate IS NOT NULL
       AND (OLD.deposit_paid_at IS NOT NULL OR OLD.balance_paid_at IS NOT NULL
            OR EXISTS (SELECT 1 FROM stay_payments sp WHERE sp.booking_id = OLD.id)) THEN
      RETURN NEW;
    END IF;
  END IF;
  SELECT p.short_term_tax_rate INTO pct
    FROM units u JOIN properties p ON p.id = u.property_id
   WHERE u.id = NEW.unit_id;
  NEW.stay_tax_rate := ROUND(COALESCE(pct, 0) / 100, 4);
  RETURN NEW;
END $$;


--
-- Name: fn_unit_number_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_unit_number_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO unit_number_history (unit_id, unit_number, building, effective_from)
    VALUES (NEW.id, NEW.unit_number, NEW.building, COALESCE(NEW.created_at, now()));
    RETURN NEW;
  END IF;

  -- Only a real change of identity opens a new period.
  IF NEW.unit_number IS DISTINCT FROM OLD.unit_number
     OR NEW.building IS DISTINCT FROM OLD.building THEN
    UPDATE unit_number_history
       SET effective_to = now()
     WHERE unit_id = NEW.id AND effective_to IS NULL;
    INSERT INTO unit_number_history (unit_id, unit_number, building, effective_from)
    VALUES (NEW.id, NEW.unit_number, NEW.building, now());
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fold_old_task_list_into_property_lists(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fold_old_task_list_into_property_lists() RETURNS TABLE(folded integer, left_alone integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
    item        record;
    parks       uuid[];
    park        uuid;
    owner_user  uuid;
    line        text;
    repeats     text;
    when_said   text;
    new_line_id uuid;
    n_folded    integer := 0;
    n_left      integer := 0;
BEGIN
    FOR item IN
        SELECT d.id, d.landlord_id, d.title, d.description, d.due_date,
               d.recurrence, d.assigned_to, d.created_at
          FROM daily_tasks d
         -- A done item has nothing left to do, so there is nothing to put on a
         -- checklist; its record stays here, ticked, with who finished it.
         WHERE d.completed = FALSE
           AND d.folded_into_property_task_id IS NULL
         ORDER BY d.created_at, d.id
    LOOP
        park := NULL;

        -- 1. The person it was given to, when they work exactly one of this
        --    company's parks. A worker set to all_properties points at every
        --    park, which points at none of them.
        IF item.assigned_to IS NOT NULL THEN
            SELECT array_agg(DISTINCT s.property_id) INTO parks
              FROM (
                SELECT user_id, landlord_id, unnest(property_ids) AS property_id
                  FROM maintenance_worker_scopes WHERE all_properties = FALSE
                UNION ALL
                SELECT user_id, landlord_id, unnest(property_ids) AS property_id
                  FROM onsite_manager_scopes WHERE all_properties = FALSE
                UNION ALL
                SELECT user_id, landlord_id, unnest(property_ids) AS property_id
                  FROM property_manager_scopes WHERE all_properties = FALSE
              ) s
              JOIN properties p ON p.id = s.property_id AND p.landlord_id = item.landlord_id
             WHERE s.user_id = item.assigned_to
               AND s.landlord_id = item.landlord_id;
            IF parks IS NOT NULL AND array_length(parks, 1) = 1 THEN
                park := parks[1];
            END IF;
        END IF;

        -- 2. The company itself, when it owns one park. Then the line can only
        --    be about that park.
        IF park IS NULL THEN
            SELECT array_agg(p.id) INTO parks
              FROM properties p WHERE p.landlord_id = item.landlord_id;
            IF parks IS NOT NULL AND array_length(parks, 1) = 1 THEN
                park := parks[1];
            END IF;
        END IF;

        IF park IS NULL THEN
            UPDATE daily_tasks
               SET fold_note = 'Left on the old list: nothing on this item names a property, and the '
                               'company it belongs to has more than one. Putting somebody''s job on the '
                               'wrong park is worse than leaving it here, so it was not guessed at.'
             WHERE id = item.id;
            n_left := n_left + 1;
            CONTINUE;
        END IF;

        -- The line, in the words that were typed. Title and detail read as one
        -- sentence because the park's list has no title/detail split: the whole
        -- thing is the task.
        line := btrim(coalesce(item.title, ''));
        IF coalesce(btrim(item.description), '') <> '' THEN
            line := CASE WHEN line = '' THEN btrim(item.description)
                         ELSE line || ' — ' || btrim(item.description) END;
        END IF;
        IF line = '' THEN
            -- The old POST had no title validator, so a wordless row is
            -- possible. There is nothing to put on a checklist.
            UPDATE daily_tasks
               SET fold_note = 'Left on the old list: the item has no words on it, so there is nothing '
                               'to put on a park''s list.'
             WHERE id = item.id;
            n_left := n_left + 1;
            CONTINUE;
        END IF;

        -- The due date and the repeat, said the way a landlord would say them.
        -- Never a raw enum: 'weekly' is not a thing anybody says out loud.
        repeats := CASE item.recurrence
                     WHEN 'none'    THEN NULL
                     WHEN 'daily'   THEN 'every day'
                     WHEN 'weekly'  THEN 'every week'
                     WHEN 'monthly' THEN 'every month'
                     ELSE replace(item.recurrence, '_', ' ')
                   END;
        when_said := NULL;
        IF item.due_date IS NOT NULL AND repeats IS NOT NULL THEN
            when_said := 'was due ' || to_char(item.due_date, 'FMMon FMDD, YYYY')
                         || ' and set to repeat ' || repeats;
        ELSIF item.due_date IS NOT NULL THEN
            when_said := 'was due ' || to_char(item.due_date, 'FMMon FMDD, YYYY');
        ELSIF repeats IS NOT NULL THEN
            when_said := 'was set to repeat ' || repeats;
        END IF;
        IF when_said IS NOT NULL THEN
            line := line || ' (' || when_said || ')';
        END IF;

        -- Whose line it is. The old list was the landlord's own list, so the
        -- folded line is theirs; the person it used to be assigned to is NOT
        -- carried over, because the park's list belongs to the park and not to
        -- anybody (20261022150000: "whoever is there does the next line"). Their
        -- name is still on the row here.
        SELECT l.user_id INTO owner_user FROM landlords l WHERE l.id = item.landlord_id;
        IF owner_user IS NULL THEN
            UPDATE daily_tasks
               SET fold_note = 'Left on the old list: the company that owns it has no owner account to '
                               'put the line under.'
             WHERE id = item.id;
            n_left := n_left + 1;
            CONTINUE;
        END IF;

        -- created_at is carried over, not restamped: these lines were asked for
        -- before today's, and the park's list reads in the order things were
        -- asked for.
        INSERT INTO property_task_list_items (property_id, body, added_by_user_id, created_at)
        VALUES (park, line, owner_user, item.created_at)
        RETURNING id INTO new_line_id;

        -- updated_at is deliberately left alone: a pointer to where the line
        -- went is not the landlord editing their task.
        UPDATE daily_tasks
           SET folded_into_property_task_id = new_line_id,
               fold_note = NULL
         WHERE id = item.id;
        n_folded := n_folded + 1;
    END LOOP;

    RETURN QUERY SELECT n_folded, n_left;
END;
$$;


--
-- Name: FUNCTION fold_old_task_list_into_property_lists(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fold_old_task_list_into_property_lists() IS '10/20 (Nic): moves every still-open item from the retired landlord-wide Tasks list (daily_tasks) onto the park task list it belongs to, and leaves a note on the ones no park could be worked out for. Idempotent — run it again after the old tab stops being offered to catch anything added in between.';


--
-- Name: journal_entries_closed_period_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_entries_closed_period_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  locked_to date;
BEGIN
  IF NEW.landlord_id IS NULL AND NEW.business_id IS NULL THEN
    RETURN NEW;  -- an admin's ownerless entry has no company books to lock
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.date IS NOT DISTINCT FROM OLD.date THEN
    RETURN NEW;  -- the date was written back unchanged
  END IF;
  PERFORM pg_advisory_xact_lock_shared(ledger_owner_lock_key(NEW.landlord_id, NEW.business_id));
  locked_to := ledger_closed_through(NEW.landlord_id, NEW.business_id);
  IF locked_to IS NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.date <= locked_to THEN
    RAISE EXCEPTION 'The books are closed through %. Date the entry after that; it will show as a correction.', locked_to
      USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.date <= locked_to THEN
    RAISE EXCEPTION 'This entry is in a month closed through %; it cannot move out of it.', locked_to
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: journal_entries_number_per_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_entries_number_per_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'journal_entry_number:' || COALESCE(NEW.landlord_id::text, NEW.business_id::text, 'no-owner'), 0));
  SELECT COALESCE(max(je.entry_number), 0) + 1
    INTO NEW.entry_number
    FROM journal_entries je
   WHERE je.landlord_id IS NOT DISTINCT FROM NEW.landlord_id
     AND je.business_id IS NOT DISTINCT FROM NEW.business_id;
  RETURN NEW;
END $$;


--
-- Name: journal_entry_lines_closed_period_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_entry_lines_closed_period_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  e         record;
  locked_to date;
BEGIN
  FOR e IN
    SELECT DISTINCT je.landlord_id, je.business_id, je.date
      FROM journal_entries je
     WHERE je.id IN (CASE WHEN TG_OP <> 'INSERT' THEN OLD.entry_id END, CASE WHEN TG_OP <> 'DELETE' THEN NEW.entry_id END)
       AND (je.landlord_id IS NOT NULL OR je.business_id IS NOT NULL)
  LOOP
    PERFORM pg_advisory_xact_lock_shared(ledger_owner_lock_key(e.landlord_id, e.business_id));
    locked_to := ledger_closed_through(e.landlord_id, e.business_id);
    IF locked_to IS NOT NULL AND e.date <= locked_to THEN
      RAISE EXCEPTION 'This entry is in a month closed through %. Add a new entry dated after it; it will show as a correction.', locked_to
        USING ERRCODE = 'check_violation';
    END IF;
  END LOOP;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;


--
-- Name: journal_entry_lines_control_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_entry_lines_control_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  acct_name text;
BEGIN
  IF EXISTS (SELECT 1 FROM books_account_map m
              WHERE m.account_id = NEW.account_id AND m.map_kind = 'role'
                AND ledger_account_role_is_control(m.map_value)) THEN
    SELECT name INTO acct_name FROM books_accounts WHERE id = NEW.account_id;
    RAISE EXCEPTION '% is kept by GAM from the money records, so it takes no journal lines. Post the adjustment to another account.', acct_name
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: landlord_expense_payments_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landlord_expense_payments_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'A payment is never removed; void it instead.' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.voided_at IS NOT NULL THEN
    RAISE EXCEPTION 'Payment % was voided: it is a record and does not change.', OLD.id USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.expense_id IS DISTINCT FROM OLD.expense_id OR NEW.landlord_id IS DISTINCT FROM OLD.landlord_id
     OR NEW.source IS DISTINCT FROM OLD.source THEN
    RAISE EXCEPTION 'A payment''s expense, company and source never change; void it and record another.'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: landlord_expense_payments_sums(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landlord_expense_payments_sums() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  r          record;
  line_amt   numeric;
  line_owner uuid;
  paid       numeric;
  e          record;
BEGIN
  r := NEW;
  IF r.bank_transaction_id IS NOT NULL THEN
    SELECT bt.amount, bt.landlord_id INTO line_amt, line_owner FROM bank_transactions bt WHERE bt.id = r.bank_transaction_id;
    SELECT COALESCE(sum(p.amount), 0) INTO paid FROM landlord_expense_payments p
     WHERE p.bank_transaction_id = r.bank_transaction_id AND p.voided_at IS NULL;
    IF paid > 0 AND line_amt >= 0 THEN
      RAISE EXCEPTION 'That bank line is money coming in; only money going out pays an expense.' USING ERRCODE = 'check_violation';
    END IF;
    IF paid > abs(line_amt) THEN
      RAISE EXCEPTION 'The payments on that bank line (%) come to more than the line itself (%).', paid, abs(line_amt)
        USING ERRCODE = 'check_violation';
    END IF;
    IF line_owner IS DISTINCT FROM r.landlord_id THEN
      RAISE EXCEPTION 'That bank line belongs to another company.' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  SELECT x.amount, x.landlord_id INTO e FROM landlord_expenses x WHERE x.id = r.expense_id;
  IF e.landlord_id IS DISTINCT FROM r.landlord_id THEN
    RAISE EXCEPTION 'A payment belongs to its expense''s company.' USING ERRCODE = 'check_violation';
  END IF;
  SELECT COALESCE(sum(p.amount), 0) INTO paid FROM landlord_expense_payments p
   WHERE p.expense_id = r.expense_id AND p.voided_at IS NULL;
  IF paid > e.amount THEN
    RAISE EXCEPTION 'The payments on that expense (%) come to more than the expense itself (%).', paid, e.amount
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: landlord_expenses_asset_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landlord_expenses_asset_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  a record;
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- 10/13 review: an expense an asset stands on is never removed (a line
    -- naming a missing expense would drop that part of the asset's cost).
    SELECT f.name INTO a FROM books_fixed_assets f WHERE f.id = books_expense_fixed_asset(OLD.id);
    IF FOUND THEN
      RAISE EXCEPTION 'This expense is part of the fixed asset "%", so it is never removed. Void the asset, or change where its money came from, on the Fixed assets page first.', a.name
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;
  IF (NEW.status IS DISTINCT FROM 'active' OR NEW.voided_at IS NOT NULL)
     AND OLD.status = 'active' AND OLD.voided_at IS NULL THEN
    SELECT f.name INTO a FROM books_fixed_assets f WHERE f.source_expense_id = NEW.id AND f.voided_at IS NULL LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'This expense became the fixed asset "%". Void the asset on the Fixed assets page first.', a.name
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF (NEW.status IS DISTINCT FROM 'active' OR NEW.voided_at IS NOT NULL OR NEW.amount IS DISTINCT FROM OLD.amount
      OR NEW.property_id IS DISTINCT FROM OLD.property_id OR NEW.unit_id IS DISTINCT FROM OLD.unit_id)
     AND OLD.status = 'active' AND OLD.voided_at IS NULL THEN
    SELECT f.name INTO a FROM books_fixed_assets f
      JOIN books_fixed_asset_funding x ON x.asset_id = f.id AND x.expense_id = NEW.id AND x.replaced_at IS NULL
     WHERE f.voided_at IS NULL LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'This expense paid for part of the fixed asset "%". Change where that asset''s money came from on the Fixed assets page first.', a.name
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: landlord_expenses_cover_payments(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landlord_expenses_cover_payments() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  paid numeric;
BEGIN
  SELECT COALESCE(sum(p.amount), 0) INTO paid FROM landlord_expense_payments p
   WHERE p.expense_id = NEW.id AND p.voided_at IS NULL;
  IF NEW.status = 'active' AND paid > NEW.amount THEN
    RAISE EXCEPTION 'This expense has % paid on it; its amount cannot be less than that.', paid USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: landlord_expenses_legacy_payment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landlord_expenses_legacy_payment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  conn uuid;
  day  date;
BEGIN
  IF NEW.bank_transaction_id IS NOT NULL THEN
    SELECT bt.bank_connection_id, bt.posted_date INTO conn, day FROM bank_transactions bt WHERE bt.id = NEW.bank_transaction_id;
  END IF;
  INSERT INTO landlord_expense_payments
    (expense_id, landlord_id, paid_on, amount, method, bank_connection_id, bank_transaction_id, source, memo, created_by)
  SELECT NEW.id, NEW.landlord_id, COALESCE(day, NEW.expense_date), NEW.amount,
         CASE WHEN NEW.bank_transaction_id IS NOT NULL THEN 'bank' ELSE 'other' END,
         conn, NEW.bank_transaction_id, 'migrated',
         'Logged as paid before payments were recorded', NEW.created_by
   WHERE NEW.amount > 0;
  RETURN NULL;
END $$;


--
-- Name: landlord_expenses_legacy_payment_follows(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landlord_expenses_legacy_payment_follows() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  pay record;
  n   integer;
BEGIN
  SELECT count(*) INTO n FROM landlord_expense_payments p WHERE p.expense_id = NEW.id AND p.voided_at IS NULL;
  IF n <> 1 OR NEW.amount <= 0 THEN RETURN NULL; END IF;
  SELECT p.id, p.amount, p.paid_on INTO pay FROM landlord_expense_payments p
   WHERE p.expense_id = NEW.id AND p.voided_at IS NULL AND p.source = 'migrated'
     AND p.bank_transaction_id IS NULL AND p.amount = OLD.amount;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF pay.amount = NEW.amount AND NOT (pay.paid_on = OLD.expense_date AND OLD.expense_date IS DISTINCT FROM NEW.expense_date) THEN
    RETURN NULL;
  END IF;
  UPDATE landlord_expense_payments
     SET amount = NEW.amount,
         paid_on = CASE WHEN pay.paid_on = OLD.expense_date THEN NEW.expense_date ELSE pay.paid_on END,
         updated_at = now()
   WHERE id = pay.id;
  RETURN NULL;
END $$;


--
-- Name: landlord_expenses_void_payments(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landlord_expenses_void_payments() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE landlord_expense_payments
     SET voided_at = COALESCE(NEW.voided_at, now()), void_reason = 'The expense was voided', updated_at = now()
   WHERE expense_id = NEW.id AND voided_at IS NULL;
  RETURN NULL;
END $$;


--
-- Name: landlord_gam_charge_collections_backfill(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landlord_gam_charge_collections_backfill() RETURNS TABLE(rows_written integer, amount_written numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
  ev        record;
  ch        record;
  left_amt  numeric;
  take      numeric;
  n         integer := 0;
  total     numeric := 0;
  bad       text;
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS _gam_charge_left (id uuid PRIMARY KEY, landlord_id uuid, created_at timestamptz, left_amount numeric) ON COMMIT DROP;
  TRUNCATE _gam_charge_left;
  INSERT INTO _gam_charge_left SELECT c.id, c.landlord_id, c.created_at, c.amount FROM landlord_gam_charges c;

  -- Every collection that ever happened, in the order it happened: a batch
  -- netted at its RESERVE (the intent's created_at, the same NOW() the netting
  -- stamped on a charge it finished), a pull at its settlement.
  FOR ev IN
    SELECT 'intent'::text AS kind, i.id, i.landlord_id, i.created_at AS at,
           i.gam_fees_kept_amount AS amt, NULL::uuid[] AS charge_ids,
           EXISTS (SELECT 1 FROM landlord_gam_charge_collections x WHERE x.platform_transfer_intent_id = i.id) AS done
      FROM platform_transfer_intents i
     WHERE i.landlord_id IS NOT NULL AND i.gam_fees_kept_amount > 0
    UNION ALL
    SELECT 'debit', d.id, d.landlord_id, d.settled_at, d.total_amount, d.charge_ids,
           EXISTS (SELECT 1 FROM landlord_gam_charge_collections x WHERE x.landlord_gam_debit_id = d.id)
      FROM landlord_gam_debits d
     WHERE d.status = 'succeeded'
     ORDER BY at, kind, id
  LOOP
    IF ev.done THEN
      -- Already on file (written by the code, or by an earlier run): what it
      -- collected is what its own rows say, never a re-derivation.
      UPDATE _gam_charge_left l SET left_amount = l.left_amount - x.amount
        FROM landlord_gam_charge_collections x
       WHERE x.charge_id = l.id
         AND (x.platform_transfer_intent_id = ev.id OR x.landlord_gam_debit_id = ev.id);
    ELSIF ev.kind = 'intent' THEN
      left_amt := ev.amt;
      FOR ch IN
        SELECT l.id, l.left_amount FROM _gam_charge_left l
         WHERE l.landlord_id = ev.landlord_id AND l.left_amount > 0 AND l.created_at <= ev.at
         ORDER BY l.created_at, l.id
      LOOP
        EXIT WHEN left_amt <= 0;
        take := LEAST(ch.left_amount, left_amt);
        INSERT INTO landlord_gam_charge_collections
          (charge_id, platform_transfer_intent_id, amount, collected_at, derived)
        VALUES (ch.id, ev.id, take, ev.at, true);
        n := n + 1; total := total + take;
        UPDATE _gam_charge_left SET left_amount = left_amount - take WHERE id = ch.id;
        left_amt := left_amt - take;
      END LOOP;
      IF left_amt > 0 THEN
        RAISE EXCEPTION 'GAM charge collections replay: payout batch % kept % of GAM charges that no charge of its company can explain', ev.id, left_amt;
      END IF;
    ELSE
      left_amt := ev.amt;
      FOR ch IN
        SELECT l.id, l.left_amount FROM _gam_charge_left l
         WHERE l.id = ANY (ev.charge_ids) AND l.left_amount > 0
         ORDER BY l.created_at, l.id
      LOOP
        INSERT INTO landlord_gam_charge_collections
          (charge_id, landlord_gam_debit_id, amount, collected_at, derived)
        VALUES (ch.id, ev.id, ch.left_amount, ev.at, true);
        n := n + 1; total := total + ch.left_amount;
        left_amt := left_amt - ch.left_amount;
        UPDATE _gam_charge_left SET left_amount = 0 WHERE id = ch.id;
      END LOOP;
      -- A pull that took more than its charges still owed collected some of
      -- them a second time (the double collection this table exists to show).
      IF left_amt <> 0 THEN
        RAISE EXCEPTION 'GAM charge collections replay: bank pull % took % and its charges explain %', ev.id, ev.amt, ev.amt - left_amt;
      END IF;
    END IF;
  END LOOP;

  SELECT string_agg(format('%s (collected %s, records %s)', c.id, c.collected_amount, COALESCE(s.amt, 0)), '; ')
    INTO bad
    FROM landlord_gam_charges c
    LEFT JOIN (SELECT charge_id, SUM(amount) AS amt FROM landlord_gam_charge_collections GROUP BY charge_id) s
      ON s.charge_id = c.id
   WHERE COALESCE(s.amt, 0) <> c.collected_amount;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'GAM charge collections do not tie to collected_amount: %', bad;
  END IF;

  RETURN QUERY SELECT n, total;
END $$;


--
-- Name: FUNCTION landlord_gam_charge_collections_backfill(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.landlord_gam_charge_collections_backfill() IS '10/12 (ledger P0): idempotent replay of past GAM charge collections into landlord_gam_charge_collections (derived rows). Run by migration 20261013090000 and again after the code that writes the rows itself is live.';


--
-- Name: landlord_members_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landlord_members_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO landlord_member_history
      (landlord_id, user_id, action, role, added_by_user_id, application)
    VALUES (NEW.landlord_id, NEW.user_id, 'added', NEW.role, NEW.added_by_user_id,
            current_setting('application_name', true));
    RETURN NEW;
  ELSE
    INSERT INTO landlord_member_history
      (landlord_id, user_id, action, role, added_by_user_id, application)
    VALUES (OLD.landlord_id, OLD.user_id, 'removed', OLD.role, NULL,
            current_setting('application_name', true));
    RETURN OLD;
  END IF;
END;
$$;


--
-- Name: lease_units_in_window(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_units_in_window(p_lease_id uuid, p_from date, p_to date) RETURNS TABLE(unit_id uuid, from_date date, to_date date)
    LANGUAGE sql STABLE
    AS $$
  SELECT h.unit_id,
         GREATEST(h.effective_from, p_from) AS from_date,
         LEAST(COALESCE(h.effective_to, p_to), p_to) AS to_date
    FROM lease_unit_history h
   WHERE h.lease_id = p_lease_id
     AND h.effective_from <= p_to
     AND (h.effective_to IS NULL OR h.effective_to > p_from)
   ORDER BY h.effective_from
$$;


--
-- Name: ledger_account_role_is_control(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ledger_account_role_is_control(p_role text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT p_role IN ('undeposited_funds', 'deposits_in_transit', 'due_from_gam', 'due_from_gam_tenant_money',
                    'stripe_in_transit', 'deposits_gam_holds', 'ar_tenants', 'ar_store_accounts',
                    'home_notes_receivable', 'accounts_payable', 'outstanding_checks', 'security_deposits_payable',
                    'tenant_prepayments', 'guest_deposits', 'due_to_gam', 'equipment_owed_to_gam',
                    'interproperty_clearing')
$$;


