--
-- Name: prepaid_fee_follows_payment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepaid_fee_follows_payment() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  kind text;
BEGIN
  -- 10/4 (decisions #46.4): a box closed at $0 (never paid, the lease ended)
  -- has no money behind it — nothing to bank.
  IF NEW.status = 'settled' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'settled')
     AND NEW.lease_fee_id IS NOT NULL AND NEW.lease_id IS NOT NULL AND NEW.amount > 0 THEN
    SELECT money_kind INTO kind FROM lease_fees WHERE id = NEW.lease_fee_id;
    IF kind = 'prepaid' THEN
      INSERT INTO lease_prepaid_credits
        (lease_id, tenant_id, amount_original, amount_remaining, source_payment_id, note,
         funded_by, received_at)
      VALUES (NEW.lease_id, NEW.tenant_id, NEW.amount, NEW.amount, NEW.id,
              'Rent paid ahead on the lease (move-in)',
              CASE WHEN NEW.manual_method IS NULL
                         AND (NEW.platform_held
                              OR NEW.stripe_charge_id IS NOT NULL
                              OR NEW.stripe_payment_intent_id IS NOT NULL
                              OR NEW.flexpay_advance_id IS NOT NULL)
                   THEN 'gam' ELSE 'landlord' END,
              COALESCE(NEW.settled_at, now()))
      ON CONFLICT (source_payment_id) WHERE source_payment_id IS NOT NULL DO UPDATE
         SET funded_by   = EXCLUDED.funded_by,
             received_at = EXCLUDED.received_at,
             voided_at   = NULL,
             void_reason = NULL,
             updated_at  = now()
       WHERE lease_prepaid_credits.voided_at IS NOT NULL
         AND lease_prepaid_credits.amount_remaining = lease_prepaid_credits.amount_original
         AND lease_prepaid_credits.amount_original = EXCLUDED.amount_original;
    END IF;
  END IF;
  RETURN NEW;
END $_$;


--
-- Name: properties_timezone_must_be_real(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.properties_timezone_must_be_real() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.timezone IS NULL OR NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = NEW.timezone) THEN
    RAISE EXCEPTION 'Unknown time zone "%" for a property', NEW.timezone USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: property_stay_tax_pct(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.property_stay_tax_pct(p_property_id uuid) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  WITH reaching AS (
    SELECT r.rate, r.property_id
      FROM pos_tax_rates r
      JOIN properties p ON p.id = p_property_id AND p.landlord_id = r.landlord_id
     WHERE r.is_active AND r.on_stays
       AND (r.property_id = p_property_id OR r.property_id IS NULL)
  )
  SELECT LEAST(100, COALESCE(ROUND(SUM(rate) * 100, 2), 0))
    FROM reaching
   WHERE (property_id IS NOT NULL)
         = EXISTS (SELECT 1 FROM reaching WHERE property_id IS NOT NULL)
$$;


--
-- Name: FUNCTION property_stay_tax_pct(p_property_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.property_stay_tax_pct(p_property_id uuid) IS '10/17 (Nic): the percent a stay at this property is taxed at, read from the one home (the active on_stays rows of pos_tax_rates). properties.short_term_tax_rate follows it.';


--
-- Name: property_unit_subtypes_resync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.property_unit_subtypes_resync() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE r record;
BEGIN
  IF NEW.rv_site_layout IS DISTINCT FROM OLD.rv_site_layout
     OR NEW.rv_amp_service IS DISTINCT FROM OLD.rv_amp_service
     OR NEW.bedrooms IS DISTINCT FROM OLD.bedrooms
     OR NEW.bathrooms IS DISTINCT FROM OLD.bathrooms
     OR NEW.storage_size IS DISTINCT FROM OLD.storage_size
     OR NEW.dwelling_ownership IS DISTINCT FROM OLD.dwelling_ownership THEN
    FOR r IN SELECT unit_id FROM unit_subtype_links WHERE subtype_id = NEW.id LOOP
      PERFORM sync_unit_facts_from_subtypes(r.unit_id);
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: protect_platform_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_platform_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE owner_id uuid;
BEGIN
  SELECT user_id INTO owner_id FROM platform_owner LIMIT 1;
  IF owner_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_OP = 'DELETE' AND OLD.id = owner_id THEN
    RAISE EXCEPTION 'The platform owner account cannot be deleted.'
      USING ERRCODE = 'raise_exception';
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.id = owner_id AND NEW.role IS DISTINCT FROM OLD.role THEN
    RAISE EXCEPTION 'The platform owner''s role cannot be changed.'
      USING ERRCODE = 'raise_exception';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


