--
-- Name: register_book_companies(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_book_companies(company uuid, caller_user uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE
    AS $$
  SELECT l.id FROM landlords l
   WHERE caller_user IS NOT NULL
     AND l.user_id = (SELECT o.user_id FROM landlords o WHERE o.id = company)
     AND (
          -- 1. the account behind this company is the caller's own
          l.user_id = caller_user
          -- 2. a co-owner reaches the companies they co-own, and no siblings
       OR EXISTS (SELECT 1 FROM landlord_members cm
                   WHERE cm.landlord_id = l.id AND cm.user_id = caller_user)
     )
  UNION
  SELECT company
$$;


--
-- Name: reject_booking_on_retired_unit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_booking_on_retired_unit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  u_retired timestamptz;
  u_number  text;
BEGIN
  IF NEW.status = 'cancelled' THEN
    RETURN NEW;
  END IF;
  SELECT u.retired_at, u.unit_number INTO u_retired, u_number
    FROM units u WHERE u.id = NEW.unit_id;
  IF u_retired IS NOT NULL THEN
    RAISE EXCEPTION 'Unit % ("%") is retired and cannot take a booking. Use its replacement unit instead.', NEW.unit_id, u_number
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: reject_lease_on_unavailable_unit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_lease_on_unavailable_unit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  u_status  text;
  u_retired timestamptz;
  u_number  text;
BEGIN
  IF NEW.status NOT IN ('active', 'pending') THEN
    RETURN NEW;
  END IF;
  SELECT u.status, u.retired_at, u.unit_number
    INTO u_status, u_retired, u_number
    FROM units u WHERE u.id = NEW.unit_id;

  IF u_retired IS NOT NULL THEN
    RAISE EXCEPTION 'Unit % ("%") is retired and cannot hold a lease. Use its replacement unit instead.', NEW.unit_id, u_number
      USING ERRCODE = 'check_violation';
  END IF;
  IF u_status = 'owner_use' THEN
    RAISE EXCEPTION 'Unit % is marked owner-occupied and cannot hold a lease. Change its status first.', NEW.unit_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: security_deposits_voided_is_a_record(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.security_deposits_voided_is_a_record() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.status = 'voided' AND (
       NEW.status IS DISTINCT FROM OLD.status
    OR NEW.voided_at IS DISTINCT FROM OLD.voided_at
    OR NEW.void_reason IS DISTINCT FROM OLD.void_reason
    OR NEW.total_amount IS DISTINCT FROM OLD.total_amount
    OR NEW.collected_amount IS DISTINCT FROM OLD.collected_amount
    OR NEW.lease_id IS DISTINCT FROM OLD.lease_id
    OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
    OR NEW.held_by IS DISTINCT FROM OLD.held_by) THEN
    RAISE EXCEPTION 'Deposit record % was voided: it is a record and does not change', OLD.id
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


