--
-- Name: supersede_utility_service_agreement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supersede_utility_service_agreement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Only a LIVE tenancy supersedes. A draft or a signed-but-not-started lease
  -- has not put anybody in the space yet, and stamping on those would move the
  -- fee for a tenancy that may never begin.
  IF NEW.status = 'active' THEN
    UPDATE utility_service_agreements sa
       SET superseded_by_lease_id = NEW.id,
           updated_at = NOW()
     WHERE sa.unit_id = NEW.unit_id
       AND sa.status = 'active'
       AND sa.superseded_by_lease_id IS NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION supersede_utility_service_agreement(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.supersede_utility_service_agreement() IS 'S615: a lease going active on a serviced space stamps the agreement so the $2 platform fee follows the tenancy and is never charged twice for one space. The agreement keeps billing utilities — only the fee moves.';


--
-- Name: sync_unit_delinquency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_unit_delinquency() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_unit uuid := COALESCE(NEW.unit_id, OLD.unit_id);
  owed        numeric;
BEGIN
  IF target_unit IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;
  -- S655 (Nic): saved credit does not stop a late bill. A credit that covers the
  -- whole bill is applied to it (creditUse.settleWholeBillIfCovered), which
  -- settles the rows and lands back here with nothing owed.
  -- 10/12 (Nic): late from the first late day — the later of the due date and
  -- the day GAM wrote the bill, + GREATEST(grace, 1), the day late fees start
  -- (services/lateness lateCountsFromSql / writtenAtSql / pastGraceSql).
  -- 10/19: the grace comes from the LEASE, where the real policy is stamped
  -- when the lease is drafted (property_unit_type_late_fees -> the lease), with
  -- the same 5 behind it the property column held for every property.
  SELECT COALESCE(SUM(p.amount), 0) INTO owed
    FROM payments p
    JOIN units u ON u.id = p.unit_id
    JOIN properties pr ON pr.id = u.property_id
    LEFT JOIN leases l ON l.id = p.lease_id
    CROSS JOIN LATERAL (
      SELECT (NOW() AT TIME ZONE COALESCE(pr.timezone, 'America/Phoenix'))::date AS today,
             ((CASE WHEN p.reversal_id IS NOT NULL
                      OR (p.is_remainder AND (p.notes LIKE 'What is left of the old balance after a part payment%'
                                           OR p.notes LIKE 'What is left of this bill after a part payment%'))
                    THEN (SELECT MIN(GREATEST(wf.created_at,
                                   (CASE WHEN wf.work_trade_suspended_at IS NULL
                                              AND (wf.notes LIKE '%suspended while the hours are worked%'
                                                OR wf.notes LIKE '%suspended until month close%'
                                                OR wf.notes LIKE '%No longer covered by the work trade%')
                                         THEN (SELECT MAX(wr.changed_at) FROM audit_row_changes wr
                                                WHERE wr.table_name = 'payments' AND wr.row_id = wf.id
                                                  AND wr.old_row->>'work_trade_suspended_at' IS NOT NULL
                                                  AND wr.new_row->>'work_trade_suspended_at' IS NULL) END)))
                            FROM payments wf
                           WHERE wf.lease_id IS NOT DISTINCT FROM p.lease_id
                             AND wf.tenant_id IS NOT DISTINCT FROM p.tenant_id
                             AND wf.type = p.type
                             AND wf.due_date = p.due_date
                             AND wf.invoice_id IS NOT DISTINCT FROM p.invoice_id
                             AND wf.created_at <= p.created_at)
                    ELSE GREATEST(p.created_at,
                           (CASE WHEN p.work_trade_suspended_at IS NULL
                                      AND (p.notes LIKE '%suspended while the hours are worked%'
                                        OR p.notes LIKE '%suspended until month close%'
                                        OR p.notes LIKE '%No longer covered by the work trade%')
                                 THEN (SELECT MAX(wr.changed_at) FROM audit_row_changes wr
                                        WHERE wr.table_name = 'payments' AND wr.row_id = p.id
                                          AND wr.old_row->>'work_trade_suspended_at' IS NOT NULL
                                          AND wr.new_row->>'work_trade_suspended_at' IS NULL) END))
               END) AT TIME ZONE COALESCE(pr.timezone, 'America/Phoenix'))::date AS written_day
    ) d
   WHERE p.unit_id = target_unit
     AND p.type = 'rent'
     AND p.status IN ('pending','failed')
     AND p.work_trade_suspended_at IS NULL
     AND p.amount > 0
     AND d.today >= GREATEST(p.due_date, COALESCE(d.written_day, p.due_date))
                    + GREATEST(COALESCE(l.late_fee_grace_days, 5), 1);
  IF owed > 0 THEN
    UPDATE units SET status = 'delinquent', updated_at = NOW()
     WHERE id = target_unit AND status = 'active';
  ELSE
    UPDATE units SET status = 'active', updated_at = NOW()
     WHERE id = target_unit AND status = 'delinquent';
  END IF;
  RETURN COALESCE(NEW, OLD);
END $$;


--
-- Name: sync_unit_facts_from_subtypes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_unit_facts_from_subtypes(p_unit_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_layouts text[]; v_amps text[]; v_beds int[]; v_baths numeric[];
  v_sizes text[]; v_owns text[]; v_amp text;
BEGIN
  SELECT array_agg(DISTINCT s.rv_site_layout) FILTER (WHERE s.rv_site_layout IS NOT NULL AND s.rv_site_layout <> 'none'),
         array_agg(DISTINCT s.bedrooms)       FILTER (WHERE s.bedrooms IS NOT NULL),
         array_agg(DISTINCT s.bathrooms)      FILTER (WHERE s.bathrooms IS NOT NULL),
         array_agg(DISTINCT btrim(s.storage_size)) FILTER (WHERE btrim(COALESCE(s.storage_size,'')) <> ''),
         array_agg(DISTINCT s.dwelling_ownership)  FILTER (WHERE s.dwelling_ownership IS NOT NULL)
    INTO v_layouts, v_beds, v_baths, v_sizes, v_owns
    FROM unit_subtype_links l JOIN property_unit_subtypes s ON s.id = l.subtype_id
   WHERE l.unit_id = p_unit_id;

  -- 30 amp AND 50 amp is a real pedestal, so amp tags UNION rather than clash.
  SELECT array_agg(DISTINCT a) INTO v_amps FROM (
    SELECT unnest(CASE WHEN s.rv_amp_service = 'both' THEN ARRAY['30','50']
                       ELSE ARRAY[s.rv_amp_service] END) AS a
      FROM unit_subtype_links l JOIN property_unit_subtypes s ON s.id = l.subtype_id
     WHERE l.unit_id = p_unit_id
       AND s.rv_amp_service IS NOT NULL AND s.rv_amp_service <> 'none') q;

  IF array_length(v_layouts, 1) > 1 THEN
    RAISE EXCEPTION 'A site is back-in or pull-through, not both — pick one layout for this space.'
      USING ERRCODE = 'check_violation';
  END IF;
  IF array_length(v_beds, 1) > 1 OR array_length(v_baths, 1) > 1
     OR array_length(v_sizes, 1) > 1 OR array_length(v_owns, 1) > 1 THEN
    RAISE EXCEPTION 'Two of those subtypes describe the same thing differently — untick one.'
      USING ERRCODE = 'check_violation';
  END IF;

  v_amp := CASE
    WHEN v_amps @> ARRAY['30','50'] THEN 'both'
    WHEN array_length(v_amps, 1) = 1 THEN v_amps[1]
    ELSE NULL END;

  UPDATE units SET
    rv_site_layout     = COALESCE(v_layouts[1], rv_site_layout),
    rv_amp_service     = COALESCE(v_amp,        rv_amp_service),
    bedrooms           = COALESCE(v_beds[1],    bedrooms),
    bathrooms          = COALESCE(v_baths[1],   bathrooms),
    storage_size       = COALESCE(v_sizes[1],   storage_size),
    dwelling_ownership = COALESCE(v_owns[1],    dwelling_ownership),
    updated_at         = NOW()
  WHERE id = p_unit_id;
END;
$$;


