-- Name: TABLE business_invoice_sequences; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.business_invoice_sequences IS 'S493 per-business invoice number counter. nextval-style: each invoice create reads + bumps in one transaction.';


--
-- Name: business_invoices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.business_invoices (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    invoice_number text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    issue_date date NOT NULL,
    due_date date NOT NULL,
    subtotal numeric(12,2) DEFAULT 0 NOT NULL,
    tax_amount numeric(12,2) DEFAULT 0 NOT NULL,
    total_amount numeric(12,2) DEFAULT 0 NOT NULL,
    amount_paid numeric(12,2) DEFAULT 0 NOT NULL,
    sent_at timestamp with time zone,
    paid_at timestamp with time zone,
    voided_at timestamp with time zone,
    void_reason text,
    payment_method text,
    stripe_payment_intent_id text,
    notes text,
    internal_notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    stripe_checkout_session_id text,
    hosted_pay_url text,
    source_work_order_id uuid,
    source_quote_id uuid,
    source_recurring_schedule_id uuid,
    auto_charge_attempted_at timestamp with time zone,
    auto_charge_last_error text,
    discount_code_id uuid,
    discount_amount numeric(10,2) DEFAULT 0 NOT NULL,
    refunded_amount numeric(12,2) DEFAULT 0 NOT NULL,
    refunded_at timestamp with time zone,
    refund_reason text,
    stripe_refund_id text,
    deposit_amount numeric(12,2) DEFAULT 0 NOT NULL,
    deposit_type text,
    deposit_paid_at timestamp with time zone,
    CONSTRAINT business_invoices_deposit_amount_nonneg CHECK ((deposit_amount >= (0)::numeric)),
    CONSTRAINT business_invoices_deposit_pairing CHECK ((((deposit_amount = (0)::numeric) AND (deposit_type IS NULL)) OR ((deposit_amount > (0)::numeric) AND (deposit_type IS NOT NULL)))),
    CONSTRAINT business_invoices_deposit_type_check CHECK (((deposit_type IS NULL) OR (deposit_type = ANY (ARRAY['service'::text, 'materials'::text])))),
    CONSTRAINT business_invoices_discount_nonneg CHECK ((discount_amount >= (0)::numeric)),
    CONSTRAINT business_invoices_paid_audit CHECK ((((status = 'paid'::text) AND (paid_at IS NOT NULL)) OR (status <> 'paid'::text))),
    CONSTRAINT business_invoices_paid_nn CHECK ((amount_paid >= (0)::numeric)),
    CONSTRAINT business_invoices_refunded_amount_nonneg CHECK ((refunded_amount >= (0)::numeric)),
    CONSTRAINT business_invoices_sent_audit CHECK ((((status = ANY (ARRAY['sent'::text, 'paid'::text])) AND (sent_at IS NOT NULL)) OR (status <> ALL (ARRAY['sent'::text, 'paid'::text])))),
    CONSTRAINT business_invoices_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'sent'::text, 'paid'::text, 'partially_refunded'::text, 'refunded'::text, 'void'::text]))),
    CONSTRAINT business_invoices_subtotal_nn CHECK ((subtotal >= (0)::numeric)),
    CONSTRAINT business_invoices_tax_nn CHECK ((tax_amount >= (0)::numeric)),
    CONSTRAINT business_invoices_total_nn CHECK ((total_amount >= (0)::numeric)),
    CONSTRAINT business_invoices_void_audit CHECK ((((status = 'void'::text) AND (voided_at IS NOT NULL)) OR (status <> 'void'::text)))
);


--
-- Name: TABLE business_invoices; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.business_invoices IS 'S493 business-portal invoicing. Per-business per-customer invoices with free-form line items. Distinct from real-estate invoices (which are lease-coupled). Status: draft → sent → paid (or void from any).';


--
-- Name: COLUMN business_invoices.auto_charge_attempted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.business_invoices.auto_charge_attempted_at IS 'S508 set when a recurring cycle attempted an off-session charge. If auto_charge_last_error is also set, the charge failed and the invoice remains in draft for owner follow-up.';


--
-- Name: COLUMN business_invoices.discount_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.business_invoices.discount_amount IS 'S513 pre-tax discount applied via discount_code_id. total_amount = (subtotal - discount_amount) + tax_amount.';


--
-- Name: COLUMN business_invoices.refunded_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.business_invoices.refunded_amount IS 'S519 amount refunded against a paid invoice (bookkeeping). Operator runs the actual money refund on Stripe/terminal; GAM records it.';


--
-- Name: COLUMN business_invoices.deposit_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.business_invoices.deposit_amount IS 'S511 upfront deposit due before the balance. 0 = no deposit. Must be <= total_amount (enforced in app).';


--
-- Name: COLUMN business_invoices.deposit_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.business_invoices.deposit_type IS 'S511 service|materials — a bookkeeping label for the deposit; no behavioral difference.';


--
-- Name: COLUMN business_invoices.deposit_paid_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.business_invoices.deposit_paid_at IS 'S511 stamped when cumulative amount_paid first covers deposit_amount.';


--
-- Name: business_platform_fee_accruals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.business_platform_fee_accruals (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
