--
-- Name: flexcredit_inquiries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.flexcredit_inquiries (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id uuid NOT NULL,
    status text DEFAULT 'interested'::text NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT flexcredit_inquiries_status_check CHECK ((status = ANY (ARRAY['interested'::text, 'enrolled'::text, 'declined'::text])))
);


--
-- Name: TABLE flexcredit_inquiries; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.flexcredit_inquiries IS 'S565 FlexCredit demand-capture: one interest row per tenant. Demand-test only — no billing/Esusu enrollment wired. Mirrors flexpay_inquiries but with no income verification (credit reporting needs none).';


--
-- Name: flexdeposit_capacity; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.flexdeposit_capacity (
    id boolean DEFAULT true NOT NULL,
    max_active_plans integer,
    max_uncollected numeric(12,2),
    note text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT flexdeposit_capacity_one_row CHECK ((id IS TRUE)),
    CONSTRAINT flexdeposit_capacity_sane CHECK ((((max_active_plans IS NULL) OR (max_active_plans >= 0)) AND ((max_uncollected IS NULL) OR (max_uncollected >= (0)::numeric))))
);


--
-- Name: TABLE flexdeposit_capacity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.flexdeposit_capacity IS 'Platform-wide ceiling on concurrent FlexDeposit plans and total uncollected deposit (10/26, Nic). Either limit closes enrollment; NULL disables that limit. One row.';


--
-- Name: flexdeposit_fee_schedule; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.flexdeposit_fee_schedule (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    deposit_min numeric(12,2) NOT NULL,
    deposit_max numeric(12,2),
    payments integer NOT NULL,
    fee numeric(12,2) NOT NULL,
    effective_from date DEFAULT CURRENT_DATE NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT flexdeposit_fee_nonneg CHECK ((fee >= (0)::numeric)),
    CONSTRAINT flexdeposit_fee_payments_check CHECK (((payments >= 2) AND (payments <= 6))),
    CONSTRAINT flexdeposit_fee_range_check CHECK (((deposit_max IS NULL) OR (deposit_max > deposit_min))),
    CONSTRAINT flexdeposit_fee_schedule_payments_check CHECK (((payments >= 2) AND (payments <= 6)))
);


--
-- Name: TABLE flexdeposit_fee_schedule; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.flexdeposit_fee_schedule IS 'FlexDeposit service fee by deposit bracket and installment count. Exactly two counts are sold, 2 and 4 (10/26, Nic), at the SAME price for everybody at a given deposit size — that uniformity is what keeps it a service price rather than a credit decision. Not offered at $3,000 or more. Re-pricing appends a row with a later effective_from.';


--
-- Name: flexpay_advances; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.flexpay_advances (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    cycle_month date NOT NULL,
    tenant_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    unit_id uuid NOT NULL,
    lease_id uuid NOT NULL,
    rent_amount numeric(10,2) NOT NULL,
    tenant_fee_amount numeric(10,2) NOT NULL,
    pull_day integer NOT NULL,
    grace_advance_suppressed boolean DEFAULT false NOT NULL,
    stripe_transfer_id text,
    transfer_attempted_at timestamp with time zone,
    transfer_error text,
    fronted_at timestamp with time zone,
    rent_payment_id uuid,
    fee_payment_id uuid,
    pulled_at timestamp with time zone,
    reconciled_at timestamp with time zone,
    defaulted_at timestamp with time zone,
    default_reason text,
    status text DEFAULT 'pending'::text NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    invoice_id uuid,
    pull_date date,
    pull_attempts integer DEFAULT 0 NOT NULL,
    pull_last_error text,
    subscription_fee numeric(10,2),
    CONSTRAINT flexpay_advances_amounts_check CHECK (((rent_amount >= (0)::numeric) AND (tenant_fee_amount > (0)::numeric))),
    CONSTRAINT flexpay_advances_pull_attempts_nonneg CHECK ((pull_attempts >= 0)),
    CONSTRAINT flexpay_advances_pull_day_check CHECK (((pull_day >= 1) AND (pull_day <= 28))),
    CONSTRAINT flexpay_advances_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'fronted'::text, 'pulled'::text, 'reconciled'::text, 'nsf'::text, 'defaulted'::text])))
);


--
-- Name: COLUMN flexpay_advances.invoice_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.flexpay_advances.invoice_id IS 'S655: the cycle invoice whose open landlord lines the cover paid (the whole monthly bill).';


--
-- Name: COLUMN flexpay_advances.pull_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.flexpay_advances.pull_date IS 'S655: the day GAM takes the covered amount plus the $25 back from the tenant''s bank. Never the 1st-5th (FLEXPAY_FORBIDDEN_PULL_DAYS).';


--
-- Name: COLUMN flexpay_advances.pull_attempts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.flexpay_advances.pull_attempts IS 'S655: runs that tried to create the pull intent. The pull row is written first; a row with no intent is "create pending". After 3 failed creates the advance is defaulted and an admin is alerted.';


--
-- Name: COLUMN flexpay_advances.subscription_fee; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.flexpay_advances.subscription_fee IS 'The FlexPay subscription fee this cycle was PRICED at, from flexpay_fee_schedule, stamped at cover and never changed (10/26). GAM''s revenue for the month; platform_revenue_ledger books this. tenant_fee_amount is the TOTAL the tenant owes and grows with pass-through return/dispute costs, which are never GAM earnings.';


--
-- Name: flexpay_blocked_states; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.flexpay_blocked_states (
    state text NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT flexpay_blocked_states_state_check CHECK ((length(state) = 2))
);


--
-- Name: flexpay_fee_schedule; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.flexpay_fee_schedule (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    rent_min numeric(12,2) NOT NULL,
    rent_max numeric(12,2),
    benefit_wednesday integer NOT NULL,
    fee numeric(12,2) NOT NULL,
    effective_from date DEFAULT CURRENT_DATE NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT flexpay_fee_nonneg CHECK ((fee >= (0)::numeric)),
    CONSTRAINT flexpay_fee_range_check CHECK (((rent_max IS NULL) OR (rent_max > rent_min))),
    CONSTRAINT flexpay_fee_wednesday_check CHECK ((benefit_wednesday = ANY (ARRAY[2, 3, 4])))
);


--
-- Name: TABLE flexpay_fee_schedule; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.flexpay_fee_schedule IS 'FlexPay price by rent bracket x benefit Wednesday (Nic, 10/26). A FIXED price
   for the bracket, never a percentage of the particular rent — "we are trying
   to stay out of lender territory". Replaces the flat $25/month.';


--
-- Name: flexpay_inquiries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.flexpay_inquiries (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    claimed_income_source text NOT NULL,
    tenant_note text,
    admin_notes text,
    reviewed_by_user_id uuid,
    reviewed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    proof_file_path text,
    proof_original_name text,
    proof_uploaded_at timestamp with time zone,
    desired_pull_day integer,
    benefit_schedule text,
    held_at timestamp with time zone,
    hold_reason text,
    auto_verification jsonb,
    CONSTRAINT flexpay_inquiries_benefit_schedule_check CHECK (((benefit_schedule IS NULL) OR (benefit_schedule = ANY (ARRAY['ssi_day_1'::text, 'ssdi_day_3'::text, 'ssdi_wed_2'::text, 'ssdi_wed_3'::text, 'ssdi_wed_4'::text, 'fixed_day'::text])))),
    CONSTRAINT flexpay_inquiries_claimed_income_source_check CHECK ((claimed_income_source = ANY (ARRAY['ssi'::text, 'ssdi'::text, 'other_fixed'::text, 'none'::text]))),
    CONSTRAINT flexpay_inquiries_desired_pull_day_check CHECK (((desired_pull_day IS NULL) OR ((desired_pull_day >= 1) AND (desired_pull_day <= 28)))),
    CONSTRAINT flexpay_inquiries_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'declined'::text])))
);


--
-- Name: flexsuite_enrollment_acceptances; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.flexsuite_enrollment_acceptances (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    product_type text NOT NULL,
    template_version text NOT NULL,
    populated_content jsonb NOT NULL,
    rendered_text text NOT NULL,
    content_hash text NOT NULL,
    accepted_at timestamp with time zone DEFAULT now() NOT NULL,
    accepted_ip text,
    accepted_user_agent text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT flexsuite_enrollment_acceptances_product_type_check CHECK ((product_type = ANY (ARRAY['flexpay'::text, 'flexdeposit'::text])))
);


--
-- Name: TABLE flexsuite_enrollment_acceptances; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.flexsuite_enrollment_acceptances IS 'Audit record per FlexPay / FlexDeposit enrollment click-through. Stores the populated terms text the tenant saw at acceptance, hash-anchored. Structural defense for SLA-not-loan / subscription characterization.';


--
-- Name: float_account_state; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.float_account_state (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    balance numeric(10,2) DEFAULT 25000 NOT NULL,
    seed_capital numeric(10,2) DEFAULT 25000 NOT NULL,
    apy numeric(5,4) DEFAULT 0.045 NOT NULL,
    monthly_interest numeric(10,2) DEFAULT 0,
    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: TABLE float_account_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.float_account_state IS 'GAM''s FlexPay float. balance is REAL money available to advance (0 until funded from reinvested revenue + tips). Superseded model figures, seeded 2026-05-15 and zeroed S642: balance 26750, seed_capital 25000, apy 0.045, monthly_interest 100.';


--
-- Name: generated_routes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.generated_routes (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    vehicle_id uuid NOT NULL,
    depot_id uuid NOT NULL,
    generated_for_date date NOT NULL,
    start_at_planned timestamp with time zone NOT NULL,
    generated_by_user_id uuid,
    status text DEFAULT 'generated'::text NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    total_miles numeric(10,2) NOT NULL,
    total_minutes numeric(10,2) NOT NULL,
    stop_count integer NOT NULL,
    dump_count integer NOT NULL,
    skipped_ungeocoded_count integer DEFAULT 0 NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    last_lat numeric(9,6),
    last_lon numeric(9,6),
    last_position_at timestamp with time zone,
    CONSTRAINT generated_routes_completed_audit CHECK (((status <> 'completed'::text) OR (completed_at IS NOT NULL))),
    CONSTRAINT generated_routes_started_audit CHECK (((status = 'generated'::text) OR (started_at IS NOT NULL))),
    CONSTRAINT generated_routes_status_check CHECK ((status = ANY (ARRAY['generated'::text, 'in_progress'::text, 'completed'::text])))
);


--
-- Name: held_payout_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.held_payout_items (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    landlord_id uuid,
    business_id uuid,
    source_type text NOT NULL,
    source_id text NOT NULL,
    amount numeric(12,2) NOT NULL,
    description text,
    payout_intent_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    property_id uuid,
    CONSTRAINT held_payout_items_amount_check CHECK ((amount <> (0)::numeric)),
    CONSTRAINT held_payout_items_one_payee CHECK (((landlord_id IS NULL) <> (business_id IS NULL))),
    CONSTRAINT held_payout_items_source_type_check CHECK ((source_type = ANY (ARRAY['pos_sale'::text, 'booking_deposit'::text, 'business_invoice_payment'::text, 'business_pos_sale'::text, 'refund'::text, 'dispute'::text, 'platform_fee'::text, 'prepaid_draw'::text, 'deposit_settlement'::text])))
);


--
-- Name: TABLE held_payout_items; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.held_payout_items IS 'S648: what GAM holds for a landlord or business, outside rent. Positive = owed to them; negative = owed back. Batched weekly via platform_transfer_intents.';


--
-- Name: COLUMN held_payout_items.property_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.held_payout_items.property_id IS '10/12 (Nic, ledger P1): the property this payout line belongs to, written by its writer. NULL: company-level (a business''s line, or a charge''s fee spanning properties).';


--
-- Name: home_ownerships; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.home_ownerships (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    unit_id uuid NOT NULL,
    owner_user_id uuid NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    acquired_via text DEFAULT 'recorded'::text NOT NULL,
    sale_document_id uuid,
    acquired_at timestamp with time zone DEFAULT now() NOT NULL,
    released_at timestamp with time zone,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT home_ownerships_acquired_via_check CHECK ((acquired_via = ANY (ARRAY['recorded'::text, 'sale'::text, 'transfer'::text, 'financed_payoff'::text]))),
    CONSTRAINT home_ownerships_status_check CHECK ((status = ANY (ARRAY['active'::text, 'transferred'::text, 'removed'::text])))
);


--
-- Name: TABLE home_ownerships; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.home_ownerships IS 'S568: who owns the tenant-owned home/RV on a unit. Owner = economic sublessor. Owner may be the occupant, an in-park tenant investor, or an external cross-park investor. History retained (status flips, never deleted).';


--
-- Name: home_sale_assumptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.home_sale_assumptions (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    contract_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    from_tenant_id uuid NOT NULL,
    to_tenant_id uuid NOT NULL,
    effective_month date NOT NULL,
    document_id uuid,
    balance_goes_to text DEFAULT 'leaver'::text NOT NULL,
    note text,
    recorded_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT home_sale_assumption_changes_hands CHECK ((from_tenant_id <> to_tenant_id)),
    CONSTRAINT home_sale_assumption_whole_month CHECK ((effective_month = (date_trunc('month'::text, (effective_month)::timestamp with time zone))::date)),
    CONSTRAINT home_sale_assumptions_balance_goes_to_check CHECK ((balance_goes_to = ANY (ARRAY['leaver'::text, 'space'::text])))
);


--
-- Name: TABLE home_sale_assumptions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.home_sale_assumptions IS '10/23 (Nic): a home-installment sale taken over by the next resident "straight across" — same price, same payment. The contract keeps its original buyer (a watched ledger column); this says who owes it from which month.';


--
-- Name: home_sale_contracts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.home_sale_contracts (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    unit_id uuid NOT NULL,
    lease_id uuid,
    tenant_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    sale_price numeric(12,2) NOT NULL,
    down_payment numeric(12,2) DEFAULT 0 NOT NULL,
    financed_amount numeric(12,2) NOT NULL,
    annual_interest_rate numeric(6,3) DEFAULT 0 NOT NULL,
    term_months integer NOT NULL,
    monthly_payment numeric(12,2) NOT NULL,
    start_month date NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    installments_total integer NOT NULL,
    installments_billed integer DEFAULT 0 NOT NULL,
    installments_paid integer DEFAULT 0 NOT NULL,
    paid_off_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    plan_type text DEFAULT 'amortized'::text NOT NULL,
    purchase_document_id uuid,
    activated_at timestamp with time zone,
    late_fee_enabled boolean DEFAULT false NOT NULL,
    late_fee_grace_days integer,
    late_fee_initial_type text,
    late_fee_initial_amount numeric(12,2),
    late_fee_accrual_type text,
    late_fee_accrual_amount numeric(12,2),
    late_fee_accrual_period text,
    late_fee_accrual_from text,
    late_fee_cap_type text,
    late_fee_cap_amount numeric(12,2),
    card_payments_blocked boolean DEFAULT false NOT NULL,
    tracked_not_billed boolean DEFAULT false NOT NULL,
    CONSTRAINT home_sale_contracts_annual_interest_rate_check CHECK ((annual_interest_rate >= (0)::numeric)),
    CONSTRAINT home_sale_contracts_down_payment_check CHECK ((down_payment >= (0)::numeric)),
    CONSTRAINT home_sale_contracts_financed_amount_check CHECK ((financed_amount >= (0)::numeric)),
    CONSTRAINT home_sale_contracts_late_fee_accrual_from_check CHECK (((late_fee_accrual_from IS NULL) OR (late_fee_accrual_from = ANY (ARRAY['grace_end'::text, 'due_date'::text])))),
    CONSTRAINT home_sale_contracts_late_fee_accrual_period_check CHECK (((late_fee_accrual_period IS NULL) OR (late_fee_accrual_period = ANY (ARRAY['daily'::text, 'weekly'::text, 'monthly'::text])))),
    CONSTRAINT home_sale_contracts_late_fee_accrual_type_check CHECK (((late_fee_accrual_type IS NULL) OR (late_fee_accrual_type = ANY (ARRAY['flat'::text, 'percent'::text])))),
    CONSTRAINT home_sale_contracts_late_fee_cap_type_check CHECK (((late_fee_cap_type IS NULL) OR (late_fee_cap_type = ANY (ARRAY['flat'::text, 'percent'::text])))),
    CONSTRAINT home_sale_contracts_late_fee_grace_days_check CHECK (((late_fee_grace_days IS NULL) OR (late_fee_grace_days >= 0))),
    CONSTRAINT home_sale_contracts_late_fee_initial_type_check CHECK (((late_fee_initial_type IS NULL) OR (late_fee_initial_type = ANY (ARRAY['flat'::text, 'percent'::text])))),
    CONSTRAINT home_sale_contracts_monthly_payment_check CHECK ((monthly_payment >= (0)::numeric)),
    CONSTRAINT home_sale_contracts_plan_type_check CHECK ((plan_type = ANY (ARRAY['amortized'::text, 'flat'::text]))),
    CONSTRAINT home_sale_contracts_sale_price_check CHECK ((sale_price > (0)::numeric)),
    CONSTRAINT home_sale_contracts_status_check CHECK ((status = ANY (ARRAY['pending_signature'::text, 'active'::text, 'paid_off'::text, 'cancelled'::text]))),
    CONSTRAINT home_sale_contracts_term_months_check CHECK (((term_months > 0) AND (term_months <= 600)))
);


--
-- Name: TABLE home_sale_contracts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.home_sale_contracts IS 'S568: financed sale of a landlord-owned home/RV to a tenant. Space rent stays separate; this is the amortized purchase installment (type=home_payment), auto-stops at term, flips unit to tenant-owned on payoff.';


--
-- Name: COLUMN home_sale_contracts.plan_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.home_sale_contracts.plan_type IS 'S594: amortized (price+interest+term) or flat ($X × N, no interest). Flat is stored as 0% amortization so downstream billing/payoff is identical.';


--
-- Name: COLUMN home_sale_contracts.purchase_document_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.home_sale_contracts.purchase_document_id IS 'S629: the signed purchase agreement this billing comes from. 10/12 (Nic): the contract stays pending_signature until the LANDLORD signs it (a buyer who belongs to another company: until the buyer signs, S655); that signature writes the schedule and starts the billing.';


--
-- Name: COLUMN home_sale_contracts.activated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.home_sale_contracts.activated_at IS '10/12 (ledger P1): when the sale went active (started billing). NULL for a sale never activated.';


--
-- Name: COLUMN home_sale_contracts.late_fee_enabled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.home_sale_contracts.late_fee_enabled IS 'The signed installment contract charges a late fee. Default FALSE: a fee
   nobody signed for is never charged. The bill is written late_fee_exempt
   while this is false (services/homeSale ownBillFor).';


--
-- Name: COLUMN home_sale_contracts.card_payments_blocked; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.home_sale_contracts.card_payments_blocked IS 'Refuse card payments on this contract''s bills (Nic, 10/25). For an
   installment whose money belongs to another set of books — Dominic Gonzalez''s
   goes to the trust — where a chargeback would have to be unwound twice.';


--
-- Name: COLUMN home_sale_contracts.tracked_not_billed; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.home_sale_contracts.tracked_not_billed IS 'TRUE: GAM bills nothing for this contract — no invoice, no charge, no money
   through GAM. It keeps the schedule, reminds when a payment is due, and records
   it when somebody marks it paid (home_sale_installments.settled_off_platform_at).
   For an installment whose money belongs to another set of books: Dominic
   Gonzalez pays the trust, not the park. Default FALSE = GAM invoices it.';


--
-- Name: home_sale_installments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.home_sale_installments (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    contract_id uuid NOT NULL,
