    revoked_by_user_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    first_name text,
    last_name text,
    phone text,
    CONSTRAINT invitations_role_check CHECK ((role = ANY (ARRAY['property_manager'::text, 'onsite_manager'::text, 'maintenance'::text, 'bookkeeper'::text]))),
    CONSTRAINT invitations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'expired'::text, 'revoked'::text])))
);


--
-- Name: invoice_sequences; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.invoice_sequences (
    landlord_id uuid NOT NULL,
    year integer NOT NULL,
    next_number integer DEFAULT 1 NOT NULL
);


--
-- Name: invoices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.invoices (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    landlord_id uuid NOT NULL,
    tenant_id uuid,
    lease_id uuid,
    unit_id uuid NOT NULL,
    invoice_number text NOT NULL,
    due_date date NOT NULL,
    subtotal_rent numeric(12,2) DEFAULT 0 NOT NULL,
    subtotal_fees numeric(12,2) DEFAULT 0 NOT NULL,
    subtotal_utilities numeric(12,2) DEFAULT 0 NOT NULL,
    subtotal_deposits numeric(12,2) DEFAULT 0 NOT NULL,
    subtotal_late_fees numeric(12,2) DEFAULT 0 NOT NULL,
    total_amount numeric(12,2) NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    sent_at timestamp with time zone,
    viewed_at timestamp with time zone,
    pdf_url text,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    work_trade_credit_amount numeric(12,2) DEFAULT 0 NOT NULL,
    work_trade_credit_hours numeric(8,2) DEFAULT 0 NOT NULL,
    work_trade_agreement_id uuid,
    is_opening_balance boolean DEFAULT false NOT NULL,
    late_fee_exempt boolean DEFAULT false NOT NULL,
    service_agreement_id uuid,
    subtotal_home_payments numeric(12,2) DEFAULT 0 NOT NULL,
    voided_from_lease_id uuid,
    home_sale_contract_id uuid,
    CONSTRAINT invoices_payer_source_check CHECK (((((((lease_id IS NOT NULL))::integer + ((service_agreement_id IS NOT NULL))::integer) + ((home_sale_contract_id IS NOT NULL))::integer) = 1) OR ((status = 'void'::text) AND (lease_id IS NULL) AND (service_agreement_id IS NULL) AND (home_sale_contract_id IS NULL) AND (voided_from_lease_id IS NOT NULL)))),
    CONSTRAINT invoices_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'partial'::text, 'settled'::text, 'void'::text]))),
    CONSTRAINT invoices_subtotal_deposits_check CHECK ((subtotal_deposits >= (0)::numeric)),
    CONSTRAINT invoices_subtotal_fees_check CHECK ((subtotal_fees >= (0)::numeric)),
    CONSTRAINT invoices_subtotal_late_fees_check CHECK ((subtotal_late_fees >= (0)::numeric)),
    CONSTRAINT invoices_subtotal_rent_check CHECK ((subtotal_rent >= (0)::numeric)),
    CONSTRAINT invoices_subtotal_utilities_check CHECK ((subtotal_utilities >= (0)::numeric)),
    CONSTRAINT invoices_total_amount_check CHECK ((total_amount >= (0)::numeric)),
    CONSTRAINT invoices_voided_from_lease_check CHECK (((voided_from_lease_id IS NULL) OR ((status = 'void'::text) AND (lease_id IS NULL)))),
    CONSTRAINT invoices_work_trade_credit_nonneg CHECK (((work_trade_credit_amount >= (0)::numeric) AND (work_trade_credit_hours >= (0)::numeric)))
);


--
-- Name: COLUMN invoices.is_opening_balance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.invoices.is_opening_balance IS 'S605: a balance carried in from the landlord''s prior system, not generated by the billing engine.';


--
-- Name: COLUMN invoices.late_fee_exempt; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.invoices.late_fee_exempt IS 'S605: the nightly late-fee engine skips this invoice. Defaults TRUE on carried balances so migrated arrears do not start compounding; landlord may override per balance.';


--
-- Name: COLUMN invoices.service_agreement_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.invoices.service_agreement_id IS 'S615: set when this invoice bills a space the landlord SERVICES but does not lease (cross-property utilities). Mutually exclusive with lease_id. Such an invoice carries utility rows only — there is no rent to charge.';


--
-- Name: COLUMN invoices.subtotal_home_payments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.invoices.subtotal_home_payments IS 'S654: home-sale installments riding this invoice (type=home_payment rows); gross, like the other subtotals.';


--
-- Name: COLUMN invoices.voided_from_lease_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.invoices.voided_from_lease_id IS '10/12 (G7): the lease a void bill was written on, when the void gave the lease''s due date back (lease_id is then NULL): a bill a shortened stay emptied. Kept forever.';


--
-- Name: COLUMN invoices.home_sale_contract_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.invoices.home_sale_contract_id IS 'The installment (home/trailer) sale this bill is for. Set => the bill is that
   contract''s own document, paid by itself, and carries no space rent. NULL on
   every lease bill and every utility-service bill.';


--
-- Name: journal_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.journal_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    landlord_id uuid,
    entry_number integer NOT NULL,
    date date NOT NULL,
    description text NOT NULL,
    reference text,
    type character varying(30) DEFAULT 'manual'::character varying,
    status character varying(20) DEFAULT 'posted'::character varying,
    total_debits numeric(12,2) DEFAULT 0,
    total_credits numeric(12,2) DEFAULT 0,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    business_id uuid,
    adjusts_line_key text,
    reverses_entry_id uuid,
    voided_at timestamp with time zone,
    voided_by uuid,
    CONSTRAINT journal_entries_adjusting_key CHECK (((adjusts_line_key IS NULL) OR (((type)::text = 'adjusting'::text) AND (adjusts_line_key ~ '^[a-z_]+:[0-9A-Za-z._:|-]{1,200}$'::text)))),
    CONSTRAINT journal_entries_not_its_own_reversal CHECK (((reverses_entry_id IS NULL) OR (reverses_entry_id <> id))),
    CONSTRAINT journal_entries_one_owner CHECK ((num_nonnulls(landlord_id, business_id) <= 1)),
    CONSTRAINT journal_entries_reversing_names_entry CHECK ((((type)::text = 'reversing'::text) = (reverses_entry_id IS NOT NULL))),
    CONSTRAINT journal_entries_type_check CHECK (((type)::text = ANY ((ARRAY['manual'::character varying, 'adjusting'::character varying, 'reversing'::character varying])::text[])))
);


--
-- Name: journal_entries_entry_number_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.journal_entries_entry_number_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: journal_entries_entry_number_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.journal_entries_entry_number_seq OWNED BY public.journal_entries.entry_number;


--
-- Name: journal_entry_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.journal_entry_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entry_id uuid NOT NULL,
    account_id uuid NOT NULL,
    description text,
    debit numeric(12,2) DEFAULT 0 NOT NULL,
    credit numeric(12,2) DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    property_id uuid,
    unit_id uuid,
    lease_id uuid,
    CONSTRAINT journal_entry_lines_amounts_check CHECK (((debit >= (0)::numeric) AND (credit >= (0)::numeric)))
);


--
-- Name: landlord_deposit_interest_rate_overrides; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.landlord_deposit_interest_rate_overrides (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    landlord_id uuid NOT NULL,
    state_code text NOT NULL,
    effective_year integer NOT NULL,
    annual_rate_pct numeric(6,4) NOT NULL,
    source_notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ldior_rate_check CHECK (((annual_rate_pct >= (0)::numeric) AND (annual_rate_pct <= (100)::numeric))),
    CONSTRAINT ldior_state_check CHECK (((state_code = upper(state_code)) AND (length(state_code) = 2))),
    CONSTRAINT ldior_year_check CHECK (((effective_year >= 2020) AND (effective_year <= 2100)))
);


--
-- Name: TABLE landlord_deposit_interest_rate_overrides; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.landlord_deposit_interest_rate_overrides IS 'Per-landlord, per-state, per-year deposit interest rate. Falls back path when state_deposit_interest_rates has no row for the (state, year). Used for variable-rate statutory states (NY/NJ/CT/IL/PA/NH) where the rate depends on the landlord''s bank.';


--
-- Name: COLUMN landlord_deposit_interest_rate_overrides.source_notes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_deposit_interest_rate_overrides.source_notes IS 'Free-text — landlord captures their bank name + current passbook rate, the state-published rate, or the date they verified it. Audit trail for "why this rate".';


--
-- Name: landlord_expense_payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.landlord_expense_payments (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    expense_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    paid_on date NOT NULL,
    amount numeric(12,2) NOT NULL,
    method text NOT NULL,
    bank_connection_id uuid,
    bank_transaction_id uuid,
    source text NOT NULL,
    memo text,
    voided_at timestamp with time zone,
    voided_by uuid,
    void_reason text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT landlord_expense_payments_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT landlord_expense_payments_line_is_bank CHECK (((bank_transaction_id IS NULL) OR (method = ANY (ARRAY['bank'::text, 'check'::text])))),
    CONSTRAINT landlord_expense_payments_match_names_line CHECK (((source <> 'bank_match'::text) OR (bank_transaction_id IS NOT NULL))),
    CONSTRAINT landlord_expense_payments_method_check CHECK ((method = ANY (ARRAY['bank'::text, 'check'::text, 'card'::text, 'cash'::text, 'owner_paid'::text, 'other'::text]))),
    CONSTRAINT landlord_expense_payments_source_check CHECK ((source = ANY (ARRAY['payment'::text, 'bank_match'::text, 'migrated'::text]))),
    CONSTRAINT landlord_expense_payments_void_is_stamped CHECK (((voided_by IS NULL) OR (voided_at IS NOT NULL)))
);


--
-- Name: TABLE landlord_expense_payments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.landlord_expense_payments IS '10/12 (Nic, L5): every payment toward an expense — when, how much, how, and the bank line that paid it. An expense''s paid / unpaid state is worked out from these (v_expense_balance). Never deleted; a payment taken back is voided.';


--
-- Name: landlord_expenses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.landlord_expenses (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    landlord_id uuid NOT NULL,
    property_id uuid,
    unit_id uuid,
    category text NOT NULL,
    amount numeric(12,2) NOT NULL,
    description text,
    vendor text,
    expense_date date NOT NULL,
    is_common boolean DEFAULT false NOT NULL,
    allocate_per_unit boolean DEFAULT false NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    voided_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    receipt_url text,
    receipt_name text,
    receipt_mime text,
    receipt_size integer,
    utility_type text,
    bank_transaction_id uuid,
    category_id uuid,
    vendor_id uuid,
    bill_number text,
    due_date date,
    payments_tracked boolean DEFAULT false NOT NULL,
    maintenance_request_id uuid,
    work_trade_extra_hours_id uuid,
    allocation_split_id uuid,
    migrated_from_table text,
    migrated_from_id uuid,
    cost_place text,
    CONSTRAINT landlord_expenses_amount_check CHECK ((amount >= (0)::numeric)),
    CONSTRAINT landlord_expenses_bill_number_check CHECK (((bill_number IS NULL) OR (length(bill_number) <= 100))),
    CONSTRAINT landlord_expenses_check CHECK ((((unit_id IS NOT NULL) AND (is_common = false)) OR (unit_id IS NULL))),
    CONSTRAINT landlord_expenses_cost_place_check CHECK (((cost_place IS NULL) OR ((cost_place = 'unit'::text) AND (unit_id IS NOT NULL)) OR ((cost_place = 'property'::text) AND (property_id IS NOT NULL) AND (unit_id IS NULL)) OR ((cost_place = 'split_by_units'::text) AND (property_id IS NULL) AND (unit_id IS NULL)))),
    CONSTRAINT landlord_expenses_migrated_from_check CHECK ((((migrated_from_table IS NULL) = (migrated_from_id IS NULL)) AND ((migrated_from_table IS NULL) OR (migrated_from_table = ANY (ARRAY['books_bills'::text, 'books_transactions'::text]))))),
    CONSTRAINT landlord_expenses_status_check CHECK ((status = ANY (ARRAY['active'::text, 'voided'::text]))),
    CONSTRAINT landlord_expenses_utility_type_check CHECK (((utility_type IS NULL) OR (utility_type = ANY (ARRAY['water'::text, 'gas'::text, 'electric'::text, 'sewer'::text, 'trash'::text, 'propane'::text]))))
);


--
-- Name: TABLE landlord_expenses; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.landlord_expenses IS 'S568: landlord-entered expenses (unit-linked or common; common can allocate per unit). Feeds the landlord P&L expense side. Soft-void, never hard-delete.';


--
-- Name: COLUMN landlord_expenses.utility_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_expenses.utility_type IS 'S613: which utility this expense was for, when category = utilities. NULL is fine and means "utilities, unspecified" — it still counts in the total spent.';


--
-- Name: COLUMN landlord_expenses.category_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_expenses.category_id IS '10/12 (Nic, L5): the company''s category this expense is filed under (books_categories). category (text) keeps the older reports'' word: the seeded key, else ''other''.';


--
-- Name: COLUMN landlord_expenses.payments_tracked; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_expenses.payments_tracked IS '10/12 (Nic, L5): TRUE = written by code that records its own payments (landlord_expense_payments). FALSE = an older writer; the AFTER INSERT trigger records it as paid in full that day, as the old screens meant.';


--
-- Name: COLUMN landlord_expenses.allocation_split_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_expenses.allocation_split_id IS '10/12 (Nic, L18): the manager''s cut GAM held too little to pay — the unpaid bill the landlord owes the manager. Its cost posts from the split (ledger ''allocation''); the bill posts its payments only.';


--
-- Name: COLUMN landlord_expenses.cost_place; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_expenses.cost_place IS '10/13 (Nic): where this cost goes, picked when it was logged — split_by_units (across the company''s properties by units on its day; property and unit NULL), property, or unit. NULL: logged before 10/13 (its property, else the Company column) or a bill GAM made for another record that places no cost. BOOKS_COST_PLACES.';


--
-- Name: landlord_gam_balance_marks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.landlord_gam_balance_marks (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    landlord_id uuid NOT NULL,
    peak_owed numeric(12,2) NOT NULL,
    threshold numeric(12,2) NOT NULL,
    debited boolean DEFAULT false NOT NULL,
    observed_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: landlord_gam_charge_collections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.landlord_gam_charge_collections (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    charge_id uuid NOT NULL,
    platform_transfer_intent_id uuid,
    landlord_gam_debit_id uuid,
    amount numeric(12,2) NOT NULL,
    collected_at timestamp with time zone DEFAULT now() NOT NULL,
    derived boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT landlord_gam_charge_collections_amount_positive CHECK ((amount > (0)::numeric)),
    CONSTRAINT landlord_gam_charge_collections_one_source CHECK (((platform_transfer_intent_id IS NULL) <> (landlord_gam_debit_id IS NULL)))
);


--
-- Name: TABLE landlord_gam_charge_collections; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.landlord_gam_charge_collections IS '10/12 (ledger P0): one row per GAM charge collected per source — a payout batch that netted it (platform_transfer_intent_id) or a bank pull that collected it (landlord_gam_debit_id). Σ amount per charge = landlord_gam_charges.collected_amount. derived = written by the 20261013090000 replay, not at collection.';


--
-- Name: landlord_gam_charges; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.landlord_gam_charges (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    landlord_id uuid NOT NULL,
    property_id uuid,
    kind text NOT NULL,
    amount numeric(12,2) NOT NULL,
    collected_amount numeric(12,2) DEFAULT 0 NOT NULL,
    collected_at timestamp with time zone,
    source_type text NOT NULL,
    source_id uuid,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    voided_at timestamp with time zone,
    void_reason text,
    reader_order_id uuid,
    installment_number smallint,
    CONSTRAINT collected_never_exceeds_amount CHECK ((collected_amount <= amount)),
    CONSTRAINT landlord_gam_charges_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT landlord_gam_charges_collected_amount_check CHECK ((collected_amount >= (0)::numeric)),
    CONSTRAINT landlord_gam_charges_kind_check CHECK ((kind = ANY (ARRAY['subscription'::text, 'manual_payment_fee'::text, 'bank_debit_cost'::text, 'device_installment'::text, 'screening_fee'::text, 'bank_debit_failed_cost'::text, 'uncovered_processing_fee'::text]))),
    CONSTRAINT landlord_gam_charges_reader_piece_check CHECK ((((reader_order_id IS NULL) = (installment_number IS NULL)) AND ((installment_number IS NULL) OR (installment_number > 0)))),
    CONSTRAINT landlord_gam_charges_void_is_stamped CHECK (((voided_at IS NULL) = (void_reason IS NULL))),
    CONSTRAINT landlord_gam_charges_void_reason_check CHECK (((void_reason IS NULL) OR (void_reason = ANY (ARRAY['bank_debit_not_made'::text, 'screening_payment_taken_back'::text, 'bank_debit_failed'::text, 'dispute_won'::text, 'dispute_cost_rebilled'::text]))))
);


--
-- Name: COLUMN landlord_gam_charges.kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_charges.kind IS 'subscription = the monthly platform fee. manual_payment_fee = a fee on a payment taken outside the platform (history). bank_debit_cost = S651, the $6 price of the bank pull that collects GAM''s fees, its own line. device_installment = a card reader piece. screening_fee = a background check paid inside a stay. bank_debit_failed_cost = 10/12, what a failed or returned bank pull actually cost GAM (Stripe''s fees on it), passed on at cost. uncovered_processing_fee = 10/12, the part of a processing fee the landlord covers that was more than the money GAM held from that payment.';


--
-- Name: COLUMN landlord_gam_charges.voided_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_charges.voided_at IS '10/12 (ledger P0): set when GAM takes the charge back (it is then owed by nobody); the row is kept. Readers of what a landlord owes skip voided rows.';


--
-- Name: COLUMN landlord_gam_charges.void_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_charges.void_reason IS '10/12: why the charge was voided — @gam/shared LANDLORD_GAM_CHARGE_VOID_REASONS.';


--
-- Name: COLUMN landlord_gam_charges.reader_order_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_charges.reader_order_id IS '10/12 (ledger P0): the card reader order this device_installment piece pays (pos_reader_orders). With installment_number, unique.';


--
-- Name: COLUMN landlord_gam_charges.installment_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_charges.installment_number IS '10/12: which piece of the reader order (1..installments).';


--
-- Name: landlord_gam_debits; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.landlord_gam_debits (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    landlord_id uuid NOT NULL,
    charges_amount numeric(12,2) NOT NULL,
    bank_cost_amount numeric(12,2) DEFAULT 0 NOT NULL,
    total_amount numeric(12,2) NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    stripe_payment_intent_id text,
    payment_method_id text,
    failure_reason text,
    charge_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    threshold_at_debit numeric(12,2),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    settled_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    failure_cost_amount numeric(12,2),
    failure_cost_charge_id uuid,
    failure_cost_read_at timestamp with time zone,
    disputed_at timestamp with time zone,
    stripe_dispute_id text,
    dispute_reopened_amount numeric(12,2),
    dispute_cost_amount numeric(12,2),
    dispute_cost_charge_id uuid,
    dispute_cost_read_at timestamp with time zone,
    dispute_fee_amount numeric(12,2),
    dispute_fee_assumed_at timestamp with time zone,
    dispute_fee_stated_at timestamp with time zone,
    dispute_won_at timestamp with time zone,
    dispute_won_restored_amount numeric(12,2),
    dispute_won_given_back_amount numeric(12,2),
    CONSTRAINT landlord_gam_debits_bank_cost_amount_check CHECK ((bank_cost_amount >= (0)::numeric)),
    CONSTRAINT landlord_gam_debits_charges_amount_check CHECK ((charges_amount > (0)::numeric)),
    CONSTRAINT landlord_gam_debits_dispute_cost_shape CHECK ((((dispute_cost_amount IS NULL) OR (dispute_cost_amount >= (0)::numeric)) AND ((dispute_cost_amount IS NULL) = (dispute_cost_read_at IS NULL)) AND ((dispute_cost_read_at IS NULL) OR (disputed_at IS NOT NULL)) AND ((dispute_cost_charge_id IS NULL) OR (dispute_cost_amount > (0)::numeric)))),
    CONSTRAINT landlord_gam_debits_dispute_fee_shape CHECK ((((dispute_fee_amount IS NULL) OR ((dispute_fee_amount >= (0)::numeric) AND (dispute_cost_read_at IS NOT NULL))) AND ((dispute_fee_assumed_at IS NULL) OR (dispute_fee_amount IS NOT NULL)) AND ((dispute_fee_stated_at IS NULL) OR (dispute_fee_amount IS NOT NULL)))),
    CONSTRAINT landlord_gam_debits_dispute_won_shape CHECK ((((dispute_won_at IS NULL) OR (disputed_at IS NOT NULL)) AND ((dispute_won_at IS NULL) = (dispute_won_restored_amount IS NULL)) AND ((dispute_won_at IS NULL) = (dispute_won_given_back_amount IS NULL)) AND ((dispute_won_restored_amount IS NULL) OR (dispute_won_restored_amount >= (0)::numeric)) AND ((dispute_won_given_back_amount IS NULL) OR (dispute_won_given_back_amount >= (0)::numeric)))),
    CONSTRAINT landlord_gam_debits_disputed_shape CHECK ((((disputed_at IS NULL) = (stripe_dispute_id IS NULL)) AND ((disputed_at IS NULL) = (dispute_reopened_amount IS NULL)) AND ((disputed_at IS NULL) OR (status = 'succeeded'::text)) AND ((dispute_reopened_amount IS NULL) OR (dispute_reopened_amount >= (0)::numeric)))),
    CONSTRAINT landlord_gam_debits_failure_cost_check CHECK ((((failure_cost_amount IS NULL) OR (failure_cost_amount >= (0)::numeric)) AND ((failure_cost_amount IS NULL) = (failure_cost_read_at IS NULL)) AND ((failure_cost_charge_id IS NULL) OR (failure_cost_amount > (0)::numeric)))),
    CONSTRAINT landlord_gam_debits_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'succeeded'::text, 'failed'::text, 'canceled'::text]))),
    CONSTRAINT landlord_gam_debits_total_amount_check CHECK ((total_amount > (0)::numeric))
);


--
-- Name: TABLE landlord_gam_debits; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.landlord_gam_debits IS 'S651: every time GAM pulled from a landlord''s bank because there was no payout to net against. One row per attempt, failures kept. charges_amount and bank_cost_amount are separate columns for the same reason they are separate line items — see the migration header.';


--
-- Name: COLUMN landlord_gam_debits.failure_cost_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_debits.failure_cost_amount IS '10/12 (G1): what this failed pull actually cost GAM (Stripe''s fee on the debit plus its failure fee), billed to the landlord at cost. NULL = not read from Stripe yet.';


--
-- Name: COLUMN landlord_gam_debits.failure_cost_charge_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_debits.failure_cost_charge_id IS '10/12 (G1): the landlord_gam_charges row (kind bank_debit_failed_cost) that bills failure_cost_amount.';


--
-- Name: COLUMN landlord_gam_debits.disputed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_debits.disputed_at IS '10/13 (Nic): when the landlord''s bank disputed this pull and took the money back — every fee it collected was made owed again (collected_amount reduced by what this pull took for it), its own $6 cost line voided (Nic G1), and an admin told. The pull stays succeeded and its landlord_gam_charge_collections rows stay as written; they no longer count toward collected_amount. NULL = not disputed.';


--
-- Name: COLUMN landlord_gam_debits.stripe_dispute_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_debits.stripe_dispute_id IS '10/13: the Stripe dispute that took this pull back (connect_disputes.stripe_dispute_id). Set with disputed_at.';


--
-- Name: COLUMN landlord_gam_debits.dispute_reopened_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_debits.dispute_reopened_amount IS '10/13: what the dispute made owed again across the pull''s charges (its own $6 cost line is voided instead, not counted here). Set with disputed_at.';


--
-- Name: COLUMN landlord_gam_debits.dispute_cost_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_debits.dispute_cost_amount IS '10/13 (Nic G1): what the dispute costs the landlord now, billed at cost — Stripe''s fee on the pull plus Stripe''s dispute fee; after a win (dispute_won_at), only the part of the dispute fee Stripe kept. A correction or a win re-bills it (migration 20261015180000). NULL = not read from Stripe yet (the nightly sweep asks again).';


--
-- Name: COLUMN landlord_gam_debits.dispute_cost_charge_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_debits.dispute_cost_charge_id IS '10/13: the landlord_gam_charges row (kind bank_debit_failed_cost, source_type gam_bank_debit_disputed) that bills dispute_cost_amount now. A re-bill voids the one before it (reason dispute_cost_rebilled or dispute_won) and points here at the new one (source_id md5(''<pull id>:<basis>'')::uuid). NULL when it costs nothing.';


--
-- Name: COLUMN landlord_gam_debits.dispute_cost_read_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_debits.dispute_cost_read_at IS '10/13: when dispute_cost_amount was read from Stripe. NULL = not read yet.';


--
-- Name: COLUMN landlord_gam_debits.dispute_fee_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_debits.dispute_fee_amount IS '10/13 (Nic): Stripe''s dispute fee inside dispute_cost_amount — Stripe''s own word, or $15 (Stripe''s usual fee) when Stripe had not stated it three days after the dispute (dispute_fee_assumed_at). NULL = not read yet.';


--
-- Name: COLUMN landlord_gam_debits.dispute_fee_assumed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_debits.dispute_fee_assumed_at IS '10/13 (Nic: "Dispute fee unknown → bill $15"): when $15 was billed as the dispute fee because Stripe had not stated it. Kept as history; dispute_fee_stated_at says when Stripe''s word replaced it.';


--
-- Name: COLUMN landlord_gam_debits.dispute_fee_stated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_debits.dispute_fee_stated_at IS '10/13: when Stripe''s own word on its dispute fee was recorded — at the first read, or correcting the $15 assumed (the bill re-billed to it, never billed twice). NULL with dispute_fee_assumed_at set: still the $15, and the sweep keeps asking Stripe.';


--
-- Name: COLUMN landlord_gam_debits.dispute_won_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_debits.dispute_won_at IS '10/13 (Nic: "Won GAM pull dispute: AUTOMATIC (back to collected; anything collected twice credited back)"): when Stripe''s win for GAM was applied — every charge the pull collected back to collected, its own $6 cost line un-voided and collected (+$6 earned again on GAM''s book: banking_spread, reference_type gam_bank_debit_dispute_won), what was collected twice given back on held_payout_items lines (refund, gam_debit_dispute_won:<pull>:<charge>), the dispute''s cost charge voided (dispute_won; collected part given back, gam_charge_voided:<charge>). The pull''s ''cancellation'' posting is taken back by the ledger. NULL = not won (or not applied yet).';


--
-- Name: COLUMN landlord_gam_debits.dispute_won_restored_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_debits.dispute_won_restored_amount IS '10/13: what the win put back to collected across the pull''s charges, its own $6 cost line included. Set with dispute_won_at.';


--
-- Name: COLUMN landlord_gam_debits.dispute_won_given_back_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_gam_debits.dispute_won_given_back_amount IS '10/13: what the win gave back to the landlord on their next payout (held_payout_items, source_type refund): charges collected again since the dispute (collected twice), what the pull had paid on charges voided since (gam_debit_dispute_won:<pull>:<charge> both), and what was collected on the voided dispute cost charge (gam_charge_voided:<charge>). Set with dispute_won_at.';


--
-- Name: landlord_instant_margins; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.landlord_instant_margins (
