    CONSTRAINT landlord_instant_margins_status_check CHECK ((status = ANY (ARRAY['owed'::text, 'collected'::text])))
);


--
-- Name: landlord_member_history; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.landlord_member_history (
