);


--
-- Name: COLUMN landlord_members.role; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_members.role IS '10/22: owner = the account owns this company; manager = the account manages its properties for the owner, inside a scope and permissions the owner granted (services/managedCompanies).';


--
-- Name: COLUMN landlord_members.via_pm_company_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_members.via_pm_company_id IS 'The management company this access came through, when it came through one. NULL = the owner added this person directly (in-house staff).';


--
-- Name: landlord_merchant_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.landlord_merchant_rules (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    landlord_id uuid NOT NULL,
    normalized_merchant text NOT NULL,
    category text NOT NULL,
    scope_kind text NOT NULL,
    property_id uuid,
    unit_id uuid,
    hit_count integer DEFAULT 1 NOT NULL,
    last_used_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    last_direction text,
    auto_file_income boolean DEFAULT true NOT NULL,
    category_id uuid,
    CONSTRAINT landlord_merchant_rules_last_direction_check CHECK (((last_direction IS NULL) OR (last_direction = ANY (ARRAY['in'::text, 'out'::text])))),
    CONSTRAINT landlord_merchant_rules_scope_kind_check CHECK ((scope_kind = ANY (ARRAY['unit'::text, 'property_common'::text, 'property_allocate'::text])))
);


--
-- Name: TABLE landlord_merchant_rules; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.landlord_merchant_rules IS 'S570: per-landlord memory of how a merchant was last categorized (category + scope). Pre-fills the bank-feed suggestion; never auto-books — landlord confirms.';


--
-- Name: COLUMN landlord_merchant_rules.last_direction; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_merchant_rules.last_direction IS 'S655: whether the landlord last filed money IN or OUT from this payer. Auto-filing needs in.';


--
-- Name: COLUMN landlord_merchant_rules.auto_file_income; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_merchant_rules.auto_file_income IS 'S655 (Nic): after the landlord files money IN from this payer once (last_direction = in), later deposits from the same payer file themselves as the same income, labeled, with one-click undo. Never for money out, a rent-channel payer (RENT_CHANNEL_PAYERS), a payer ever matched to a tenant bill, or a deposit that equals any open bill. Undo can switch this off for the payer.';


--
-- Name: landlord_onboarding_booking_tokens; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.landlord_onboarding_booking_tokens (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    token uuid DEFAULT public.gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    used_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    first_clicked_at timestamp with time zone,
    click_count integer DEFAULT 0 NOT NULL
);


--
-- Name: TABLE landlord_onboarding_booking_tokens; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.landlord_onboarding_booking_tokens IS 'S605: opaque prefill credential for the onboarding-call booking link in the post-signup outreach email. Trades server-side for the landlord''s own name/email so the form does not re-ask. Not single-use — expiry is the bound, so a reschedule from the same email still works.';


--
-- Name: COLUMN landlord_onboarding_booking_tokens.first_clicked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_onboarding_booking_tokens.first_clicked_at IS 'S605: when the landlord first opened the booking link from the outreach email. The honest alternative to open-pixel tracking.';


--
-- Name: landlord_other_income; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.landlord_other_income (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    landlord_id uuid NOT NULL,
    property_id uuid,
    unit_id uuid,
    category text NOT NULL,
    amount numeric(12,2) NOT NULL,
    description text,
    payer text,
    income_date date NOT NULL,
    is_common boolean DEFAULT false NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    voided_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    bank_transaction_id uuid,
    category_id uuid,
    migrated_from_table text,
    migrated_from_id uuid,
    CONSTRAINT landlord_other_income_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT landlord_other_income_migrated_from_check CHECK ((((migrated_from_table IS NULL) = (migrated_from_id IS NULL)) AND ((migrated_from_table IS NULL) OR (migrated_from_table = 'books_transactions'::text)))),
    CONSTRAINT landlord_other_income_status_check CHECK ((status = ANY (ARRAY['active'::text, 'voided'::text])))
);


--
-- Name: TABLE landlord_other_income; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.landlord_other_income IS 'S605: landlord income GAM did not collect (laundry, vending, insurance claims, cash rent deposited). Feeds the P&L income side alongside payments. NEVER holds GAM-collected rent — that would double-count.';


--
-- Name: COLUMN landlord_other_income.category_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlord_other_income.category_id IS '10/12 (Nic, L5): the company''s category this money in is filed under (books_categories).';


--
-- Name: landlord_platform_fee_overrides; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.landlord_platform_fee_overrides (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    landlord_id uuid NOT NULL,
    rate_per_unit numeric(10,2),
    min_per_connect_account numeric(10,2),
    effective_from date DEFAULT CURRENT_DATE NOT NULL,
    effective_until date,
    set_by_user_id uuid,
    reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    str_fee_pct numeric(5,4),
    CONSTRAINT landlord_pfo_at_least_one CHECK (((rate_per_unit IS NOT NULL) OR (min_per_connect_account IS NOT NULL))),
    CONSTRAINT landlord_pfo_effective_range CHECK (((effective_until IS NULL) OR (effective_until > effective_from))),
    CONSTRAINT landlord_pfo_min_nonneg CHECK (((min_per_connect_account IS NULL) OR (min_per_connect_account >= (0)::numeric))),
    CONSTRAINT landlord_pfo_rate_nonneg CHECK (((rate_per_unit IS NULL) OR (rate_per_unit >= (0)::numeric)))
);


--
-- Name: landlords; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.landlords (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id uuid NOT NULL,
