    maint_approval_threshold numeric(10,2) DEFAULT 500 NOT NULL,
    theme_accent text,
    font_style text,
    agreement_signed_at timestamp with time zone,
    agreement_signature text,
    management_type text,
    network_tier text DEFAULT 'tier_2_full'::text NOT NULL,
    default_entry_notice_hours integer DEFAULT 24 NOT NULL,
    default_early_termination_months_rent numeric(5,2),
    otp_rollout_enabled boolean DEFAULT false NOT NULL,
    default_pm_company_id uuid,
    flex_charge_disqualified_until timestamp with time zone,
    flex_charge_disqualified_reason text,
    background_provider text DEFAULT 'checkr'::text NOT NULL,
    default_ach_fee_payer text DEFAULT 'tenant'::text NOT NULL,
    pos_default_margin_pct numeric(5,2),
    deposit_return_approval_threshold numeric(10,2) DEFAULT 500 NOT NULL,
    is_demo boolean DEFAULT false NOT NULL,
    stripe_connect_account_id text,
    stripe_connect_status_synced_at timestamp with time zone,
    connect_charges_enabled boolean DEFAULT false NOT NULL,
    connect_payouts_enabled boolean DEFAULT false NOT NULL,
    connect_details_submitted boolean DEFAULT false NOT NULL,
    adverse_action_template text,
    is_system boolean DEFAULT false NOT NULL,
    portfolio_manager_id uuid,
    service_manager_id uuid,
    referred_by_user_id uuid,
    reconciliation_until timestamp with time zone,
    stripe_fc_customer_id text,
    billing_starts_at date,
    billing_grace_until date,
    welcome_outreach_sent_at timestamp with time zone,
    books_start_date date,
    migration_window_ends_at timestamp with time zone,
    first_billing_cycle date,
    gam_debit_authorized_at timestamp with time zone,
    gam_debit_authorized_by_user_id uuid,
    gam_debit_authorized_ip text,
    gam_debit_payment_method_id text,
    gam_debit_bank_last4 text,
    gam_debit_bank_name text,
    gam_debit_revoked_at timestamp with time zone,
    platform_locked_at timestamp with time zone,
    platform_locked_reason text,
    platform_locked_by uuid,
    uncollectable_notice_at timestamp with time zone,
    review_utility_bills boolean DEFAULT false NOT NULL,
    books_timezone text,
    books_close_by text DEFAULT 'owner_or_bookkeeper'::text NOT NULL,
    books_reopen_by text DEFAULT 'owner'::text NOT NULL,
    books_open_month_fixes text DEFAULT 'restate'::text NOT NULL,
    rent_roll_moved_out text DEFAULT 'billed_last_12_months'::text NOT NULL,
    books_history_start text,
    books_home_sale_method text,
    books_work_trade_method text,
    books_company_costs_method text,
    books_write_off_by text DEFAULT 'owner'::text NOT NULL,
    books_register_stock text DEFAULT 'expense_when_bought'::text NOT NULL,
    books_register_stock_from date,
    books_repair_bills text,
    books_company_costs_from timestamp with time zone,
    connect_bank_checked_at timestamp with time zone,
    CONSTRAINT landlords_background_provider_check CHECK ((background_provider = ANY (ARRAY['mock'::text, 'checkr'::text]))),
    CONSTRAINT landlords_books_close_by_check CHECK ((books_close_by = ANY (ARRAY['owner'::text, 'owner_or_bookkeeper'::text]))),
    CONSTRAINT landlords_books_company_costs_method_check CHECK (((books_company_costs_method IS NULL) OR (books_company_costs_method = ANY (ARRAY['company_bucket'::text, 'split_by_units'::text])))),
    CONSTRAINT landlords_books_history_start_check CHECK (((books_history_start IS NULL) OR (books_history_start = ANY (ARRAY['since_joining'::text, 'start_date'::text])))),
    CONSTRAINT landlords_books_home_sale_method_check CHECK (((books_home_sale_method IS NULL) OR (books_home_sale_method = ANY (ARRAY['whole_sale_at_signing'::text, 'income_as_paid'::text])))),
    CONSTRAINT landlords_books_open_month_fixes_check CHECK ((books_open_month_fixes = ANY (ARRAY['restate'::text, 'day_made'::text]))),
    CONSTRAINT landlords_books_register_stock_check CHECK ((books_register_stock = ANY (ARRAY['expense_when_bought'::text, 'cost_per_item_sold'::text]))),
    CONSTRAINT landlords_books_reopen_by_check CHECK ((books_reopen_by = ANY (ARRAY['owner'::text, 'owner_or_bookkeeper'::text]))),
    CONSTRAINT landlords_books_repair_bills_check CHECK (((books_repair_bills IS NULL) OR (books_repair_bills = ANY (ARRAY['automatic'::text, 'button'::text])))),
    CONSTRAINT landlords_books_work_trade_method_check CHECK (((books_work_trade_method IS NULL) OR (books_work_trade_method = ANY (ARRAY['rent_and_labor'::text, 'rent_discount'::text, 'left_out'::text])))),
    CONSTRAINT landlords_books_write_off_by_check CHECK ((books_write_off_by = ANY (ARRAY['owner'::text, 'owner_or_property_manager'::text]))),
    CONSTRAINT landlords_default_ach_fee_payer_check CHECK ((default_ach_fee_payer = ANY (ARRAY['landlord'::text, 'tenant'::text]))),
    CONSTRAINT landlords_first_billing_cycle_is_month CHECK (((first_billing_cycle IS NULL) OR (date_trunc('month'::text, (first_billing_cycle)::timestamp with time zone) = first_billing_cycle))),
    CONSTRAINT landlords_network_tier_check CHECK ((network_tier = 'tier_2_full'::text)),
    CONSTRAINT landlords_pos_default_margin_pct_check CHECK (((pos_default_margin_pct IS NULL) OR ((pos_default_margin_pct >= (0)::numeric) AND (pos_default_margin_pct < (100)::numeric)))),
    CONSTRAINT landlords_rent_roll_moved_out_check CHECK ((rent_roll_moved_out = ANY (ARRAY['billed_last_12_months'::text, 'while_owing'::text, 'all_time'::text]))),
    CONSTRAINT landlords_volume_tier_check CHECK ((volume_tier = ANY (ARRAY['standard'::text, 'growth'::text, 'professional'::text, 'enterprise'::text, 'partner'::text])))
);


--
-- Name: COLUMN landlords.theme_accent; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.theme_accent IS 'S633 SUPERSEDED by users.theme_accent — portal chrome is per account, not per company. Retained as the record of what was set before the move; nothing reads it.';


--
-- Name: COLUMN landlords.font_style; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.font_style IS 'S633 SUPERSEDED by users.font_style. See landlords.theme_accent.';


--
-- Name: COLUMN landlords.background_provider; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.background_provider IS 'S423: which background-check provider this landlord uses. Default mock; flip to checkr once Checkr is provisioned for the landlord.';


--
-- Name: COLUMN landlords.is_system; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.is_system IS 'S564: true for GAM-owned system entities (e.g. the renter-pool intake shell landlord). Excluded from aggregate landlord counts + revenue reports; not a customer.';


--
-- Name: COLUMN landlords.portfolio_manager_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.portfolio_manager_id IS 'The CLOSING portfolio manager — the rep who won this deal (25¢/occupied unit/mo residual). Set via referral code at signup, a claim, or super_admin assignment. NULL = no closer, that 25¢ accrues to the pot. See service_manager_id for the customer-service half.';


--
-- Name: COLUMN landlords.service_manager_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.service_manager_id IS 'The portfolio manager who handles this landlord''s customer service (25¢/occupied unit/mo). NULL = unstaffed, that 25¢ accrues to the pot. Distinct from portfolio_manager_id, which is the CLOSING manager (the other 25¢).';


--
-- Name: COLUMN landlords.referred_by_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.referred_by_user_id IS 'The referring LANDLORD''s user id (S567). Set when this landlord signed up with another landlord''s referral code. That referrer earns the closing 25¢/occupied unit/mo residual (as a closer); customer service still routes to a PM via service_manager_id. Mutually exclusive with portfolio_manager_id.';


--
-- Name: COLUMN landlords.reconciliation_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.reconciliation_until IS 'S568: end of the landlord''s onboarding reconciliation window. While NOW() < this, the FIRST rent invoice of any of the landlord''s leases may be marked paid off-platform (old-system autopay overlap) fee-free. Default now()+21d at creation; admin-extendable.';


--
-- Name: COLUMN landlords.billing_starts_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.billing_starts_at IS 'First billing cycle (first-of-month) platformFeeAccrual bills this landlord. NULL = in onboarding grace / not yet activated (no platform fee). Set to the current cycle on first settled rent (operating), or to the grace cap by the daily grace-cap cron. See PLATFORM_FEE_GRACE_CYCLES.';


--
-- Name: COLUMN landlords.billing_grace_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.billing_grace_until IS 'Cap cycle (first-of-month) at which platform-fee billing must begin if the landlord never activates. Set at signup to first-of-month(signup) + PLATFORM_FEE_GRACE_CYCLES months; superadmin-overridable for long setups. NULL falls back to created_at + 2 months in the cron.';


--
-- Name: COLUMN landlords.welcome_outreach_sent_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.welcome_outreach_sent_at IS 'S605: when the automated post-signup onboarding-call outreach was sent. NULL = not yet sent (or not eligible). Set once, never cleared — the idempotency guard for jobs/landlordWelcomeOutreach.ts.';


--
-- Name: COLUMN landlords.books_start_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.books_start_date IS 'S605: bank transactions posted before this date are imported but auto-ignored, keeping pre-GAM history out of the review queue and the P&L. NULL = no cutoff.';


--
-- Name: COLUMN landlords.first_billing_cycle; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.first_billing_cycle IS 'S632 SUPERSEDED by properties.first_billing_cycle — onboarding is per property. Retained only as the record of what was set before the move; nothing reads it.';


--
-- Name: COLUMN landlords.gam_debit_authorized_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.gam_debit_authorized_at IS 'S651: when GAM first set up a debit path against this landlord''s linked bank. AUDIT ONLY — it is not consent and nothing gates on it. Fee collection is mandatory per the landlord agreement; a debit is simply what happens when there is no payout to net against and the balance crosses the threshold. See services/landlordGamDebit.ts.';


--
-- Name: COLUMN landlords.gam_debit_payment_method_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.gam_debit_payment_method_id IS 'S651: the us_bank_account PaymentMethod GAM pulls fees from, minted from the bank the landlord linked. Filled lazily at the first debit rather than by any landlord action. NULL means no usable link — which blocks collection and raises an alert, it does not excuse the debt.';


--
-- Name: COLUMN landlords.gam_debit_revoked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.gam_debit_revoked_at IS 'S651: DEAD. A landlord cannot revoke fee collection. Kept only so an existing row is not lost; nothing reads it.';


--
-- Name: COLUMN landlords.platform_locked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.platform_locked_at IS 'S652: portal access suspended — owes GAM with no bank to collect from. Set by a person at GAM, never by a job. Tenants are unaffected.';


--
-- Name: COLUMN landlords.books_timezone; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.books_timezone IS '10/12 (Nic, ledger): the calendar company-level ledger lines are dated on. Pinned by the engine to the first property''s timezone when the chart is first set up.';


--
-- Name: COLUMN landlords.books_close_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.books_close_by IS '10/12 (Nic, L3): who may close a month — owner, or owner_or_bookkeeper (Books write access + company-wide box). LEDGER_CLOSE_PERMISSIONS.';


--
-- Name: COLUMN landlords.books_reopen_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.books_reopen_by IS '10/12 (Nic, L3): who may reopen a closed month. LEDGER_CLOSE_PERMISSIONS.';


--
-- Name: COLUMN landlords.books_open_month_fixes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.books_open_month_fixes IS '10/12 (Nic, L4): a fix to an open month — restate (change that month) or day_made (show it on the day made). LEDGER_OPEN_MONTH_FIX_MODES.';


--
-- Name: COLUMN landlords.rent_roll_moved_out; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.rent_roll_moved_out IS '10/12 (Nic): which households that moved out stay on the Rent Roll — billed_last_12_months (default), while_owing, all_time. RENT_ROLL_MOVED_OUT_RULES.';


--
-- Name: COLUMN landlords.books_history_start; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.books_history_start IS '10/12 (Nic): how books_start_date was picked — since_joining (first day of the month the company joined GAM) or start_date (the owner''s date + opening balances). NULL = not chosen. BOOKS_HISTORY_STARTS.';


--
-- Name: COLUMN landlords.books_home_sale_method; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.books_home_sale_method IS '10/12 (Nic, L11): home sales count as the whole sale at signing or as income when paid. NULL = not chosen. BOOKS_HOME_SALE_METHODS.';


--
-- Name: COLUMN landlords.books_work_trade_method; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.books_work_trade_method IS '10/12 (Nic, L12): work-trade hours covering rent count as full rent + a labor cost, or a rent discount. NULL = not chosen. BOOKS_WORK_TRADE_METHODS.';


--
-- Name: COLUMN landlords.books_company_costs_method; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.books_company_costs_method IS 'RETIRED 10/13 (Nic): "there should never be a default setting to apply expenses." Nothing reads it; where a cost goes is picked on each record (cost_place). Kept until a contract migration drops it.';


--
-- Name: COLUMN landlords.books_write_off_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.books_write_off_by IS '10/12 (Nic, L15): who may write off a balance a tenant will never pay — owner, or owner_or_property_manager. Never a bookkeeper. LEDGER_WRITE_OFF_PERMISSIONS.';


--
-- Name: COLUMN landlords.books_register_stock; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.books_register_stock IS '10/12 (Nic, L8): register stock — expense_when_bought or cost_per_item_sold (Inventory → Cost of goods sold per sale). LEDGER_REGISTER_STOCK_METHODS.';


--
-- Name: COLUMN landlords.books_register_stock_from; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.books_register_stock_from IS '10/12 (Nic, L8): the first day the current register-stock choice applies (NULL = from the books start); earlier sales keep their treatment.';


--
-- Name: COLUMN landlords.books_repair_bills; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.books_repair_bills IS '10/12 (Nic, L6): what a repair closed with a cost does — ''automatic'' makes an unpaid bill by itself, ''button'' only on "Record as bill". NULL = not chosen yet (the button is offered).';


--
-- Name: COLUMN landlords.books_company_costs_from; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.books_company_costs_from IS '10/13 (Nic): the moment books_company_costs_method was picked, when the books had already posted — the method applies to company-level costs recorded from then on; costs recorded before stay in the Company column (the default while not chosen). NULL = the method applies to every cost.';


--
-- Name: COLUMN landlords.connect_bank_checked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.landlords.connect_bank_checked_at IS '10/20: when GAM last asked this landlord''s connected account which bank links it holds. Bounds the Stripe calls — the answer itself is a bank_connections row, not this column.';


--
-- Name: lease_document_fields; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lease_document_fields (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    document_id uuid NOT NULL,
    template_field_id uuid,
    signer_id uuid,
    field_type text NOT NULL,
    signer_role text,
    label text,
    lease_column text,
    page integer DEFAULT 1,
    x double precision,
    y double precision,
    width double precision,
    height double precision,
    required boolean DEFAULT true,
    value text,
    font_css text,
    signed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    options text,
    parent_field_id uuid,
    parent_option text,
    checkbox_mark text DEFAULT 'x'::text NOT NULL,
    CONSTRAINT lease_document_fields_checkbox_mark_check CHECK ((checkbox_mark = ANY (ARRAY['x'::text, 'check'::text]))),
    CONSTRAINT lease_document_fields_lease_column_check CHECK (((lease_column IS NULL) OR (lease_column = ANY (ARRAY['tenant_name'::text, 'tenant_email'::text, 'landlord_name'::text, 'unit_number'::text, 'property_name'::text, 'property_address'::text, 'date_signed_day'::text, 'date_signed_month'::text, 'tenant_2_name'::text, 'tenant_3_name'::text, 'tenant_4_name'::text, 'occupant_names'::text, 'sale_price'::text, 'sale_down_payment'::text, 'sale_financed_amount'::text, 'sale_monthly_payment'::text, 'sale_term_months'::text, 'sale_interest_rate'::text, 'sale_first_payment_month'::text, 'tenant_signature'::text, 'landlord_signature'::text, 'tenant_initial'::text, 'landlord_initial'::text, 'date_signed'::text, 'rent_amount'::text, 'start_date'::text, 'end_date'::text, 'security_deposit'::text, 'move_in_first_month_rent'::text, 'move_in_proration'::text, 'move_in_security_deposit'::text, 'move_in_total_due'::text, 'rent_due_day'::text, 'lease_type'::text, 'auto_renew'::text, 'auto_renew_mode'::text, 'notice_days_required'::text, 'expiration_notice_days'::text, 'late_fee_grace_days'::text, 'late_fee_initial_flat'::text, 'late_fee_initial_percent'::text, 'late_fee_accrual_flat_daily'::text, 'late_fee_accrual_flat_weekly'::text, 'late_fee_accrual_flat_monthly'::text, 'late_fee_accrual_percent_daily'::text, 'late_fee_accrual_percent_weekly'::text, 'late_fee_accrual_percent_monthly'::text, 'late_fee_cap_flat'::text, 'late_fee_cap_percent'::text, 'pet_deposit'::text, 'key_deposit'::text, 'cleaning_deposit'::text, 'utility_deposit'::text, 'move_in_fee'::text, 'cleaning_fee'::text, 'pet_fee'::text, 'application_fee'::text, 'amenity_fee'::text, 'hoa_transfer_fee'::text, 'lease_prep_fee'::text, 'pet_rent'::text, 'parking_rent'::text, 'storage_rent'::text, 'amenity_fee_monthly'::text, 'trash_fee'::text, 'pest_control_fee'::text, 'technology_fee'::text, 'last_month_rent'::text, 'early_termination_fee'::text, 'other_fee'::text, 'utility_water_responsibility'::text, 'utility_gas_responsibility'::text, 'utility_electric_responsibility'::text, 'utility_sewer_responsibility'::text, 'utility_trash_responsibility'::text, 'custom_text'::text, 'sale_final_payment_amount'::text, 'sale_final_payment_month'::text]))))
);


--
-- Name: lease_document_signers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lease_document_signers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    document_id uuid NOT NULL,
    user_id uuid NOT NULL,
    role text NOT NULL,
    name text NOT NULL,
    email text NOT NULL,
    phone text,
    order_index integer DEFAULT 1 NOT NULL,
    token text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    invite_sent boolean DEFAULT false,
    viewed_at timestamp with time zone,
    signed_at timestamp with time zone,
    signature_data text,
    ip_address text,
    user_agent text,
    created_at timestamp with time zone DEFAULT now(),
    invite_sent_at timestamp with time zone,
    reminder_sent_at timestamp with time zone,
    declined_at timestamp with time zone,
    decline_reason text,
    reminder_count integer DEFAULT 0 NOT NULL,
    invite_resend_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT lease_document_signers_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'sent'::text, 'viewed'::text, 'signed'::text, 'declined'::text])))
);


--
-- Name: COLUMN lease_document_signers.reminder_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lease_document_signers.reminder_count IS 'S639: how many signing reminders this signer has been sent. Capped so a document that is never signed stops mailing the person instead of nudging forever.';


--
-- Name: COLUMN lease_document_signers.invite_resend_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lease_document_signers.invite_resend_count IS 'How many times the 48-hour timeout path has re-sent this signer their signing request. Capped (see processEsignTimeouts) so a document nobody signs stops emailing rather than asking forever.';


--
-- Name: lease_documents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lease_documents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    template_id uuid,
    landlord_id uuid NOT NULL,
    unit_id uuid,
    lease_id uuid,
    title text NOT NULL,
    base_pdf_url text,
    executed_pdf_url text,
    status text DEFAULT 'pending'::text NOT NULL,
    page_count integer DEFAULT 1,
    sent_at timestamp with time zone,
    completed_at timestamp with time zone,
    voided_at timestamp with time zone,
    void_reason text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    document_type text DEFAULT 'original_lease'::text NOT NULL,
    target_lease_tenant_id uuid,
    promote_lease_tenant_id uuid,
    batch_id uuid,
    execution_failed_at timestamp with time zone,
    renews_lease_id uuid,
    work_trade_agreement_id uuid,
    finalized_at timestamp with time zone,
    delivery_mode text DEFAULT 'agreement'::text NOT NULL,
    deposit_already_held boolean DEFAULT false NOT NULL,
    signing_window_restarted_at timestamp with time zone,
    template_version integer,
    package_group_id uuid,
    package_id uuid,
    package_sort_order integer,
    issued_at timestamp with time zone,
    renewal_unsigned_alert_14d_at timestamp with time zone,
    renewal_unsigned_alert_start_at timestamp with time zone,
    new_lease_cancel_held_at timestamp with time zone,
    replaces_lease_id uuid,
    CONSTRAINT lease_documents_addendum_fields_check CHECK ((((document_type = 'addendum_remove'::text) AND (target_lease_tenant_id IS NOT NULL)) OR ((document_type = ANY (ARRAY['original_lease'::text, 'addendum_add'::text, 'addendum_terms'::text, 'sublease_agreement'::text, 'purchase_agreement'::text, 'bill_of_sale'::text, 'general_contract'::text, 'work_trade_addendum'::text])) AND (target_lease_tenant_id IS NULL) AND (promote_lease_tenant_id IS NULL)))),
    CONSTRAINT lease_documents_delivery_mode_check CHECK ((delivery_mode = ANY (ARRAY['agreement'::text, 'notice'::text]))),
    CONSTRAINT lease_documents_document_type_check CHECK ((document_type = ANY (ARRAY['original_lease'::text, 'addendum_add'::text, 'addendum_remove'::text, 'addendum_terms'::text, 'sublease_agreement'::text, 'purchase_agreement'::text, 'bill_of_sale'::text, 'general_contract'::text, 'work_trade_addendum'::text]))),
    CONSTRAINT lease_documents_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'sent'::text, 'in_progress'::text, 'completed'::text, 'voided'::text, 'execution_failed'::text])))
);


--
-- Name: COLUMN lease_documents.deposit_already_held; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lease_documents.deposit_already_held IS 'S604: TRUE = the landlord already holds this tenant''s security deposit (migration onboarding). The lease still states the deposit amount, but it is excluded from the move-in invoice and the security_deposits row is created funded + held_by=landlord. Default false — new tenants are billed normally.';


--
-- Name: COLUMN lease_documents.signing_window_restarted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lease_documents.signing_window_restarted_at IS 'S637: when the 48h signing window was last restarted by resending to outstanding tenant signers. Anchors the auto-void clock alongside the landlord signature.';


--
-- Name: COLUMN lease_documents.issued_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lease_documents.issued_at IS 'S647: when the landlord signed and the lease + move-in invoice were created. NULL means not yet issued. completed_at still means every signer is done.';


--
-- Name: COLUMN lease_documents.renewal_unsigned_alert_14d_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lease_documents.renewal_unsigned_alert_14d_at IS 'S655: when the landlord was told, 14 days before a new lease for a sitting tenant starts, that the tenant has not signed it. Once per document.';


--
-- Name: COLUMN lease_documents.renewal_unsigned_alert_start_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lease_documents.renewal_unsigned_alert_start_at IS 'S655: when the landlord was told, on the day a new lease for a sitting tenant started, that the tenant still has not signed it. Once per document.';


--
-- Name: COLUMN lease_documents.new_lease_cancel_held_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lease_documents.new_lease_cancel_held_at IS 'S655: when the 15-minute job could not cancel this new lease (the lease it follows ended early and nobody signed it) because money had already been paid on it, and told the landlord side and GAM. Once per document. NULL = never held.';


--
-- Name: COLUMN lease_documents.replaces_lease_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lease_documents.replaces_lease_id IS '10/24: the sitting lease this new lease replaces on the same space. Set deliberately by the landlord when drafting; never by a booking or application draft. NULL = an ordinary new lease that ends nobody.';


--
-- Name: lease_fees; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lease_fees (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    lease_id uuid NOT NULL,
    fee_type text NOT NULL,
    amount numeric NOT NULL,
    is_refundable boolean NOT NULL,
    due_timing text NOT NULL,
    description text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    is_override boolean DEFAULT false NOT NULL,
    override_reason text,
    condition_text text,
    condition_result text,
    condition_assessed_at timestamp with time zone,
    condition_assessed_by uuid,
    money_kind text DEFAULT 'fee'::text NOT NULL,
    CONSTRAINT lease_fees_amount_check CHECK ((amount >= (0)::numeric)),
    CONSTRAINT lease_fees_condition_result_check CHECK (((condition_result IS NULL) OR (condition_result = ANY (ARRAY['met'::text, 'failed'::text])))),
    CONSTRAINT lease_fees_due_timing_check CHECK ((due_timing = ANY (ARRAY['move_in'::text, 'monthly_ongoing'::text, 'move_out'::text, 'other'::text]))),
    CONSTRAINT lease_fees_fee_type_check CHECK ((fee_type = ANY (ARRAY['security_deposit'::text, 'pet_deposit'::text, 'key_deposit'::text, 'cleaning_deposit'::text, 'utility_deposit'::text, 'move_in_fee'::text, 'cleaning_fee'::text, 'pet_fee'::text, 'application_fee'::text, 'amenity_fee'::text, 'hoa_transfer_fee'::text, 'lease_prep_fee'::text, 'pet_rent'::text, 'parking_rent'::text, 'storage_rent'::text, 'amenity_fee_monthly'::text, 'trash_fee'::text, 'pest_control_fee'::text, 'technology_fee'::text, 'last_month_rent'::text, 'early_termination_fee'::text, 'other_fee'::text]))),
    CONSTRAINT lease_fees_money_kind_check CHECK ((money_kind = ANY (ARRAY['fee'::text, 'deposit'::text, 'prepaid'::text])))
);


--
-- Name: COLUMN lease_fees.money_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lease_fees.money_kind IS 'S653: what this money IS on the signed lease — fee (landlord keeps), deposit (held, returned at move-out) or prepaid (credit to the renter, drawn down by rent).';


--
-- Name: lease_notices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lease_notices (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    lease_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    source_document_id uuid,
    title text NOT NULL,
    body text NOT NULL,
    effective_date date,
    status text DEFAULT 'pending'::text NOT NULL,
    viewed_at timestamp with time zone,
    acknowledged_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT lease_notices_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'acknowledged'::text])))
);


--
-- Name: lease_occupants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lease_occupants (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    lease_id uuid NOT NULL,
    full_name text NOT NULL,
    relationship_to_primary_tenant text,
    date_of_birth date,
    is_minor boolean DEFAULT false NOT NULL,
    requires_background_check boolean DEFAULT false NOT NULL,
    background_check_id uuid,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: lease_pets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lease_pets (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    lease_id uuid NOT NULL,
    name text,
    species text NOT NULL,
    breed text,
    color text,
    age_years numeric(4,1),
    weight_lbs numeric(6,1),
    is_service_animal boolean DEFAULT false NOT NULL,
    is_emotional_support boolean DEFAULT false NOT NULL,
    service_animal_documentation_url text,
    license_county text,
    license_number text,
    vaccinations_current boolean,
    vet_name text,
    vet_phone text,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT lease_pets_species_check CHECK ((species = ANY (ARRAY['dog'::text, 'cat'::text, 'bird'::text, 'reptile'::text, 'fish'::text, 'small_mammal'::text, 'livestock'::text, 'other'::text])))
);


--
-- Name: lease_prepaid_credit_draws; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lease_prepaid_credit_draws (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    lease_id uuid NOT NULL,
    credit_id uuid,
    payment_id uuid,
    amount numeric(12,2) NOT NULL,
    billing_month date NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT lease_prepaid_credit_draws_amount_check CHECK ((amount > (0)::numeric))
);


--
-- Name: TABLE lease_prepaid_credit_draws; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.lease_prepaid_credit_draws IS 'S653: each draw of paid-ahead credit, by billing month — the monthly cap is measured here.';


--
-- Name: lease_prepaid_credits; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lease_prepaid_credits (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    lease_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    amount_original numeric(12,2) NOT NULL,
    amount_remaining numeric(12,2) NOT NULL,
    source_remittance_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    source_payment_id uuid,
    note text,
    funded_by text,
    received_at timestamp with time zone,
    voided_at timestamp with time zone,
    void_reason text,
    left_by_choice_id uuid,
    received_lease_id uuid,
    CONSTRAINT lease_prepaid_credits_amount_original_check CHECK ((amount_original > (0)::numeric)),
    CONSTRAINT lease_prepaid_credits_amount_remaining_check CHECK ((amount_remaining >= (0)::numeric)),
    CONSTRAINT lease_prepaid_credits_funded_by_check CHECK (((funded_by IS NULL) OR (funded_by = ANY (ARRAY['landlord'::text, 'gam'::text, 'reclassified'::text])))),
    CONSTRAINT lease_prepaid_credits_void_has_reason CHECK (((voided_at IS NULL) = (void_reason IS NULL)))
);


--
-- Name: COLUMN lease_prepaid_credits.funded_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lease_prepaid_credits.funded_by IS 'S655: who holds this money. landlord = the landlord took it (cash, check, money order, a bank deposit, a typed-in carry-forward); gam = it reached GAM through Stripe (or a platform-held prepaid fee) and is released to the landlord as it is used; reclassified = rent already paid and already counted, moved to credit when a stay was shortened (source_payment_id = the row it reclassifies). NULL only before the P2 backfill; NOT NULL in C1.';


--
-- Name: COLUMN lease_prepaid_credits.received_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lease_prepaid_credits.received_at IS 'S655: when the money actually arrived (Russ Fuller: 2026-08-12). Under "Money received" paid-ahead money counts on this day, in full, and $0 when it later pays a bill.';


--
-- Name: COLUMN lease_prepaid_credits.voided_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lease_prepaid_credits.voided_at IS 'S655: withdrawn (an undone bank-deposit settle''s excess). amount_remaining is left as it was; a voided credit can never be used and is out of every balance.';


--
-- Name: COLUMN lease_prepaid_credits.void_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lease_prepaid_credits.void_reason IS 'S655: why the credit was withdrawn, in plain words. Set exactly when voided_at is.';


--
-- Name: COLUMN lease_prepaid_credits.left_by_choice_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lease_prepaid_credits.left_by_choice_id IS '10/4 (decisions #46.1a): the paid-ahead choice that left this money as the tenant''s ("Leave it as their credit") on an ended lease. It stays their money paid ahead (GAM-held money is released to the landlord only when it pays a bill) and moves to their next lease with this landlord (paid_ahead_carry_left), which clears the mark. NULL: an ordinary credit.';


--
-- Name: COLUMN lease_prepaid_credits.received_lease_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lease_prepaid_credits.received_lease_id IS '10/4 (decisions #46.1a): the lease this money paid ahead ARRIVED on, set once when paid_ahead_carry_left moves money left as the tenant''s credit to their next lease with the landlord. NULL: it never moved (lease_id is where it arrived). Readers of where money arrived (Money received''s paid-ahead line, the owner statement) read COALESCE(received_lease_id, lease_id), so a carry never rewrites a past month or another property''s report.';


