--
-- Name: payment_reversals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payment_reversals (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    payment_id uuid NOT NULL,
    landlord_id uuid,
    tenant_id uuid,
    lease_id uuid,
    reversal_type text NOT NULL,
    reversed_amount numeric(10,2) NOT NULL,
    reversal_fee numeric(10,2) DEFAULT 0 NOT NULL,
    stripe_event_id text NOT NULL,
    stripe_object_id text,
    connect_dispute_id uuid,
    raw_event jsonb NOT NULL,
    recovery_method text,
    recovery_status text DEFAULT 'pending'::text NOT NULL,
    recovered_amount numeric(10,2) DEFAULT 0 NOT NULL,
    recovered_at timestamp with time zone,
    outcome text,
    late_fee_owner text,
    resolved_at timestamp with time zone,
    status text DEFAULT 'open'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT payment_reversals_late_fee_owner_check CHECK (((late_fee_owner IS NULL) OR (late_fee_owner = ANY (ARRAY['gam'::text, 'landlord'::text])))),
    CONSTRAINT payment_reversals_outcome_check CHECK (((outcome IS NULL) OR (outcome = ANY (ARRAY['tenant_paid'::text, 'landlord_clawback'::text, 'written_off'::text])))),
    CONSTRAINT payment_reversals_recovery_method_check CHECK (((recovery_method IS NULL) OR (recovery_method = ANY (ARRAY['netting'::text, 'ach_pull'::text])))),
    CONSTRAINT payment_reversals_recovery_status_check CHECK ((recovery_status = ANY (ARRAY['pending'::text, 'scheduled_netting'::text, 'recovered'::text, 'not_needed'::text]))),
    CONSTRAINT payment_reversals_status_check CHECK ((status = ANY (ARRAY['open'::text, 'recovering'::text, 'resolved'::text]))),
    CONSTRAINT payment_reversals_type_check CHECK ((reversal_type = ANY (ARRAY['ach_return'::text, 'ach_unauthorized'::text, 'card_dispute'::text])))
);


--
-- Name: payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payments (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    unit_id uuid,
    lease_id uuid,
    tenant_id uuid,
    landlord_id uuid NOT NULL,
    type text NOT NULL,
    amount numeric(10,2) NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    stripe_payment_intent_id text,
    stripe_charge_id text,
    ach_trace_number text,
    entry_description text NOT NULL,
    return_code text,
    return_reason text,
    zero_tolerance_flag boolean DEFAULT false,
    due_date date NOT NULL,
    processed_at timestamp with time zone,
    settled_at timestamp with time zone,
    retry_count integer DEFAULT 0,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    lease_fee_id uuid,
    invoice_id uuid,
    next_retry_at timestamp with time zone,
    last_retry_at timestamp with time zone,
    platform_held boolean DEFAULT false NOT NULL,
    sublease_credit_applied boolean DEFAULT false NOT NULL,
    gam_supersedence_amount numeric(10,2) DEFAULT 0 NOT NULL,
    gam_supersedence_breakdown jsonb,
    gam_supersedence_applied_at timestamp with time zone,
    import_source text,
    imported_at timestamp with time zone,
    import_extra_data jsonb,
    is_remainder boolean DEFAULT false NOT NULL,
    reversal_id uuid,
    manual_method text,
    sublease_markup_amount numeric DEFAULT 0 NOT NULL,
    home_sale_installment_id uuid,
    revenue_owner text DEFAULT 'landlord'::text NOT NULL,
    work_trade_suspended_at timestamp with time zone,
    payment_channel text,
    issued_credit_amount numeric(10,2) DEFAULT 0 NOT NULL,
    flexpay_advance_id uuid,
    voided_at timestamp with time zone,
    void_reason text,
    released_by_deposit_return_id uuid,
    deposit_collected_by text,
    work_trade_credit numeric(12,2) DEFAULT 0 NOT NULL,
    work_trade_settlement_id uuid,
    space_carryforward_id uuid,
    CONSTRAINT payments_deposit_collected_by_check CHECK (((deposit_collected_by IS NULL) OR (deposit_collected_by = ANY (ARRAY['gam'::text, 'landlord'::text])))),
    CONSTRAINT payments_entry_description_check CHECK ((entry_description = ANY (ARRAY['RENT'::text, 'SUBSCRIP'::text, 'DEPOSIT'::text, 'UTILITY'::text, 'ONTIMEPAY'::text, 'LATEFEE'::text, 'FLEXPAY'::text, 'FLEXDEP'::text, 'PROPANE'::text, 'RETURNFEE'::text, 'MANUALPAY'::text, 'HOMEPMT'::text, 'FCPAYDOWN'::text, 'DECLINEFEE'::text, 'BALANCE'::text, 'OTHERFEE'::text]))),
    CONSTRAINT payments_gam_supersedence_amount_nonneg CHECK ((gam_supersedence_amount >= (0)::numeric)),
    CONSTRAINT payments_issued_credit_amount_nonneg CHECK ((issued_credit_amount >= (0)::numeric)),
    CONSTRAINT payments_manual_method_check CHECK (((manual_method IS NULL) OR (manual_method = ANY (ARRAY['cash'::text, 'check'::text, 'money_order'::text, 'bank_deposit'::text, 'prior_arrangement'::text])))),
    CONSTRAINT payments_payment_channel_check CHECK (((payment_channel IS NULL) OR (payment_channel = ANY (ARRAY['online'::text, 'in_person'::text])))),
    CONSTRAINT payments_retry_count_check CHECK (((retry_count >= 0) AND (retry_count <= 2))),
    CONSTRAINT payments_revenue_owner_check CHECK ((revenue_owner = ANY (ARRAY['landlord'::text, 'gam'::text, 'held'::text]))),
    CONSTRAINT payments_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'settled'::text, 'failed'::text, 'returned'::text, 'paid_via_deposit'::text, 'voided'::text]))),
    CONSTRAINT payments_type_check CHECK ((type = ANY (ARRAY['rent'::text, 'fee'::text, 'deposit'::text, 'utility'::text, 'float_fee'::text, 'late_fee'::text, 'platform_fee'::text, 'home_payment'::text, 'carried_balance'::text]))),
    CONSTRAINT payments_voided_is_stamped CHECK ((((status = 'voided'::text) = (voided_at IS NOT NULL)) AND ((voided_at IS NULL) = (void_reason IS NULL)))),
    CONSTRAINT payments_work_trade_credit_nonneg CHECK ((work_trade_credit >= (0)::numeric))
);


--
-- Name: COLUMN payments.gam_supersedence_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.gam_supersedence_amount IS 'S261: dollar amount of this payment redirected to satisfy older GAM-owed debts. Captured at PI creation, distributed FIFO on settlement.';


--
-- Name: COLUMN payments.gam_supersedence_breakdown; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.gam_supersedence_breakdown IS 'S261: ordered FIFO list of which GAM debts this payment satisfied. Shape: [{source, ref_id, amount, satisfied_at}]. Source ∈ flexdeposit_installment | flexdeposit_acceleration | flexcharge_statement | flexpay_advance | custody_charge. NULL until applyTenantSupersedence runs.';


--
-- Name: COLUMN payments.gam_supersedence_applied_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.gam_supersedence_applied_at IS 'S261: idempotency stamp — set once when applyTenantSupersedence completes for this payment. NULL means the boost has not yet been distributed.';


--
-- Name: COLUMN payments.import_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.import_source IS 'Phase B: which prior platform brought this payment in via CSV import (buildium / appfolio / doorloop / yardi / rentmanager / propertyware / rentec / tenantcloud / generic). NULL = native GAM payment.';


--
-- Name: COLUMN payments.imported_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.imported_at IS 'Phase B: timestamp the import commit ran. Distinct from settled_at (which carries the historical payment date from the source CSV).';


--
-- Name: COLUMN payments.home_sale_installment_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.home_sale_installment_id IS 'S594: the home_sale_installments row this home_payment charge bills. Partial-unique so an installment is billed at most once even across concurrent cron runs / multiple API instances.';


--
-- Name: COLUMN payments.revenue_owner; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.revenue_owner IS 'S609: whose money this charge is. ''landlord'' (the default) = the tenant owes it because of their LEASE — rent, utilities, late fees, any fee a landlord billed. ''gam'' = the tenant owes it for using a GAM service — a returned bank payment, a declined card, a manual-payment recording, or an opt-in product. Stamped at creation because entry_description cannot distinguish a landlord''s hand-billed fee from a GAM subscription (both write ''SUBSCRIP''). Read by services/allocation.ts to decide whether an owner share is booked.';


--
-- Name: COLUMN payments.work_trade_suspended_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.work_trade_suspended_at IS 'S634: set while a work-trade agreement covers this charge for a month still being worked. A suspended row is NOT owed — it is excluded from invoices.total_amount and from outstanding balances. Month-close settlement clears it, leaving 0 (hours met) or the prorated lapse.';


--
-- Name: COLUMN payments.payment_channel; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.payment_channel IS 'S654: online (portal / autopay / emailed link) or in_person (card on the counter reader); NULL for cash, check, money order.';


--
-- Name: COLUMN payments.issued_credit_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.issued_credit_amount IS 'S655: dollars of this charge paid by a credit the LANDLORD issued (move-in special, goodwill, refunded fee, overcharge). No money moved for this part: never landlord income, never part of a payout. Deposit-interest credits are GAM-funded and are NOT included; paid-ahead money is NOT included (it is the tenant''s own money and counts on the day it arrived). Maintained only by trg_credit_uses_apply as the sum of the row''s applied landlord-issued uses.';


--
-- Name: COLUMN payments.flexpay_advance_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.flexpay_advance_id IS 'S655: on a bill line FlexPay covered (GAM float paid it on time) and on the one FLEXPAY pull row that repays it. Covered lines are GAM-held money for allocation.';


--
-- Name: COLUMN payments.voided_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.voided_at IS 'decisions #48.5: when a charge nobody owes, that a payment had already touched, was taken off (status voided). NOT NULL exactly when status = voided. The row is kept forever and left out of every balance.';


--
-- Name: COLUMN payments.void_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.void_reason IS 'decisions #48.5: the plain reason a voided charge is no longer owed (e.g. the reservation it was for was canceled). Set with voided_at.';


--
-- Name: COLUMN payments.released_by_deposit_return_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.released_by_deposit_return_id IS '10/4 (decisions #46.3): the finalized move-out (deposit_returns.id) that released this GAM-collected deposit payment — it cleared platform_held because the money now rides a held payout item or the refund GAM owes. Set only on payments GAM collected, so leaseFeesSync.depositCollectedBySql reads such a payment as collected by GAM before and after the move-out. NULL: never released by a move-out.';


--
-- Name: COLUMN payments.deposit_collected_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.deposit_collected_by IS '10/12 (Nic, ledger P1): who collected this deposit payment when it settled (decisions #46.3) — gam: by card or bank onto GAM''s balance; landlord: in person or into their own bank. Written at each settle from leaseFeesSync.depositCollectedBySql; cleared when that settle is undone.';


--
-- Name: COLUMN payments.work_trade_credit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.work_trade_credit IS '10/12 (ledger P1): dollars of work-trade credit applied to this row at the month close (the row''s amount was lowered by it). amount + work_trade_credit = what the row billed.';


--
-- Name: COLUMN payments.work_trade_settlement_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.work_trade_settlement_id IS '10/12 (ledger P1): set on the carried-balance row a work-trade period''s unworked hours were billed on when no bill carried them (jobs/workTradeSettlement billDeficit).';


--
-- Name: COLUMN payments.space_carryforward_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.space_carryforward_id IS '10/19 (Nic): the carried space-rent claim this row belongs to — the one carried_balance charge that is the debt, its part-payment remainders, and the voided rent rows it was carried from.';


--
-- Name: payout_triggers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payout_triggers (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    entity_kind text NOT NULL,
    entity_id uuid NOT NULL,
    cycle_month date NOT NULL,
    trigger_kind text NOT NULL,
    units_total integer,
    units_paid integer,
    scheduled_for date NOT NULL,
    fired_at timestamp with time zone,
    skipped_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    defer_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT payout_triggers_entity_kind_check CHECK ((entity_kind = ANY (ARRAY['user'::text, 'pm_company'::text, 'business'::text]))),
    CONSTRAINT payout_triggers_trigger_kind_check CHECK ((trigger_kind = ANY (ARRAY['threshold_50'::text, 'threshold_90'::text, 'monthly_sweep'::text])))
);


--
-- Name: TABLE payout_triggers; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.payout_triggers IS 'S616: what earned a landlord payout and when it is scheduled. At most three rows per Connect account per rent cycle — 50% of units paid, 90%, and a guaranteed late-month sweep — so the per-initiation cost is capped at $0.75 a month and known in advance.';


--
-- Name: COLUMN payout_triggers.defer_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payout_triggers.defer_count IS 'S617: times this trigger fired into an empty balance and was pushed to the next business day rather than retired. Capped in code (MAX_DEFERRALS).';


--
-- Name: payroll_run_expenses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payroll_run_expenses (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    landlord_id uuid NOT NULL,
    payroll_run_id uuid NOT NULL,
    payroll_run_line_id uuid,
    expense_id uuid NOT NULL,
    kind text NOT NULL,
    liability_role text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT payroll_run_expenses_kind_check CHECK ((kind = ANY (ARRAY['payroll_net'::text, 'tax_payment'::text]))),
    CONSTRAINT payroll_run_expenses_role_check CHECK ((liability_role = ANY (ARRAY['net_pay_payable'::text, 'payroll_federal_withholding'::text, 'payroll_fica'::text, 'payroll_futa'::text, 'payroll_state_withholding'::text, 'payroll_suta'::text, 'payroll_liabilities'::text]))),
    CONSTRAINT payroll_run_expenses_shape CHECK ((((kind = 'payroll_net'::text) AND (payroll_run_line_id IS NOT NULL) AND (liability_role = 'net_pay_payable'::text)) OR ((kind = 'tax_payment'::text) AND (payroll_run_line_id IS NULL) AND (liability_role <> 'net_pay_payable'::text))))
);


--
-- Name: TABLE payroll_run_expenses; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.payroll_run_expenses IS '10/12 (Nic, ledger P7): the unpaid expenses an approved payroll run created — take-home pay per paycheck and one tax payment per payroll liability — and which liability each clears (design J3). Insert-only.';


--
-- Name: payroll_run_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payroll_run_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    pay_type character varying(20) NOT NULL,
    hours_worked numeric(8,2),
    gross_pay numeric(10,2) NOT NULL,
    federal_tax numeric(10,2) DEFAULT 0 NOT NULL,
    state_tax numeric(10,2) DEFAULT 0 NOT NULL,
    ss_tax numeric(10,2) DEFAULT 0 NOT NULL,
    medicare_tax numeric(10,2) DEFAULT 0 NOT NULL,
    other_deductions numeric(10,2) DEFAULT 0,
    net_pay numeric(10,2) NOT NULL,
    memo text,
    created_at timestamp with time zone DEFAULT now(),
    employer_ss_tax numeric(10,2) DEFAULT 0 NOT NULL,
    employer_medicare_tax numeric(10,2) DEFAULT 0 NOT NULL,
    futa_tax numeric(10,2) DEFAULT 0 NOT NULL,
    suta_tax numeric(10,2) DEFAULT 0 NOT NULL,
    work_trade_extra_hours_id uuid,
    pay_place text,
    pay_property_id uuid,
    CONSTRAINT payroll_run_lines_employer_taxes_nonneg CHECK (((employer_ss_tax >= (0)::numeric) AND (employer_medicare_tax >= (0)::numeric) AND (futa_tax >= (0)::numeric) AND (suta_tax >= (0)::numeric))),
    CONSTRAINT payroll_run_lines_pay_place_check CHECK ((((pay_place IS NULL) AND (pay_property_id IS NULL)) OR ((pay_place = 'property'::text) AND (pay_property_id IS NOT NULL)) OR ((pay_place = 'company'::text) AND (pay_property_id IS NULL))))
);


--
-- Name: COLUMN payroll_run_lines.employer_ss_tax; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_run_lines.employer_ss_tax IS '10/12 (Nic, ledger P7): the employer''s Social Security on this check — 6.2% up to the year''s wage base, equal to the employee''s.';


--
-- Name: COLUMN payroll_run_lines.employer_medicare_tax; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_run_lines.employer_medicare_tax IS '10/12 (Nic, ledger P7): the employer''s Medicare on this check — 1.45% of gross (no Additional Medicare Tax).';


--
-- Name: COLUMN payroll_run_lines.futa_tax; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_run_lines.futa_tax IS '10/12 (Nic, ledger P7): the employer''s federal unemployment tax on this check, as entered when the run was calculated.';


--
-- Name: COLUMN payroll_run_lines.suta_tax; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_run_lines.suta_tax IS '10/12 (Nic, ledger P7): the employer''s state unemployment tax on this check, as entered when the run was calculated.';


--
-- Name: COLUMN payroll_run_lines.work_trade_extra_hours_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_run_lines.work_trade_extra_hours_id IS '10/12 (Nic, ledger P7): the work-trade extra hours (sent to GAM Books as W-2 pay) this paycheck line pays.';


--
-- Name: COLUMN payroll_run_lines.pay_place; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_run_lines.pay_place IS '10/14 (Nic): the place this paycheck was booked with, copied from its employee (property or company). A draft run''s paychecks follow the owner''s change of the employee''s place; once the run is approved it never moves. NULL: a paycheck on a run approved before 10/14 — the run''s own cost_place places it.';


--
-- Name: COLUMN payroll_run_lines.pay_property_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_run_lines.pay_property_id IS '10/14 (Nic): the property this paycheck was booked to (pay_place property).';


--
-- Name: payroll_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payroll_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    landlord_id uuid,
    period_start date NOT NULL,
    period_end date NOT NULL,
    pay_date date NOT NULL,
    pay_frequency character varying(20) NOT NULL,
    status character varying(20) DEFAULT 'draft'::character varying NOT NULL,
    total_gross numeric(12,2) DEFAULT 0,
    total_federal_tax numeric(12,2) DEFAULT 0,
    total_state_tax numeric(12,2) DEFAULT 0,
    total_ss numeric(12,2) DEFAULT 0,
    total_medicare numeric(12,2) DEFAULT 0,
    total_net numeric(12,2) DEFAULT 0,
    employee_count integer DEFAULT 0,
    notes text,
    approved_at timestamp with time zone,
    approved_by uuid,
    voided_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    business_id uuid,
    total_employer_ss numeric(12,2) DEFAULT 0 NOT NULL,
    total_employer_medicare numeric(12,2) DEFAULT 0 NOT NULL,
    total_futa numeric(12,2) DEFAULT 0 NOT NULL,
    total_suta numeric(12,2) DEFAULT 0 NOT NULL,
    cost_place text,
    property_id uuid,
    unit_id uuid,
    CONSTRAINT payroll_runs_cost_place_check CHECK ((((cost_place IS NULL) AND (property_id IS NULL) AND (unit_id IS NULL)) OR ((landlord_id IS NOT NULL) AND (((cost_place = 'unit'::text) AND (unit_id IS NOT NULL) AND (property_id IS NOT NULL)) OR ((cost_place = 'property'::text) AND (property_id IS NOT NULL) AND (unit_id IS NULL)) OR ((cost_place = 'split_by_units'::text) AND (property_id IS NULL) AND (unit_id IS NULL)))))),
    CONSTRAINT payroll_runs_employer_taxes_nonneg CHECK (((total_employer_ss >= (0)::numeric) AND (total_employer_medicare >= (0)::numeric) AND (total_futa >= (0)::numeric) AND (total_suta >= (0)::numeric))),
    CONSTRAINT payroll_runs_one_owner CHECK ((num_nonnulls(landlord_id, business_id) <= 1)),
    CONSTRAINT payroll_runs_status_check CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'approved'::character varying, 'voided'::character varying])::text[])))
);


--
-- Name: COLUMN payroll_runs.cost_place; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_runs.cost_place IS '10/13 (Nic): where the run''s gross wages and the employer''s taxes go, picked when the run is logged — split_by_units, property (property_id) or unit (unit_id). Required to approve a landlord company''s run. NULL: a run approved before 10/13 (the Company column) or a business''s run. BOOKS_COST_PLACES.';


--
-- Name: COLUMN payroll_runs.property_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_runs.property_id IS '10/13 (Nic): the property the run''s wages and employer taxes go to (cost_place property, or the unit''s property for unit).';


--
-- Name: COLUMN payroll_runs.unit_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_runs.unit_id IS '10/13 (Nic): the unit the run''s wages and employer taxes go to (cost_place unit).';


--
-- Name: pending_lease_drafts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pending_lease_drafts (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    landlord_id uuid NOT NULL,
    unit_id uuid NOT NULL,
    tenant_user_id uuid NOT NULL,
    household_order integer DEFAULT 0 NOT NULL,
    resolved_at timestamp with time zone,
    resolved_document_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE pending_lease_drafts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.pending_lease_drafts IS 'S605: tenants invited to a unit whose lease has not been drafted yet — usually because the unit type had no default lease template at invite time. Drafting is retried when one is set.';


--
-- Name: pending_tenant_intents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pending_tenant_intents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    landlord_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    parser_status text DEFAULT 'not_uploaded'::text NOT NULL,
    imported_pdf_url text,
    parser_output jsonb,
    parser_flags jsonb,
    parser_error text,
    parser_started_at timestamp with time zone,
    parser_finished_at timestamp with time zone,
    resolved_at timestamp with time zone,
    resolved_lease_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    unit_id uuid,
    accepted_at timestamp with time zone,
    draft_document_id uuid,
    cancelled_at timestamp with time zone,
    property_id uuid,
    screening_waived boolean DEFAULT false NOT NULL,
    screening_waived_by uuid,
    screening_waived_at timestamp with time zone,
    screening_attested boolean DEFAULT false NOT NULL,
    screening_waived_unit_id uuid,
    invite_last_nudged_at timestamp with time zone,
    is_existing_tenancy boolean DEFAULT false NOT NULL,
    is_work_trade boolean DEFAULT false NOT NULL,
    work_trade_hours_target integer,
    work_trade_duties text,
    work_trade_covered_charges text[],
    work_trade_tracks_hours boolean,
    home_sale_terms jsonb,
    package_template_ids uuid[],
    waive_reason text,
    rent_due_day integer,
    CONSTRAINT pending_intent_work_trade_covered_check CHECK (((work_trade_covered_charges IS NULL) OR ((array_length(work_trade_covered_charges, 1) > 0) AND (work_trade_covered_charges <@ ARRAY['rent'::text, 'fees'::text, 'water'::text, 'sewer'::text, 'electric'::text, 'gas'::text, 'trash'::text, 'propane'::text])))),
    CONSTRAINT pending_tenant_intents_parser_status_check CHECK ((parser_status = ANY (ARRAY['not_uploaded'::text, 'parsing'::text, 'parsed'::text, 'mismatch'::text, 'error'::text, 'resolved'::text]))),
    CONSTRAINT pending_tenant_intents_rent_due_day_range CHECK (((rent_due_day IS NULL) OR ((rent_due_day >= 1) AND (rent_due_day <= 28)))),
    CONSTRAINT pti_work_trade_hours_positive CHECK (((work_trade_hours_target IS NULL) OR (work_trade_hours_target > 0)))
);


--
-- Name: COLUMN pending_tenant_intents.cancelled_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pending_tenant_intents.cancelled_at IS 'Set when a landlord backs out of a pending invite. Soft-hide: the row + its tenant/user/PDF are retained on the server; the invite just leaves the landlord''s view and releases the held unit. Distinct from resolved_at (became a lease).';


--
-- Name: COLUMN pending_tenant_intents.is_existing_tenancy; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pending_tenant_intents.is_existing_tenancy IS 'S631: the landlord is papering an existing resident rather than inviting a new move-in. Copied onto the lease at signing. 10/19: set by the app only — the landlord attests it and the onboarding window must be open (services/onboardingWindow.isExistingTenancyInvite). The old 28-day trigger that forced it TRUE is gone; it overrode the landlord''s own answer during a new account''s first 28 days.';


--
-- Name: COLUMN pending_tenant_intents.is_work_trade; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pending_tenant_intents.is_work_trade IS 'S631: this resident trades work for rent. A work_trade_agreement is created from this the moment their lease exists, BEFORE the move-in invoice, so the first invoice is late-fee exempt from birth.';


--
-- Name: COLUMN pending_tenant_intents.work_trade_tracks_hours; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pending_tenant_intents.work_trade_tracks_hours IS 'S637: false = create the agreement as a trusted trade (no hours logged). NULL = not stated, tracked.';


--
-- Name: COLUMN pending_tenant_intents.rent_due_day; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pending_tenant_intents.rent_due_day IS 'S652: the day of the month this household''s rent is due, stated on the invite. NULL = follow the property''s rule. Same 1-28 range as leases.rent_due_day.';


--
-- Name: person_merges; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.person_merges (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    landlord_id uuid NOT NULL,
    proposal_id uuid,
    keeper_key text NOT NULL,
    keeper_kind text NOT NULL,
    keeper_user_id uuid,
    keeper_booking_id uuid,
    loser_key text NOT NULL,
    loser_kind text NOT NULL,
    loser_user_id uuid,
    loser_booking_id uuid,
    email_moved text,
    email_retired_to text,
    reservations_repointed integer DEFAULT 0 NOT NULL,
    emails_filled integer DEFAULT 0 NOT NULL,
    detail jsonb,
    merged_at timestamp with time zone DEFAULT now() NOT NULL,
    merged_by uuid,
    CONSTRAINT pm_keeper_shape CHECK ((((keeper_kind = 'account'::text) AND (keeper_user_id IS NOT NULL) AND (keeper_booking_id IS NULL)) OR ((keeper_kind = 'guest'::text) AND (keeper_booking_id IS NOT NULL) AND (keeper_user_id IS NULL)))),
    CONSTRAINT pm_loser_shape CHECK ((((loser_kind = 'account'::text) AND (loser_user_id IS NOT NULL) AND (loser_booking_id IS NULL)) OR ((loser_kind = 'guest'::text) AND (loser_booking_id IS NOT NULL) AND (loser_user_id IS NULL)))),
    CONSTRAINT pm_sides_differ CHECK ((keeper_key <> loser_key))
);


--
-- Name: TABLE person_merges; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.person_merges IS '10/20 (Nic): one row per person the landlord said was already in the book. A merge keeps BOTH records and points them at one person — GAM never erases. The matcher reads this so an answered pair is never asked again.';


--
-- Name: COLUMN person_merges.email_retired_to; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.person_merges.email_retired_to IS 'The duplicate-<id>@invalid address the folded account now answers to (RFC 2606 — can never receive mail). The row itself stays, and stays findable by name and phone.';


--
-- Name: COLUMN person_merges.emails_filled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.person_merges.emails_filled IS 'Reservations that carried NO email and now carry the person''s. The stay chain matches on tenant_id OR guest_email (services/stayTerms), so this is what makes two halves of one guest read as one.';


--
-- Name: platform_announcements; Type: TABLE; Schema: public; Owner: -
