    invoice_gallons numeric(12,2),
    service_agreement_id uuid,
    booking_id uuid,
    CONSTRAINT propane_fills_delivery_fee_share_check CHECK ((delivery_fee_share >= (0)::numeric)),
    CONSTRAINT propane_fills_gallons_check CHECK ((gallons > (0)::numeric)),
    CONSTRAINT propane_fills_installment_count_check CHECK ((installment_count = ANY (ARRAY[1, 2, 4]))),
    CONSTRAINT propane_fills_names_an_occupancy CHECK (((lease_id IS NOT NULL) OR (service_agreement_id IS NOT NULL) OR (booking_id IS NOT NULL))),
    CONSTRAINT propane_fills_price_per_gallon_check CHECK ((price_per_gallon >= (0)::numeric))
);


--
-- Name: COLUMN propane_fills.lease_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.propane_fills.lease_id IS '10/20: the lease that was on the space, when there was one. Nullable since delivered propane reaches RV sites held by a stay or a serviced agreement.';


--
-- Name: COLUMN propane_fills.client_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.propane_fills.client_key IS 'S594: client-supplied idempotency key (one per Record-Fill intent). Partial-unique so a repeated submission is a no-op instead of a double-charge.';


--
-- Name: COLUMN propane_fills.delivery_fee_share; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.propane_fills.delivery_fee_share IS 'S613: this tank''s share of the delivery charge on the supplier ticket (hazmat / fuel surcharge / per-stop fee). Included in total_amount and in the instalment schedule. Untaxed — the propane tax applies to the fuel.';


--
-- Name: COLUMN propane_fills.true_cost_per_gallon; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.propane_fills.true_cost_per_gallon IS 'S632: the delivery''s blended cost — supplier invoice total (tax, delivery, surcharges included) divided by total gallons delivered. NULL on fills recorded before S632 or entered at a flat rate.';


--
-- Name: COLUMN propane_fills.invoice_total; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.propane_fills.invoice_total IS 'S632: the whole supplier invoice for the delivery this fill came from — kept so a margin can be re-derived years later without the paper.';


--
-- Name: COLUMN propane_fills.service_agreement_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.propane_fills.service_agreement_id IS '10/20: the utility service agreement that was on the space — the occupant who owes for what they used without signing a lease.';


--
-- Name: COLUMN propane_fills.booking_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.propane_fills.booking_id IS '10/20: the stay that was on the space. A stay guest may have no tenant row at all, which is why tenant_id is nullable beside this.';


--
-- Name: properties; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.properties (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    landlord_id uuid NOT NULL,
    name text NOT NULL,
    street1 text NOT NULL,
    street2 text,
    city text NOT NULL,
    state text NOT NULL,
    zip text NOT NULL,
    type text DEFAULT 'mixed'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    unit_types text[] DEFAULT '{}'::text[],
    review_status text DEFAULT 'active'::text NOT NULL,
    timezone text DEFAULT 'America/Phoenix'::text NOT NULL,
    late_fee_enabled boolean DEFAULT true NOT NULL,
    late_fee_grace_days integer DEFAULT 5 NOT NULL,
    deposit_handling_mode text DEFAULT 'landlord_held'::text NOT NULL,
    deposit_interest_rate_annual numeric,
    deposit_interest_accrual_method text,
    deposit_interest_payment_cadence text,
    owner_user_id uuid NOT NULL,
    managed_by_user_id uuid NOT NULL,
    pm_company_id uuid,
    pm_fee_plan_id uuid,
    requires_booking_acknowledgment boolean DEFAULT false NOT NULL,
    subleasing_allowed boolean DEFAULT false NOT NULL,
    sublease_agreement_template_url text,
    flex_charge_default_credit_limit numeric(10,2) DEFAULT 500.00 NOT NULL,
    flexcharge_enabled boolean DEFAULT false NOT NULL,
    work_trade_hours_target integer DEFAULT 80 NOT NULL,
    public_booking_enabled boolean DEFAULT false NOT NULL,
    booking_slug text,
    booking_intro text,
    booking_deposit_pct numeric(5,2) DEFAULT 10.00 NOT NULL,
    nightly_rate numeric(10,2),
    weekly_rate numeric(10,2),
    monthly_rate numeric(10,2),
    short_term_tax_rate numeric(5,2) DEFAULT 0 NOT NULL,
    weekly_lease_mode boolean DEFAULT false NOT NULL,
    propane_allow_installments boolean DEFAULT false NOT NULL,
    propane_split_min_gallons integer DEFAULT 40 NOT NULL,
    propane_split_four_min_gallons integer DEFAULT 100 NOT NULL,
    booking_monthly_deposit numeric(10,2),
    booking_utilities_billed boolean DEFAULT true NOT NULL,
    office_phone text,
    office_email text,
    office_hours text,
    latitude numeric(9,6),
    longitude numeric(9,6),
    address_verification text DEFAULT 'unverified'::text NOT NULL,
    address_verified_at timestamp with time zone,
    default_occupancy_mode text DEFAULT 'whole_unit'::text NOT NULL,
    operator_owns_land boolean DEFAULT true NOT NULL,
    onboarding_started_at timestamp with time zone,
    onboarding_window_until timestamp with time zone,
    onboarding_completed_at timestamp with time zone,
    flex_charge_finance_pct numeric(5,4) DEFAULT 0 NOT NULL,
    booking_about text,
    booking_area text,
    lease_signer_user_id uuid,
    gam_debit_threshold numeric(12,2) DEFAULT 100.00 NOT NULL,
    timezone_source text DEFAULT 'derived'::text NOT NULL,
    lease_signing_email text,
    lease_signing_name text,
    propane_markup_per_gallon numeric(8,4) DEFAULT 0 NOT NULL,
    first_billing_cycle date,
    onboarding_late_fee_waiver boolean,
    estimates_stuck_meters boolean DEFAULT false NOT NULL,
    move_in_collects_next_period boolean DEFAULT false NOT NULL,
    rent_due_mode text DEFAULT 'fixed_day'::text NOT NULL,
    rent_due_day integer DEFAULT 1 NOT NULL,
    stripe_terminal_location_id text,
    register_card_fee_payer text DEFAULT 'customer'::text NOT NULL,
    booking_card_fee_payer text DEFAULT 'customer'::text NOT NULL,
    maintenance_categories text[],
    maintenance_note text,
    meter_photo_required boolean DEFAULT false NOT NULL,
    accept_partial_payments boolean DEFAULT false NOT NULL,
    tenants_deposit_at_bank boolean DEFAULT false NOT NULL,
    early_departure_refunds boolean DEFAULT true NOT NULL,
    prorates_mid_month_rent boolean DEFAULT true NOT NULL,
    late_fee_initial_amount numeric(10,2),
    late_fee_initial_type text,
    late_fee_accrual_amount numeric(10,2),
    late_fee_accrual_type text,
    late_fee_accrual_period text,
    late_fee_cap_amount numeric(10,2),
    late_fee_cap_type text,
    accepts_checks boolean DEFAULT true NOT NULL,
    home_payments_own_bill boolean DEFAULT true NOT NULL,
    credit_save_up_allowed boolean DEFAULT true NOT NULL,
    print_all_bills boolean DEFAULT false NOT NULL,
    CONSTRAINT properties_address_verification_check CHECK ((address_verification = ANY (ARRAY['unverified'::text, 'geocoded'::text, 'parcel'::text]))),
    CONSTRAINT properties_booking_card_fee_payer_check CHECK ((booking_card_fee_payer = ANY (ARRAY['customer'::text, 'landlord'::text]))),
    CONSTRAINT properties_booking_deposit_pct_steps CHECK ((booking_deposit_pct = ANY (ARRAY[(5)::numeric, (10)::numeric, (15)::numeric, (20)::numeric]))),
    CONSTRAINT properties_booking_slug_format CHECK (((booking_slug IS NULL) OR ((booking_slug ~ '^[a-z0-9][a-z0-9-]{1,60}$'::text) AND (booking_slug !~ '--'::text)))),
    CONSTRAINT properties_default_occupancy_mode_check CHECK ((default_occupancy_mode = ANY (ARRAY['whole_unit'::text, 'by_room'::text]))),
    CONSTRAINT properties_deposit_handling_mode_check CHECK ((deposit_handling_mode = ANY (ARRAY['gam_escrow'::text, 'landlord_held'::text]))),
    CONSTRAINT properties_deposit_interest_accrual_method_check CHECK ((deposit_interest_accrual_method = ANY (ARRAY['simple'::text, 'compound'::text]))),
    CONSTRAINT properties_deposit_interest_payment_cadence_check CHECK ((deposit_interest_payment_cadence = ANY (ARRAY['annual'::text, 'at_return'::text, 'on_anniversary'::text]))),
    CONSTRAINT properties_first_billing_cycle_is_month CHECK (((first_billing_cycle IS NULL) OR (date_trunc('month'::text, (first_billing_cycle)::timestamp with time zone) = first_billing_cycle))),
    CONSTRAINT properties_flex_charge_finance_pct_check CHECK (((flex_charge_finance_pct >= (0)::numeric) AND (flex_charge_finance_pct <= 0.06))),
    CONSTRAINT properties_propane_markup_sane CHECK (((propane_markup_per_gallon >= (0)::numeric) AND (propane_markup_per_gallon <= (10)::numeric))),
    CONSTRAINT properties_propane_split_four_gte_min_check CHECK ((propane_split_four_min_gallons >= propane_split_min_gallons)),
    CONSTRAINT properties_propane_split_min_gallons_check CHECK ((propane_split_min_gallons > 0)),
    CONSTRAINT properties_public_booking_enabled_needs_slug CHECK (((public_booking_enabled = false) OR (booking_slug IS NOT NULL))),
    CONSTRAINT properties_register_card_fee_payer_check CHECK ((register_card_fee_payer = ANY (ARRAY['customer'::text, 'landlord'::text]))),
    CONSTRAINT properties_rent_due_day_check CHECK (((rent_due_day >= 1) AND (rent_due_day <= 28))),
    CONSTRAINT properties_rent_due_mode_check CHECK ((rent_due_mode = ANY (ARRAY['fixed_day'::text, 'move_in_day'::text]))),
    CONSTRAINT properties_review_status_check CHECK ((review_status = ANY (ARRAY['active'::text, 'pending_review'::text, 'rejected'::text]))),
    CONSTRAINT properties_short_term_tax_rate_range CHECK (((short_term_tax_rate >= (0)::numeric) AND (short_term_tax_rate <= (100)::numeric))),
    CONSTRAINT properties_timezone_source_check CHECK ((timezone_source = ANY (ARRAY['derived'::text, 'manual'::text]))),
    CONSTRAINT properties_work_trade_hours_target_pos CHECK ((work_trade_hours_target > 0))
);


--
-- Name: COLUMN properties.requires_booking_acknowledgment; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.requires_booking_acknowledgment IS 'When true, bookings on this property require landlord/staff to mark acknowledged after collecting signature on property-rules doc.';


--
-- Name: COLUMN properties.flexcharge_enabled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.flexcharge_enabled IS 'S309: per-Location FlexCharge enablement gate. When FALSE (default), createFlexChargeAccount rejects new accounts at this property with a 403 and the landlord-side create UI hides the property from the dropdown. Existing flex_charge_accounts continue to function regardless of this flag — the gate applies to NEW account creation only.';


--
-- Name: COLUMN properties.short_term_tax_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.short_term_tax_rate IS '10/17 (Nic): DERIVED — the percent a stay here is taxed at, kept in step with the company''s own tax list (the active on_stays rows of pos_tax_rates) by trg_pos_tax_rates_sync_stay_tax. Every door prices a stay from this one number; change the rate on the Taxes screen, never here.';


--
-- Name: COLUMN properties.operator_owns_land; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.operator_owns_land IS 'S568: FALSE = homes-only external park (investor operates here without owning the land; park owner not on GAM). TRUE = operator owns the park.';


--
-- Name: COLUMN properties.booking_about; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.booking_about IS 'S602 public booking site — the landlord''s story / about-us section (who they are, family-owned, years running). Free text, rendered on the subdomain site.';


--
-- Name: COLUMN properties.booking_area; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.booking_area IS 'S602 public booking site — local area & things-to-do section. Free text, rendered on the subdomain site.';


--
-- Name: COLUMN properties.lease_signer_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.lease_signer_user_id IS 'S605: on-site manager designated to sign leases for this property, in place of the account owner. Exactly one. Entitlement is re-checked at signing time; NULL or an un-entitled user means the owner signs.';


--
-- Name: COLUMN properties.gam_debit_threshold; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.gam_debit_threshold IS 'Outstanding balance owed to GAM at which we debit the landlord directly rather than waiting to net it out of their next disbursement. Raise it when the cost of the movement outweighs the fees. Default $100 (S620).';


--
-- Name: COLUMN properties.timezone_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.timezone_source IS 'S624: derived = from the property state; manual = a human set it and no derivation may overwrite it.';


--
-- Name: COLUMN properties.lease_signing_email; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.lease_signing_email IS 'Where landlord lease-signature requests and lease notifications for THIS property go. Falls back to the account email. Never shown to guests — see office_email for that.';


--
-- Name: COLUMN properties.propane_markup_per_gallon; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.propane_markup_per_gallon IS 'S632: cents-per-gallon added to the delivery''s true cost to reach the billed rate. Applies to every fill at the property regardless of payment plan — a margin, not a finance charge.';


--
-- Name: COLUMN properties.first_billing_cycle; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.first_billing_cycle IS 'S632: the first month GAM invoices THIS property''s existing (onboarded) tenants for. Per property because onboarding is per property. NULL = bill the month each lease starts in.';


--
-- Name: COLUMN properties.onboarding_late_fee_waiver; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.onboarding_late_fee_waiver IS 'S648: landlord''s answer to "waive late fees on each existing resident''s first bill while they migrate?". TRUE = that first invoice never accrues late fees. FALSE or NULL (unanswered) = late fees apply per the lease.';


--
-- Name: COLUMN properties.estimates_stuck_meters; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.estimates_stuck_meters IS 'S648: landlord setting. TRUE = a stuck or out-of-service submeter on an occupied space bills the low-end usage of occupied neighbours until repaired. FALSE (default) = the meter is flagged broken and bills nothing until it is marked repaired with a fresh starting reading.';


--
-- Name: COLUMN properties.move_in_collects_next_period; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.move_in_collects_next_period IS 'S648: TRUE = a new tenant moving in mid-cycle pays the proration AND the next full month at move-in (that regular bill is then skipped). FALSE = proration only; the next month bills on the regular cycle.';


--
-- Name: COLUMN properties.rent_due_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.rent_due_mode IS 'S648: fixed_day = every lease due on rent_due_day; move_in_day = each lease due on its move-in day (no proration; 29th-31st move-ins due on the 1st).';


--
-- Name: COLUMN properties.accept_partial_payments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.accept_partial_payments IS '10/5 (Nic): a payment RECORDED here (cash, check, money order, bank deposit) may be less than what is owed: it pays the oldest bills first, a rent bill it does not cover stays open for the rest, and late fees keep applying to it. Online payments still pay in full. Default off.';


--
-- Name: COLUMN properties.tenants_deposit_at_bank; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.tenants_deposit_at_bank IS '10/6 (Nic): tenants may deposit rent directly at the landlord''s bank. ON: the tenant may report a bank deposit, the landlord may record a "Bank deposit", and the bank feed matches bank lines to tenants'' bills here by itself (the bank''s date decides late fees). OFF (default): all three are refused; the office''s own deposit slips still match.';


--
-- Name: COLUMN properties.early_departure_refunds; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.early_departure_refunds IS '10/18 (Nic): does this property give money back when someone leaves early? "the difference for the refund if the landlord does refunds at all at that property." FALSE = the price as booked stands: the check-out window offers no refund and says so, and rent paid past the day they left stays on the resident''s account as money paid ahead. Never gates checking the guest out, ending their lease, or what an unpaid stay is charged. Default TRUE = what every property did before this column existed.';


--
-- Name: COLUMN properties.prorates_mid_month_rent; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.prorates_mid_month_rent IS '10/18 (Nic): does this property prorate rent when a long-term resident moves in or out mid-month? "only if the landlord allows the pro rate." FALSE = a whole month is a whole month both ways: the month moved into is billed whole on page 8 and the move-in invoice, and the month moved out of is owed whole. TRUE = the days are counted against the ACTUAL days in that month, via the one proration GAM has (shared moveInCharges prorateMoveInRent) — never a flat 30. Also governs the prorated tail of a long stay whose guest leaves part-way into another month (shared stayPricing priceNightsStayed), which is NEW on 10/18 and arrives switched on at every property by this default, deliberately; move-in proration is what every property already did.';


--
-- Name: COLUMN properties.late_fee_initial_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.late_fee_initial_amount IS '10/19 (Nic): no default here, ever. A real late-fee policy lives in property_unit_type_late_fees per unit type and is stamped onto the lease; this is read only by the state-law warning on the property page and is NULL until somebody deliberately sets it.';


--
-- Name: COLUMN properties.accepts_checks; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.accepts_checks IS '10/23 (Nic): "that needs to be turned on or off if a property chooses to accept checks. A lot of places don''t accept them." Defaults TRUE because every property already takes a check on an invoice.';


--
-- Name: COLUMN properties.home_payments_own_bill; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.home_payments_own_bill IS 'TRUE (default): an installment (home/trailer) payment is billed on the
   contract''s own bill, paid separately from the space rent. FALSE: it rides
   the buyer''s rent bill for that month, when there is one. A buyer with no
   rent bill for the month is billed on their own bill either way.';


--
-- Name: COLUMN properties.credit_save_up_allowed; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.credit_save_up_allowed IS 'FALSE: the pay screen never offers "Save it for later" — account credit goes
   on the bill being paid and the tenant pays the rest (Nic, 10/26). Credit
   already auto-applies to an open balance on every property regardless of this
   (10/15); this governs only the payer''s option to hold it back. An
   overpayment surplus is still banked and applied at the next bill run.';


--
-- Name: COLUMN properties.print_all_bills; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.properties.print_all_bills IS 'Landlord prints every bill regardless of each resident''s preference (10/26, Nic: "maybe there''s a quick toggle for landlords that are just like, I''m going to print them all anyway").';


--
-- Name: property_agent_permissions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.property_agent_permissions (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    property_id uuid NOT NULL,
    capability text NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT property_agent_permissions_capability_check CHECK ((capability = ANY (ARRAY['take_payment'::text, 'lease_renewal'::text, 'bill_fee'::text])))
);


--
-- Name: TABLE property_agent_permissions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.property_agent_permissions IS 'Per-property landlord opt-in for revenue-affecting agent actions. No row OR enabled=false => the agent may NOT take that action on that property. Capability set mirrors AGENT_REVENUE_CAPABILITIES in packages/shared.';


--
-- Name: property_allocation_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.property_allocation_rules (
    property_id uuid NOT NULL,
    rent_percent numeric(5,2),
    rent_percent_floor numeric(10,2),
    rent_percent_ceiling numeric(10,2),
    flat_monthly_fee numeric(10,2),
    per_unit_fee numeric(10,2),
    placement_fee_type text,
    placement_fee_value numeric(10,2),
    maintenance_markup_percent numeric(5,2),
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    owner_bank_account_id uuid,
    ach_fee_payer text NOT NULL,
    card_fee_payer text NOT NULL,
    platform_fee_payer text DEFAULT 'landlord'::text NOT NULL,
    manual_fee_payer text DEFAULT 'tenant'::text NOT NULL,
    CONSTRAINT property_allocation_rules_ach_fee_payer_check CHECK ((ach_fee_payer = ANY (ARRAY['landlord'::text, 'tenant'::text]))),
    CONSTRAINT property_allocation_rules_card_fee_payer_check CHECK ((card_fee_payer = ANY (ARRAY['landlord'::text, 'tenant'::text]))),
    CONSTRAINT property_allocation_rules_manual_fee_payer_check CHECK ((manual_fee_payer = ANY (ARRAY['landlord'::text, 'tenant'::text]))),
    CONSTRAINT property_allocation_rules_placement_fee_paired CHECK (((placement_fee_type IS NULL) = (placement_fee_value IS NULL))),
    CONSTRAINT property_allocation_rules_placement_fee_type_check CHECK (((placement_fee_type IS NULL) OR (placement_fee_type = ANY (ARRAY['flat'::text, 'percent_of_first_month'::text])))),
    CONSTRAINT property_allocation_rules_platform_fee_payer_check CHECK ((platform_fee_payer = 'landlord'::text))
);


--
-- Name: COLUMN property_allocation_rules.platform_fee_payer; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.property_allocation_rules.platform_fee_payer IS 'S607: LOCKED to landlord. The platform fee is GAM''s commercial relationship with the landlord and must never reach a tenant''s bill — otherwise a volume discount GAM grants a landlord would change what that landlord''s tenants pay. Column retained (rather than dropped) because platform_fee_accruals.payer snapshots it per accrual.';


--
-- Name: COLUMN property_allocation_rules.manual_fee_payer; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.property_allocation_rules.manual_fee_payer IS 'S607: who reimburses the $10 cash/check/money-order fee. tenant (default) = the tenant is invoiced for it. landlord = the landlord absorbs it and no tenant charge is raised. GAM recovers the fee from the landlord''s collections either way; this only decides whether the tenant is billed to make them whole.';


--
-- Name: property_duplicate_flags; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.property_duplicate_flags (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    property_id uuid NOT NULL,
    conflicting_property_id uuid NOT NULL,
    reason text DEFAULT 'duplicate_address'::text NOT NULL,
    normalized_key text,
    detected_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    resolved_by uuid,
    resolution text,
    notes text,
    CONSTRAINT property_duplicate_flags_resolution_check CHECK ((resolution = ANY (ARRAY['approved_separate'::text, 'merged'::text, 'rejected'::text])))
);


--
-- Name: property_faqs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.property_faqs (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    property_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    question text NOT NULL,
    answer text NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: property_fee_schedules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.property_fee_schedules (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    property_id uuid NOT NULL,
    fee_type text NOT NULL,
    slot_index integer DEFAULT 0 NOT NULL,
    description text,
    amount numeric(10,2) NOT NULL,
    is_refundable boolean NOT NULL,
    due_timing text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    unit_type text NOT NULL,
    CONSTRAINT property_fee_schedules_amount_check CHECK ((amount >= (0)::numeric)),
    CONSTRAINT property_fee_schedules_due_timing_check CHECK ((due_timing = ANY (ARRAY['move_in'::text, 'monthly_ongoing'::text, 'move_out'::text, 'other'::text]))),
    CONSTRAINT property_fee_schedules_fee_type_check CHECK ((fee_type = ANY (ARRAY['security_deposit'::text, 'pet_deposit'::text, 'key_deposit'::text, 'cleaning_deposit'::text, 'utility_deposit'::text, 'move_in_fee'::text, 'cleaning_fee'::text, 'pet_fee'::text, 'application_fee'::text, 'amenity_fee'::text, 'hoa_transfer_fee'::text, 'lease_prep_fee'::text, 'pet_rent'::text, 'parking_rent'::text, 'storage_rent'::text, 'amenity_fee_monthly'::text, 'trash_fee'::text, 'pest_control_fee'::text, 'technology_fee'::text, 'last_month_rent'::text, 'early_termination_fee'::text, 'other_fee'::text]))),
    CONSTRAINT property_fee_schedules_slot_index_check CHECK ((slot_index >= 0)),
    CONSTRAINT property_fee_schedules_unit_type_check CHECK ((unit_type = ANY (ARRAY['apartment'::text, 'single_family'::text, 'rv_spot'::text, 'campsite'::text, 'mobile_home'::text, 'hotel_room'::text, 'storage'::text, 'parking'::text, 'boat_slip'::text, 'land_lot'::text, 'commercial'::text])))
);


--
-- Name: COLUMN property_fee_schedules.unit_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.property_fee_schedules.unit_type IS 'S648: which kind of unit at this property the fee applies to. A new lease''s fee boxes pre-fill from the rows matching its unit''s type.';


--
-- Name: property_growth_snapshots; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.property_growth_snapshots (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    snapshot_date date NOT NULL,
    property_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    units integer DEFAULT 0 NOT NULL,
    occupied_units integer DEFAULT 0 NOT NULL,
    vacant_units integer DEFAULT 0 NOT NULL,
    delinquent_units integer DEFAULT 0 NOT NULL,
    suspended_units integer DEFAULT 0 NOT NULL,
    active_leases integer DEFAULT 0 NOT NULL,
    active_tenants integer DEFAULT 0 NOT NULL,
    monthly_rent_roll numeric(14,2) DEFAULT 0 NOT NULL,
    outstanding_balance numeric(14,2) DEFAULT 0 NOT NULL,
    open_maintenance integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: property_inquiries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.property_inquiries (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    property_id uuid NOT NULL,
    guest_name text NOT NULL,
    guest_email text NOT NULL,
    guest_phone text,
    message text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    handled_at timestamp with time zone
);


--
