    CONSTRAINT state_application_fee_caps_check CHECK (((fee_prohibited = false) OR (cap_amount IS NULL)))
);


--
-- Name: state_deposit_custody_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.state_deposit_custody_rules (
    state_code text NOT NULL,
    custody_status text NOT NULL,
    allows_treasury_bills boolean DEFAULT false NOT NULL,
    requires_in_state_depository boolean DEFAULT false NOT NULL,
    requires_federally_insured boolean DEFAULT false NOT NULL,
    requires_interest_bearing boolean DEFAULT false NOT NULL,
    prohibits_use_of_funds boolean DEFAULT false NOT NULL,
    statute_citation text,
    notes text,
    researched_at date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    institution_test text,
    geography_test text,
    qualifies_with_segregated_account boolean,
    bond_alternative boolean DEFAULT false NOT NULL,
    bond_notes text,
    blocked_reason text,
    CONSTRAINT sdcr_geography_check CHECK (((geography_test IS NULL) OR (geography_test = ANY (ARRAY['none'::text, 'doing_business'::text, 'physical_office'::text, 'state_chartered'::text, 'n/a'::text])))),
    CONSTRAINT sdcr_state_check CHECK (((state_code = upper(state_code)) AND (length(state_code) = 2))),
    CONSTRAINT sdcr_status_check CHECK ((custody_status = ANY (ARRAY['supported'::text, 'needs_research'::text, 'blocked'::text]))),
    CONSTRAINT state_deposit_custody_rules_blocked_reason_check CHECK (((blocked_reason IS NULL) OR (blocked_reason = ANY (ARRAY['vehicle_unconfirmed'::text, 'in_state_depository'::text, 'pooling_restricted'::text, 'other'::text]))))
);


--
-- Name: TABLE state_deposit_custody_rules; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.state_deposit_custody_rules IS 'S604: where deposit principal may lawfully be held, per state. Constrains the custody VEHICLE (T-bills vs insured depository). Fail-closed: an absent state reads as needs_research.';


--
-- Name: COLUMN state_deposit_custody_rules.prohibits_use_of_funds; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_deposit_custody_rules.prohibits_use_of_funds IS 'Statute bars hypothecating/pledging/otherwise using the funds (e.g. FL 83.49) — rules out investing the principal regardless of institution.';


--
-- Name: COLUMN state_deposit_custody_rules.geography_test; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_deposit_custody_rules.geography_test IS 'S604: how much in-state presence the institution needs. none < doing_business < physical_office < state_chartered. Only half the test — the account-TYPE question is separate.';


--
-- Name: COLUMN state_deposit_custody_rules.qualifies_with_segregated_account; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_deposit_custody_rules.qualifies_with_segregated_account IS 'S604: would a per-tenant account at an FDIC-insured national bank (Jiko pocket accounts, GAM-controlled disbursement) satisfy this state? NULL = supported already / not applicable.';


--
-- Name: COLUMN state_deposit_custody_rules.blocked_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_deposit_custody_rules.blocked_reason IS 'Why custody_status is blocked. vehicle_unconfirmed = a federally insured FBO would likely satisfy it; in_state_depository = needs a bank in that state; pooling_restricted = a single pooled trust may not be permitted at all. NULL when not blocked.';


--
-- Name: state_deposit_interest_rates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.state_deposit_interest_rates (
    state_code text NOT NULL,
    effective_year integer NOT NULL,
    annual_rate_pct numeric(6,4) NOT NULL,
    statute_citation text NOT NULL,
    source_url text,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    unit_types text[] DEFAULT '{}'::text[] NOT NULL,
    act_key text,
    rate_basis text DEFAULT 'fixed'::text NOT NULL,
    actual_share_pct numeric(6,4),
    admin_retention_pct numeric(6,4),
    min_tenure_months integer,
    min_property_units integer,
    threshold_rule text,
    threshold_amount numeric(10,2),
    threshold_months_rent numeric(5,2),
    min_units_basis text DEFAULT 'all_units'::text NOT NULL,
    CONSTRAINT sdir_rate_basis_check CHECK (((rate_basis = ANY (ARRAY['fixed'::text, 'lesser_of_actual'::text, 'share_of_actual'::text, 'actual_earned'::text, 'actual_minus_admin'::text, 'index_linked'::text, 'none'::text])) AND ((rate_basis <> 'share_of_actual'::text) OR (actual_share_pct IS NOT NULL)) AND ((rate_basis <> 'actual_minus_admin'::text) OR (admin_retention_pct IS NOT NULL)))),
    CONSTRAINT sdir_threshold_check CHECK (((threshold_rule IS NULL) OR (threshold_rule = ANY (ARRAY['trigger'::text, 'excess_only'::text])))),
    CONSTRAINT state_deposit_interest_rates_min_units_basis_check CHECK ((min_units_basis = ANY (ARRAY['all_units'::text, 'occupied_of_type'::text, 'homes_present'::text]))),
    CONSTRAINT state_deposit_interest_rates_rate_check CHECK (((annual_rate_pct >= (0)::numeric) AND (annual_rate_pct <= (100)::numeric))),
    CONSTRAINT state_deposit_interest_rates_state_check CHECK (((state_code = upper(state_code)) AND (length(state_code) = 2))),
    CONSTRAINT state_deposit_interest_rates_year_check CHECK (((effective_year >= 2020) AND (effective_year <= 2100)))
);


--
-- Name: TABLE state_deposit_interest_rates; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.state_deposit_interest_rates IS 'Per-state, per-year deposit interest rate catalog. Annual-refresh migration cadence per CLAUDE.md S177 carve-out. States not listed have no statutory accrual requirement.';


--
-- Name: COLUMN state_deposit_interest_rates.unit_types; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_deposit_interest_rates.unit_types IS 'GAM unit types this statutory rate governs. EMPTY = blanket rule for the state (applies to any unit type with no more specific row). A specific match always beats the blanket row.';


--
-- Name: COLUMN state_deposit_interest_rates.act_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_deposit_interest_rates.act_key IS 'act_key in state_law_section_texts this rate was read from, so an annual refresh can re-read the statute rather than trust a copied number.';


--
-- Name: COLUMN state_deposit_interest_rates.rate_basis; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_deposit_interest_rates.rate_basis IS 'S604: how the obligation is computed. fixed = flat rate (only basis that can go negative vs market); lesser_of_actual = MIN(rate, earned) e.g. MA; share_of_actual = actual_share_pct%% of earned, e.g. FL 75%%.';


--
-- Name: COLUMN state_deposit_interest_rates.actual_share_pct; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_deposit_interest_rates.actual_share_pct IS 'S604: for share_of_actual — the percentage of ACTUAL earnings owed to the tenant (FL 83.49 = 75).';


--
-- Name: COLUMN state_deposit_interest_rates.admin_retention_pct; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_deposit_interest_rates.admin_retention_pct IS 'S604: annual %% of principal the landlord may retain as administrative expense before the balance of interest goes to the tenant (NY 7-103, PA 511.2 = 1%%).';


--
-- Name: COLUMN state_deposit_interest_rates.min_tenure_months; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_deposit_interest_rates.min_tenure_months IS 'S604: obligation only attaches once the deposit has been held this long (IA 60, NH 12, PA 24). NULL = from day one.';


--
-- Name: COLUMN state_deposit_interest_rates.min_property_units; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_deposit_interest_rates.min_property_units IS 'S604: obligation only attaches at properties of at least this size (IL mobile home parks 25+, NY 6-or-more-family). NULL = any size.';


--
-- Name: COLUMN state_deposit_interest_rates.threshold_rule; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_deposit_interest_rates.threshold_rule IS 'S604: NULL = whole deposit always earns. trigger = whole deposit earns only once it exceeds the threshold (NM). excess_only = only the amount ABOVE the threshold earns (OH).';


--
-- Name: COLUMN state_deposit_interest_rates.threshold_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_deposit_interest_rates.threshold_amount IS 'S604: dollar leg of the threshold. When both this and threshold_months_rent are set, the statute takes WHICHEVER IS GREATER (OH: $50 or one month rent).';


--
-- Name: COLUMN state_deposit_interest_rates.min_units_basis; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_deposit_interest_rates.min_units_basis IS 'What min_property_units counts. all_units = units that exist (765 ILCS 715/1 "25 or more units" — an uninhabitable apartment still counts). homes_present = rows in mobile_homes not yet removed (765 ILCS 745/18 "regularly containing 25 or more mobile homes" — a park-owned home standing empty still counts, a bare slab does not).';


--
-- Name: state_landlord_tenant_acts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.state_landlord_tenant_acts (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    state_code text NOT NULL,
    act_key text NOT NULL,
    act_name text NOT NULL,
    unit_types text[] DEFAULT '{}'::text[] NOT NULL,
    official_url text,
    summary text,
    source_date date NOT NULL,
    effective_year integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT slta_state_check CHECK (((state_code = upper(state_code)) AND (length(state_code) = 2))),
    CONSTRAINT slta_year_check CHECK (((effective_year >= 2020) AND (effective_year <= 2100)))
);


--
-- Name: state_law_provisions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.state_law_provisions (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    act_id uuid NOT NULL,
    state_code text NOT NULL,
    topic text NOT NULL,
    rule_kind text NOT NULL,
    threshold_numeric numeric(12,2),
    threshold_unit text,
    summary text NOT NULL,
    statute_citation text,
    source_url text,
    source_date date NOT NULL,
    effective_year integer NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT slp_rule_kind_check CHECK ((rule_kind = ANY (ARRAY['min'::text, 'max'::text, 'required'::text, 'info'::text]))),
    CONSTRAINT slp_state_check CHECK (((state_code = upper(state_code)) AND (length(state_code) = 2))),
    CONSTRAINT slp_year_check CHECK (((effective_year >= 2020) AND (effective_year <= 2100)))
);


--
-- Name: state_law_section_texts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.state_law_section_texts (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    state_code text NOT NULL,
    act_key text NOT NULL,
    section_number text NOT NULL,
    section_title text,
    full_text text NOT NULL,
    source_url text,
    source_date date NOT NULL,
    effective_year integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    search_tsv tsvector GENERATED ALWAYS AS (to_tsvector('english'::regconfig, ((COALESCE(section_title, ''::text) || ' '::text) || COALESCE(full_text, ''::text)))) STORED,
    law_category text DEFAULT 'landlord_tenant'::text NOT NULL,
    CONSTRAINT slst_law_category_check CHECK ((law_category = ANY (ARRAY['landlord_tenant'::text, 'conveyancing_title'::text, 'condo_coop'::text, 'broker_licensing'::text, 'mortgage_lien_foreclosure'::text, 'property_tax'::text, 'land_use_zoning'::text, 'environmental_disclosure'::text, 'general_real_property'::text]))),
    CONSTRAINT slst_state_check CHECK (((state_code = upper(state_code)) AND (length(state_code) = 2))),
    CONSTRAINT slst_year_check CHECK (((effective_year >= 2020) AND (effective_year <= 2100)))
);


--
-- Name: state_nexus_measure_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.state_nexus_measure_rules (
    state_code text NOT NULL,
    effective_year integer NOT NULL,
    counts_subscription boolean DEFAULT true NOT NULL,
    counts_markup boolean DEFAULT true NOT NULL,
    counts_screening boolean DEFAULT true NOT NULL,
    counts_optin boolean DEFAULT true NOT NULL,
    counts_other boolean DEFAULT true NOT NULL,
    source text,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT snmr_state_check CHECK (((state_code = upper(state_code)) AND (length(state_code) = 2))),
    CONSTRAINT snmr_year_check CHECK (((effective_year >= 2020) AND (effective_year <= 2100)))
);


--
-- Name: TABLE state_nexus_measure_rules; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.state_nexus_measure_rules IS '10/17 (Nic): which of GAM''s revenue line items each state measures toward its economic-nexus threshold. Seeded to count everything — the law differs by state and the published tables disagree, so this is data a tax pro can correct without a code change. Never collects tax.';


--
-- Name: COLUMN state_nexus_measure_rules.counts_subscription; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_nexus_measure_rules.counts_subscription IS 'Does this state count GAM''s platform subscription receipts toward its threshold?';


--
-- Name: COLUMN state_nexus_measure_rules.counts_markup; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_nexus_measure_rules.counts_markup IS 'Does this state count GAM''s card and bank payment markup toward its threshold?';


--
-- Name: COLUMN state_nexus_measure_rules.counts_screening; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_nexus_measure_rules.counts_screening IS 'Does this state count GAM''s screening margin toward its threshold?';


--
-- Name: COLUMN state_nexus_measure_rules.counts_optin; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_nexus_measure_rules.counts_optin IS 'Does this state count what customers pay for opt-in services (FlexPay, credit reporting) toward its threshold?';


--
-- Name: COLUMN state_nexus_measure_rules.counts_other; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_nexus_measure_rules.counts_other IS 'Does this state count GAM''s remaining earnings (card-reader markup, placement fees, anything new) toward its threshold?';


--
-- Name: COLUMN state_nexus_measure_rules.source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_nexus_measure_rules.source IS 'Where the answer came from — the state''s own publication, or the pro who confirmed it.';


--
-- Name: state_nexus_thresholds; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.state_nexus_thresholds (
    state_code text NOT NULL,
    effective_year integer NOT NULL,
    revenue_threshold_usd numeric(12,2),
    txn_threshold integer,
    count_rule text DEFAULT 'or'::text NOT NULL,
    measurement_period text DEFAULT 'prior_or_current_calendar_year'::text NOT NULL,
    status text DEFAULT 'research'::text NOT NULL,
    source text,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT snt_count_rule_check CHECK ((count_rule = ANY (ARRAY['or'::text, 'and'::text, 'revenue_only'::text]))),
    CONSTRAINT snt_revenue_check CHECK (((revenue_threshold_usd IS NULL) OR (revenue_threshold_usd > (0)::numeric))),
    CONSTRAINT snt_state_check CHECK (((state_code = upper(state_code)) AND (length(state_code) = 2))),
    CONSTRAINT snt_status_check CHECK ((status = ANY (ARRAY['research'::text, 'confirmed'::text]))),
    CONSTRAINT snt_txn_check CHECK (((txn_threshold IS NULL) OR (txn_threshold > 0))),
    CONSTRAINT snt_year_check CHECK (((effective_year >= 2020) AND (effective_year <= 2100)))
);


--
-- Name: TABLE state_nexus_thresholds; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.state_nexus_thresholds IS 'Per-state, per-year economic-nexus registration thresholds (S565). Compared against GAM own-revenue-by-customer-state by the nightly nexus tally. A crossing PROMPTS registration; it does not collect tax (collection = state_tax_registrations). Revenue figures high-confidence; txn-count research-grade.';


--
-- Name: COLUMN state_nexus_thresholds.revenue_threshold_usd; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_nexus_thresholds.revenue_threshold_usd IS 'NULL for the no-sales-tax states (DE, MT, NH, OR) — GAM never registers there. AK has no STATE tax but a statewide LOCAL commission (ARSSTC) with a $100k threshold, seeded as such.';


--
-- Name: COLUMN state_nexus_thresholds.count_rule; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_nexus_thresholds.count_rule IS 'or = either threshold triggers (classic Wayfair). and = both required (NY). revenue_only = txn count ignored / repealed.';


--
-- Name: state_property_tax_provisions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.state_property_tax_provisions (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    state_code text NOT NULL,
    jurisdiction_level text DEFAULT 'state'::text NOT NULL,
    topic text NOT NULL,
    subtype text,
    summary text NOT NULL,
    params jsonb DEFAULT '{}'::jsonb NOT NULL,
    statute_citation text,
    source_url text,
    source_date date NOT NULL,
    effective_year integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sptp_level_check CHECK ((jurisdiction_level = ANY (ARRAY['state'::text, 'county'::text, 'municipal'::text]))),
    CONSTRAINT sptp_state_check CHECK (((state_code = upper(state_code)) AND (length(state_code) = 2))),
    CONSTRAINT sptp_topic_check CHECK ((topic = ANY (ARRAY['exemption'::text, 'assessment'::text, 'assessment_appeal'::text, 'payment'::text, 'delinquency_redemption'::text]))),
    CONSTRAINT sptp_year_check CHECK (((effective_year >= 2020) AND (effective_year <= 2100)))
);


--
-- Name: state_screening_tax_rates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.state_screening_tax_rates (
    state_code text NOT NULL,
    effective_year integer NOT NULL,
    taxable boolean DEFAULT false NOT NULL,
    rate_pct numeric(6,4) DEFAULT 0 NOT NULL,
    basis text DEFAULT 'screening'::text NOT NULL,
    status text DEFAULT 'research'::text NOT NULL,
    source text,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sstr_basis_check CHECK ((basis = ANY (ARRAY['screening'::text, 'screening_plus_gamfee'::text, 'total'::text]))),
    CONSTRAINT sstr_rate_check CHECK (((rate_pct >= (0)::numeric) AND (rate_pct <= (100)::numeric))),
    CONSTRAINT sstr_state_check CHECK (((state_code = upper(state_code)) AND (length(state_code) = 2))),
    CONSTRAINT sstr_status_check CHECK ((status = ANY (ARRAY['research'::text, 'confirmed'::text]))),
    CONSTRAINT sstr_taxable_rate_coherent CHECK ((((taxable = false) AND (rate_pct = (0)::numeric)) OR ((taxable = true) AND (rate_pct > (0)::numeric)))),
    CONSTRAINT sstr_year_check CHECK (((effective_year >= 2020) AND (effective_year <= 2100)))
);


--
-- Name: TABLE state_screening_tax_rates; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.state_screening_tax_rates IS 'Per-state, per-year screening-service sales-tax catalog (S565). taxable+rate = the legal fact; actual collection is ALSO gated on state_tax_registrations.registered. Non-$0 rows are status=research until a tax pro confirms. Base = the screening price line only.';


--
-- Name: COLUMN state_screening_tax_rates.rate_pct; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_screening_tax_rates.rate_pct IS 'State base rate only. Local/county surtaxes (TX, SD, NM, HI county surcharge) are NOT modeled here — flagged in notes; add a local-rate layer only if a registered state needs it.';


--
-- Name: COLUMN state_screening_tax_rates.basis; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_screening_tax_rates.basis IS 'What the rate multiplies: screening = the Checkr pass-through screening line only (default, per S564). screening_plus_gamfee / total reserved if a state proves to tax the full receipt.';


--
-- Name: state_tax_forms; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.state_tax_forms (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    state_code text NOT NULL,
    form_code text NOT NULL,
    form_name text NOT NULL,
    agency text NOT NULL,
    agency_url text,
    category text NOT NULL,
    frequency text NOT NULL,
    due_dates jsonb NOT NULL,
    applies_to text NOT NULL,
    statute text,
    notes text,
    effective_year integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    filing_method text DEFAULT 'paper_form'::text NOT NULL,
    CONSTRAINT state_tax_forms_applies_check CHECK ((applies_to = ANY (ARRAY['all_landlords'::text, 'with_employees_in_state'::text, 'with_property_in_state'::text, 'with_contractors_paid_600'::text]))),
    CONSTRAINT state_tax_forms_category_check CHECK ((category = ANY (ARRAY['withholding'::text, 'unemployment'::text, 'reconciliation'::text, 'income'::text, 'sales_tax'::text, 'other'::text]))),
    CONSTRAINT state_tax_forms_filing_method_check CHECK ((filing_method = ANY (ARRAY['paper_form'::text, 'online_portal'::text]))),
    CONSTRAINT state_tax_forms_frequency_check CHECK ((frequency = ANY (ARRAY['quarterly'::text, 'annual'::text, 'monthly'::text, 'biennial'::text]))),
    CONSTRAINT state_tax_forms_state_check CHECK (((state_code = upper(state_code)) AND (length(state_code) = 2))),
    CONSTRAINT state_tax_forms_year_check CHECK (((effective_year >= 2020) AND (effective_year <= 2100)))
);


--
-- Name: TABLE state_tax_forms; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.state_tax_forms IS 'S203 / S177 carve-out: hardcoded per-state tax form catalog with annual-refresh migration cadence. GAM surfaces deadlines; never files forms.';


--
-- Name: COLUMN state_tax_forms.filing_method; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.state_tax_forms.filing_method IS 'S207: paper_form (form_code is official agency code) vs online_portal (form_code is descriptive label, file via agency_url). Source of truth for values: packages/shared/src/index.ts FILING_METHOD_VALUES.';


--
-- Name: state_tax_registrations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.state_tax_registrations (
    state_code text NOT NULL,
    registered boolean DEFAULT false NOT NULL,
    registered_date date,
    source text DEFAULT 'manual'::text NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT str_source_check CHECK ((source = ANY (ARRAY['manual'::text, 'nexus_auto'::text]))),
    CONSTRAINT str_state_check CHECK (((state_code = upper(state_code)) AND (length(state_code) = 2)))
);


--
-- Name: TABLE state_tax_registrations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.state_tax_registrations IS 'Per-state sales-tax registration status (S565). The gate the tax catalog reads: collection happens ONLY where registered=true. Empty/false everywhere at launch → $0 collected nationwide, zero risk. Flipped by admin (manual) or by the nexus monitor crossing a threshold.';


--
-- Name: stay_checkout_decisions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.stay_checkout_decisions (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    booking_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    lease_id uuid,
    left_on date NOT NULL,
    question text NOT NULL,
    choice text,
    status text DEFAULT 'pending'::text NOT NULL,
    booked_price numeric(10,2) NOT NULL,
    stayed_worth numeric(10,2) NOT NULL,
    paid numeric(10,2) NOT NULL,
    price_after numeric(10,2),
    refund_total numeric(10,2) DEFAULT 0 NOT NULL,
    stamped_paid boolean DEFAULT false NOT NULL,
    idempotency_key text,
    created_by uuid,
    decided_by uuid,
    decided_at timestamp with time zone,
    undone_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT stay_checkout_decisions_choice_check CHECK (((choice IS NULL) OR (choice = ANY (ARRAY['keep_price'::text, 'nights_only'::text, 'no_refund'::text, 'refund_unused'::text, 'refund_other'::text])))),
    CONSTRAINT stay_checkout_decisions_decided_shape CHECK ((((status = 'pending'::text) AND (choice IS NULL) AND (decided_at IS NULL)) OR ((status = 'decided'::text) AND (choice IS NOT NULL) AND (decided_at IS NOT NULL)) OR ((status = 'undone'::text) AND (undone_at IS NOT NULL)))),
    CONSTRAINT stay_checkout_decisions_money_check CHECK (((booked_price >= (0)::numeric) AND (stayed_worth >= (0)::numeric) AND (paid >= (0)::numeric) AND (refund_total >= (0)::numeric) AND (refund_total <= paid))),
    CONSTRAINT stay_checkout_decisions_question_check CHECK ((question = ANY (ARRAY['owes'::text, 'overpaid'::text]))),
    CONSTRAINT stay_checkout_decisions_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'decided'::text, 'undone'::text])))
);


--
-- Name: TABLE stay_checkout_decisions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.stay_checkout_decisions IS '10/4 (decisions #37.B, #38): the money question an early check-out asked (still owes / paid more than the nights stayed are worth), what was chosen and by whom. One live (pending or decided) per stay.';


--
-- Name: stay_payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.stay_payments (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    booking_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    kind text NOT NULL,
    pos_transaction_id uuid,
    stripe_payment_intent_id text,
    method text NOT NULL,
    toward_stay numeric(10,2) NOT NULL,
    card_fee numeric(10,2) DEFAULT 0 NOT NULL,
    landlord_card_fee numeric(10,2) DEFAULT 0 NOT NULL,
    paid_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    lodging_tax_amount numeric(10,2),
    CONSTRAINT stay_payments_card_has_intent CHECK (((method <> ALL (ARRAY['card'::text, 'card_on_file'::text])) OR (stripe_payment_intent_id IS NOT NULL))),
    CONSTRAINT stay_payments_fees_check CHECK (((card_fee >= (0)::numeric) AND (landlord_card_fee >= (0)::numeric))),
    CONSTRAINT stay_payments_kind_check CHECK ((kind = ANY (ARRAY['site_deposit'::text, 'pos_sale'::text]))),
    CONSTRAINT stay_payments_method_check CHECK ((method = ANY (ARRAY['card'::text, 'card_on_file'::text, 'cash'::text, 'check'::text, 'charge'::text]))),
    CONSTRAINT stay_payments_source_shape CHECK ((((kind = 'pos_sale'::text) AND (pos_transaction_id IS NOT NULL)) OR ((kind = 'site_deposit'::text) AND (pos_transaction_id IS NULL) AND (stripe_payment_intent_id IS NOT NULL) AND (method = 'card'::text)))),
    CONSTRAINT stay_payments_toward_check CHECK ((toward_stay > (0)::numeric))
);


--
-- Name: TABLE stay_payments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.stay_payments IS '10/4 (decisions #37.B, #38): one row per payment toward a stay — how it was paid, how much of it was for the stay, and the card fee on that share. An early check-out reads what the guest paid only from here and refunds each payment back the way it came, most recent first.';


--
-- Name: COLUMN stay_payments.lodging_tax_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.stay_payments.lodging_tax_amount IS '10/12 (Nic, ledger P1): the lodging tax inside toward_stay on a booking-site deposit, as priced the day it was paid. NULL on a pos_sale row: the sale stores its own taxes (pos_transactions.tax_breakdown).';


--
-- Name: stay_refund_parts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.stay_refund_parts (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    decision_id uuid,
    booking_id uuid,
    landlord_id uuid NOT NULL,
    seq integer NOT NULL,
    kind text NOT NULL,
    stay_payment_id uuid,
    remittance_id uuid,
    prepaid_credit_id uuid,
    pos_transaction_id uuid,
    stripe_payment_intent_id text,
    toward_amount numeric(10,2) NOT NULL,
    card_fee_back numeric(10,2) DEFAULT 0 NOT NULL,
    amount numeric(10,2) NOT NULL,
    payout_drop numeric(10,2) DEFAULT 0 NOT NULL,
    lodging_tax_share numeric(10,2) DEFAULT 0 NOT NULL,
    label text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    stripe_refund_id text,
    pos_refund_id uuid,
    failure text,
    refunded_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    reversed_at timestamp with time zone,
    replaces_part_id uuid,
    paid_ahead_choice_id uuid,
    deposit_return_id uuid,
    deposit_payment_id uuid,
    CONSTRAINT stay_refund_parts_amount_check CHECK (((toward_amount > (0)::numeric) AND (card_fee_back >= (0)::numeric) AND (amount = (toward_amount + card_fee_back)) AND (payout_drop >= (0)::numeric) AND (lodging_tax_share >= (0)::numeric))),
    CONSTRAINT stay_refund_parts_done_shape CHECK (((status = ANY (ARRAY['refunded'::text, 'handed_back'::text, 'credited'::text])) = (refunded_at IS NOT NULL))),
    CONSTRAINT stay_refund_parts_kind_check CHECK ((kind = ANY (ARRAY['card'::text, 'bank'::text, 'cash'::text, 'check'::text, 'money_order'::text, 'charge'::text, 'credit'::text]))),
    CONSTRAINT stay_refund_parts_one_parent CHECK ((num_nonnulls(decision_id, paid_ahead_choice_id, deposit_return_id) = 1)),
    CONSTRAINT stay_refund_parts_reversed_shape CHECK (((reversed_at IS NULL) OR ((status = 'refunded'::text) AND (kind = ANY (ARRAY['card'::text, 'bank'::text])) AND (reversed_at >= refunded_at)))),
    CONSTRAINT stay_refund_parts_source_check CHECK (((num_nonnulls(stay_payment_id, remittance_id, prepaid_credit_id, deposit_payment_id) >= 1) OR (deposit_return_id IS NOT NULL))),
    CONSTRAINT stay_refund_parts_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'refunded'::text, 'handed_back'::text, 'credited'::text, 'failed'::text, 'replaced'::text]))),
    CONSTRAINT stay_refund_parts_stay_part_has_booking CHECK (((decision_id IS NULL) OR (booking_id IS NOT NULL))),
    CONSTRAINT stay_refund_parts_stripe_shape CHECK (((kind <> ALL (ARRAY['card'::text, 'bank'::text])) OR (stripe_payment_intent_id IS NOT NULL)))
);


--
-- Name: TABLE stay_refund_parts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.stay_refund_parts IS '10/4 (decisions #37.B, #38): each payment an early check-out refund went back to — the way it was paid, most recent first — with what the guest got back (card fee included, #38 Q4) and what the landlord''s payout dropped by.';


--
-- Name: COLUMN stay_refund_parts.reversed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.stay_refund_parts.reversed_at IS '10/4 fix round 2: Stripe sent this refund back at this instant. The part keeps its own refund day; income adds it back on this day; its replacement part (replaces_part_id) carries what is still owed to the guest.';


--
-- Name: COLUMN stay_refund_parts.replaces_part_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.stay_refund_parts.replaces_part_id IS '10/4 fix round 2: the part this one takes the place of — a card refund Stripe sent back (reversed_at), or a failed card part given back in cash instead (status replaced).';


--
-- Name: COLUMN stay_refund_parts.paid_ahead_choice_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.stay_refund_parts.paid_ahead_choice_id IS '10/4 (decisions #46.1): a refund part of the landlord''s choice for paid-ahead money left on an ended lease (paid_ahead_choices) instead of an early check-out decision. booking_id is the lease''s stay when it came from one, else NULL.';


--
-- Name: COLUMN stay_refund_parts.deposit_return_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.stay_refund_parts.deposit_return_id IS '10/4 (decisions #47a): a refund part of a finalized move-out — the part of the deposit refund GAM holds, sent back the way the deposit was paid (or given back in cash at the office when that payment cannot take it). booking_id is NULL.';


--
-- Name: COLUMN stay_refund_parts.deposit_payment_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.stay_refund_parts.deposit_payment_id IS '10/4 (decisions #47a): the deposit payment (payments.id, type deposit) a move-out refund part goes back to. NULL on a cash part with no Stripe payment behind it (deposit interest, a record raised without one).';


--
-- Name: stay_shortened_charge_choices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.stay_shortened_charge_choices (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    booking_id uuid NOT NULL,
    lease_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    new_check_out date NOT NULL,
    choice text NOT NULL,
    payment_ids uuid[] NOT NULL,
    chosen_by uuid,
    chosen_at timestamp with time zone DEFAULT now() NOT NULL,
    applied_at timestamp with time zone,
    CONSTRAINT stay_shortened_charge_choices_choice_check CHECK ((choice = ANY (ARRAY['void'::text, 'keep'::text])))
);


--
-- Name: TABLE stay_shortened_charge_choices; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.stay_shortened_charge_choices IS '10/12 (Nic, G6): the landlord''s answer, given when a stay was shortened, for unpaid rent on the nights it no longer has that a payment was tried on — void it (money paid on it comes back as credit) or keep it owed. Carried out by services/bookingLeaseBilling syncLeaseWithBookingDates.';


--
-- Name: stripe_processing_costs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.stripe_processing_costs (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    stripe_txn_id text NOT NULL,
    txn_type text NOT NULL,
    category text NOT NULL,
    description text,
    amount numeric(12,2) NOT NULL,
    posted_at timestamp with time zone NOT NULL,
    period_start date,
    period_end date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    stripe_payment_intent_id text,
    CONSTRAINT stripe_processing_costs_amount_check CHECK ((amount >= (0)::numeric))
);


--
-- Name: TABLE stripe_processing_costs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.stripe_processing_costs IS 'What Stripe charged GAM, as Stripe states it. Unbundled pricing attributes no cost to individual charges, so these are daily aggregates; margin is exact by day/month, never per payment.';


--
-- Name: COLUMN stripe_processing_costs.stripe_payment_intent_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.stripe_processing_costs.stripe_payment_intent_id IS '10/3: the PaymentIntent of the charge this fee came from (bank-payment and per-charge card fees only; NULL for daily card aggregates and monthly charges). Ties a bank payment to what Stripe took on it.';


--
-- Name: stripe_webhook_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.stripe_webhook_events (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    stripe_event_id text NOT NULL,
    event_type text NOT NULL,
    api_version text,
    livemode boolean NOT NULL,
    payload jsonb NOT NULL,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    processing_error text
);


--
-- Name: subleases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.subleases (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    master_lease_id uuid NOT NULL,
