    CONSTRAINT surveys_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'sent'::text, 'closed'::text])))
);


--
-- Name: suspended_utility_charges; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.suspended_utility_charges (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    meter_id uuid NOT NULL,
    unit_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    billing_cycle_month date NOT NULL,
    utility_type text NOT NULL,
    usage_amount numeric(14,4),
    allocation_method text,
    allocation_basis numeric(14,4),
    rate_per_unit numeric(12,6),
    base_fee_share numeric(12,2) DEFAULT 0 NOT NULL,
    charge_amount numeric(12,2) NOT NULL,
    tax_rate_pct numeric(6,3),
    tax_amount numeric(12,2),
    sewer_rate_per_unit numeric(12,6),
    reading_start numeric(14,4),
    reading_end numeric(14,4),
    reading_start_date date,
    reading_end_date date,
    notes text,
    released_at timestamp with time zone,
    released_bill_id uuid,
    cancelled_at timestamp with time zone,
    cancelled_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT suspended_utility_charges_amount_check CHECK ((charge_amount >= (0)::numeric)),
    CONSTRAINT suspended_utility_charges_outcome_check CHECK ((NOT ((released_at IS NOT NULL) AND (cancelled_at IS NOT NULL))))
);


--
-- Name: TABLE suspended_utility_charges; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.suspended_utility_charges IS 'S629: a utility share for a unit whose resident has been invited but has not signed yet. Held (never invoiced, no due date, no late fee) so the RUBS split is correct for everyone from the first cycle, and released onto the tenant''s first invoice when their lease is signed.';


--
-- Name: system_features; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.system_features (
    key text NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    description text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by_user_id uuid
);


--
-- Name: tenant_autopay; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_autopay (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    lease_id uuid,
    enabled boolean DEFAULT true NOT NULL,
    pull_day integer,
    payment_method_id text,
    last_run_cycle date,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    consecutive_failures integer DEFAULT 0 NOT NULL,
    disarmed_at timestamp with time zone,
    disarmed_reason text,
    last_success_cycle date,
    use_credit boolean DEFAULT false NOT NULL,
    home_sale_contract_id uuid,
    CONSTRAINT tenant_autopay_one_owner CHECK (((lease_id IS NOT NULL) <> (home_sale_contract_id IS NOT NULL))),
    CONSTRAINT tenant_autopay_pull_day_check CHECK (((pull_day IS NULL) OR ((pull_day >= 1) AND (pull_day <= 28))))
);


--
-- Name: TABLE tenant_autopay; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tenant_autopay IS 'S607: tenant-scheduled rent autopay. The pull day is the TENANT''S choice and no landlord route may write to this table — a landlord able to move the date could manufacture late fees. Charges the full outstanding balance read live at run time; nothing is forecast.';


--
-- Name: COLUMN tenant_autopay.pull_day; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_autopay.pull_day IS 'S607: day of month (1-28) the tenant chose, or NULL for the due date. Capped at 28 because 29-31 do not exist every month and a schedule that skips February is worse than none.';


--
-- Name: COLUMN tenant_autopay.last_run_cycle; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_autopay.last_run_cycle IS 'S609: the cycle the runner last ATTEMPTED (success or failure). The idempotency guard — one attempt per lease per cycle, so a restarted job or a second server cannot double-charge a tenant.';


--
-- Name: COLUMN tenant_autopay.consecutive_failures; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_autopay.consecutive_failures IS 'S609: failed pulls in a row. Reset to 0 by any success. At 2 the arrangement disarms itself — a closed account would otherwise cost the tenant a bank fee every month forever.';


--
-- Name: COLUMN tenant_autopay.disarmed_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_autopay.disarmed_reason IS 'S609: why autopay stopped, in the tenant''s words on their screen. Set only when the system disarmed it; a tenant switching it off themselves just sets enabled=FALSE.';


--
-- Name: COLUMN tenant_autopay.use_credit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_autopay.use_credit IS 'S655 (Nic): "use my account credit first". Off by default: autopay charges the whole bill and the credit waits for the tenant. Tenant-only, like the rest of this table.';


--
-- Name: COLUMN tenant_autopay.home_sale_contract_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_autopay.home_sale_contract_id IS 'The installment (home/trailer) sale this enrollment pays. Exactly one of
   lease_id / home_sale_contract_id is set: enrolling rent never enrolls the
   trailer payment, and the other way round (Nic, 10/25).';


--
-- Name: tenant_complaints; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_complaints (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    lease_id uuid,
    unit_id uuid,
    property_id uuid,
    landlord_id uuid NOT NULL,
    category text NOT NULL,
    about_unit_id uuid,
    about_text text,
    body text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    source text DEFAULT 'agent_chat'::text NOT NULL,
    conversation_id text,
    resolved_at timestamp with time zone,
    resolution_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tenant_complaints_category_check CHECK ((category = ANY (ARRAY['noise'::text, 'neighbor'::text, 'parking'::text, 'pets'::text, 'smell'::text, 'trash'::text, 'property_condition'::text, 'harassment'::text, 'safety'::text, 'other'::text]))),
    CONSTRAINT tenant_complaints_source_check CHECK ((source = ANY (ARRAY['agent_chat'::text, 'portal'::text, 'staff'::text]))),
    CONSTRAINT tenant_complaints_status_check CHECK ((status = ANY (ARRAY['open'::text, 'reviewed'::text, 'resolved'::text, 'dismissed'::text])))
);


--
-- Name: tenant_credits; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_credits (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    landlord_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    lease_id uuid,
    amount_original numeric(12,2) NOT NULL,
    amount_remaining numeric(12,2) NOT NULL,
    category text DEFAULT 'other'::text NOT NULL,
    reason text,
    status text DEFAULT 'active'::text NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    voided_at timestamp with time zone,
    undone_at timestamp with time zone,
    undone_by uuid,
    issued_by_landlord boolean DEFAULT false NOT NULL,
    CONSTRAINT tenant_credits_amount_original_check CHECK ((amount_original > (0)::numeric)),
    CONSTRAINT tenant_credits_amount_remaining_check CHECK ((amount_remaining >= (0)::numeric)),
    CONSTRAINT tenant_credits_category_check CHECK ((category = ANY (ARRAY['screening_cap'::text, 'late_fee_refund'::text, 'overcharge'::text, 'goodwill'::text, 'deposit_interest'::text, 'other'::text]))),
    CONSTRAINT tenant_credits_status_check CHECK ((status = ANY (ARRAY['active'::text, 'void'::text])))
);


--
-- Name: COLUMN tenant_credits.undone_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_credits.undone_at IS '10/18 (Nic): when this credit was taken back whole (what it had paid went back to owed). NULL on a plain void.';


--
-- Name: COLUMN tenant_credits.undone_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_credits.undone_by IS '10/18 (Nic): who took the credit back.';


--
-- Name: COLUMN tenant_credits.issued_by_landlord; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_credits.issued_by_landlord IS '10/18 (Nic): true only for a credit a landlord typed in the Issue credit box — the only kind he can undo. Credits GAM writes itself (a late fee cancelled or refunded, money paid ahead given back at lease end, deposit interest) are false. Not backfilled: credits from before the Undo existed read false.';


--
-- Name: tenant_declared_deposits; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_declared_deposits (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    lease_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    amount numeric(12,2) NOT NULL,
    declared_date date NOT NULL,
    method text NOT NULL,
    reference text,
    status text DEFAULT 'pending'::text NOT NULL,
    bank_transaction_id uuid,
    confirmed_at timestamp with time zone,
    resolution_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    recorded_remittance_id uuid,
    receipt_photo_url text,
    receipt_photo_name text,
    receipt_photo_mime text,
    receipt_photo_size integer,
    receipt_photo_uploaded_at timestamp with time zone,
    bank_posted_date date,
    false_date_flagged_at timestamp with time zone,
    declared_hour smallint,
    declared_after_hours boolean DEFAULT false NOT NULL,
    CONSTRAINT tenant_declared_deposits_amount_positive CHECK ((amount > (0)::numeric)),
    CONSTRAINT tenant_declared_deposits_confirmed_has_txn CHECK (((status <> 'confirmed'::text) OR (bank_transaction_id IS NOT NULL))),
    CONSTRAINT tenant_declared_deposits_flag_has_bank_date CHECK (((false_date_flagged_at IS NULL) OR ((bank_posted_date IS NOT NULL) AND (bank_posted_date > declared_date)))),
    CONSTRAINT tenant_declared_deposits_hour_or_after_hours CHECK ((NOT (declared_after_hours AND (declared_hour IS NOT NULL)))),
    CONSTRAINT tenant_declared_deposits_hour_range CHECK (((declared_hour IS NULL) OR ((declared_hour >= 8) AND (declared_hour <= 18)))),
    CONSTRAINT tenant_declared_deposits_method_check CHECK ((method = ANY (ARRAY['cash'::text, 'check'::text, 'money_order'::text]))),
    CONSTRAINT tenant_declared_deposits_recorded_has_receipt CHECK (((status = 'recorded'::text) = (recorded_remittance_id IS NOT NULL))),
    CONSTRAINT tenant_declared_deposits_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'confirmed'::text, 'unconfirmed'::text, 'withdrawn'::text, 'recorded'::text])))
);


--
-- Name: TABLE tenant_declared_deposits; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tenant_declared_deposits IS 'S624: a tenant''s claim that they deposited rent at the bank. Changes nothing until a bank transaction confirms it — see the migration header for why that is the anti-fraud design.';


--
-- Name: COLUMN tenant_declared_deposits.recorded_remittance_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_declared_deposits.recorded_remittance_id IS 'S655 (decisions #11): status recorded — the landlord''s own receipt (cash, check or money order, dated on or after the reported day, for at least the reported amount) that covered this report. One receipt covers one report.';


--
-- Name: COLUMN tenant_declared_deposits.receipt_photo_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_declared_deposits.receipt_photo_url IS '10/5 (Nic): the tenant''s photo of the bank''s deposit receipt (authed route /api/declared-deposits/receipt-photos/<file>, per-row authorization: the tenant who reported it, or that landlord''s own people at a property they work at).';


--
-- Name: COLUMN tenant_declared_deposits.bank_posted_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_declared_deposits.bank_posted_date IS '10/5 (Nic): the day the bank posted the deposit that confirmed this report. The reported date counts only when this is that day or the next business day after it.';


--
-- Name: COLUMN tenant_declared_deposits.false_date_flagged_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_declared_deposits.false_date_flagged_at IS '10/5 (Nic): the bank posted this deposit later than the next business day after the reported date, so the reported date was false: the bank''s date decided the late fees, and this report counts as a strike toward the report button''s trust.';


--
-- Name: COLUMN tenant_declared_deposits.declared_hour; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_declared_deposits.declared_hour IS '10/6 (Nic): about what time the tenant says they were at the bank — the hour they picked, 8 (8 AM) through 18 (6 PM). NULL: after hours / ATM (declared_after_hours), or a report made before the time was asked.';


--
-- Name: COLUMN tenant_declared_deposits.declared_after_hours; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_declared_deposits.declared_after_hours IS '10/6 (Nic): the tenant says they deposited after banking hours or at an ATM.';


--
-- Name: tenant_identifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_identifications (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id uuid NOT NULL,
    id_type text NOT NULL,
    id_number text NOT NULL,
    issuing_state text,
    issuing_country text DEFAULT 'US'::text NOT NULL,
    expiry_date date,
    document_url text,
    is_primary boolean DEFAULT false NOT NULL,
    verified_at timestamp with time zone,
    verified_by uuid,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tenant_identifications_id_type_check CHECK ((id_type = ANY (ARRAY['drivers_license'::text, 'state_id'::text, 'passport'::text, 'military_id'::text, 'tribal_id'::text, 'permanent_resident_card'::text, 'other'::text])))
);


--
-- Name: tenant_income_documents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_income_documents (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id uuid NOT NULL,
    url text NOT NULL,
    filename text NOT NULL,
    uploaded_at timestamp with time zone DEFAULT now() NOT NULL,
    removed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE tenant_income_documents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tenant_income_documents IS 'Proof of income a resident attached in the tenant portal (10/26, Nic). Not a gate on anything; soft-deleted, never erased.';


--
-- Name: tenant_left_owing; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_left_owing (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    landlord_id uuid NOT NULL,
    property_id uuid,
    user_id uuid,
    email text,
    who text,
    amount numeric(12,2) NOT NULL,
    source_kind text NOT NULL,
    source_key text NOT NULL,
    left_on date,
    settled_at timestamp with time zone,
    settled_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    phone text,
    CONSTRAINT tenant_left_owing_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT tenant_left_owing_source_kind_check CHECK ((source_kind = ANY (ARRAY['lease'::text, 'stay'::text, 'import'::text])))
);


--
-- Name: TABLE tenant_left_owing; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tenant_left_owing IS 'A debt somebody walked away from, kept so a DIFFERENT landlord can be told it exists without being told what it is (10/20-21, Nic). Matched to an applicant only through a verified GAM account — never a name.';


--
-- Name: COLUMN tenant_left_owing.phone; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_left_owing.phone IS 'The phone on the invoice this debt came from — one of the two contact points a person is recognised by (services/nameMatch).';


--
-- Name: tenant_left_owing_match_reviews; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_left_owing_match_reviews (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    owing_id uuid NOT NULL,
    user_id uuid,
    person_name text,
    person_email text,
    person_phone text,
    person_key text NOT NULL,
    matched_on text NOT NULL,
    name_agreement text NOT NULL,
    why text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    decided_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT left_owing_review_decided_shape CHECK (((status = 'open'::text) = (decided_at IS NULL))),
    CONSTRAINT tenant_left_owing_match_reviews_matched_on_check CHECK ((matched_on = ANY (ARRAY['email'::text, 'phone'::text, 'account'::text]))),
    CONSTRAINT tenant_left_owing_match_reviews_name_agreement_check CHECK ((name_agreement = ANY (ARRAY['same'::text, 'unsure'::text, 'different'::text]))),
    CONSTRAINT tenant_left_owing_match_reviews_status_check CHECK ((status = ANY (ARRAY['open'::text, 'same_person'::text, 'not_the_same_person'::text])))
);


--
-- Name: TABLE tenant_left_owing_match_reviews; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tenant_left_owing_match_reviews IS '10/22 (Nic): "when there is a not sure call, we can leave it to the admin to do some research on". A contact point agreed but the name only half did; nobody is flagged until a person at GAM decides.';


--
-- Name: tenant_left_owing_reveals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_left_owing_reveals (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    owing_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    user_id uuid NOT NULL,
    door text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tenant_left_owing_reveals_door_check CHECK ((door = ANY (ARRAY['where_and_when'::text, 'the_total'::text])))
);


--
-- Name: TABLE tenant_left_owing_reveals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tenant_left_owing_reveals IS 'Who opened which door on somebody else''s debt, and when. The second door means that landlord has assumed the debt (10/21, Nic) — never to be remembered differently by the two parties later.';


--
-- Name: tenant_notifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_notifications (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id uuid NOT NULL,
    type text NOT NULL,
    title text NOT NULL,
    body text,
    data jsonb,
    read boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: tenant_one_off_charges; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_one_off_charges (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    landlord_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    lease_id uuid,
    unit_id uuid NOT NULL,
    charge_type text NOT NULL,
    amount numeric(10,2) NOT NULL,
    reason text NOT NULL,
    incident_date date NOT NULL,
    internal_note text,
    bill_on_or_after date DEFAULT CURRENT_DATE NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    payment_id uuid,
    billed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    cancel_reason text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tenant_one_off_charges_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT tenant_one_off_charges_charge_type_check CHECK ((charge_type = ANY (ARRAY['violation'::text, 'damage'::text, 'replacement'::text, 'service'::text, 'other'::text]))),
    CONSTRAINT tenant_one_off_charges_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'billed'::text, 'cancelled'::text]))),
    CONSTRAINT tooc_billed_has_payment CHECK (((status = 'billed'::text) = (payment_id IS NOT NULL))),
    CONSTRAINT tooc_cancelled_has_reason CHECK (((status <> 'cancelled'::text) OR (cancelled_at IS NOT NULL)))
);


--
-- Name: TABLE tenant_one_off_charges; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tenant_one_off_charges IS 'S616: a charge that happened rather than a term that was agreed — a parking violation, damage, a replacement key. Rides the tenant''s next invoice as an ordinary fee row. Kept OUT of lease_fees on purpose: lease_fees is what the signed lease says, and the lease is the only thing that holds up in court.';


--
-- Name: tenant_questionnaires; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_questionnaires (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id uuid NOT NULL,
    trigger_type text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    answers jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    answered_at timestamp with time zone,
    CONSTRAINT tenant_questionnaires_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'answered'::text, 'dismissed'::text]))),
    CONSTRAINT tenant_questionnaires_trigger_type_check CHECK ((trigger_type = ANY (ARRAY['ssi_ssdi_signal'::text, 'late_fee_fixed_income'::text])))
);


--
-- Name: tenant_remittances; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_remittances (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id uuid NOT NULL,
    lease_id uuid,
    landlord_id uuid NOT NULL,
    amount numeric(12,2) NOT NULL,
    applied_amount numeric(12,2) NOT NULL,
    unapplied_amount numeric(12,2) DEFAULT 0 NOT NULL,
    status text DEFAULT 'processing'::text NOT NULL,
    payment_method text,
    stripe_payment_intent_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    settled_at timestamp with time zone,
    gross_amount numeric(12,2),
    processing_fee_amount numeric(12,2) DEFAULT 0 NOT NULL,
    reference text,
    notes text,
    received_by uuid,
    deposit_photo_url text,
    deposit_photo_name text,
    deposit_photo_mime text,
    deposit_photo_size integer,
    deposit_photo_uploaded_by uuid,
    deposit_photo_uploaded_at timestamp with time zone,
    undone_at timestamp with time zone,
    undone_by uuid,
    received_ip inet,
    received_device text,
    CONSTRAINT tenant_remittances_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT tenant_remittances_applied_amount_check CHECK ((applied_amount >= (0)::numeric)),
    CONSTRAINT tenant_remittances_deposit_photo_bank_deposit_only CHECK (((deposit_photo_url IS NULL) OR (payment_method = 'bank_deposit'::text))),
    CONSTRAINT tenant_remittances_payment_method_check CHECK ((payment_method = ANY (ARRAY['ach'::text, 'card'::text, 'cash'::text, 'check'::text, 'money_order'::text, 'bank_deposit'::text]))),
    CONSTRAINT tenant_remittances_status_check CHECK ((status = ANY (ARRAY['processing'::text, 'settled'::text, 'failed'::text]))),
    CONSTRAINT tenant_remittances_unapplied_amount_check CHECK ((unapplied_amount >= (0)::numeric))
);


--
-- Name: COLUMN tenant_remittances.gross_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_remittances.gross_amount IS 'S616: what Stripe actually charged the tenant — the obligation plus any processing fee they bear. NULL on rows written before S616, which is why it is nullable: a backfilled guess would be indistinguishable from a real figure, and the point of this column is being able to tie out.';


--
-- Name: COLUMN tenant_remittances.processing_fee_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_remittances.processing_fee_amount IS 'S616: the processing fee the TENANT bore on top, which is zero when the property routes the fee to the landlord. gross_amount − this = the obligation collected.';


--
-- Name: COLUMN tenant_remittances.reference; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_remittances.reference IS 'S652: the check or money-order number, as handed over.';


--
-- Name: COLUMN tenant_remittances.received_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_remittances.received_by IS 'S652: who at the office posted this manual receipt.';


--
-- Name: COLUMN tenant_remittances.deposit_photo_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_remittances.deposit_photo_url IS '10/5 (Nic): the photo of the bank''s deposit receipt for a recorded bank deposit (authed route /api/payments/deposit-photos/<file>, per-row authorization). Never shown to the tenant.';


--
-- Name: COLUMN tenant_remittances.undone_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_remittances.undone_at IS '10/12 (Nic, ledger P1): when a settled receipt was taken back off the bills it paid (bank-deposit Undo match). NULL: never undone.';


--
-- Name: COLUMN tenant_remittances.undone_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_remittances.undone_by IS '10/12 (Nic, ledger P1): who pressed Undo match (NULL when undone by the system or before 10/12 with no record).';


--
-- Name: COLUMN tenant_remittances.received_ip; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_remittances.received_ip IS '10/15 (Nic): the address a hand-recorded payment was entered from; NULL when GAM wrote the receipt itself.';


--
-- Name: COLUMN tenant_remittances.received_device; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_remittances.received_device IS '10/15 (Nic): the browser that entered a hand-recorded payment (user agent, 300 chars).';


--
-- Name: tenant_roster_drafts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_roster_drafts (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    landlord_id uuid NOT NULL,
    property_id uuid,
    unit_id uuid,
    household_order integer DEFAULT 0 NOT NULL,
    first_name text NOT NULL,
    last_name text NOT NULL,
    email text NOT NULL,
    phone text,
    rent_due_day integer,
    existing_resident boolean DEFAULT true NOT NULL,
    package_template_ids uuid[],
    home_sale boolean DEFAULT false NOT NULL,
    opening_balance numeric(12,2),
    file_values jsonb DEFAULT '{}'::jsonb NOT NULL,
    source_platform text,
    import_attempt_id uuid,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    confirmed_at timestamp with time zone,
    confirmed_by uuid,
    intent_id uuid,
    discarded_at timestamp with time zone,
    discarded_by uuid,
    opening_balance_posted_at timestamp with time zone,
    opening_balance_invoice_id uuid,
    CONSTRAINT tenant_roster_drafts_opening_balance_positive CHECK (((opening_balance IS NULL) OR (opening_balance > (0)::numeric))),
    CONSTRAINT tenant_roster_drafts_rent_due_day_range CHECK (((rent_due_day IS NULL) OR ((rent_due_day >= 1) AND (rent_due_day <= 28))))
);


--
-- Name: TABLE tenant_roster_drafts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tenant_roster_drafts IS 'S655: people from a tenant CSV waiting for the landlord to review and confirm. No account, intent or lease exists for a live row.';


--
-- Name: COLUMN tenant_roster_drafts.unit_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_roster_drafts.unit_id IS 'NULL = not placed yet. Confirming refuses while any live row of the property is unplaced.';


--
-- Name: COLUMN tenant_roster_drafts.opening_balance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_roster_drafts.opening_balance IS 'Old-system balance owed. Posts once, as a carried-balance charge on the household''s lease when it issues. The household''s first person carries it.';


--
-- Name: COLUMN tenant_roster_drafts.file_values; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_roster_drafts.file_values IS 'What the old system''s file said (rent, dates, deposit, late fee, raw names). Reference only; the lease drafts from the landlord''s setup.';


--
-- Name: COLUMN tenant_roster_drafts.opening_balance_posted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_roster_drafts.opening_balance_posted_at IS 'When the household''s old balance posted. Set on every row of the household; once set, no later lease posts it again.';


--
-- Name: tenant_walkthrough_media; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_walkthrough_media (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    unit_id uuid,
    uploaded_by_user_id uuid NOT NULL,
    media_type text NOT NULL,
    file_url text NOT NULL,
    caption text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    captured_live boolean DEFAULT true NOT NULL,
    CONSTRAINT tenant_walkthrough_media_media_type_check CHECK ((media_type = ANY (ARRAY['photo'::text, 'video'::text])))
);


--
-- Name: tenants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenants (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id uuid NOT NULL,
    stripe_customer_id text,
    ach_verified boolean DEFAULT false,
    bank_last4 text,
    bank_routing_last4 text,
    ssi_ssdi boolean DEFAULT false,
    income_arrival_day integer,
    on_time_pay_enrolled boolean DEFAULT false,
    float_fee_active boolean DEFAULT false,
    credit_reporting_enrolled boolean DEFAULT false,
    flex_deposit_enrolled boolean DEFAULT false,
    late_payment_count integer DEFAULT 0,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    theme_accent text,
    font_style text,
    bio text,
    avatar_url text,
    platform_status text DEFAULT 'active'::text NOT NULL,
    onboarding_source text DEFAULT 'applied'::text NOT NULL,
    date_of_birth date,
    mailing_address text,
    background_check_id uuid,
    background_check_status text DEFAULT 'not_started'::text NOT NULL,
    otp_disqualified_until timestamp with time zone,
    otp_disqualified_reason text,
    flexpay_enrolled boolean DEFAULT false NOT NULL,
    flexpay_pull_day integer,
    flexpay_monthly_fee numeric(5,2),
    flexpay_enrolled_at timestamp with time zone,
    flexpay_disqualified_until timestamp with time zone,
    flexpay_disqualified_reason text,
    flex_deposit_disqualified_until timestamp with time zone,
    flex_deposit_disqualified_reason text,
    flexpay_prequal jsonb,
    flexpay_clean_streak integer DEFAULT 0 NOT NULL,
    flexpay_returner_cleared boolean DEFAULT false NOT NULL,
    flexpay_permanently_banned boolean DEFAULT false NOT NULL,
    bank_verify_nudge_at timestamp with time zone,
    bank_verify_nudge_count integer DEFAULT 0 NOT NULL,
    bank_pending_since timestamp with time zone,
    ach_suspended_at timestamp with time zone,
    fixed_income_self_reported boolean,
    fixed_income_asked_at timestamp with time zone,
    fixed_income_answered_at timestamp with time zone,
    prefers_paper_bill boolean,
    paper_bill_asked_at timestamp with time zone,
    CONSTRAINT tenants_background_check_status_check CHECK ((background_check_status = ANY (ARRAY['not_started'::text, 'submitted'::text, 'approved'::text, 'denied'::text, 'cancelled'::text, 'expired'::text, 'waived'::text]))),
    CONSTRAINT tenants_flexpay_pull_day_check CHECK (((flexpay_pull_day IS NULL) OR ((flexpay_pull_day >= 1) AND (flexpay_pull_day <= 28)))),
    CONSTRAINT tenants_income_arrival_day_check CHECK (((income_arrival_day >= 1) AND (income_arrival_day <= 28))),
    CONSTRAINT tenants_onboarding_source_check CHECK ((onboarding_source = ANY (ARRAY['applied'::text, 'onboarded'::text]))),
    CONSTRAINT tenants_platform_status_check CHECK ((platform_status = ANY (ARRAY['active'::text, 'suspended'::text, 'blocked'::text])))
);


--
-- Name: COLUMN tenants.flexpay_clean_streak; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenants.flexpay_clean_streak IS 'S578: consecutive on-time first-attempt (zero-retry) FlexPay pulls in the current tenancy. Reset to 0 on enroll, on any retry, and on default. At FLEXPAY_REHAB_CLEAN_PULLS (12) a returner''s mark clears.';


--
-- Name: COLUMN tenants.flexpay_returner_cleared; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenants.flexpay_returner_cleared IS 'S578: TRUE once a returner has completed 12 clean pulls and shed the queue demotion (treated as a first-timer again for future re-entry).';


--
-- Name: COLUMN tenants.flexpay_permanently_banned; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenants.flexpay_permanently_banned IS 'S578: TRUE after the 2nd lifetime FlexPay default. Terminal — blocks all future enrollment.';


--
-- Name: COLUMN tenants.bank_verify_nudge_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenants.bank_verify_nudge_count IS 'S641: reminders sent for the CURRENT unfinished bank setup. Reset when a new setup starts or the bank verifies.';


--
-- Name: COLUMN tenants.bank_pending_since; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenants.bank_pending_since IS 'S655: a bank is waiting on microdeposit verification. The verified bank(s) already on file stay usable meanwhile.';


--
-- Name: COLUMN tenants.ach_suspended_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenants.ach_suspended_at IS 'S655: NACHA zero-tolerance block, written by handle-return. Split out of ach_verified, which now only means "has a verified bank". chargeLeaseBalance refuses ACH while set.';


--
-- Name: COLUMN tenants.fixed_income_self_reported; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenants.fixed_income_self_reported IS 'What the resident said in the "Are you on fixed income?" banner. NULL = never answered. SELF-REPORTED ONLY — tenants.ssi_ssdi is the verified flag that gates FlexPay, and a tap here must never set it.';


--
-- Name: COLUMN tenants.fixed_income_asked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenants.fixed_income_asked_at IS 'When the banner was last shown, so it is asked once and not every login.';


--
-- Name: COLUMN tenants.fixed_income_answered_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenants.fixed_income_answered_at IS 'When they answered either way. With a NULL answer and a non-NULL asked_at, they dismissed it.';


--
-- Name: COLUMN tenants.prefers_paper_bill; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenants.prefers_paper_bill IS 'Resident wants their bill on paper, hand delivered (10/26, Nic). NULL = never asked, which is NOT the same as no. Read by the bill-generation print queue (PAPER_BILLS_SPEC.md); never gates anything.';


--
-- Name: COLUMN tenants.paper_bill_asked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenants.paper_bill_asked_at IS 'When the preference was last asked, so onboarding can tell "no" from "not asked yet".';


--
-- Name: unit_applications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.unit_applications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    unit_id uuid,
    landlord_id uuid,
    first_name text NOT NULL,
    last_name text NOT NULL,
    email text NOT NULL,
    phone text,
    move_in_date date,
    monthly_income numeric(10,2),
    occupants integer DEFAULT 1,
    has_pets boolean DEFAULT false,
    pet_description text,
    message text,
    status text DEFAULT 'pending'::text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    applicant_user_id uuid,
    property_id uuid,
    background_check_id uuid,
    desired_term_months integer,
    CONSTRAINT unit_applications_term_sane CHECK (((desired_term_months IS NULL) OR ((desired_term_months > 0) AND (desired_term_months <= 120))))
);


--
-- Name: unit_booking_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.unit_booking_events (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    booking_id uuid,
    unit_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    event_type text NOT NULL,
    summary text NOT NULL,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    actor_user_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT unit_booking_events_type_check CHECK ((event_type = ANY (ARRAY['created'::text, 'moved'::text, 'dates_changed'::text, 'status_changed'::text, 'cancelled'::text, 'money_settled'::text])))
);


--
-- Name: unit_booking_waitlists; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.unit_booking_waitlists (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    unit_id uuid,
    property_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    guest_name text NOT NULL,
    guest_email text NOT NULL,
    guest_phone text,
    check_in date NOT NULL,
    check_out date NOT NULL,
    status text DEFAULT 'waiting'::text NOT NULL,
    claim_token text,
    notified_at timestamp with time zone,
    claim_expires_at timestamp with time zone,
    claimed_booking_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT unit_booking_waitlists_dates_check CHECK ((check_out > check_in)),
    CONSTRAINT unit_booking_waitlists_status_check CHECK ((status = ANY (ARRAY['waiting'::text, 'notified'::text, 'claimed'::text, 'expired'::text, 'cancelled'::text])))
);


--
-- Name: unit_bookings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.unit_bookings (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    unit_id uuid NOT NULL,
    tenant_id uuid,
    guest_name text,
    guest_email text,
    guest_phone text,
    check_in date NOT NULL,
    check_out date NOT NULL,
    nights integer,
    total_amount numeric(10,2),
    status text DEFAULT 'confirmed'::text NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    landlord_id uuid NOT NULL,
    lease_type text NOT NULL,
    nightly_rate numeric(10,2),
    weekly_rate numeric(10,2),
    platform_fee numeric(10,2) DEFAULT 0 NOT NULL,
    source text DEFAULT 'direct'::text NOT NULL,
    acknowledgment_signed_at timestamp with time zone,
    deposit_amount numeric(10,2),
    deposit_paid_at timestamp with time zone,
    stripe_checkout_session_id text,
    hold_expires_at timestamp with time zone,
    required_site_layout text DEFAULT 'none'::text NOT NULL,
    required_amp_service text DEFAULT 'none'::text NOT NULL,
    site_reveal_sent_at timestamp with time zone,
    locked_to_unit boolean DEFAULT false NOT NULL,
    stripe_payment_intent_id text,
    balance_pay_link_id uuid,
    balance_billed_at timestamp with time zone,
    balance_paid_at timestamp with time zone,
    pos_transaction_id uuid,
    displaced_at timestamp with time zone,
    displaced_reason text,
    displaced_from_unit uuid,
    cancelled_at timestamp with time zone,
    avoided_unit_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    booked_check_out date,
    stay_terms text,
    screening_required boolean DEFAULT false NOT NULL,
    returning_guest_at timestamp with time zone,
    returning_guest_by uuid,
    stay_tax_rate numeric(7,4),
    deposit_link_sent_at timestamp with time zone,
    deposit_link_sent_by uuid,
    deposit_pay_link_id uuid,
    confirmation_sent_at timestamp with time zone,
    confirmation_sent_by uuid,
    migrated_at timestamp with time zone,
    migrated_by uuid,
    migrated_door text,
    migration_key text,
    told_outside_gam boolean DEFAULT false NOT NULL,
    lock_reason text,
    deposit_off_platform_method text,
    deposit_off_platform_ref text,
    import_extra_data jsonb,
    folded_into_person_merge_id uuid,
    rig_length_ft integer,
    CONSTRAINT unit_bookings_deposit_off_platform_method_check CHECK (((deposit_off_platform_method IS NULL) OR (deposit_off_platform_method = ANY (ARRAY['cash'::text, 'check'::text, 'money_order'::text, 'bank_deposit'::text, 'other'::text])))),
    CONSTRAINT unit_bookings_lease_type_check CHECK ((lease_type = ANY (ARRAY['nightly'::text, 'weekly'::text, 'month_to_month'::text, 'long_term'::text, 'lease_hold'::text]))),
    CONSTRAINT unit_bookings_lock_reason_check CHECK (((lock_reason IS NULL) OR (lock_reason = ANY (ARRAY['promised_before_gam'::text, 'promised_at_the_counter'::text, 'moved_off_promised_site'::text])))),
    CONSTRAINT unit_bookings_migrated_door_check CHECK (((migrated_door IS NULL) OR (migrated_door = ANY (ARRAY['file'::text, 'hand'::text])))),
    CONSTRAINT unit_bookings_migration_shape CHECK (((migrated_at IS NULL) = (migrated_door IS NULL))),
    CONSTRAINT unit_bookings_required_amp_service_check CHECK ((required_amp_service = ANY (ARRAY['none'::text, '30'::text, '50'::text, 'both'::text]))),
    CONSTRAINT unit_bookings_required_site_layout_check CHECK ((required_site_layout = ANY (ARRAY['none'::text, 'back_in'::text, 'pull_through'::text]))),
    CONSTRAINT unit_bookings_rig_length_sane CHECK (((rig_length_ft IS NULL) OR ((rig_length_ft > 0) AND (rig_length_ft <= 120)))),
    CONSTRAINT unit_bookings_status_check CHECK ((status = ANY (ARRAY['tentative'::text, 'confirmed'::text, 'checked_in'::text, 'checked_out'::text, 'cancelled'::text, 'no_show'::text]))),
    CONSTRAINT unit_bookings_stay_terms_check CHECK (((stay_terms IS NULL) OR (stay_terms = ANY (ARRAY['lease'::text, 'stay'::text]))))
);


--
-- Name: COLUMN unit_bookings.acknowledgment_signed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.acknowledgment_signed_at IS 'Stamped via PATCH /units/:id/bookings/:bookingId/acknowledge once landlord/staff confirms guest signed the property rules. NULL while pending.';


--
-- Name: COLUMN unit_bookings.pos_transaction_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.pos_transaction_id IS 'S651: the register sale this stay was rung up on, when it came from the counter. NULL for every other source (storefront, reservation form, waitlist).';


--
-- Name: COLUMN unit_bookings.displaced_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.displaced_at IS 'S652: when an unpaid hold yielded its site to a paid booking. Set on both outcomes — moved elsewhere, or left with no site at all.';


--
-- Name: COLUMN unit_bookings.cancelled_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.cancelled_at IS 'S652: when the cancellation happened. Nights are exempt from the platform fee only when this is strictly before check_in — a stay cancelled on or after arrival was a stay.';


--
-- Name: COLUMN unit_bookings.avoided_unit_ids; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.avoided_unit_ids IS 'S653: sites this guest asked not to be put on. Every placement path skips them.';


--
-- Name: COLUMN unit_bookings.booked_check_out; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.booked_check_out IS '10/3 (decisions #33): the check-out the stay was sold for. Set on create and on every deliberate date change; an early check-out moves check_out only. Price, tax, deposit and revenue split read the later of this and check_out (empty = check_out): services/registerStay soldCheckOutSql.';


--
-- Name: COLUMN unit_bookings.returning_guest_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.returning_guest_at IS '10/6 (Nic): when the landlord attested the guest has stayed at this property before. A 22+ night stay carrying it needs no background check; it counts against the property''s rolling-year returning-resident allowance (one count per person per year).';


--
-- Name: COLUMN unit_bookings.returning_guest_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.returning_guest_by IS '10/6 (Nic): who attested the guest is returning (an owner or a staff member allowed to skip the background check).';


--
-- Name: COLUMN unit_bookings.stay_tax_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.stay_tax_rate IS '10/17 (Nic, "never reprice history"): the lodging tax rate (a fraction) in force when this stay was priced, stamped by trg_unit_bookings_stamp_stay_tax. Every payment toward the stay records its share of THIS rate, so a later change never re-rates a stay already sold. NULL on stays priced before 10/17 — they read the property''s rate, as they did before.';


--
-- Name: COLUMN unit_bookings.deposit_link_sent_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.deposit_link_sent_at IS '10/18 (Nic): when this reservation''s deposit link was last emailed to the guest — by the reservation form, or by the schedule''s Ask for the deposit button. Paces a second press (nothing is emailed again within the hour) and tells the schedule the guest has been asked. NULL = never asked.';


--
-- Name: COLUMN unit_bookings.deposit_link_sent_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.deposit_link_sent_by IS '10/18 (Nic): who asked. NULL for a link GAM sent itself (the booking site).';


--
-- Name: COLUMN unit_bookings.deposit_pay_link_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.deposit_pay_link_id IS '10/18 (Nic): the pay link that was made as THIS reservation''s deposit (routes/posPayLinks createBookingDepositLink). Beside balance_pay_link_id, which is the arrival-day balance link. A reservation can also carry the link that created it, or an Add-a-month link; those ask for other money and are never handed back as the deposit.';


--
-- Name: COLUMN unit_bookings.confirmation_sent_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.confirmation_sent_at IS 'When a person chose to email this guest their reservation confirmation. NULL = never told. Never set by a job or a hook — see services/bookingConfirmation.';


--
-- Name: COLUMN unit_bookings.confirmation_sent_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.confirmation_sent_by IS 'Who pressed send on the confirmation.';


--
-- Name: COLUMN unit_bookings.migrated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.migrated_at IS 'When this reservation was brought in from the old system or a text thread. NULL = taken in GAM.';


--
-- Name: COLUMN unit_bookings.migrated_door; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.migrated_door IS 'file = the old system''s export (booked first, sites already promised); hand = typed in off a text thread afterwards.';


--
-- Name: COLUMN unit_bookings.migration_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.migration_key IS 'Identity of the row in its source, so re-importing the same file adds nobody twice. See lib/reservationImportColumns.';


--
-- Name: COLUMN unit_bookings.told_outside_gam; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.told_outside_gam IS 'The guest was already told they have this reservation, outside GAM. The confirmation endpoint will not email them again without a deliberate second ask.';


--
-- Name: COLUMN unit_bookings.lock_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.lock_reason IS 'Why this stay cannot be moved off its site. promised_before_gam = the old system gave them this space number; promised_at_the_counter = the desk did; moved_off_promised_site = a person moved them off the space they were promised, so nothing here may call this one promised.';


--
-- Name: COLUMN unit_bookings.deposit_off_platform_method; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.deposit_off_platform_method IS 'How a deposit that never came through GAM was handed over. Set = this money moved somewhere GAM was not; GAM owes the landlord nothing for it.';


--
-- Name: COLUMN unit_bookings.folded_into_person_merge_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.folded_into_person_merge_id IS '10/20 (Nic): the landlord said this reservation''s guest is somebody already in the book (person_merges). The row stays on the board exactly as booked; the matcher stops asking about it.';


--
-- Name: COLUMN unit_bookings.rig_length_ft; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_bookings.rig_length_ft IS '10/24: how long the guest''s camper is (feet), asked at the counter and on the booking site. NULL = not stated.';


--
-- Name: unit_entry_request_responses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.unit_entry_request_responses (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    request_id uuid NOT NULL,
    responder_user_id uuid NOT NULL,
    decision text NOT NULL,
    responded_at timestamp with time zone DEFAULT now() NOT NULL,
    reason text,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT unit_entry_request_responses_decision_check CHECK ((decision = ANY (ARRAY['granted'::text, 'denied'::text])))
);


--
-- Name: unit_entry_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.unit_entry_requests (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    unit_id uuid NOT NULL,
    lease_id uuid,
    tenant_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    requested_by_user_id uuid NOT NULL,
    reason text NOT NULL,
    reason_category text NOT NULL,
    notice_given_at timestamp with time zone DEFAULT now() NOT NULL,
    proposed_entry_window_start timestamp with time zone NOT NULL,
    proposed_entry_window_end timestamp with time zone NOT NULL,
    notice_window_hours integer NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    entry_actual_at timestamp with time zone,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    maintenance_request_id uuid,
    inspection_id uuid,
    CONSTRAINT unit_entry_requests_reason_category_check CHECK ((reason_category = ANY (ARRAY['maintenance'::text, 'inspection'::text, 'showing'::text, 'emergency'::text, 'other'::text]))),
    CONSTRAINT unit_entry_requests_single_anchor CHECK ((NOT ((maintenance_request_id IS NOT NULL) AND (inspection_id IS NOT NULL)))),
    CONSTRAINT unit_entry_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'granted'::text, 'denied'::text, 'completed'::text, 'breached'::text, 'cancelled'::text])))
);


--
-- Name: unit_inspection_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.unit_inspection_items (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    inspection_id uuid NOT NULL,
    area text NOT NULL,
    item_label text NOT NULL,
    condition text,
    notes text,
    estimated_repair_cost numeric(10,2),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    lease_fee_id uuid,
    CONSTRAINT unit_inspection_items_condition_check CHECK (((condition IS NULL) OR (condition = ANY (ARRAY['excellent'::text, 'good'::text, 'fair'::text, 'damaged_missing'::text, 'na'::text]))))
);


--
-- Name: unit_inspection_photos; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.unit_inspection_photos (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    inspection_id uuid NOT NULL,
    item_id uuid,
    photo_url text NOT NULL,
    caption text,
    uploaded_by uuid NOT NULL,
    uploaded_at timestamp with time zone DEFAULT now() NOT NULL,
    captured_live boolean DEFAULT false NOT NULL
);


--
-- Name: unit_inspection_signatures; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.unit_inspection_signatures (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    inspection_id uuid NOT NULL,
    signer_user_id uuid NOT NULL,
    signer_role text NOT NULL,
    signed_at timestamp with time zone DEFAULT now() NOT NULL,
    signature_evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT unit_inspection_signatures_signer_role_check CHECK ((signer_role = ANY (ARRAY['tenant'::text, 'landlord'::text, 'inspector'::text])))
);


--
-- Name: unit_inspection_videos; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.unit_inspection_videos (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    inspection_id uuid NOT NULL,
    title text,
    video_url text NOT NULL,
    thumbnail_url text,
    duration_seconds integer,
    file_size bigint,
    mime_type text,
    captured_live boolean DEFAULT false NOT NULL,
    uploaded_by uuid NOT NULL,
    uploaded_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: unit_inspections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.unit_inspections (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    unit_id uuid NOT NULL,
    lease_id uuid,
    tenant_id uuid,
    landlord_id uuid NOT NULL,
    inspection_type text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    comparison_inspection_id uuid,
    scheduled_for timestamp with time zone,
    conducted_at timestamp with time zone,
    conducted_by_user_id uuid,
    finalized_at timestamp with time zone,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    reminder_sent_at timestamp with time zone,
    guided_walkthrough_declined boolean DEFAULT false NOT NULL,
    guided_walkthrough_declined_at timestamp with time zone,
    move_in_deadline_missed_at timestamp with time zone,
    flagged_suspicious_at timestamp with time zone,
    flagged_by_user_id uuid,
    flag_reason text,
    followup_inspection_id uuid,
    report_url text,
    report_generated_at timestamp with time zone,
    CONSTRAINT unit_inspections_inspection_type_check CHECK ((inspection_type = ANY (ARRAY['move_in'::text, 'move_out'::text, 'periodic'::text, 'turnover'::text]))),
    CONSTRAINT unit_inspections_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'tenant_signed'::text, 'landlord_signed'::text, 'finalized'::text, 'disputed'::text, 'cancelled'::text])))
);


--
-- Name: unit_number_history; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.unit_number_history (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    unit_id uuid NOT NULL,
    unit_number text NOT NULL COLLATE public.unit_natural,
    building text,
    effective_from timestamp with time zone DEFAULT now() NOT NULL,
    effective_to timestamp with time zone,
    changed_by_user_id uuid,
    reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: unit_occupancy_nights; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.unit_occupancy_nights (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    landlord_id uuid NOT NULL,
    property_id uuid NOT NULL,
    unit_id uuid NOT NULL,
    booking_id uuid NOT NULL,
    night date NOT NULL,
    lease_type text NOT NULL,
    unit_type text NOT NULL,
    status_at_stamp text NOT NULL,
    stay_terms text,
    stamped_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE unit_occupancy_nights; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.unit_occupancy_nights IS '10/21 (Nic): one row per site per night, stamped the morning after and never rewritten — the nights GAM bills in arrears, so re-dating or deleting a reservation later cannot lower the count. services/occupancyNights.';


--
-- Name: COLUMN unit_occupancy_nights.lease_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_occupancy_nights.lease_type IS 'The reservation''s kind AS AT THE NIGHT. The count reads this, not the live row (editing it later must not un-count a night).';


--
-- Name: COLUMN unit_occupancy_nights.unit_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.unit_occupancy_nights.unit_type IS 'The site''s type AS AT THE NIGHT, for the same reason — only some types aggregate nights (NIGHTS_AGGREGATION_UNIT_TYPES).';


--
-- Name: unit_out_of_order; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.unit_out_of_order (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    unit_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    starts_on date DEFAULT CURRENT_DATE NOT NULL,
    ends_on date,
    reason text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    cleared_at timestamp with time zone,
    cleared_by uuid,
    CONSTRAINT unit_out_of_order_window CHECK (((ends_on IS NULL) OR (ends_on > starts_on)))
);


--
-- Name: unit_photos; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.unit_photos (
