    subtype_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: units; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.units (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    property_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    unit_number text NOT NULL COLLATE public.unit_natural,
    bedrooms integer DEFAULT 1 NOT NULL,
    bathrooms numeric(3,1) DEFAULT 1.0 NOT NULL,
    sqft integer,
    status text DEFAULT 'vacant'::text NOT NULL,
    rent_amount numeric(10,2) NOT NULL,
    security_deposit numeric(10,2) DEFAULT 0 NOT NULL,
    on_time_pay_active boolean DEFAULT false,
    payment_block boolean DEFAULT false,
    payment_block_set_at timestamp with time zone,
    payment_block_set_by uuid,
    listed_vacant boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    available_date date,
    listing_description text,
    unit_type text DEFAULT 'apartment'::text,
    scheduled_activation_at timestamp with time zone,
    scheduled_activation_by uuid,
    nightly_rate numeric(10,2),
    weekly_rate numeric(10,2),
    is_bookable boolean DEFAULT false NOT NULL,
    lease_types_allowed text[] DEFAULT '{}'::text[],
    check_in_time time without time zone,
    check_out_time time without time zone,
    amenities text[] DEFAULT ARRAY[]::text[],
    unit_description text,
    monthly_rate numeric(10,2),
    min_stay_nights integer,
    max_stay_nights integer,
    import_extra_data jsonb,
    rv_site_layout text DEFAULT 'none'::text NOT NULL,
    rv_amp_service text DEFAULT 'none'::text NOT NULL,
    status_before_block text,
    storage_size text,
    subtype_id uuid,
    dwelling_ownership text DEFAULT 'landlord'::text NOT NULL,
    occupancy_mode text DEFAULT 'whole_unit'::text NOT NULL,
    lot_rent_amount numeric(10,2) DEFAULT 0 NOT NULL,
    is_multi_level boolean DEFAULT false NOT NULL,
    is_ada_accessible boolean DEFAULT false NOT NULL,
    floor_level text,
    features jsonb DEFAULT '{}'::jsonb NOT NULL,
    living_areas integer DEFAULT 1 NOT NULL,
    retired_at timestamp with time zone,
    superseded_by_unit_id uuid,
    replaces_unit_id uuid,
    water_fixture_count integer,
    owner_household_size integer DEFAULT 1 NOT NULL,
    has_propane_tank boolean DEFAULT false NOT NULL,
    building text,
    display_label text COLLATE public.unit_natural,
    owner_occupant_name text,
    owner_occupant_phone text,
    owner_occupant_email text,
    rv_max_rig_length_ft integer,
    CONSTRAINT units_building_not_blank CHECK (((building IS NULL) OR (btrim(building) <> ''::text))),
    CONSTRAINT units_dwelling_ownership_check CHECK ((dwelling_ownership = ANY (ARRAY['landlord'::text, 'tenant'::text]))),
    CONSTRAINT units_floor_level_check CHECK (((floor_level IS NULL) OR (floor_level = ANY (ARRAY['ground_floor'::text, 'upper_floor'::text, 'basement'::text, 'multi_floor'::text])))),
    CONSTRAINT units_lot_rent_amount_check CHECK ((lot_rent_amount >= (0)::numeric)),
    CONSTRAINT units_occupancy_mode_check CHECK ((occupancy_mode = ANY (ARRAY['whole_unit'::text, 'by_room'::text]))),
    CONSTRAINT units_owner_household_size_check CHECK (((owner_household_size >= 1) AND (owner_household_size <= 30))),
    CONSTRAINT units_rv_amp_service_check CHECK ((rv_amp_service = ANY (ARRAY['none'::text, '30'::text, '50'::text, 'both'::text]))),
    CONSTRAINT units_rv_max_rig_length_sane CHECK (((rv_max_rig_length_ft IS NULL) OR ((rv_max_rig_length_ft > 0) AND (rv_max_rig_length_ft <= 120)))),
    CONSTRAINT units_rv_site_layout_check CHECK ((rv_site_layout = ANY (ARRAY['none'::text, 'back_in'::text, 'pull_through'::text]))),
    CONSTRAINT units_status_check CHECK ((status = ANY (ARRAY['vacant'::text, 'available'::text, 'active'::text, 'delinquent'::text, 'suspended'::text, 'owner_use'::text, 'utility_service'::text]))),
    CONSTRAINT units_unit_type_check CHECK ((unit_type = ANY (ARRAY['apartment'::text, 'single_family'::text, 'rv_spot'::text, 'campsite'::text, 'mobile_home'::text, 'hotel_room'::text, 'storage'::text, 'parking'::text, 'boat_slip'::text, 'land_lot'::text, 'commercial'::text])))
);


--
-- Name: COLUMN units.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.units.status IS 'S614: adds ''utility_service'' — a space this landlord bills utilities for but does not own or lease (next door, cross-property). Never rentable, never listed, never bookable; it exists to hold meter assignments and a payer.';


--
-- Name: COLUMN units.subtype_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.units.subtype_id IS 'LEGACY single subtype. Source of truth is unit_subtype_links (a unit holds many). Kept in step as the first link for readers not yet migrated.';


--
-- Name: COLUMN units.lot_rent_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.units.lot_rent_amount IS 'S568: monthly lot rent the operator pays the EXTERNAL park for this home''s lot (homes-only properties). Their net = tenant rent − lot rent.';


--
-- Name: COLUMN units.retired_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.units.retired_at IS 'S605: when this unit was retired and replaced. NULL = live. A retired unit keeps all history but can never take a new lease or booking (enforced by trigger), so it is also never billed the per-unit platform fee.';


--
-- Name: COLUMN units.superseded_by_unit_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.units.superseded_by_unit_id IS 'S605: the replacement unit that took this one''s place under a new number.';


--
-- Name: COLUMN units.replaces_unit_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.units.replaces_unit_id IS 'S605: the retired unit this one replaced. Inverse of superseded_by_unit_id.';


--
-- Name: COLUMN units.water_fixture_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.units.water_fixture_count IS 'S607: plumbing fixture count, for the fixture_count RUBS allocation basis. NULL = not recorded; such a unit contributes 0 to a fixture split and is reported as skipped.';


--
-- Name: COLUMN units.owner_household_size; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.units.owner_household_size IS 'S609: how many people live in an OWNER-OCCUPIED unit. Read only when units.status = ''owner_use'' — such a unit has no lease, so there are no lease_tenants rows to count, and a zero basis would push the owner''s own utility usage onto the paying tenants. Ignored for every other status.';


--
-- Name: COLUMN units.has_propane_tank; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.units.has_propane_tank IS 'S613: this space has a propane tank that gets filled. Drives which units the delivery form offers; propane still bills through propane_fills, not a meter.';


--
-- Name: COLUMN units.building; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.units.building IS 'S641: the building within the property. NULL for properties that have none — most parks. Part of the uniqueness key, so Apt 101 can exist in Building 1 and Building 2.';


--
-- Name: COLUMN units.display_label; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.units.display_label IS 'S652: what the park calls this space — "Lot 1", "Space 7". Printed on leases and shown to residents; NULL prints unit_number. NEVER used to decide what a space is or what may be put on it — unit_type does that.';


--
-- Name: COLUMN units.owner_occupant_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.units.owner_occupant_name IS 'S653: who lives in an owner-use space (contact only; read when status = owner_use).';


--
-- Name: COLUMN units.rv_max_rig_length_ft; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.units.rv_max_rig_length_ft IS '10/24: the longest rig (feet) this site takes. NULL = not stated, and never blocks.';


--
-- Name: user_balance_ledger; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_balance_ledger (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id uuid NOT NULL,
    type text NOT NULL,
    amount numeric(10,2) NOT NULL,
    balance_after numeric(10,2) NOT NULL,
    reference_id uuid,
    reference_type text,
    property_id uuid,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    bank_account_id uuid,
    stripe_transfer_id text,
    CONSTRAINT user_balance_ledger_type_check CHECK ((type = ANY (ARRAY['allocation_owner_share'::text, 'allocation_manager_fee'::text, 'allocation_pm_company_fee'::text, 'placement_fee'::text, 'maintenance_markup'::text, 'withdrawal_auto'::text, 'withdrawal_manual'::text, 'withdrawal_fee'::text, 'adjustment'::text])))
);


--
-- Name: COLUMN user_balance_ledger.stripe_transfer_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.user_balance_ledger.stripe_transfer_id IS 'S640: NOT unique. One platform-held passthrough transfer covers every owner-share row in the batch, so a transfer id legitimately repeats across rows.';


--
-- Name: user_bank_accounts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_bank_accounts (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id uuid NOT NULL,
    nickname text NOT NULL,
    account_holder_name text NOT NULL,
    account_type text NOT NULL,
    routing_number text NOT NULL,
    account_number_last4 text NOT NULL,
    account_number_encrypted text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    account_holder_type text DEFAULT 'individual'::text NOT NULL,
    CONSTRAINT user_bank_accounts_account_holder_type_check CHECK ((account_holder_type = ANY (ARRAY['individual'::text, 'business'::text]))),
    CONSTRAINT user_bank_accounts_account_number_last4_length_check CHECK ((length(account_number_last4) = 4)),
    CONSTRAINT user_bank_accounts_account_type_check CHECK ((account_type = ANY (ARRAY['checking'::text, 'savings'::text]))),
    CONSTRAINT user_bank_accounts_routing_number_length_check CHECK ((length(routing_number) = 9)),
    CONSTRAINT user_bank_accounts_status_check CHECK ((status = ANY (ARRAY['active'::text, 'archived'::text])))
);


--
-- Name: user_totp_recovery_codes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_totp_recovery_codes (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    user_id uuid NOT NULL,
    code_hash text NOT NULL,
    used_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: user_ui_layout; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_ui_layout (
    user_id uuid NOT NULL,
    surface text NOT NULL,
    layout jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT user_ui_layout_is_a_list CHECK ((jsonb_typeof(layout) = 'array'::text)),
    CONSTRAINT user_ui_layout_surface_known CHECK ((surface = ANY (ARRAY['landlord_nav'::text, 'landlord_dashboard'::text])))
);


--
-- Name: TABLE user_ui_layout; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.user_ui_layout IS 'One person''s arrangement of one of their own screens (10/21, Nic: the draggable nav and the dashboard widgets). Never permissions — what somebody may SEE is still decided by visibleNavItemsFor and the API.';


--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    email text NOT NULL,
    password_hash text NOT NULL,
    role text NOT NULL,
    first_name text NOT NULL,
    last_name text NOT NULL,
    phone text,
    email_verified boolean DEFAULT false,
    email_verify_token text,
    reset_token text,
    reset_token_expires timestamp with time zone,
    last_login_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    default_management_payout_bank_account_id uuid,
    stripe_connect_account_id text,
    stripe_connect_status_synced_at timestamp with time zone,
    connect_charges_enabled boolean DEFAULT false NOT NULL,
    connect_payouts_enabled boolean DEFAULT false NOT NULL,
    connect_details_submitted boolean DEFAULT false NOT NULL,
    failed_login_count integer DEFAULT 0 NOT NULL,
    locked_until timestamp with time zone,
    email_verified_at timestamp with time zone,
    totp_enabled boolean DEFAULT false NOT NULL,
    totp_secret text,
    totp_enrolled_at timestamp with time zone,
    accepted_tos_at timestamp with time zone,
    accepted_privacy_at timestamp with time zone,
    tenant_invite_token text,
    tenant_invite_expires_at timestamp with time zone,
    landlord_invite_token text,
    landlord_invite_expires_at timestamp with time zone,
    email_verify_token_expires_at timestamp with time zone,
    email_2fa_enabled boolean DEFAULT false NOT NULL,
    referral_code text,
    referred_by_user_id uuid,
    pending_email text,
    pending_email_token text,
    pending_email_expires_at timestamp with time zone,
    theme_accent text,
    font_style text,
    tenant_invite_accepted_at timestamp with time zone,
    tenant_invite_sent_at timestamp with time zone,
    sessions_valid_from timestamp with time zone,
    date_of_birth date,
    CONSTRAINT users_role_check CHECK ((role = ANY (ARRAY['admin'::text, 'super_admin'::text, 'landlord'::text, 'tenant'::text, 'bookkeeper'::text, 'property_manager'::text, 'onsite_manager'::text, 'maintenance'::text, 'business_owner'::text, 'business_staff'::text, 'fitness_user'::text, 'contact'::text, 'portfolio_manager'::text])))
);


--
-- Name: COLUMN users.accepted_tos_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.accepted_tos_at IS 'Timestamp when this user accepted the Terms of Service at registration. NULL = pre-acceptance-gate user; not yet re-prompted.';


--
-- Name: COLUMN users.accepted_privacy_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.accepted_privacy_at IS 'Timestamp when this user accepted the Privacy Policy at registration. NULL = pre-acceptance-gate user; not yet re-prompted.';


--
-- Name: COLUMN users.tenant_invite_token; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.tenant_invite_token IS 'S410/S377: separate from email_verify_token. Used by tenant invite + esign signing flows.';


--
-- Name: COLUMN users.tenant_invite_expires_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.tenant_invite_expires_at IS 'S410/S377: NULL means no expiry check (pre-S410 row); NOT NULL enforced by accept route.';


--
-- Name: COLUMN users.landlord_invite_token; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.landlord_invite_token IS 'S410/S377: separate from email_verify_token. Used by admin landlord create + re-invite.';


--
-- Name: COLUMN users.landlord_invite_expires_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.landlord_invite_expires_at IS 'S410/S377: NULL means no expiry check (pre-S410 row); NOT NULL enforced by accept route.';


--
-- Name: COLUMN users.email_verify_token_expires_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.email_verify_token_expires_at IS 'S410/S377: 7-day expiry window on the email verification link.';


--
-- Name: COLUMN users.email_2fa_enabled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.email_2fa_enabled IS 'S565: when true (and totp_enabled false), login requires a 6-digit code emailed to the user. Satisfies the mandatory-2FA requirement for admin/super_admin without an authenticator app.';


--
-- Name: COLUMN users.referral_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.referral_code IS 'Portfolio manager''s personal referral code (S567). A landlord self-registering with ?ref=<code> is auto-attributed to this rep as CLOSING manager. Generated lazily; NULL until the rep first requests their link.';


--
-- Name: COLUMN users.referred_by_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.referred_by_user_id IS 'S592: this person''s single referral upline (who brought them onto GAM). Anchored to the person so it survives 1031s / new entities. The accrual job (commissionAccrual.ts) reads the landlord ENTITY attribution first and falls back to this. Single-tier — never stacked.';


--
-- Name: COLUMN users.pending_email; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.pending_email IS 'A requested new login email, not yet in effect. Becomes users.email only when the link mailed to it is opened.';


--
-- Name: COLUMN users.theme_accent; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.theme_accent IS 'S633: portal accent colour, per ACCOUNT. Chrome belongs to the person, not to any company they own.';


--
-- Name: COLUMN users.font_style; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.font_style IS 'S633: portal font, per ACCOUNT. See users.theme_accent.';


--
-- Name: COLUMN users.tenant_invite_accepted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.tenant_invite_accepted_at IS 'S637: when a tenant invite was activated. Set = the token is spent and authorises nothing; it is kept only so a returning tenant can be told they are already set up rather than "expired".';


--
-- Name: COLUMN users.tenant_invite_sent_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.tenant_invite_sent_at IS 'S639: when a tenant invite token was first issued to this user. Survives the token being consumed or cleared, so the pending pool can tell "we have written to them" from "we never have".';


--
-- Name: COLUMN users.date_of_birth; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.date_of_birth IS '10/13 (Nic): a landlord''s own birthday, typed on Settings → Account, for the happy-birthday email (jobs/birthdayEmails.ts). Optional. Tenants'' birthdays live on tenants.date_of_birth.';


--
-- Name: utility_absorbed_charges; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.utility_absorbed_charges (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    meter_id uuid NOT NULL,
    unit_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    utility_type text NOT NULL,
    billing_cycle_month date NOT NULL,
    allocation_method text,
    allocation_basis numeric(12,4),
    charge_amount numeric(12,2) NOT NULL,
    base_fee_share numeric(12,2) DEFAULT 0 NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    reason text DEFAULT 'owner_use'::text NOT NULL,
    wash_id uuid,
    lease_id uuid,
    booking_id uuid,
    tenant_id uuid,
    departed_on date,
    tax_amount numeric(12,2) DEFAULT 0 NOT NULL,
    usage_amount numeric(14,4),
    rate_per_unit numeric(12,6),
    reading_start numeric(14,4),
    reading_end numeric(14,4),
    reading_start_date date,
    reading_end_date date,
    CONSTRAINT utility_absorbed_charges_amount_check CHECK ((charge_amount >= (0)::numeric)),
    CONSTRAINT utility_absorbed_charges_reason_check CHECK ((reason = ANY (ARRAY['owner_use'::text, 'early_departure_wash'::text, 'short_stay_in_rate'::text, 'vacant'::text]))),
    CONSTRAINT utility_absorbed_charges_tax_check CHECK ((tax_amount >= (0)::numeric)),
    CONSTRAINT utility_absorbed_charges_wash_shape CHECK (((reason = 'early_departure_wash'::text) = (wash_id IS NOT NULL)))
);


--
-- Name: TABLE utility_absorbed_charges; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.utility_absorbed_charges IS '10/20 (Nic): the one book for utility cost GAM billed to NOBODY, whatever the reason — an owner-occupied unit''s share of a RUBS pool (S609, the original purpose), a departing guest''s final stub called a wash, power inside a nightly rate, a vacant space. "If we''re keeping track of electric that''s not billed back, we need to count that there, but it doesn''t need to get attached to anything." Was utility_owner_use_absorptions, generalized rather than joined by a second table, because the first report that forgets to add the two together is the day the number stops being trustworthy. A wash row points at its departure in early_departure_washes.';


--
-- Name: COLUMN utility_absorbed_charges.reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_absorbed_charges.reason IS 'Why this cost was billed to nobody: owner_use (an owner-occupied unit''s share), early_departure_wash (they left early, kept no refund, so GAM ate the final stub), short_stay_in_rate (a nightly guest whose power is in the rate), vacant. Single source: ABSORBED_CHARGE_REASONS in services/earlyDepartureWash.ts.';


--
-- Name: COLUMN utility_absorbed_charges.wash_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_absorbed_charges.wash_id IS 'The departure this stub belonged to (early_departure_washes). Set for exactly the early_departure_wash rows, and the thing the per-departure unique index keys on — one absorbed stub per departure per meter, however many months the reads straddle.';


--
-- Name: utility_bills; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.utility_bills (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    meter_id uuid NOT NULL,
    unit_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    lease_id uuid,
    landlord_id uuid NOT NULL,
    billing_cycle_month date NOT NULL,
    usage_amount numeric(12,4),
    allocation_method text,
    allocation_basis numeric(12,4),
    rate_per_unit numeric(14,6),
    base_fee_share numeric(10,2) DEFAULT 0 NOT NULL,
    charge_amount numeric(10,2) NOT NULL,
    status text DEFAULT 'unbilled'::text NOT NULL,
    billed_at timestamp with time zone,
    paid_at timestamp with time zone,
    payment_id uuid,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tax_rate_pct numeric(6,4) DEFAULT 0 NOT NULL,
    tax_amount numeric(10,2) DEFAULT 0 NOT NULL,
    utility_type text NOT NULL,
    sewer_rate_per_unit numeric,
    reading_start numeric,
    reading_end numeric,
    reading_start_date date,
    reading_end_date date,
    service_agreement_id uuid,
    voided_at timestamp with time zone,
    void_reason text,
    CONSTRAINT utility_bills_payer_source_check CHECK (((lease_id IS NOT NULL) <> (service_agreement_id IS NOT NULL))),
    CONSTRAINT utility_bills_status_check CHECK ((status = ANY (ARRAY['unbilled'::text, 'billed'::text, 'paid'::text, 'disputed'::text, 'void'::text]))),
    CONSTRAINT utility_bills_utility_type_check CHECK ((utility_type = ANY (ARRAY['water'::text, 'gas'::text, 'electric'::text, 'sewer'::text, 'trash'::text]))),
    CONSTRAINT utility_bills_voided_is_stamped CHECK ((((voided_at IS NULL) = (void_reason IS NULL)) AND ((voided_at IS NULL) OR ((status = 'void'::text) AND (payment_id IS NULL)))))
);


--
-- Name: COLUMN utility_bills.rate_per_unit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_bills.rate_per_unit IS 'S607: the rate this bill was charged at, snapshotted so policy changes never rewrite an issued bill. 6dp because a blended rate (provider bill ÷ usage) is derived, not typed. charge_amount is authoritative.';


--
-- Name: COLUMN utility_bills.reading_end_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_bills.reading_end_date IS 'S607: the date of the closing read. Both A.R.S. § 33-1413.01(A) and § 33-1314.01(E)(1) require each bill to show the opening and closing readings AND their dates.';


--
-- Name: COLUMN utility_bills.service_agreement_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_bills.service_agreement_id IS 'S614: set when this bill is for a space the landlord SERVICES but does not lease (cross-property utilities). Mutually exclusive with lease_id.';


--
-- Name: COLUMN utility_bills.voided_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_bills.voided_at IS '10/12 (G8): when this bill was voided out of its cycle slot (a tenancy that never happened; the usage went back on hold). Kept forever; owed by nobody. NULL on every other bill, including the older $0 void markers, which keep their slot.';


--
-- Name: COLUMN utility_bills.void_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_bills.void_reason IS '10/12 (G8): why the bill was voided out of its slot, in plain words.';


--
-- Name: utility_meter_readings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.utility_meter_readings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    meter_id uuid NOT NULL,
    reading_date date NOT NULL,
    reading_value numeric NOT NULL,
    billing_cycle_month date NOT NULL,
    created_by_user_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    needs_review boolean DEFAULT false NOT NULL,
    review_note text,
    is_rollover boolean DEFAULT false NOT NULL,
    reason text DEFAULT 'monthly_cycle'::text NOT NULL,
    reason_note text,
    bill_amount numeric(12,2),
    photo_url text,
    move_out_lease_id uuid,
    move_out_space_move boolean DEFAULT false NOT NULL,
    CONSTRAINT utility_meter_readings_reason_check CHECK ((reason = ANY (ARRAY['monthly_cycle'::text, 'stay_turnover'::text, 'move_out_final'::text, 'meter_replaced'::text, 'baseline'::text, 'billed_off_platform'::text, 'other'::text])))
);


--
-- Name: COLUMN utility_meter_readings.reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_meter_readings.reason IS 'S605: monthly_cycle = the billed read; baseline = opening odometer captured at meter setup (never occupies the one-cycle-read-per-month slot); others are event reads.';


--
-- Name: COLUMN utility_meter_readings.bill_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_meter_readings.bill_amount IS 'S607: RUBS master only — the utility provider''s total dollar charge for this cycle (A.R.S. § 33-2107(C)(1) "actual expense of obtaining the utility, including the taxes and fees"). With reading_value (total gallons) it gives the blended rate the whole line bills at. NULL on submeters, and on a master means the dollar bill was not entered.';


--
-- Name: COLUMN utility_meter_readings.move_out_lease_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_meter_readings.move_out_lease_id IS 'The household a HELD move-out read closes out, stamped when the read is held for the landlord''s double-check so resolving it bills the same household the desk named.';


--
-- Name: COLUMN utility_meter_readings.move_out_space_move; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_meter_readings.move_out_space_move IS 'TRUE when a HELD move-out read is a space move''s closing read: the resident is staying, so resolving it bills their old space with no final invoice and no "your last days" email.';


--
-- Name: utility_meter_units; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.utility_meter_units (
    meter_id uuid NOT NULL,
    unit_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    quantity integer DEFAULT 1 NOT NULL,
    CONSTRAINT utility_meter_units_quantity_check CHECK (((quantity >= 1) AND (quantity <= 99)))
);


--
-- Name: COLUMN utility_meter_units.quantity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_meter_units.quantity IS 'S613: how many of this service the unit receives (e.g. 2 trash cans). Multiplies a FLAT-RATE charge only — metered and RUBS meters ignore it, since usage already reflects how much a unit used.';


--
-- Name: utility_meters; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.utility_meters (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    property_id uuid NOT NULL,
    utility_type text NOT NULL,
    label text NOT NULL,
    billing_method text NOT NULL,
    rate_per_unit numeric,
    base_fee numeric DEFAULT 0 NOT NULL,
    rubs_allocation_method text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    digits integer,
    sewer_rate_per_unit numeric,
    out_of_service boolean DEFAULT false NOT NULL,
    out_of_service_since date,
    rubs_basis text DEFAULT 'usage_rate'::text NOT NULL,
    rubs_submeter_rate text DEFAULT 'property_rate'::text NOT NULL,
    rubs_exclusion_mode text DEFAULT 'usage'::text NOT NULL,
    rubs_weights jsonb,
    reading_multiplier numeric(10,4) DEFAULT 1 NOT NULL,
    zero_use_confirmed_at timestamp with time zone,
    zero_use_confirmed_by_user_id uuid,
    zero_use_stops_flat_charge boolean DEFAULT false NOT NULL,
    looks_broken_at timestamp with time zone,
    looks_broken_reason text,
    CONSTRAINT utility_meters_billing_method_check CHECK ((billing_method = ANY (ARRAY['submeter'::text, 'rubs'::text, 'master_bill_to_landlord'::text, 'flat_rate'::text]))),
    CONSTRAINT utility_meters_check CHECK ((((billing_method = 'rubs'::text) AND (rubs_allocation_method IS NOT NULL)) OR ((billing_method <> 'rubs'::text) AND (rubs_allocation_method IS NULL)))),
    CONSTRAINT utility_meters_digits_check CHECK (
CASE
    WHEN ((utility_type = 'trash'::text) OR (billing_method = 'flat_rate'::text)) THEN (digits IS NULL)
    ELSE (digits = ANY (ARRAY[4, 5, 6, 7, 8]))
END),
    CONSTRAINT utility_meters_reading_multiplier_check CHECK ((reading_multiplier > (0)::numeric)),
    CONSTRAINT utility_meters_rubs_allocation_method_check CHECK ((rubs_allocation_method = ANY (ARRAY['occupant_count'::text, 'sqft'::text, 'bedrooms'::text, 'rented_spaces'::text, 'fixture_count'::text, 'unit_type_weight'::text, 'hybrid'::text]))),
    CONSTRAINT utility_meters_rubs_basis_check CHECK ((rubs_basis = ANY (ARRAY['usage_rate'::text, 'bill_amount'::text]))),
    CONSTRAINT utility_meters_rubs_exclusion_mode_check CHECK ((rubs_exclusion_mode = ANY (ARRAY['usage'::text, 'dollars'::text]))),
    CONSTRAINT utility_meters_rubs_submeter_rate_check CHECK ((rubs_submeter_rate = ANY (ARRAY['property_rate'::text, 'blended'::text]))),
    CONSTRAINT utility_meters_utility_type_check CHECK ((utility_type = ANY (ARRAY['water'::text, 'gas'::text, 'electric'::text, 'sewer'::text, 'trash'::text, 'propane'::text])))
);


--
-- Name: COLUMN utility_meters.digits; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_meters.digits IS 'S613: how many windows are on the METER FACE — not how long a reading is. Used only to work out the wrap when a meter passes its ceiling, and to bound what can be entered. NULL where nothing is read: trash, and any flat rate.';


--
-- Name: COLUMN utility_meters.rubs_basis; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_meters.rubs_basis IS 'S607: how a RUBS master prices its pool. usage_rate = usage × the property rate + base fee (default, unchanged behaviour, valid wherever a landlord may bill a published rate). bill_amount = divide the provider''s actual dollar bill for the cycle, blended into a single per-usage rate (required where the statute limits recovery to actual charges, e.g. A.R.S. § 33-2107(C)(1)). Ignored on non-RUBS meters.';


--
-- Name: COLUMN utility_meters.rubs_submeter_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_meters.rubs_submeter_rate IS 'S607: what rate a SUBMETERED unit on this master''s line is billed at. property_rate (default) = the property''s configured rate, unchanged from the usage_rate basis. blended = the master''s dollars ÷ usage. Either way the pool subtracts the dollars those units were actually billed, so the bill always closes.';


--
-- Name: COLUMN utility_meters.rubs_exclusion_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_meters.rubs_exclusion_mode IS 'S607: how a RUBS master removes its submetered units from the pool. usage (default) = subtract their measured usage, then price the remainder. dollars = subtract the dollars they were actually invoiced, so the bill closes at any submeter rate. Only meaningful when rubs_basis = bill_amount.';


--
-- Name: COLUMN utility_meters.rubs_weights; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_meters.rubs_weights IS 'S607: configuration for the allocation bases that need one. unit_type_weight: {unit_type: weight}. weighted_occupancy: {first, additional}. hybrid: {primary, secondary, primaryPct}. NULL elsewhere.';


--
-- Name: COLUMN utility_meters.reading_multiplier; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_meters.reading_multiplier IS 'S613: what ONE turn of the last digit on the FACE is worth in billing units. 1 = the face is already gallons/kWh. 100 = a face that counts per hundred gallons (413 on the dial = 41,300 gallons). Reads are entered and shown as the face; only usage is multiplied.';


--
-- Name: COLUMN utility_meters.zero_use_confirmed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_meters.zero_use_confirmed_at IS '10/12 (Nic): when somebody confirmed this meter works and the household on it uses nothing. While set (and no move-out or stay-turnover read has been taken since), a flat read on an occupied space bills $0 instead of being marked stuck. Cleared when a later cycle read shows usage or the meter is marked broken by hand.';


--
-- Name: COLUMN utility_meters.zero_use_confirmed_by_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_meters.zero_use_confirmed_by_user_id IS '10/12 (Nic): who chose "Works, tenant uses no power" (or confirmed it with a repair). Set and cleared together with zero_use_confirmed_at.';


--
-- Name: COLUMN utility_meters.zero_use_stops_flat_charge; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_meters.zero_use_stops_flat_charge IS '10/13 (Nic): the landlord''s answer to "Stop the flat charge too?" when marking a flat-rate meter "Works, nobody using it". TRUE: the flat charge is not billed while zero_use_confirmed_at is set, and bills again once it is cleared. Counts only while zero_use_confirmed_at is set; written and cleared with it.';


--
-- Name: COLUMN utility_meters.looks_broken_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_meters.looks_broken_at IS 'When a read made this meter look broken (a rollback, or a figure that barely moved when it should have). The read still bills; this is a prompt to go and look at the meter. Cleared when somebody confirms it is fine.';


--
-- Name: utility_owner_use_absorptions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.utility_owner_use_absorptions AS
 SELECT id,
    meter_id,
    unit_id,
    landlord_id,
    utility_type,
    billing_cycle_month,
    allocation_method,
    allocation_basis,
    charge_amount,
    base_fee_share,
    notes,
    reason,
    created_at,
    updated_at
   FROM public.utility_absorbed_charges
  WHERE (reason = 'owner_use'::text)
  WITH CASCADED CHECK OPTION;


--
-- Name: VIEW utility_owner_use_absorptions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.utility_owner_use_absorptions IS '10/20: the old name for utility_absorbed_charges, kept so the owner-use writers and readers work either side of the rename. Owner-use rows only. Drop it once nothing names it.';


--
-- Name: utility_pay_link_settlements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.utility_pay_link_settlements (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    pay_link_id uuid,
    landlord_id uuid NOT NULL,
    property_id uuid NOT NULL,
    utility_bill_id uuid,
    unit_id uuid,
    meter_id uuid,
    billing_cycle_month date,
    utility_type text NOT NULL,
    charge_amount numeric(12,2) NOT NULL,
    tax_amount numeric(12,2) DEFAULT 0 NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    pos_transaction_id uuid,
    pos_transaction_item_id uuid,
    payment_id uuid,
    settled_at timestamp with time zone,
    refunded_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    created_by uuid,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    raised_at_counter boolean DEFAULT false NOT NULL,
    meter_reading_id uuid,
    CONSTRAINT upls_amount_check CHECK ((charge_amount >= (0)::numeric)),
    CONSTRAINT upls_cancelled_is_stamped CHECK (((cancelled_at IS NOT NULL) = (status = 'cancelled'::text))),
    CONSTRAINT upls_counter_row_names_its_bill CHECK (((NOT raised_at_counter) OR (utility_bill_id IS NOT NULL))),
    CONSTRAINT upls_no_bill_means_a_sale CHECK (((utility_bill_id IS NOT NULL) OR (status = ANY (ARRAY['settled'::text, 'refunded'::text])))),
    CONSTRAINT upls_one_door CHECK (((pay_link_id IS NOT NULL) <> raised_at_counter)),
    CONSTRAINT upls_refunded_is_stamped CHECK (((refunded_at IS NOT NULL) = (status = 'refunded'::text))),
    CONSTRAINT upls_sale_shape CHECK (((pos_transaction_id IS NOT NULL) = (status = ANY (ARRAY['settled'::text, 'refunded'::text])))),
    CONSTRAINT upls_settled_is_stamped CHECK (((settled_at IS NOT NULL) = (status = ANY (ARRAY['settled'::text, 'refunded'::text])))),
    CONSTRAINT upls_status_check CHECK ((status = ANY (ARRAY['open'::text, 'settled'::text, 'refunded'::text, 'cancelled'::text]))),
    CONSTRAINT upls_tax_check CHECK ((tax_amount >= (0)::numeric)),
    CONSTRAINT upls_utility_type_check CHECK ((utility_type = ANY (ARRAY['water'::text, 'gas'::text, 'electric'::text, 'sewer'::text, 'trash'::text, 'propane'::text])))
);


--
-- Name: TABLE utility_pay_link_settlements; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.utility_pay_link_settlements IS '10/20 (Nic): the one book for utility money collected on a PAY LINK — "a paylink''s utility line settles the bill and counts as recovery". One row per utility line on a link: with utility_bill_id, the bill that line closes out (the bill stays the record of what was billed back, so this row adds no second figure); without one, a line rung up by hand for somebody''s power that no bill was ever cut for — which is the only kind that is itself a figure, and is what happened to Andres Razo''s $163.17 of August and September electric. Which utility comes from the bill or from pos_items.recovers_utility, never from an item name.';


--
-- Name: COLUMN utility_pay_link_settlements.pay_link_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_pay_link_settlements.pay_link_id IS 'The emailed link this utility line went out on, or NULL when the line was raised at the register with the payer standing there (raised_at_counter). Those are the only two doors, and upls_one_door holds a row to one of them.';


--
-- Name: COLUMN utility_pay_link_settlements.utility_bill_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_pay_link_settlements.utility_bill_id IS 'The utility bill this line settles, or NULL when there was never one. NULL is an answer — "collected, and no bill existed" — not a missing value: a bill invented after the fact for usage nobody read into a cycle would be a worse record than the gap it filled.';


--
-- Name: COLUMN utility_pay_link_settlements.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_pay_link_settlements.status IS 'open (a link is out for this bill), settled (paid), refunded (the WHOLE sale went back, so the bill is owed again and this stops counting as recovery), cancelled (the link was closed before it was paid). A PART refund leaves the row settled with a note: short of the whole sale going back, nothing says which line the money came off, and re-billing the full amount would ask the payer for money the landlord is still holding.';


--
-- Name: COLUMN utility_pay_link_settlements.payment_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_pay_link_settlements.payment_id IS 'The charge row on the payer''s invoice that this collection took care of. The charge is VOIDED when the link is paid (services/chargeVoids — "a charge nobody owes is voided, never deleted"), because the money came in through the register sale and the charge accruing the same income twice would double the revenue in the books. Kept here after the void so the bill''s story stays readable.';


--
-- Name: COLUMN utility_pay_link_settlements.raised_at_counter; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_pay_link_settlements.raised_at_counter IS '10/20 (Nic): TRUE when the desk took the closing read and put the bill on the ticket — "I don''t want it to generate a bill". Such a row is on no invoice and nothing was emailed for it while it is open; paying the ticket settles it, and cancelling it hands the bill back to the ordinary route.';


--
-- Name: COLUMN utility_pay_link_settlements.meter_reading_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_pay_link_settlements.meter_reading_id IS 'The closing read this bill was raised from, when it was raised at a counter. The read always stands, whether or not the bill is ever collected.';


--
-- Name: utility_reading_double_checks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.utility_reading_double_checks (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    run_id uuid NOT NULL,
    meter_id uuid NOT NULL,
    first_value numeric NOT NULL,
    is_suspicious boolean NOT NULL,
    second_value numeric,
    outcome text,
    entered_by_user_id uuid,
    entered_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT utility_reading_double_checks_outcome_check CHECK ((outcome = ANY (ARRAY['verified'::text, 'replaced'::text, 'escalated'::text])))
);


--
-- Name: utility_reading_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.utility_reading_runs (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    property_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    billing_cycle_month date NOT NULL,
    opened_on date NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    completed_at timestamp with time zone,
    completed_by_user_id uuid,
    bills_created integer,
    billed_total numeric(12,2),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    utility_type text,
    approved_at timestamp with time zone,
    approved_by_user_id uuid,
    CONSTRAINT utility_reading_runs_status_check CHECK ((status = ANY (ARRAY['open'::text, 'double_check'::text, 'completed'::text])))
);


--
-- Name: COLUMN utility_reading_runs.utility_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_reading_runs.utility_type IS 'S631: the utility this run covers, so each bills as soon as its own reads are in. NULL = every readable meter on the property (the original whole-property run).';


--
-- Name: utility_service_agreements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.utility_service_agreements (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    landlord_id uuid NOT NULL,
    unit_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    service_address text,
    note text,
    status text DEFAULT 'active'::text NOT NULL,
    start_date date DEFAULT CURRENT_DATE NOT NULL,
    end_date date,
    superseded_by_lease_id uuid,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    billing_due_day integer DEFAULT 1 NOT NULL,
    late_fee_enabled boolean DEFAULT true NOT NULL,
    late_fee_grace_days integer,
    late_fee_initial_amount numeric(10,2),
    late_fee_initial_type text DEFAULT 'flat'::text NOT NULL,
    late_fee_accrual_amount numeric,
    late_fee_accrual_type text,
    late_fee_accrual_period text,
    late_fee_accrual_from text DEFAULT 'grace_end'::text NOT NULL,
    late_fee_cap_amount numeric,
    late_fee_cap_type text,
    payer_accepted_at timestamp with time zone,
    payer_attested_at timestamp with time zone,
    payer_attested_by uuid,
    payer_attestation_note text,
    moveout_notice_at timestamp with time zone,
    moveout_expected_on date,
    moveout_note text,
    final_bill_issued_at timestamp with time zone,
    booking_id uuid,
    CONSTRAINT usa_billing_due_day_check CHECK (((billing_due_day >= 1) AND (billing_due_day <= 31))),
    CONSTRAINT usa_late_fee_accrual_from_check CHECK ((late_fee_accrual_from = ANY (ARRAY['grace_end'::text, 'due_date'::text, 'due_date_inclusive'::text]))),
    CONSTRAINT usa_late_fee_accrual_period_check CHECK (((late_fee_accrual_period IS NULL) OR (late_fee_accrual_period = ANY (ARRAY['daily'::text, 'weekly'::text, 'monthly'::text])))),
    CONSTRAINT usa_late_fee_accrual_type_check CHECK (((late_fee_accrual_type IS NULL) OR (late_fee_accrual_type = ANY (ARRAY['flat'::text, 'percent_of_rent'::text])))),
    CONSTRAINT usa_late_fee_cap_type_check CHECK (((late_fee_cap_type IS NULL) OR (late_fee_cap_type = ANY (ARRAY['flat'::text, 'percent_of_rent'::text])))),
    CONSTRAINT usa_late_fee_initial_type_check CHECK ((late_fee_initial_type = ANY (ARRAY['flat'::text, 'percent_of_rent'::text]))),
    CONSTRAINT utility_service_agreements_status_check CHECK ((status = ANY (ARRAY['active'::text, 'ended'::text])))
);


--
-- Name: COLUMN utility_service_agreements.billing_due_day; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_service_agreements.billing_due_day IS 'S615: day of month this agreement''s utility invoice is due. Clamped to the last day in shorter months, same as a lease''s rent_due_day.';


--
-- Name: COLUMN utility_service_agreements.late_fee_initial_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_service_agreements.late_fee_initial_amount IS 'S615: stamped from property policy when the agreement is created. NULL means no late fee was configured at the property, and none accrues.';


--
-- Name: COLUMN utility_service_agreements.payer_accepted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_service_agreements.payer_accepted_at IS 'S616: when the payer accepted their portal invite. Either this or payer_attested_at must be set before any invoice is issued — nobody is billed by GAM without having agreed to be.';


--
-- Name: COLUMN utility_service_agreements.payer_attested_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_service_agreements.payer_attested_at IS 'S616: when the LANDLORD attested that this person already agreed to the arrangement off-platform. For the arrangements that predate GAM — cash collected by hand for years. Recorded with who attested, because it is a claim someone made rather than something the platform verified.';


--
-- Name: COLUMN utility_service_agreements.moveout_notice_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_service_agreements.moveout_notice_at IS 'S616: when the payer told GAM they are leaving, from the button in their portal. A notice, not a termination — the landlord still confirms the final reading and who takes over.';


--
-- Name: COLUMN utility_service_agreements.moveout_expected_on; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_service_agreements.moveout_expected_on IS 'S616: the date the payer expects to be gone. Drives the final billing period and tells the landlord when to read the meter.';


--
-- Name: utility_wash_holds; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.utility_wash_holds (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    meter_id uuid NOT NULL,
    unit_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    lease_id uuid,
    booking_id uuid,
    tenant_id uuid,
    departed_on date NOT NULL,
    billing_cycle_month date NOT NULL,
    utility_type text NOT NULL,
    usage_amount numeric(14,4),
    allocation_method text,
    allocation_basis numeric(14,4),
    rate_per_unit numeric(12,6),
    base_fee_share numeric(12,2) DEFAULT 0 NOT NULL,
    charge_amount numeric(12,2) NOT NULL,
    tax_rate_pct numeric(6,3),
    tax_amount numeric(12,2),
    sewer_rate_per_unit numeric(12,6),
    reading_start numeric(14,4),
    reading_end numeric(14,4),
    reading_start_date date,
    reading_end_date date,
    notes text,
    absorbed_at timestamp with time zone,
    absorbed_charge_id uuid,
    released_at timestamp with time zone,
    released_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    released_bill_id uuid,
    CONSTRAINT utility_wash_holds_absorbed_shape CHECK (((absorbed_at IS NULL) = (absorbed_charge_id IS NULL))),
    CONSTRAINT utility_wash_holds_amount_check CHECK ((charge_amount >= (0)::numeric)),
    CONSTRAINT utility_wash_holds_departure_check CHECK (((lease_id IS NOT NULL) OR (booking_id IS NOT NULL))),
    CONSTRAINT utility_wash_holds_outcome_check CHECK ((NOT ((absorbed_at IS NOT NULL) AND (released_at IS NOT NULL)))),
    CONSTRAINT utility_wash_holds_released_shape CHECK (((released_at IS NULL) = (released_reason IS NULL)))
);


--
-- Name: TABLE utility_wash_holds; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.utility_wash_holds IS '10/20 (Nic): a departing payer''s final utility stub, parked because the money question is not answered yet — the closing read came in first, or the clerk who checked them out could not answer it without "Issue refunds". Reported to the billing engine as NOT billed, the same as the invite hold it is shaped after (suspended_utility_charges, S629), because billing it and then learning it was a wash means reversing a charge the guest may already have seen. Its own table and not suspended_utility_charges: that table''s nightly sweep closes every open hold when a property''s onboarding window shuts, with a reason that would be untrue of somebody who drove away. A hold is not an absorption and is never counted as one.';


--
-- Name: COLUMN utility_wash_holds.released_bill_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.utility_wash_holds.released_bill_id IS 'The utility_bills row this parked stub was billed onto when its hold was released — a refund went out, or the check-out was undone, so it is owed after all. Null while the hold is still waiting, null on a hold the billing run itself billed in the same breath as releasing it (its own numbers are fresher than the parked copy''s), and null when nobody is set up to be billed for utilities on that space, in which case released_reason says so. Mirrors suspended_utility_charges.released_bill_id.';


--
-- Name: v_credit_uses; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_credit_uses AS
 SELECT cu.id,
    cu.tenant_credit_id,
    cu.prepaid_credit_id,
    cu.payment_id,
    cu.deposit_return_id,
    cu.payment_reversal_id,
    cu.remittance_id,
    cu.lease_id,
    cu.amount,
    cu.billing_month,
    cu.source,
    cu.status,
    cu.release_reason,
    cu.held_at,
    cu.applied_at,
    cu.released_at,
    cu.created_by,
        CASE
            WHEN (cu.prepaid_credit_id IS NOT NULL) THEN 'paid_ahead'::text
            WHEN (tc.category = 'deposit_interest'::text) THEN 'deposit_interest'::text
            ELSE 'issued'::text
        END AS kind,
    pc.funded_by,
        CASE
            WHEN (cu.prepaid_credit_id IS NULL) THEN (tc.category = 'deposit_interest'::text)
            ELSE COALESCE((pc.funded_by = 'gam'::text), ((EXISTS ( SELECT 1
               FROM public.tenant_remittances r
              WHERE ((r.id = pc.source_remittance_id) AND (r.payment_method = ANY (ARRAY['ach'::text, 'card'::text])) AND (r.stripe_payment_intent_id IS NOT NULL)))) OR (EXISTS ( SELECT 1
               FROM public.payments sp
              WHERE ((sp.id = pc.source_payment_id) AND sp.platform_held)))))
        END AS gam_held
   FROM ((public.credit_uses cu
     LEFT JOIN public.tenant_credits tc ON ((tc.id = cu.tenant_credit_id)))
     LEFT JOIN public.lease_prepaid_credits pc ON ((pc.id = cu.prepaid_credit_id)));


--
-- Name: VIEW v_credit_uses; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_credit_uses IS 'S655: every credit use with its kind (issued | deposit_interest | paid_ahead), the paid-ahead credit''s funded_by, and gam_held (GAM holds the money behind it).';


--
-- Name: v_expense_balance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_expense_balance AS
 SELECT e.id AS expense_id,
    e.landlord_id,
    e.amount,
    (COALESCE(p.paid, (0)::numeric))::numeric(12,2) AS paid,
    ((e.amount - COALESCE(p.paid, (0)::numeric)))::numeric(12,2) AS unpaid,
    p.last_paid_on,
        CASE
            WHEN (COALESCE(p.paid, (0)::numeric) <= (0)::numeric) THEN 'unpaid'::text
            WHEN (COALESCE(p.paid, (0)::numeric) < e.amount) THEN 'partial'::text
            ELSE 'paid'::text
        END AS pay_state
   FROM (public.landlord_expenses e
     LEFT JOIN LATERAL ( SELECT sum(x.amount) AS paid,
            max(x.paid_on) AS last_paid_on
           FROM public.landlord_expense_payments x
          WHERE ((x.expense_id = e.id) AND (x.voided_at IS NULL))) p ON (true))
  WHERE (e.status = 'active'::text);


--
-- Name: VIEW v_expense_balance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_expense_balance IS '10/12 (Nic, L5): each live expense''s paid and unpaid parts, from its payments (EXPENSE_PAY_STATES).';


--
-- Name: v_installment_payments; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_installment_payments AS
 SELECT propane_fill_installments.payment_id
   FROM public.propane_fill_installments
  WHERE (propane_fill_installments.payment_id IS NOT NULL)
UNION
 SELECT home_sale_installments.payment_id
   FROM public.home_sale_installments
  WHERE (home_sale_installments.payment_id IS NOT NULL)
UNION
 SELECT flex_deposit_installments.payment_id
   FROM public.flex_deposit_installments
  WHERE (flex_deposit_installments.payment_id IS NOT NULL);


--
-- Name: VIEW v_installment_payments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_installment_payments IS 'S641: every payment row that is one instalment of an agreed plan. Such a charge is scheduled, not overdue — it must not make a unit read as delinquent. Add any new installment product here and every reader follows.';


--
-- Name: v_landlord_agent_interactions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_landlord_agent_interactions AS
 SELECT id,
    conversation_id,
    turn_index,
    agent_type,
    audience,
    agent_name,
    handled_by_tier,
    outcome,
    property_id,
    landlord_id,
    actor_user_id,
    actor_role,
    escalation_count,
    escalated_to_human,
    tool_invocation_count,
    tool_names,
    latency_ms,
    prompt_tokens,
    completion_tokens,
    model,
    grounded,
    created_at
   FROM public.agent_interaction_logs;


--
-- Name: VIEW v_landlord_agent_interactions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_landlord_agent_interactions IS 'S480 landlord-facing agent_interaction_logs metadata-only view. Omits verbatim user_message / agent_reply / tool_invocations / human_handoff / error_detail / knowledge_chunk_ids / metadata / profile_id / actor_subject_id. Route-layer scoping must add landlord_id = actor.profileId.';


--
-- Name: v_lease_active_tenants; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_lease_active_tenants AS
 SELECT lt.lease_id,
    lt.id AS lease_tenant_id,
    lt.tenant_id,
    lt.role,
    lt.status,
    lt.financial_responsibility,
    lt.responsibility_pct,
    lt.added_at,
    us.first_name,
    us.last_name,
    us.email,
    us.phone
   FROM ((public.lease_tenants lt
     JOIN public.tenants t ON ((t.id = lt.tenant_id)))
     JOIN public.users us ON ((us.id = t.user_id)))
  WHERE (lt.status = 'active'::text);


--
-- Name: v_payment_money; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_payment_money AS
 SELECT p.id AS payment_id,
    p.amount,
    p.issued_credit_amount,
    COALESCE(c.landlord_held_credit, (0)::numeric) AS landlord_held_credit,
    COALESCE(c.gam_funded_credit, (0)::numeric) AS gam_funded_credit,
    COALESCE(c.paid_ahead_credit, (0)::numeric) AS paid_ahead_credit,
    COALESCE(c.deposit_interest_credit, (0)::numeric) AS deposit_interest_credit,
    (((p.amount - p.issued_credit_amount) - COALESCE(c.landlord_held_credit, (0)::numeric)) - COALESCE(c.gam_funded_credit, (0)::numeric)) AS money_part,
        CASE
            WHEN ((p.revenue_owner = 'landlord'::text) AND (p.type <> 'deposit'::text) AND (p.amount >= (0)::numeric)) THEN (COALESCE(c.gam_funded_credit, (0)::numeric) +
            CASE
                WHEN ((p.status = 'settled'::text) AND (p.manual_method IS NULL) AND ((p.stripe_charge_id IS NOT NULL) OR (p.flexpay_advance_id IS NOT NULL))) THEN (((p.amount - p.issued_credit_amount) - COALESCE(c.landlord_held_credit, (0)::numeric)) - COALESCE(c.gam_funded_credit, (0)::numeric))
                ELSE (0)::numeric
            END)
            ELSE (0)::numeric
        END AS gam_held_part
   FROM (public.payments p
     LEFT JOIN LATERAL ( SELECT sum(v.amount) FILTER (WHERE ((v.kind = 'paid_ahead'::text) AND (NOT v.gam_held))) AS landlord_held_credit,
            sum(v.amount) FILTER (WHERE v.gam_held) AS gam_funded_credit,
            sum(v.amount) FILTER (WHERE (v.kind = 'paid_ahead'::text)) AS paid_ahead_credit,
            sum(v.amount) FILTER (WHERE (v.kind = 'deposit_interest'::text)) AS deposit_interest_credit
           FROM public.v_credit_uses v
          WHERE ((v.payment_id = p.id) AND (v.status = ANY (ARRAY['applied'::text, 'reversed'::text])))) c ON (true));


--
-- Name: VIEW v_payment_money; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_payment_money IS 'S655: each charge split by who paid it. gam_held_part is the ONLY figure a payout may carry, and is 0 on every row whose money is not paid to the landlord when it settles: GAM fees, the FlexPay pull, a held prepaid move-in box (its money is paid out on the row its paid-ahead credit pays), a deposit held in trust (type deposit; only the move-out settlement releases it) and a move-out refund row. A card-paid move-out shortfall keeps its figure. A 0 here never clears platform_held on a deposit (it stays TRUE while in trust). money_part is the row''s own money; paid_ahead_credit counted under "Money received" on the day it arrived, not again here.';


--
-- Name: v_unit_occupancy; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_unit_occupancy AS
 SELECT u.id AS unit_id,
    (primary_info.tenant_id IS NOT NULL) AS is_occupied,
    primary_info.tenant_id AS primary_tenant_id,
    primary_info.first_name AS primary_first_name,
    primary_info.last_name AS primary_last_name,
    primary_info.email AS primary_email,
    primary_info.phone AS primary_phone,
    primary_info.lease_id AS active_lease_id,
    COALESCE(counts.tenant_count, 0) AS tenant_count
   FROM ((public.units u
     LEFT JOIN LATERAL ( SELECT t.id AS tenant_id,
            us.first_name,
            us.last_name,
            us.email,
            us.phone,
            l.id AS lease_id
           FROM (((public.leases l
             JOIN public.lease_tenants lt ON ((lt.lease_id = l.id)))
             JOIN public.tenants t ON ((t.id = lt.tenant_id)))
             JOIN public.users us ON ((us.id = t.user_id)))
          WHERE ((l.unit_id = u.id) AND (l.status = 'active'::text) AND (lt.status = 'active'::text) AND (lt.role = 'primary'::text))
         LIMIT 1) primary_info ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS tenant_count
           FROM (public.leases l
             JOIN public.lease_tenants lt ON ((lt.lease_id = l.id)))
          WHERE ((l.unit_id = u.id) AND (l.status = 'active'::text) AND (lt.status = 'active'::text))) counts ON (true))
  WHERE (u.status <> 'utility_service'::text);


--
-- Name: VIEW v_unit_occupancy; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_unit_occupancy IS 'Occupancy per RENTABLE unit. S616: service points (status=''utility_service'') are excluded — they exist only to carry a neighbour''s utility bill under a payer''s name, are never rentable or bookable, and are neither occupied nor vacant.';


--
-- Name: vehicles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vehicles (
    id uuid DEFAULT public.gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    home_depot_id uuid NOT NULL,
    name text NOT NULL,
    plate_or_id text,
    stops_per_dump integer DEFAULT 50 NOT NULL,
    avg_speed_mph integer DEFAULT 25 NOT NULL,
    avg_service_minutes integer DEFAULT 3 NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT vehicles_service_minutes_positive CHECK ((avg_service_minutes > 0)),
    CONSTRAINT vehicles_speed_positive CHECK ((avg_speed_mph > 0)),
    CONSTRAINT vehicles_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'archived'::text]))),
    CONSTRAINT vehicles_stops_per_dump_positive CHECK ((stops_per_dump > 0))
);


--
-- Name: work_trade_agreements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.work_trade_agreements (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    unit_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    duties text,
    start_date date NOT NULL,
    end_date date,
    renewal_terms text,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    monthly_hours_target integer DEFAULT 80 NOT NULL,
    paused_by_hibernation boolean DEFAULT false NOT NULL,
    covered_charges text[] DEFAULT ARRAY['rent'::text, 'fees'::text, 'water'::text, 'sewer'::text, 'electric'::text, 'gas'::text, 'trash'::text, 'propane'::text] NOT NULL,
    banked_hours numeric(8,2) DEFAULT 0 NOT NULL,
    carry_forward_months integer DEFAULT 1 NOT NULL,
    tracks_hours boolean DEFAULT true NOT NULL,
    trusted boolean DEFAULT false NOT NULL,
    skills text[] DEFAULT '{}'::text[] NOT NULL,
    carry_forward_indefinite boolean DEFAULT false NOT NULL,
    field_permissions text[] DEFAULT '{}'::text[] NOT NULL,
    booking_id uuid,
    extra_hours_mode text DEFAULT 'bank'::text NOT NULL,
    extra_hours_rate numeric(10,2),
    extra_hours_pay_method text,
    paused_space_occupied boolean,
    CONSTRAINT work_trade_agreements_extra_hours_mode_check CHECK ((extra_hours_mode = ANY (ARRAY['bank'::text, 'pay'::text]))),
    CONSTRAINT work_trade_agreements_extra_hours_pay_method_check CHECK (((extra_hours_pay_method IS NULL) OR (extra_hours_pay_method = ANY (ARRAY['payroll_w2'::text, 'contractor_1099'::text])))),
    CONSTRAINT work_trade_agreements_extra_hours_pay_needs_terms CHECK (((extra_hours_mode = 'bank'::text) OR ((extra_hours_rate IS NOT NULL) AND (extra_hours_pay_method IS NOT NULL)))),
    CONSTRAINT work_trade_agreements_extra_hours_rate_positive CHECK (((extra_hours_rate IS NULL) OR (extra_hours_rate > (0)::numeric))),
    CONSTRAINT work_trade_agreements_field_permissions_check CHECK ((field_permissions <@ ARRAY['read_meters'::text])),
    CONSTRAINT work_trade_agreements_skills_check CHECK ((skills <@ ARRAY['plumbing'::text, 'electrical'::text, 'hvac'::text, 'appliance'::text, 'roofing'::text, 'structural'::text, 'pool'::text, 'locksmith'::text])),
    CONSTRAINT work_trade_agreements_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'ended'::text]))),
    CONSTRAINT work_trade_agreements_target_positive CHECK ((monthly_hours_target > 0)),
    CONSTRAINT work_trade_banked_hours_nonneg CHECK ((banked_hours >= (0)::numeric)),
    CONSTRAINT work_trade_carry_forward_months_nonneg CHECK ((carry_forward_months >= 0)),
    CONSTRAINT work_trade_covered_charges_check CHECK ((covered_charges <@ ARRAY['rent'::text, 'fees'::text, 'water'::text, 'sewer'::text, 'electric'::text, 'gas'::text, 'trash'::text, 'propane'::text]))
);


--
-- Name: COLUMN work_trade_agreements.paused_by_hibernation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_trade_agreements.paused_by_hibernation IS 'S594: TRUE when lease hibernation paused this agreement. lease /resume reactivates only these, never a hand-paused one.';


--
-- Name: COLUMN work_trade_agreements.covered_charges; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_trade_agreements.covered_charges IS 'S613: what this agreement trades for. A charge NOT listed is billed in full and takes no part in the credit basis. Default is everything, which is the behaviour every pre-S613 agreement had.';


--
-- Name: COLUMN work_trade_agreements.banked_hours; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_trade_agreements.banked_hours IS 'S624: hours worked beyond every obligation, carried forward without limit. Buys future months; never converts to cash.';


--
-- Name: COLUMN work_trade_agreements.carry_forward_months; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_trade_agreements.carry_forward_months IS 'S624: how many further month-closes a deficit may survive before it is billed in cash and the agreement ends. 0 = bill at the first close. Landlord-set.';


--
-- Name: COLUMN work_trade_agreements.tracks_hours; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_trade_agreements.tracks_hours IS 'S637: false = trusted trade. Covered charges clear each month with no hours logged; monthly_hours_target is retained but not asked for.';


--
-- Name: COLUMN work_trade_agreements.booking_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_trade_agreements.booking_id IS '10/6 (Nic): the stay this work trade was made for. Its dates and site follow the stay; a lease drafted from the stay takes it over (cleared).';


--
-- Name: COLUMN work_trade_agreements.extra_hours_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_trade_agreements.extra_hours_mode IS '10/12 (Nic): what approved hours beyond what a month needs (after any carried shortfall) do. bank = banked toward future months (the default, and the only behavior before 10/12); pay = recorded at month close as payable extra hours (work_trade_extra_hours) at extra_hours_rate. Only an agreement that tracks hours pays extra hours.';


--
-- Name: COLUMN work_trade_agreements.extra_hours_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_trade_agreements.extra_hours_rate IS '10/12: the hourly rate for PAID extra hours. The tenant may see it for paid extra hours; the trade hours themselves never carry a rate for the tenant (S643). Kept when switching back to bank.';


--
-- Name: COLUMN work_trade_agreements.extra_hours_pay_method; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_trade_agreements.extra_hours_pay_method IS '10/12: how paid extra hours are paid — payroll_w2 (Payroll (W-2)) or contractor_1099 (Contractor payment (1099)).';


--
-- Name: COLUMN work_trade_agreements.paused_space_occupied; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_trade_agreements.paused_space_occupied IS 'While this agreement is paused, is the space still being used? TRUE keeps counting hours (the month behaves as normal), FALSE asks for no hours, NULL means the landlord has not been asked and reads as TRUE. Read only while the trade is not running (paused, or ended straight out of a pause) and forgotten the moment it resumes. Nic 10/19.';


--
-- Name: work_trade_extra_hours; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.work_trade_extra_hours (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    agreement_id uuid NOT NULL,
    landlord_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    settlement_id uuid,
    period_month date NOT NULL,
    period_start date NOT NULL,
    hours numeric(8,2) NOT NULL,
    rate numeric(10,2) NOT NULL,
    amount numeric(12,2) NOT NULL,
    pay_method text NOT NULL,
    status text DEFAULT 'unpaid'::text NOT NULL,
    paid_on date,
    paid_how text,
    paid_note text,
    paid_by uuid,
    paid_at timestamp with time zone,
    sent_to_books_at timestamp with time zone,
    sent_to_books_by uuid,
    books_reference_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT work_trade_extra_hours_amount_nonneg CHECK ((amount >= (0)::numeric)),
    CONSTRAINT work_trade_extra_hours_hours_positive CHECK ((hours > (0)::numeric)),
    CONSTRAINT work_trade_extra_hours_paid_how_check CHECK (((paid_how IS NULL) OR (paid_how = ANY (ARRAY['check'::text, 'cash'::text, 'gam_books'::text])))),
    CONSTRAINT work_trade_extra_hours_paid_is_stamped CHECK (((status = 'paid'::text) = (paid_at IS NOT NULL))),
    CONSTRAINT work_trade_extra_hours_pay_method_check CHECK ((pay_method = ANY (ARRAY['payroll_w2'::text, 'contractor_1099'::text]))),
    CONSTRAINT work_trade_extra_hours_rate_positive CHECK ((rate > (0)::numeric)),
    CONSTRAINT work_trade_extra_hours_sent_is_stamped CHECK (((status <> 'sent_to_books'::text) OR (sent_to_books_at IS NOT NULL))),
    CONSTRAINT work_trade_extra_hours_status_check CHECK ((status = ANY (ARRAY['unpaid'::text, 'sent_to_books'::text, 'paid'::text])))
);


--
-- Name: TABLE work_trade_extra_hours; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.work_trade_extra_hours IS '10/12 (Nic): paid extra hours — approved work-trade hours beyond what a month and any carried shortfall needed, on an agreement set to pay them. Written by the month close; paid by hand (Mark paid) or queued for GAM Books (Send to GAM Books). Never deleted.';


--
-- Name: COLUMN work_trade_extra_hours.books_reference_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_trade_extra_hours.books_reference_id IS '10/12: the GAM Books payroll run or contractor payment that paid this record. NULL until GAM Books picks up a sent_to_books record (follow-up).';


--
-- Name: work_trade_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.work_trade_logs (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    agreement_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    submitted_by uuid NOT NULL,
    work_date date NOT NULL,
    hours numeric(6,2) NOT NULL,
    description text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    rejection_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT work_trade_logs_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text])))
);


--
-- Name: work_trade_settlements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.work_trade_settlements (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    agreement_id uuid NOT NULL,
    invoice_id uuid,
    period_month date NOT NULL,
    target_hours numeric(8,2) NOT NULL,
    hours_worked numeric(8,2) DEFAULT 0 NOT NULL,
    hours_applied numeric(8,2) DEFAULT 0 NOT NULL,
    hour_rate numeric(12,4) NOT NULL,
    basis_amount numeric(12,2) NOT NULL,
    credit_applied numeric(12,2) DEFAULT 0 NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    settled_at timestamp with time zone,
    billed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    close_run_at timestamp with time zone,
    extra_hours_banked numeric(8,2) DEFAULT 0 NOT NULL,
    voided_at timestamp with time zone,
    void_reason text,
    CONSTRAINT work_trade_settlements_applied_within_target CHECK ((hours_applied <= target_hours)),
    CONSTRAINT work_trade_settlements_credit_nonneg CHECK (((credit_applied >= (0)::numeric) AND (credit_applied <= basis_amount))),
    CONSTRAINT work_trade_settlements_extra_hours_banked_nonneg CHECK ((extra_hours_banked >= (0)::numeric)),
    CONSTRAINT work_trade_settlements_hours_nonneg CHECK (((hours_worked >= (0)::numeric) AND (hours_applied >= (0)::numeric))),
    CONSTRAINT work_trade_settlements_period_dates CHECK ((period_end >= period_start)),
    CONSTRAINT work_trade_settlements_period_is_month_start CHECK ((period_month = (date_trunc('month'::text, (period_month)::timestamp with time zone))::date)),
    CONSTRAINT work_trade_settlements_status_check CHECK ((status = ANY (ARRAY['open'::text, 'settled'::text, 'billed'::text, 'voided'::text]))),
    CONSTRAINT work_trade_settlements_target_nonnegative CHECK ((target_hours >= (0)::numeric)),
    CONSTRAINT work_trade_settlements_voided_is_stamped CHECK ((((status = 'voided'::text) = (voided_at IS NOT NULL)) AND ((voided_at IS NULL) = (void_reason IS NULL))))
);


--
-- Name: COLUMN work_trade_settlements.extra_hours_banked; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_trade_settlements.extra_hours_banked IS '10/12: hours the month close of this period added to the agreement''s bank — approved hours beyond what this month and any carried shortfall needed. Hours only (S643). Rises only; a re-run that finds nothing new adds nothing.';


--
-- Name: COLUMN work_trade_settlements.voided_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_trade_settlements.voided_at IS '10/12 (G8): when this open period was voided (its bill will never be owed: a lease voided before signing, or a new lease that never starts). Kept forever; credits nothing.';


--
-- Name: COLUMN work_trade_settlements.void_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_trade_settlements.void_reason IS '10/12 (G8): why the period was voided, in plain words.';


--
-- Name: CONSTRAINT work_trade_settlements_target_nonnegative ON work_trade_settlements; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT work_trade_settlements_target_nonnegative ON public.work_trade_settlements IS 'S639: zero is a real target — a tracks_hours=false agreement asks for no hours and still opens a settlement period, because the period is what carries the credit onto the invoice. Negative remains impossible.';


